window.HB_TR["psalms"]["ur"]=["1. مبارک ہے وہ شخص جو بددینوں کی رائے میں نہیں چلتا، نہ گناہگاروں کے راستے میں کھڑا ہوتا ہے، نہ ہی حقارت کرنے والوں کی نشست پر بیٹھتا ہے۔ {بے خدا: یا، بدکار}\n2. لیکن اس کی خوشی خداوند کے قانون میں ہے؛ اور اپنے قانون میں وہ دن رات مراقبہ کرتا ہے۔\n3۔ اور وہ ایسے درخت کی مانند ہوگا جو پانی کی ندیوں کے کنارے لگایا گیا ہو، جو اپنے موسم میں اپنا پھل دیتا ہے؛ اس کا پتہ بھی مرجھا نہیں جائے گا؛ اور جو کچھ وہ کرے گا وہ کامیاب ہوگا۔ {ودر: عبوری۔ مدھم ہو جاؤ}\n4۔ بے دین {ہیں} ایسے نہیں: بلکہ {ہیں} اس بھوسے کی طرح ہیں جسے ہوا بھگا دیتی ہے۔\n5. اس لیے بدکار انصاف میں نہیں کھڑے ہوں گے، اور نہ ہی گناہ گار نیکوں کی جماعت میں کھڑے ہوں گے۔\n6۔ کیونکہ خداوند راستبازوں کے راستے کو جانتا ہے: لیکن بدکاروں کا راستہ فنا ہو جائے گا۔","1. کافر کیوں غصے میں آتے ہیں، اور لوگ فضول باتیں کیوں سوچتے ہیں؟ {غصہ: یا، ہنگامہ خیز انداز میں جمع ہونا} {تصور کریں: عبرانی۔ مراقبہ کریں}\n2۔ زمین کے بادشاہ خود کو مقرر کرتے ہیں، اور حکمران مل کر مشورہ کرتے ہیں، خداوند کے خلاف، اور اس کے مسح شدہ کے خلاف، {کہتے ہیں}،\n3۔ آئیے ان کی پٹیاں توڑ دیں، اور ان کی رسیاں ہم سے دور کر دیں۔\n4۔ جو آسمانوں میں بیٹھا ہے وہ ہنسے گا: خداوند انہیں مذاق میں پائے گا۔\n5۔ پھر وہ اپنے غصے میں ان سے بات کرے گا، اور اپنی شدید ناراضگی میں انہیں پریشان کرے گا۔ {ویکس: یا، مصیبت}\n6۔ پھر بھی میں نے اپنے بادشاہ کو اپنے مقدس پہاڑی صیون پر رکھا ہے۔ {سیٹ: عبرانی مسح شدہ} {پر...: عبرانی۔ صیون پر، میری تقدس کی پہاڑی پر}\n7۔ میں حکم کا اعلان کروں گا: خداوند نے مجھ سے فرمایا، تو میرا بیٹا ہے؛ آج میں نے تمہیں جنم دیا ہے۔ {فرمان: یا، ایک فرمان کے لیے}\n8۔ مجھ سے مانگو، اور میں تمہیں کافر کو تمہاری میراث کے بدلے اور زمین کے سب سے بڑے حصے تمہاری ملکیت کے بدلے دوں گا۔\n9۔ تم انہیں لوہے کی چھڑی سے توڑ دو؛ تم انہیں ایسے ٹکڑوں میں توڑ دو گے جیسے کمہار کا برتن ہو۔\n10. اب عقلمند بنو، اے بادشاہو، اے زمین کے ججوں، تعلیم حاصل کرو۔\n11. خوف کے ساتھ خداوند کی خدمت کرو، اور لرزش سے خوشی مناؤ۔\n12۔ بیٹے کو بوسہ دو، ورنہ وہ غصہ ہو جائے گا، اور تم راستے سے مر جاؤ گے، جب اس کا غصہ تھوڑا سا بھڑکے گا۔ مبارک ہیں وہ سب جنہوں نے اس پر بھروسہ کیا۔","1. [داؤد کا زبور، جب وہ اپنے بیٹے ابشالوم سے بھاگ گیا۔] اے خداوند، وہ مجھے اتنا پریشان کیسے کر رہے ہیں! بہت سے لوگ ہیں جو میرے خلاف اٹھتے ہیں۔\n2. بہت سے {ہیں} جو میری روح کے بارے میں کہتے ہیں، {خدا میں اس کے لیے کوئی مدد نہیں}۔ سیلہ۔\n3. لیکن تو، اے خداوند، میرے لیے ڈھال ہے؛ میری جلال، اور میرے سر کو اٹھانے والا۔ {for: or, about}\n4۔ میں نے اپنی آواز میں خداوند سے پکارا، اور اس نے مجھے اپنے مقدس پہاڑ سے سن لیا۔ سیلہ۔\n5۔ میں نے خود کو لٹا دیا اور سو گیا؛ میں جاگ گیا؛ کیونکہ خداوند نے مجھے سہارا دیا۔\n6. میں دس ہزار لوگوں سے نہیں ڈروں گا، جنہوں نے خود کو میرے خلاف کھڑا کر دیا ہے۔\n7. اٹھو، اے خداوند؛ اے میرے خدا، مجھے بچا لے: کیونکہ تو نے میرے تمام دشمنوں کو گال کی ہڈی پر مارا ہے؛ تم نے بے دینوں کے دانت توڑ دیے ہیں۔\n8۔ نجات {ہے} خداوند کی: تیری برکت {ہے} تمہارے لوگوں پر۔ سیلہ۔","1. [نیگینوت کے چیف موسیقار کے نام، داؤد کا زبور۔] جب میں پکاروں، اے میری راستبازی کے خدا، تو نے مجھے بڑھا دیا جب میں مصیبت میں تھا؛ مجھ پر رحم کرو، اور میری دعا سنو۔ {چیف...: یا، نگران} {کیا ہے...: یا، میرے ساتھ مہربان رہو}\n2. اے انسانوں کے بیٹو، کب تک {تم میری شان کو شرمندگی میں بدل دو گے؟' {کتنی دیر تک} تم غرور سے محبت کرو گے، {اور} کرایہ پر لینے کی تلاش کرو؟ سیلہ۔\n3۔ لیکن جان لو کہ خداوند نے اپنے لیے جو دیندار ہے اسے الگ کر دیا ہے: خداوند سنے گا جب میں اسے پکاروں گا۔\n4۔ خوف میں کھڑے رہو، اور گناہ نہ کرو: اپنے بستر پر اپنے دل سے بات چیت کرو، اور خاموش رہو۔ سیلہ۔\n5۔ راستبازی کی قربانیاں پیش کرو، اور خداوند پر بھروسہ کرو۔\n6. {بہت سے} لوگ کہتے ہیں، کون ہمیں {کوئی} نیکی دکھائے گا؟ اے خداوند، اپنے چہرے کی روشنی ہم پر اٹھا دے۔\n7۔ تم نے میرے دل میں خوشی پیدا کی ہے، اس وقت سے زیادہ جب ان کا اناج اور شراب بڑھی۔\n8۔ میں سکون سے لٹاؤں گا اور سو جاؤں گا: کیونکہ تو، خداوند، مجھے صرف امن میں بٹھا دیتا ہے۔","1. [نیہلوت کے چیف موسیقار کے نام، داؤد کا زبور۔] اے خداوند، میری باتوں کو سنو، میری مراقبہ پر غور کرو۔\n2. میرے بادشاہ اور میرے خدا کی پکار کی آواز سنو: کیونکہ میں تیرے لیے دعا کروں گا۔\n3۔ اے خداوند، صبح میری آواز سنو گے؛ صبح میں {اپنی دعا} تم تک پہنچاؤں گا، اور اوپر دیکھوں گا۔\n4۔ کیونکہ تم وہ خدا نہیں ہو جو برائی میں خوشی رکھتا ہو: نہ ہی برائی تیرے ساتھ رہے گی۔\n5۔ بیوقوف تمہاری نظر میں نہیں کھڑے ہوں گے: تم تمام بدکاروں سے نفرت کرتے ہو۔ {میں...: عبرانی تمہاری آنکھوں کے سامنے}\n6. تم ان لوگوں کو تباہ کرو جو لیز بولتے ہیں: خداوند خون آلود اور دھوکہ باز انسان سے نفرت کرے گا۔ {خونریز...: عبرانی خون اور دھوکہ دہی کا آدمی}\n7۔ لیکن جہاں تک میرا تعلق ہے، میں تیری رحمت کی کثرت میں تمہارے گھر میں آؤں گا: اور تمہارے خوف میں تمہارے مقدس مندر کی طرف عبادت کروں گا۔ {تیرا مقدس...: عبرانی۔ تیری پاکیزگی کا مندر}\n8. اے خداوند، میری نیکی میں میری دشمنوں کی وجہ سے رہنمائی فرما؛ میرے سامنے سیدھا راستہ دو۔ {میرا...: عبرانی۔ جو مجھے دیکھتے ہیں}\n9۔ کیونکہ ان کے منہ میں وفاداری نہیں ہوتی؛ ان کا اندرونی حصہ {ہے} بہت شرارت؛ ان کا گلا کھلا قبر ہے؛ وہ اپنی زبان سے خوشامد کرتے ہیں۔ {وفاداری: یا، مضبوطی} {ان کے منہ سے: عبوری۔ اس کا منہ، یعنی ان میں سے کسی کا بھی منہ} {بہت...: عبرانی شرارتیں}\n10. اے خدا، تو انہیں تباہ کر دے؛ انہیں اپنی ہی نصیحتوں کے تابع ہونے دو؛ انہیں ان کی گناہوں کی کثرت میں نکال دو؛ کیونکہ انہوں نے تمہارے خلاف بغاوت کی ہے۔ {تباہ کرو...: یا، انہیں مجرم بنا دو} {by...: یا، ان کے مشوروں سے}\n11۔ لیکن جو لوگ تم پر بھروسہ کرتے ہیں وہ خوش ہوں: ہمیشہ خوشی سے چیخیں، کیونکہ تم ان کا دفاع کرتے ہو: اور جو لوگ تیرے نام سے محبت کرتے ہیں وہ بھی تم میں خوش ہوں۔ {دفاع...: عبرانی چھپ جاؤ، یا ان کی حفاظت کرو}\n12۔ کیونکہ تو، اے خداوند، راستبازوں کو برکت دے؛ فضل کے ساتھ تم اسے ڈھال کی طرح گھیر لو گے۔ {کمپاس: عبرانی۔ تاج}","1. [نیگینوتھ اپون شیمینتھ کے چیف موسیقار کے نام، داؤد کا زبور۔] اے خداوند، اپنے غصے میں مجھے ملامت نہ کر، نہ اپنی شدید ناراضگی پر مجھے سزا دے۔ {چیف...: یا، نگران} {شیمینیتھ: یا، آٹھواں}\n2. اے خداوند، مجھ پر رحم فرما؛ کیونکہ میں کمزور ہوں: اے خداوند، مجھے شفا دے؛ کیونکہ میری ہڈیاں پریشان ہیں۔\n3. میری روح بھی پریشان ہے: لیکن تو، اے خداوند، کتنی دیر تک؟\n4. اے خداوند، واپس آؤ، میری جان کو نجات دے: اے تیری رحمت کے لیے مجھے بچا۔\n5۔ کیونکہ موت میں تمہاری کوئی یاد نہیں: قبر میں کون تمہارا شکر ادا کرے گا؟\n6۔ میں اپنی کراہت سے تھکا ہوا ہوں؛ ساری رات میں تیرنے کے لیے اپنا بستر بناتا ہوں؛ میں اپنے صوفے کو اپنے آنسوؤں سے پانی دیتا ہوں۔ {سب...: یا، ہر رات}\n7. میری آنکھ غم کی وجہ سے ختم ہو جاتی ہے؛ یہ میرے تمام دشمنوں کی وجہ سے پرانا ہو گیا ہے۔\n8۔ اے تمام بدکاروں کو مجھ سے دور ہو جاؤ؛ کیونکہ خداوند نے میری رونے کی آواز سنی ہے۔\n9۔ خداوند نے میری دعا سنی ہے؛ خداوند میری دعا قبول کرے گا۔\n10۔ میرے تمام دشمن شرمندہ اور ناراض ہوں: انہیں اچانک واپس آنے دو اور شرمندہ ہو جاؤ۔","1۔ [داؤد کا شگائیون، جو اس نے خداوند کے لیے گایا، کش دی بنیمی کے الفاظ کے بارے میں۔] اے خداوند میرے خدا، میں تجھ پر بھروسہ کرتا ہوں: مجھے ان سب سے بچا جو مجھے ستاتے ہیں، اور مجھے بچا: {الفاظ: یا کاروبار}\n2. کہیں وہ میری روح کو شیر کی طرح پھاڑ نہ دے، اسے ٹکڑے ٹکڑے کر دے، اور کوئی نہ بچے۔ {کوئی نہیں...: عبرانی۔ نجات دہندہ نہیں}\n3. اے خداوند میرے خدا، اگر میں نے یہ کیا ہے؛ اگر میرے ہاتھوں میں کوئی گناہ ہو؛\n4۔ اگر میں نے اس کے ساتھ برائی کا صلہ دیا ہے جو میرے ساتھ امن میں تھا؛ (ہاں، میں نے اسے یہ بتا دیا ہے کہ بغیر وجہ کے میرا دشمن ہے :)\n5. دشمن میری روح کو ستائے، اور اسے لے لے؛ ہاں، وہ میری زندگی زمین پر قدم رکھے، اور میری عزت خاک میں ڈال دے۔ سیلہ۔\n6۔ اے خداوند، اپنے غصے میں اٹھ جا، میرے دشمنوں کے غصے کی وجہ سے خود کو اٹھا لے: اور میرے لیے اس فیصلے کو جگا جو تو نے حکم دیا ہے۔\n7۔ اسی طرح عوام کی جماعت آپ کے گرد گھومے گی: لہٰذا ان کے لیے آپ بلند مقام پر واپس آ جائیں۔\n8. خداوند لوگوں کا فیصلہ کرے گا: اے خداوند، میری راستبازی اور میری دیانتداری کے مطابق فیصلہ فرما۔\n9. اے بدکاروں کی برائی ختم ہو جائے؛ لیکن راستوں کو قائم کرو: کیونکہ نیک خدا دلوں اور لگاموں کو آزماتا ہے۔\n10. میرا دفاع خدا کا ہے، جو دل کے راستوں کو نجات دیتا ہے۔ {میرا...: عبرانی۔ میرا بکلر خدا پر ہے}\n11۔ خدا نیک لوگوں کا فیصلہ کرتا ہے، اور خدا ہر روز {بدکاروں سے} ناراض ہوتا ہے۔ {جج...: یا، ایک نیک جج ہے}\n12۔ اگر وہ نہ مڑے، تو وہ اپنی تلوار کاٹ دے گا؛ اس نے اپنا کمان موڑا ہے، اور اسے تیار کر لیا ہے۔\n13۔ اس نے اس کے لیے موت کے آلات بھی تیار کیے ہیں؛ وہ اپنے تیر ظلم کرنے والوں کے خلاف چلاتا ہے۔\n14۔ دیکھو، وہ بدکاری کرتا ہے، شرارت کرتا ہے، اور جھوٹ پھیلاتا ہے۔\n15۔ اس نے ایک گڑھا بنایا، اسے کھودا، اور وہ کھائی میں گر گیا جو اس نے بنائی تھی۔ {اس نے گڑھا بنایا: ہیب۔ اس نے گڑھا کھودا ہے}\n16۔ اس کی شرارتیں اس کے اپنے سر پر لوٹ آئیں گی، اور اس کا پرتشدد عمل اس کے اپنے سر پر نازل ہوگا۔\n17. میں خداوند کی راستبازی کے مطابق اس کی تعریف کروں گا: اور خداوند اعلیٰ کے نام کی حمد گاؤں گا۔","1. [گٹیتھ پر چیف موسیقار، داؤد کا زبور کے نام۔] اے خداوند، زمین بھر میں تیرا نام کتنا خوبصورت ہے! جس نے اپنی شان کو آسمانوں سے بلند کیا ہے۔\n2۔ بچوں اور دودھ پلانے والے بچوں کے منہ سے تم نے اپنے دشمنوں کی وجہ سے طاقت مقرر کی ہے، تاکہ تم دشمن اور انتقام لینے والے کو روک سکو۔ {مقرر: عبرانی۔ قائم شدہ}\n3۔ جب میں تیرے آسمانوں کو دیکھتا ہوں، تیری انگلیوں، چاند اور ستاروں کا کام، جنہیں تم نے مقرر کیا ہے؛\n4۔ انسان کیا ہے کہ تم اس کا خیال رکھتے ہو؟ اور انسان کے بیٹے، کہ تم اس سے ملنے آتے ہو؟\n5۔ کیونکہ تم نے اسے فرشتوں سے تھوڑا نیچا کر دیا ہے، اور اسے جلال اور عزت سے تاج پہنایا ہے۔\n6۔ تم اسے اپنے ہاتھوں کے کاموں پر حکمرانی کے لیے پاگل کرتے ہو؛ تو نے سب کچھ اس کے قدموں تلے رکھ دیا ہے:\n7. تمام بھیڑیں اور بیل، ہاں، اور میدان کے جانور؛ {سب...: عبرانی۔ ریوڑ اور بیل سب ہیں}\n8۔ ہوا کا پرندہ، اور سمندر کی مچھلی، {اور جو بھی} سمندروں کے راستوں سے گزرتا ہے۔\n9. اے خداوند ہمارے رب، تیری نام زمین پر کتنی خوبصورت ہے!","1. [مثلبن کے چیف موسیقار کے نام، داؤد کا زبور۔] اے خداوند، میں پورے دل سے {تیری} کی تعریف کروں گا؛ میں تمہارے تمام شاندار کام دکھاؤں گا۔\n2۔ میں تم پر خوش ہوں گا اور خوش ہوں گا: میں تیرے نام کی تعریف کروں گا، اے اعلیٰ ترین تو۔\n3۔ جب میرے دشمن پیچھے ہٹیں گے، تو وہ تیرے حضور میں گر کر ہلاک ہو جائیں گے۔\n4۔ کیونکہ تم نے میرے حق اور مقصد کی حفاظت کی ہے؛ تم تخت پر صحیح فیصلہ کرتے ہوئے بیٹھے ہو۔ {برقرار رکھا گیا...: عبرانی۔ میں نے اپنا فیصلہ کیا} {صحیح فیصلہ کرتے ہوئے: عبرانی۔ راستبازی میں فیصلہ کرنا}\n5۔ تم نے کافروں کو ملامت کی، بدکاروں کو تباہ کیا، ان کا نام ہمیشہ کے لیے رکھا۔\n6۔ اے دشمن، تباہی ہمیشہ کے لیے ختم ہو گئی ہے: اور تو نے شہر تباہ کر دیے ہیں؛ ان کی یادگار بھی ان کے ساتھ ختم ہو جاتی ہے۔ {اے تم...: یا، دشمن کی تباہی ہمیشہ کے لیے ختم ہو جاتی ہے: اور ان کے شہر تم نے تباہ کر دیے وغیرہ}\n7۔ لیکن خداوند ہمیشہ قائم رہے گا: اس نے اپنے تخت کو فیصلے کے لیے تیار کیا ہے۔\n8۔ اور وہ دنیا کو راستبازی میں پرکھے گا، اور لوگوں کو انصاف کے ساتھ انصاف کرے گا۔\n9. خداوند مظلوموں کے لیے پناہ گاہ، مصیبت کے وقت پناہ گاہ بھی ہوگا۔ {ایک پناہ گاہ: عبرانی۔ ایک اونچی جگہ}\n10۔ اور جو آپ کا نام جانتے ہیں وہ آپ پر بھروسہ کریں گے: کیونکہ تو، اے خداوند، نے ان لوگوں کو نہیں چھوڑا جو آپ کی تلاش میں ہیں۔\n11. صیہون میں رہنے والے خداوند کی حمد و ثنا گاؤ: لوگوں میں اس کے اعمال کا اعلان کرو۔\n12۔ جب وہ خون کے لیے تفتیش کرتا ہے، تو اسے یاد آتا ہے: وہ عاجزوں کی پکار کو نہیں بھولتا۔ {عاجز: یا، مصیبت}\n13. اے خداوند، مجھ پر رحم فرما؛ میری تکلیف پر غور کرو {جو میں برداشت کرتا ہوں} ان لوگوں سے جو مجھ سے نفرت کرتے ہیں، تو جو مجھے موت کے دروازے سے اٹھاتا ہے:\n14. تاکہ میں صہیون کی بیٹی کے دروازوں پر تیری ساری حمد پیش کروں: میں تیری نجات پر خوش ہوں گا۔\n15۔ کافر اس گڑھے میں ڈوب جاتے ہیں جو انہوں نے بنایا ہے: جال میں جو انہوں نے چھپایا ہے اس میں ان کا اپنا پاؤں ہے۔\n16. خداوند کو {وہ} کے ذریعے جانا جاتا ہے {جو وہ انجام دیتا ہے}: بدکار اپنے ہاتھوں کے کام میں پھنس جاتا ہے۔ ہیگایون۔ سیلہ۔ {ہگیون: یعنی، مراقبہ}\n17۔ بدکاروں کو جہنم میں بدل دیا جائے گا، {اور} وہ تمام قومیں جو خدا کو بھول جائیں گی۔\n18۔ کیونکہ محتاجوں کو ہمیشہ نہیں بھلایا جائے گا: غریبوں کی امید ہمیشہ کے لیے ختم نہیں ہوگی۔\n19. اٹھو، اے خداوند؛ انسان غالب نہ آئے: کافروں کو تیری نظر میں پرکھا جائے۔\n20۔ اے خداوند، انہیں خوفزدہ کر دے: تاکہ قومیں خود کو {صرف} انسان سمجھ سکیں۔ سیلہ۔","1. اے خداوند، تو دور کیوں کھڑے ہو؟ مشکل وقت میں خود کو کیوں چھپاتے ہو؟\n2۔ بدکار اپنے غرور میں غریبوں کو ستاتا ہے: انہیں ان چالوں میں پھنسنے دو جو انہوں نے تصور کی ہیں۔ {بدکار...: عبرانی۔ بدکاروں کے غرور میں وہ ظلم کرتا ہے}\n3۔ کیونکہ بدکار اپنے دل کی خواہش پر فخر کرتا ہے، اور لالچی لوگوں کو برکت دیتا ہے، {جنہیں خداوند نفرت کرتا ہے}۔ {دل: عبوری۔ روح کی} {برکت دیتا ہے...: یا، لالچی خود برکت دیتا ہے، وہ خداوند سے نفرت کرتا ہے}\n4. بدکار اپنے چہرے کے غرور سے خدا کی تلاش نہیں کرے گا: خدا {ہے} اپنے تمام خیالات میں نہیں۔ {خدا ہے...: یا، اس کے تمام خیالات ہیں، کوئی خدا نہیں ہے}\n5. اس کے طریقے ہمیشہ سخت ہوتے ہیں؛ تمہارے فیصلے اس کی نظر سے بہت اوپر ہیں: اپنے تمام دشمنوں کے لیے، وہ ان پر فخر کرتا ہے۔\n6۔ اس نے اپنے دل میں کہا ہے، میں متاثر نہیں ہوں گا: کیونکہ {میں} کبھی مصیبت میں نہیں ہوں گا۔ {کبھی نہیں: عبرانی۔ نسل در نسل تک}\n7۔ اس کا منہ لعنت، فریب اور دھوکہ سے بھرا ہوا ہے: اس کی زبان کے نیچے شرارت اور غرور ہے۔ {دھوکہ: عبوری۔ دھوکہ} {vanity: or, iniquity}\n8۔ وہ دیہاتوں کے چھپے ہوئے مقامات پر بیٹھا رہتا ہے: خفیہ جگہوں پر وہ معصوموں کو قتل کرتا ہے: اس کی نظریں واضح طور پر غریبوں پر مرکوز ہیں۔ {آر...: عبرانی خود کو چھپا لیتے ہیں}\n9۔ وہ اپنے غار میں شیر کی طرح چپکے سے انتظار کرتا ہے: وہ غریبوں کو پکڑنے کے لیے انتظار کرتا ہے: وہ غریبوں کو پکڑتا ہے، جب وہ اسے اپنے جال میں کھینچتا ہے۔ {خفیہ طور پر: ہیب۔ خفیہ جگہوں میں}\n10۔ وہ جھک جاتا ہے، {اور} خود کو عاجز کرتا ہے تاکہ غریب اس کے طاقتور لوگوں کے ہاتھوں گر جائیں۔ {وہ...: عبرانی۔ وہ خود کو توڑ دیتا ہے} {ذریعہ...: یا، اپنے مضبوط حصوں میں}\n11۔ اس نے اپنے دل میں کہا ہے، خدا بھول گیا ہے: وہ اپنا چہرہ چھپاتا ہے؛ وہ کبھی اسے نہیں دیکھ پائے گا۔\n12. اٹھو، اے خداوند؛ اے خدا، اپنا ہاتھ اٹھاؤ: عاجزوں کو نہ بھولو۔ {عاجز: یا، مصیبت}\n13. بدکار خدا کو کیوں نفرت کرتا ہے؟ اس نے اپنے دل میں کہا ہے، تمہیں اس کی ضرورت نہیں ہوگی۔\n14. تو نے اسے دیکھ لیا ہے؛ کیونکہ تم شرارت اور بغض دیکھتے ہو، تاکہ تم اپنے ہاتھ سے بدلہ دو: غریب تمہارے لیے خود کو وقف کرتا ہے؛ تم یتیم کے مددگار ہو۔ {کمیٹ: ہیب۔ چھوڑ دو}\n15. بدکار اور برے انسان کا بازو توڑ دو: اس کی برائی تلاش کرو {جب تک کہ تمہیں کوئی نہ ملے۔\n16. خداوند ہمیشہ کے لیے بادشاہ ہے: کافر اس کی سرزمین سے ختم ہو گئے۔\n17۔ اے خداوند، تو نے عاجزوں کی خواہش سنی ہے: تو ان کے دل کو تیار کرو گے، تو اپنے کان کو سناؤ گے: {تیار کرو: یا، قائم کرو}\n18۔ یتیم اور مظلوموں کا فیصلہ کرنا، تاکہ زمین کا انسان مزید ظلم نہ کرے۔ {ظلم: یا، خوفزدہ کرو}","1. [چیف موسیقار، {داؤد کا زبور} کے نام۔] خداوند پر میں اپنی بھروسہ رکھتا ہوں: تم میری روح سے کیسے کہتے ہو، جیسے پرندے اپنے پہاڑ کی طرف بھاگ جاؤ؟\n2۔ دیکھو، بدکار لوگ اپنا کمان جھکاتے ہیں، وہ اپنا تیر ڈور پر تیار کرتے ہیں تاکہ وہ سیدھے دل والوں پر آسانی سے تیر چلا سکیں۔ {آزادانہ طور پر: عبرانی۔ اندھیرے میں}\n3۔ اگر بنیادیں تباہ ہو جائیں تو نیک لوگ کیا کر سکتے ہیں؟\n4. خداوند {ہے} اپنے مقدس مندر میں، خداوند کا تخت {ہے} آسمان میں: اس کی آنکھیں دیکھتی ہیں، اس کی پلکیں کوشش کرتی ہیں، انسانوں کے بچے ہیں۔\n5۔ خداوند راستبازوں کو آزماتا ہے: لیکن بدکاروں اور جو ظلم سے محبت کرتا ہے اس کی روح سے نفرت کرتی ہے۔\n6۔ بدکاروں پر وہ جال، آگ اور گندھک اور ایک خوفناک طوفان برسائے گا: {یہ} ان کے پیالے کا حصہ ہوگا۔ {ایک خوفناک...: یا، ایک جلتا ہوا طوفان}\n7۔ کیونکہ راستباز خداوند راستبازی سے محبت کرتا ہے؛ اس کا چہرہ سیدھے کھڑے ہونے کو دیکھتا ہے۔","1. [شیمینتھ پر چیف موسیقار کے نام، داؤد کا زبور۔] مدد کرو، خداوند؛ کیونکہ دیندار انسان رک جاتا ہے؛ کیونکہ مومنین انسانوں کے بچوں میں ناکام ہو جاتے ہیں۔ {پر...: یا، آٹھویں تاریخ پر} {مدد: یا، محفوظ کریں}\n2. وہ ہر ایک اپنے پڑوسی کے ساتھ غرور کی بات کرتے ہیں: {خوشامد کرنے والے} ہونٹوں کے ساتھ {اور} دوہری دل کے ساتھ بات کرتے ہیں۔ {ایک دوہر...: عبرانی۔ ایک دل اور ایک دل}\n3. خداوند تمام خوشامد کرنے والے ہونٹوں کو کاٹ دے گا، {اور} زبان جو مغرور باتیں کرتی ہے: {غرور: عبرانی۔ زبردست}\n4۔ جنہوں نے کہا ہے، اپنی زبان سے ہم غالب آئیں گے؛ ہمارے ہونٹ {ہیں} ہمارے اپنے: ہم پر کون {ہے} لارڈ؟ {آر...: عبرانی ہمارے ساتھ ہیں}\n5۔ غریبوں پر ظلم کے لیے، محتاجوں کی آہ بھرنے کے لیے، اب میں اٹھوں گا، خداوند فرماتا ہے؛ میں {اسے} کو محفوظ جگہ پر رکھوں گا {اس سے جو اس پر پھونک مارتا ہے}۔ {پفتھ...: یا، اسے پھنسا دیتا}\n6۔ خداوند کے الفاظ {ہیں} پاک الفاظ: {ویسے} چاندی جو زمین کی بھٹی میں آزمائی گئی، سات بار پاک ہوئی۔\n7۔ اے خداوند، تو انہیں ہمیشہ کے لیے اس نسل سے محفوظ رکھنا۔ {ان سے: عبوری۔ وہ، وغیرہ: یعنی ہر ایک، وغیرہ}\n8۔ بدکار ہر طرف چلتے ہیں، جب سب سے بدترین لوگ بلند کیے جاتے ہیں۔ {مرد: عبرانی۔ انسانوں کے بیٹوں کی}","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے خداوند، تم مجھے کتنی دیر تک بھول جاؤ گے؟ ہمیشہ کے لیے؟ تم کب تک اپنا چہرہ مجھ سے چھپاؤ گے؟ {چیف...: یا، نگران}\n2. میں کب تک اپنی روح میں مشورہ لوں گا، روزانہ دل میں غم رکھتے ہوئے؟ میرا دشمن کب تک مجھ پر بلند رہے گا؟\n3. غور کرو {اور} میری بات سنو، اے خداوند میرے خدا: میری آنکھیں روشن فرما، ورنہ میں موت کی نیند میں سو جاؤں گا؛\n4۔ کہیں میرا دشمن نہ کہے کہ میں نے اس پر غالب آ گیا ہوں؛ {اور} جو لوگ مجھے پریشان کرتے ہیں وہ خوش ہوتے ہیں جب میں متاثر ہوتا ہوں۔\n5۔ لیکن میں نے تیری رحمت پر بھروسہ کیا ہے؛ میرا دل تیری نجات پر خوش ہوگا۔\n6۔ میں خداوند کے لیے گاؤں گا، کیونکہ اس نے میرے ساتھ فیاضی سے سلوک کیا ہے۔","1. [چیف موسیقار، {داؤد کا زبور} کے نام۔] بیوقوف نے اپنے دل میں کہا ہے، {کوئی خدا نہیں ہے}۔ وہ کرپٹ ہیں، انہوں نے گھناؤنے کام کیے ہیں، کوئی بھی اچھا کام نہیں کرتا۔\n2. خداوند نے آسمان سے انسانوں کے بچوں کو دیکھا، تاکہ دیکھے کہ کیا کوئی ہے جو سمجھتا ہے، {اور} خدا کی تلاش کرتا ہے۔\n3. وہ سب چلے جاتے ہیں، وہ سب مل کر گندے ہو جاتے ہیں: کوئی بھی اچھا کام نہیں کرتا، نہیں، کوئی نہیں۔ {گندی: ہیب۔ بدبو}\n4. کیا تمام بدکاری کے مزدوروں کو علم نہیں؟ جو میرے لوگوں کو کھاتے ہیں جیسے وہ روٹی کھاتے ہیں، اور خداوند کو نہیں پکارتے۔\n5۔ وہ بہت خوفزدہ تھے: کیونکہ خدا {ہے} راستبازوں کی نسل میں۔ {تھے...: عبرانی وہ خوف سے ڈرتے تھے}\n6۔ تم نے غریبوں کی نصیحت کو شرمندہ کیا ہے، کیونکہ خداوند اس کی پناہ گاہ ہے۔\n7. اے کاش اسرائیل کی نجات صیون سے نکل آتی! جب خداوند اپنی قوم کی قید واپس لے آئے گا، یعقوب خوش ہوگا، {اور} اسرائیل خوش ہوگا۔ {اوہ...: عبرانی۔ کون دے گا}","1. [داؤد کا زبور۔] اے خداوند، تیرے خیمے میں کون رہے گا؟ کون تمہارے مقدس پہاڑ میں رہے گا؟ {پابندی کریں: عبرانی۔ سفر\n2۔ جو سیدھا چلتا ہے، راستبازی کرتا ہے، اور اپنے دل میں سچ بولتا ہے۔\n3۔ {جو} اپنی زبان سے غیبت نہیں کرتا، نہ اپنے پڑوسی کے ساتھ برا سلوک کرتا ہے، اور نہ ہی اپنے پڑوسی پر ملامت کرتا ہے۔ {taketh...: or, receiveth, or, endureth}\n4۔ جس کی نظر میں ایک گھٹیا شخص بدنام ہو؛ لیکن وہ ان لوگوں کی عزت کرتا ہے جو خداوند سے ڈرتے ہیں۔ {جو کہ} قسم کھاتا ہے کہ {اپنی} تکلیف پہنچائے گا، اور نہیں بدلتا۔\n5۔ {جو} اپنا پیسہ سود کے لیے نہیں رکھتا، اور نہ ہی معصوموں کے خلاف انعام لیتا ہے۔ جو یہ سب کرے گا وہ کبھی نہیں ہلائے گا۔","1. [داؤد کا میختام۔] اے خدا، مجھے محفوظ رکھ: کیونکہ میں نے اپنی بھروسہ تجھ پر رکھی ہے۔ {میختم: یا، ایک سنہری زبور}\n2. {اے میری جان}، تو نے خداوند سے کہا ہے، تو {میرا رب} ہے: میری نیکی {تجھ تک نہیں پھیلتی}؛\n3. {لیکن} ان مقدسین کے لیے جو {ہیں} زمین پر، اور {عظیموں کو} کے لیے، جن میں {ہے} میری ساری خوشی۔\n4۔ ان کے غم بڑھ جائیں گے {جو کسی اور {خدا} کے پیچھے جلدی کریں گے: ان کے خون کی نذرانہ میں پیش نہیں کروں گا، نہ ان کے نام اپنے ہونٹوں پر لے جاؤں گا۔ {جلدی کرو...: یا، کسی اور کو تحفے دو}\n5۔ خداوند میری وراثت اور میرے پیالے کا حصہ ہے: تو میری قسمت کا خیال رکھتا ہے۔ {میرا...: عبرانی۔ میری طرف سے}\n6. لکیریں خوشگوار {جگہوں} میں میرے لیے گرتی ہیں؛ ہاں، میری اچھی وراثت ہے۔\n7۔ میں خداوند کو برکت دوں گا، جس نے مجھے مشورہ دیا ہے: میری لگام مجھے رات کے موسموں میں بھی تعلیم دیتی ہے۔\n8. میں نے خداوند کو ہمیشہ اپنے سامنے رکھا ہے: کیونکہ {وہ} میرے دائیں ہاتھ پر ہے، میں حرکت نہیں کروں گا۔\n9۔ اسی لیے میرا دل خوش ہے، اور میرا جلال خوش ہے: میرا جسم بھی امید میں آرام کرے گا۔ {باقی...: عبرانی۔ اعتماد کے ساتھ ڈول}\n10۔ کیونکہ تم میری جان کو جہنم میں نہیں چھوڑو گے؛ نہ ہی تم اپنے مقدس وجود کو فساد دیکھنے دو گے۔\n11۔ تو مجھے زندگی کا راستہ دکھاؤ گے: تیری موجودگی میں خوشی کی بھرپوریت ہے؛ تیرے دائیں ہاتھ ہمیشہ کے لیے خوشیاں ہیں۔","1. [داؤد کی دعا۔] اے خداوند، صحیح سنو، میری فریاد سن، میری دعا کو سن، {جو جعلی ہونٹوں سے نکلتی ہے}۔ {دائیں: عبرانی۔ انصاف} {نہیں...: عبرانی۔ دھوکہ دہی کے ہونٹوں کے بغیر}\n2۔ میرا حکم تیرے حضور سے نکلے؛ اپنی آنکھیں ان چیزوں کو دیکھے جو برابر ہیں۔\n3۔ تو نے میرا دل ثابت کر دیا؛ تم رات کو مجھ سے ملنے آئے ہو؛ تم نے مجھے آزمایا ہے، {اور} کچھ نہیں پاؤ گے؛ میرا ارادہ ہے {تاکہ} میرا منہ زیادتی نہ کرے۔\n4۔ انسانوں کے کاموں کے بارے میں، تیری زبان کے کلام سے میں نے {خود کو تباہ کرنے والے کے راستوں سے روکا ہے}۔\n5. میری راہ کو اپنے راستے میں روکو، {تاکہ} میرے قدم نہ پھسلیں۔ {پھسل...: عبرانی حرکت نہ کرو}\n6۔ میں نے تجھ سے پکارا ہے، کیونکہ تم مجھے سنو گے، اے خدا، اپنا کان میری طرف جھکاؤ، اور میری بات سنو۔\n7. اپنی حیرت انگیز محبت دکھاؤ، اے وہ جو اپنے دائیں ہاتھ سے ان لوگوں کو بچاتی ہے جنہوں نے تم پر بھروسہ کیا ہے، ان لوگوں سے جو ان کے خلاف اٹھ کھڑے ہوتے ہیں۔ {تیرے...: یا وہ لوگ جو تم پر بھروسہ کرتے ہیں، ان لوگوں سے جو تمہارے دائیں ہاتھ کے خلاف اٹھتے ہیں}\n8. مجھے آنکھ کا تارا سمجھ کر رکھ، اپنے پروں کے سائے میں چھپا لے،\n9۔ ان بدکاروں سے جو مجھے ظلم کرتے ہیں، {میرے مہلک دشمنوں سے} سے، {جو} مجھے گھیرے میں رکھتے ہیں۔ {دباؤ: عبرانی۔ فضلہ} {میرا...: عبرانی۔ میرے دشمن روح کے خلاف}\n10۔ وہ اپنی چربی میں بند ہیں: اپنے منہ سے فخر سے بات کرتے ہیں۔\n11۔ اب وہ ہمارے قدموں میں ہمیں گھیر چکے ہیں: انہوں نے زمین کی طرف آنکھیں جھکا دی ہیں؛\n12. جیسے کوئی شیر {جو} اپنے شکار کا لالچی ہے، اور جیسے کوئی نوجوان شیر خفیہ جگہوں پر چھپا ہو۔ {جیسے...: عبوری۔ اس کی مشابہت (یعنی ہر ایک کی) ایک شیر کی طرح ہے جو دیوانہ بننے کی خواہش رکھتا ہے} {چھپا ہوا: عبرانی۔ بیٹھنا}\n13. اے خداوند، اٹھو، اسے مایوس کر، اسے نیچے گرا دے: میری جان کو بدکاروں سے بچا، {جو تیری تلوار ہے}: {مایوس کر...: عبرانی اس کے چہرے کو روکیں} {جو ہے: یا، بائی}\n14. ان لوگوں سے {جو} تیرا ہاتھ ہیں، اے خداوند، دنیا کے لوگوں سے، {جن کی زندگی میں ان کا حصہ ہے}، اور جن کا پیٹ تو اپنے خزانے سے بھر دیتا ہے: وہ بچوں سے بھرے ہوئے ہیں، اور باقی مال اپنے بچوں کے لیے چھوڑ دیتے ہیں۔ {جو ہیں: یا، بائی} {وہ...: یا، ان کے بچے بھرے ہوئے ہیں}\n15۔ جہاں تک میرا تعلق ہے، میں تیرا چہرہ راستبازی میں دیکھوں گا: جب میں جاگوں گا تو تیری شکل سے مطمئن ہوں گا۔","1. [داؤد کے سردار موسیقار، {زبور} کے نام، خداوند کا بندہ، جس نے اس دن خداوند سے اس گیت کے الفاظ بیان کیے جب خداوند نے اسے اپنے تمام دشمنوں کے ہاتھوں اور ساؤل کے ہاتھوں سے نجات دلائ: اور اس نے کہا،] اے خداوند، میں تم سے محبت کروں گا، اے خداوند، میری طاقت۔\n2۔ خداوند میرا چٹان، میرا قلعہ اور میرا نجات دہندہ ہے؛ میرا خدا، میری طاقت، جس پر میں بھروسہ کروں گا؛ میرا بکلر، اور میری نجات کا سینگ، {اور} میرا اونچا مینار۔ {میری طاقت: عبرانی۔ میرا پتھر}\n3۔ میں خداوند کو پکاروں گا، {جو تعریف کے لائق ہے}: اسی طرح میں اپنے دشمنوں سے بچ جاؤں گا۔\n4۔ موت کے غم نے مجھے گھیر لیا، اور بے دین لوگوں کے سیلاب نے مجھے خوفزدہ کر دیا۔ {بے دین لوگ: عبرانی۔ بیلیال}\n5. جہنم کے غم میرے گرد تھے: موت کے جال نے مجھے روکا۔ {غم: یا، رسیا}\n6۔ اپنی تکلیف میں میں نے خداوند کو پکارا اور اپنے خدا سے پکارا: اس نے میری آواز اپنے مندر سے سنی، اور میری پکار اس کے سامنے آئی، {حتیٰ کہ} اس کے کانوں تک۔\n7۔ پھر زمین لرز اٹھی اور لرز گئی؛ پہاڑیوں کی بنیادیں بھی ہلیں اور ہل گئیں، کیونکہ وہ غصے میں تھا۔\n8۔ اس کی نتھنوں سے دھواں اٹھا، اور منہ سے آگ نکل گئی: اس سے کوئلے جل اٹھے۔ {اس کی ناک سے: عبرانی۔ اس کے ذریعے، وغیرہ}\n9۔ اس نے بھی آسمانوں کو جھکایا اور نیچے آیا: اور اس کے قدموں تلے تاریکی چھا گئی۔\n10۔ اور وہ ایک فرشتہ پر سوار ہوا، اور واقعی اڑا: ہاں، وہ ہوا کے پروں پر اڑا۔\n11۔ اس نے تاریکی کو اپنا خفیہ مقام بنایا؛ اس کے ارد گرد اس کا پویلین گہرے پانی اور آسمان کے گھنے بادل تھے۔\n12۔ اس روشنی {جو اس کے سامنے تھی} پر اس کے گھنے بادل گزر گئے، اولے {پتھر} اور آگ کے انگارے۔\n13۔ خداوند نے بھی آسمانوں میں گرج ماری، اور اعلیٰ نے اپنی آواز دی؛ اولے {پتھر} اور آگ کے کوئلے۔\n14۔ ہاں، اس نے اپنے تیر بھیجے اور انہیں بکھیر دیا؛ اور اس نے بجلی پھینکی، اور انہیں بے چین کر دیا۔\n15۔ پھر پانیوں کے راستے نظر آئے، اور دنیا کی بنیادیں دریافت ہوئیں، اے خداوند، تیری ناک کی سانس کے پھٹنے پر۔\n16۔ اس نے اوپر سے بھیجا، اس نے مجھے لیا، اس نے مجھے کئی پانیوں سے نکالا۔ {بہت سے: یا، زبردست}\n17۔ اس نے مجھے میرے سخت دشمن سے بچایا، اور ان سے بھی جو مجھ سے نفرت کرتے تھے: کیونکہ وہ میرے لیے بہت طاقتور تھے۔\n18۔ انہوں نے میرے مصیبت کے دن مجھے روکا: لیکن خداوند میرا قیام تھا۔\n19۔ اس نے مجھے بھی ایک بڑے مقام پر لے آیا؛ اس نے مجھے اس لیے پہنچایا، کیونکہ وہ مجھ میں خوش تھا۔\n20۔ خداوند نے مجھے میری راستبازی کے مطابق اجر دیا؛ میرے ہاتھوں کی پاکیزگی کے مطابق اس نے مجھے انعام دیا۔\n21۔ کیونکہ میں نے خداوند کے طریقے قائم رکھے ہیں، اور اپنے خدا سے برے طریقے سے نہیں بھٹکا۔\n22۔ کیونکہ اس کے تمام فیصلے میرے سامنے تھے، اور میں نے اس کے قوانین مجھ سے نہیں چھپائے۔\n23۔ میں اس کے سامنے بھی سیدھا تھا، اور اپنی غلطیوں سے خود کو بچاتا تھا۔ {پہلے: عبرانی with}\n24۔ لہٰذا خداوند نے مجھے میری راستبازی کے مطابق، اپنے ہاتھوں کی پاکیزگی کے مطابق اس کی نظر میں بدلہ دیا ہے۔ {میں...: عبرانی اس کی آنکھوں کے سامنے}\n25. رحم کرنے والے کے ساتھ تم اپنی رحمت دکھاؤ گے؛ ایک راست باز آدمی کے ساتھ تم خود کو سیدھا دکھاؤ گے؛\n26۔ پاکیزگی کے ساتھ تم خود کو پاکیزہ ظاہر کرو گے؛ اور شرارتی کے ساتھ تم خود کو ناراض دکھاؤ گے۔ {ادھر ادھر دکھاؤ: یا، کشتی کرو}\n27. کیونکہ تم مظلوم لوگوں کو بچاؤ گے؛ لیکن ولٹ اعلیٰ نظروں کو نیچے لے آتا ہے۔\n28۔ کیونکہ تو میری شمع روشن کرو گے: خداوند میرا خدا میری تاریکی کو روشن کرے گا۔ {موم بتی: یا، چراغ}\n29۔ کیونکہ تیرے ذریعے میں نے ایک دستے کو پار کیا ہے؛ اور خدا کی قسم، میں نے دیوار کے اوپر سے چھلانگ لگا دی۔ {دوڑو...: یا، ٹوٹا ہوا}\n30۔ {جہاں تک} خدا کا تعلق ہے، اس کا راستہ {کامل ہے}: خداوند کا کلام آزمایا جاتا ہے: وہ {ہے} ان سب کے لیے جو اس پر بھروسہ کرتے ہیں۔ {کوشش کی: یا، نفیس}\n31. کیونکہ خدا خدا کو بچائے گا کون ہے؟ یا کون ہے جو ہمارے خدا کو بچانے والا پتھر ہے؟\n32۔ {یہ} خدا ہے جو مجھے طاقت سے باندھتا ہے، اور میرا راستہ کامل بناتا ہے۔\n33۔ وہ میرے پاؤں ہنڈوں کے پاؤں کی طرح بناتا ہے، اور مجھے میرے اونچے مقامات پر بٹھاتا ہے۔\n34۔ وہ میرے ہاتھوں کو جنگ سکھاتا ہے، تاکہ لوہے کا کمان میرے بازوؤں سے ٹوٹ جائے۔\n35۔ تو نے مجھے اپنی نجات کی ڈھال بھی دی ہے: اور تمہارا دایاں ہاتھ مجھے تھامے ہوئے ہے، اور تمہاری نرمی نے مجھے عظیم بنایا ہے۔ {تمہاری نرمی...: یا، اپنی عاجزی سے تم نے مجھے بڑھا دیا}\n36۔ تو نے میرے قدم میرے نیچے بڑھائے تاکہ میرے قدم نہ پھسلے۔ {میرے پاؤں: عبرانی۔ میرے ٹخنے}\n37۔ میں نے اپنے دشمنوں کا پیچھا کیا اور انہیں پکڑ لیا: نہ میں نے دوبارہ پلٹا جب تک وہ ختم نہ ہو گئے۔\n38۔ میں نے انہیں زخمی کیا کہ وہ اٹھ نہ سکے: وہ میرے قدموں تلے گر گئے۔\n39۔ کیونکہ تم نے مجھے جنگ کے لیے طاقت دی ہے: تو نے میرے نیچے ان لوگوں کو زیر کیا جو میرے خلاف اٹھے۔ {دبی ہوئی: عبرانی۔ جھکنے پر مجبور کیا}\n40۔ تو نے مجھے میرے دشمنوں کی گردن بھی دی ہے؛ تاکہ میں ان لوگوں کو تباہ کر دوں جو مجھ سے نفرت کرتے ہیں۔\n41۔ انہوں نے پکارا، لیکن {کوئی نہیں تھا} جو {انہیں} کو بچانے والا {حتی} خداوند کے پاس بھی، لیکن اس نے ان کا جواب نہ دیا۔\n42۔ پھر میں نے انہیں ہوا سے پہلے کی گرد کی طرح چھوٹے مارا تھا: میں نے انہیں سڑکوں کی مٹی کی طرح پھینک دیا۔\n43۔ تو نے مجھے لوگوں کی کوششوں سے نجات دلائی ہے؛ {اور} تو نے مجھے کافروں کا سربراہ بنا دیا ہے: ایک قوم {جسے میں نے نہیں جانا کہ وہ میری خدمت کرے گی۔\n44۔ جیسے ہی وہ میرے بارے میں سنیں گے، میری اطاعت کریں گے: اجنبی میرے سامنے سر تسلیم خم کریں گے۔ {جیسے ہی...: عبرانی۔ کان کی سماعت پر} {سر تسلیم خم کرو...: یا، دکھاوے کی اطاعت کرو} {اجنبی: عبرانی۔ اجنبی کے بیٹے}\n45۔ اجنبی غائب ہو جائیں گے، اور اپنے قریبی مقامات سے ڈر جائیں گے۔ {اجنبی: عبرانی۔ اجنبی کے بیٹے}\n46. خداوند زندہ ہے؛ اور میری چٹان پر مبارک ہو؛ اور میری نجات کے خدا کو بلند کرے۔\n47۔ {یہ} خدا ہے جو میرا بدلہ لیتا ہے، اور میرے ماتحت لوگوں کو زیر کرتا ہے۔ {انتقام: عبرانی۔ انتقام دیتا ہے} {زیر کرنا: یا، تباہ کرنا}\n48۔ وہ مجھے میرے دشمنوں سے بچاتا ہے: ہاں، تو مجھے ان لوگوں سے بلند کرتا ہے جو میرے خلاف اٹھتے ہیں: تو نے مجھے ظالم آدمی سے بچایا۔ {تشدد...: عبرانی۔ تشدد کا آدمی}\n49۔ اسی لیے اے خداوند، میں تیرا شکر ادا کروں گا اور تیرے نام کی حمد کروں گا۔ {دو...: یا، اعتراف کرو}\n50۔ وہ اپنے بادشاہ کو عظیم نجات دیتا ہے؛ اور اپنے مسح شدہ، داؤد اور اس کی نسل کو ہمیشہ کے لیے رحم دلاتا ہے۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] آسمان خدا کی جلال کا اعلان کرتے ہیں؛ اور آسمان اس کے کام کو دکھاتا ہے۔\n2۔ دن سے دن بات کرتا ہے، اور رات سے رات علم ظاہر کرتا ہے۔\n3. {جہاں آواز سنی نہ جائے} کوئی بول چال ہے نہ زبان۔ {جہاں...: یا، ان کے بغیر ان کی آواز سنی جاتی ہے: عبرانی۔ ان کی آواز سنے بغیر\n4۔ ان کی نسل پوری زمین میں پھیل چکی ہے، اور ان کے الفاظ دنیا کے آخر تک پہنچ چکے ہیں۔ ان میں اس نے سورج کے لیے ایک خیمہ قائم کیا ہے، {لائن: یا، حکمرانی، یا، سمت}\n5. جو {ہے} ایک دولہا کے اپنے کمرے سے نکلتے ہوئے، {اور} ایک مضبوط آدمی کے طور پر خوشی مناتا ہے جو دوڑ دوڑتا ہے۔\n6۔ اس کا باہر نکلنا {ہے} آسمان کے کنارے سے، اور اس کا چکر اس کے کنارے تک: اور اس کی گرمی سے کوئی چیز چھپی نہیں۔\n7۔ خداوند کا قانون {ہے} کامل ہے، جو روح کو بدل دیتا ہے: خداوند کی گواہی {یقین} ہے، سادہ کو دانا بناتی ہے۔ {قانون: یا، عقیدہ} {کنورٹنگ: یا، بحال}\n8۔ خداوند کے قوانین درست ہیں، دل کو خوش کرتے ہیں: خداوند کا حکم پاک ہے، آنکھوں کو روشن کرتا ہے۔\n9۔ خداوند کا خوف {پاک} ہے، ہمیشہ قائم رہتا ہے: خداوند کے فیصلے {راست} ہیں {اور} مکمل طور پر راستباز ہیں۔ {true: عبرانی سچ}\n10. سونے سے زیادہ خواہش کی جا سکتی ہے، ہاں، بہت زیادہ باریک سونے سے: شہد اور شہد کے چھتے سے بھی زیادہ میٹھا۔ {شہد کا چھتا: عبوری۔ شہد کے چھتوں کا گرنا}\n11۔ مزید یہ کہ آپ کے خادم کو انہی سے خبردار کیا گیا ہے: {اور} ان کی دیکھ بھال میں بڑا انعام ہے۔\n12. کون اس کی غلطیوں کو سمجھ سکتا ہے؟ تو مجھے خفیہ {غلطیوں} سے پاک کر دے۔\n13۔ اپنے بندے کو بھی گناہوں سے دور رکھو؛ انہیں مجھ پر حکمرانی نہ کرنے دو: تب میں سیدھا رہوں گا، اور اس عظیم گناہ سے بے قصور ہوں گا۔ {عظیم: یا، بہت زیادہ}\n14. میرے منہ کے الفاظ اور میرے دل کی غور و فکر تیرے سامنے قابل قبول ہو، اے خداوند، میری طاقت اور میرا نجات دہندہ۔ {طاقت: عبرانی۔ راک}","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] خداوند مصیبت کے دن تیرا سنے؛ یعقوب کے خدا کا نام تمہاری حفاظت کرے؛ {دفاع...: عببرانی۔ تمہیں کسی اونچی جگہ پر رکھو}\n2۔ پناہ گاہ سے مدد بھیجو، اور تمہیں صہیون سے باہر نکالو؛ {آپ کی مدد: عبرانی۔ تیری مدد} {مضبوط: عبرانی سپورٹ}\n3۔ اپنی تمام قربانیوں کو یاد رکھو، اور اپنی جلی ہوئی قربانی قبول کرو؛ سیلہ۔ {قبول کریں: عبرانی۔ راکھ بن جاؤ: یا، موٹا بنا دو}\n4۔ اپنے دل کے مطابق تمہیں عطا کرو، اور اپنی تمام نصیحتیں پوری کرو۔\n5۔ ہم تیری نجات پر خوش ہوں گے، اور اپنے خدا کے نام پر ہم {اپنے} جھنڈے نصب کریں گے: خداوند تیری تمام درخواستیں پوری کرے۔\n6۔ اب میں جانتا ہوں کہ خداوند اپنے مسح شدہ کو نجات دیتا ہے؛ وہ اسے اپنے مقدس آسمان سے اپنے دائیں ہاتھ کی نجات دہندہ طاقت سے سنے گا۔ {اس کا مقدس...: عبرانی۔ ان کی پاکیزگی کا آسمان} {ساتھ...: عبرانی۔ نجات کی طاقت سے}\n7. کچھ {رتھوں پر بھروسہ} کرتے ہیں، اور کچھ گھوڑوں پر: لیکن ہم خداوند اپنے خدا کے نام کو یاد رکھیں گے۔\n8۔ وہ گرا دیے جاتے ہیں اور گر جاتے ہیں: لیکن ہم زندہ ہوتے ہیں، اور سیدھے کھڑے ہوتے ہیں۔\n9۔ بچا، خداوند: جب ہم پکار رہے تو بادشاہ ہمیں سن لے۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] بادشاہ تیری طاقت میں خوش ہوگا، اے خداوند؛ اور تیری نجات میں وہ کتنی خوشی منائے گا!\n2۔ تم نے اسے اس کے دل کی خواہش دی ہے، اور اس کے ہونٹوں کی درخواست کو نہیں روکا۔ سیلہ۔\n3۔ کیونکہ تم اسے نیکی کی برکتوں سے روکتے ہو: تو اس کے سر پر خالص سونے کا تاج رکھتی ہو۔\n4۔ اس نے تم سے زندگی مانگی، {اور} تو نے اسے {حتی} دی، {حتی} کہ ہمیشہ کے لیے دن بھر کے لیے۔\n5۔ اس کی شان تمہاری نجات میں عظیم ہے: عزت اور عظمت تو نے اس پر رکھی ہے۔\n6۔ کیونکہ تم نے اسے ہمیشہ کے لیے سب سے زیادہ بابرکت بنایا ہے: تم نے اسے اپنی شکل سے بے حد خوش کیا ہے۔ {اسے سب سے زیادہ...: عبرانی بنایا۔ اسے برکتوں کے طور پر مقرر کیا} {اسے بے حد عظیم بنایا...: عبرانی۔ اسے خوشی سے خوش کرو}\n7۔ کیونکہ بادشاہ خداوند پر بھروسہ کرتا ہے، اور سب سے بلند کی رحمت سے وہ متاثر نہیں ہوگا۔\n8۔ تمہارا ہاتھ تمہارے تمام دشمنوں کو پہچان لے گا: تمہارا دایاں ہاتھ ان لوگوں کو پہچانے گا جو تم سے نفرت کرتے ہیں۔\n9۔ تم انہیں اپنے غصے کے وقت آگ کے تندور کی طرح بنا دینا: خداوند انہیں اپنے غضب میں نگل لے گا، اور آگ انہیں نگل لے گی۔\n10. ان کے پھل زمین سے مٹ جائیں گے، اور ان کی نسل کو انسانوں کی اولاد سے مٹا دو۔\n11۔ کیونکہ وہ تمہارے خلاف برائی کا ارادہ رکھتے تھے: انہوں نے ایک شرارتی چال کا تصور کیا، {جسے وہ انجام نہیں دے سکتے}۔\n12۔ لہٰذا تم انہیں پیٹھ موڑنے پر مجبور کرو گے، {جب} تم اپنے تیروں کو اپنے دھاگوں پر ان کے چہرے کے خلاف تیار کرو گے۔ {کیا تم...: یا، تم انہیں بٹ کی طرح رکھو گے} {واپس: عبوری۔ کندھا}\n13۔ اے خداوند، اپنی طاقت میں بلند ہو جا: {اسی طرح} ہم تیری طاقت گائیں گے اور اس کی تعریف کریں گے۔","1. [چیف موسیقار آن ایجلیت شاہر، اے زبور آف ڈیوڈ۔] میرے خدا، میرے خدا، تم نے مجھے کیوں چھوڑ دیا؟ {تم اتنے} میری مدد کرنے سے اتنے دور کیوں ہو، {اور میرے دہاڑ کے الفاظ سے}؟ {ایجیلتھ...: یا، صبح کا ہنڈ} {مدد...: عبرانی میری نجات}\n2۔ اے میرے خدا، میں دن میں پکار رہا ہوں، لیکن تو سنتا نہیں؛ اور رات کے موسم میں، اور خاموش نہیں ہوتا۔ {am...: عبرانی۔ میرے لیے کوئی خاموشی نہیں ہے}\n3۔ لیکن تو {تو} مقدس ہو، {اے تو} جو اسرائیل کی حمد میں رہتا ہے۔\n4۔ ہمارے آباؤ اجداد نے تم پر بھروسہ کیا: انہوں نے بھروسہ کیا، اور تو نے انہیں نجات دی۔\n5۔ انہوں نے تم سے پکارا، اور نجات پائے: انہوں نے تم پر بھروسہ کیا، اور پریشان نہیں ہوئے۔\n6. لیکن میں ایک کیڑا ہوں، اور کوئی انسان نہیں؛ مردوں کی ملامت اور لوگوں سے نفرت کی جانے والی۔\n7۔ جو بھی مجھے دیکھتا ہے وہ مجھے ہنسا کر طنز کرتا ہے: وہ ہونٹ نکالتے ہیں، سر ہلاتے ہیں، {کہتے ہیں}، {گولی مار...: عبرانی۔ کھولو}\n8۔ اس نے خداوند پر بھروسہ کیا {کہ} کہ وہ اسے نجات دے گا: اسے نجات دے، کیونکہ وہ اس میں خوش ہے۔ {اس نے بھروسہ کیا...: عبرانی۔ اس نے خود کو رول کیا} {دیکھنا...: یا، اگر اسے خوشی ہو}\n9. لیکن تو وہی ہو جس نے مجھے رحم سے نکالا: تو نے مجھے امید دی {جب میں میری ماں کے سینوں پر تھا}۔ {کیا...: یا، مجھے محفوظ رکھا}\n10. مجھے رحم سے تم پر ڈالا گیا: تو میری ماں کے پیٹ سے میرے خدا ہو۔\n11۔ مجھ سے دور نہ رہو؛ کیونکہ مصیبت {ہے} قریب ہے؛ کیونکہ کوئی مدد کرنے والا نہیں ہے۔ {کوئی نہیں...: عبرانی۔ مددگار نہیں}\n12۔ بہت سے بیل میرے گرد گھوم چکے ہیں: باشان کے مضبوط بیلوں نے مجھے گھیر لیا ہے۔\n13۔ وہ مجھ پر اپنے منہ کھول کر دیکھتے رہے، جیسے کوئی کوا اور دہاڑتا شیر۔ {حیران...: عبرانی میرے خلاف اپنے منہ کھول دیے}\n14۔ میں پانی کی طرح بہا دیا جاتا ہوں، اور میری تمام ہڈیاں بے ربط ہیں: میرا دل موم کی طرح ہے؛ یہ میرے آنتوں کے بیچ میں پگھل جاتا ہے۔ {باہر...: یا، تقسیم شدہ}\n15. میری طاقت مٹی کے ٹکڑے کی طرح خشک ہو گئی ہے؛ اور میری زبان میرے جبڑوں سے چپک جاتی ہے؛ اور تم نے مجھے موت کی خاک میں لے آیا ہے۔\n16۔ کیونکہ کتوں نے مجھے گھیر لیا ہے: بدکاروں کے اجتماع نے مجھے گھیر لیا ہے: انہوں نے میرے ہاتھوں اور پیروں کو چھید دیا ہے۔\n17۔ میں اپنی تمام ہڈیوں کو بتا سکتا ہوں: وہ مجھے دیکھتی ہیں اور مجھے گھورتی ہیں۔\n18۔ وہ میرے کپڑے ان میں تقسیم کرتے ہیں اور میرے لباس پر قرعہ ڈالتے ہیں۔\n19. لیکن اے خداوند، مجھ سے دور نہ ہو: اے میری طاقت، جلدی فرما میری مدد کے لیے۔\n20۔ میری روح کو تلوار سے نجات دے؛ میرے پیارے، کتے کی طاقت سے۔ {میری جان: عبرانی۔ میرا واحد} {طاقت: عبرانی۔ ہاتھ}\n21. مجھے شیر کے منہ سے بچا: کیونکہ تم نے مجھے یونیکورن کے سینگوں سے سنا ہے۔\n22. میں تیرا نام اپنے بھائیوں کے سامنے اعلان کروں گا: جماعت کے درمیان میں تیری تعریف کروں گا۔\n23۔ جو خداوند سے ڈرتے ہیں، اس کی تعریف کریں؛ اے سب یعقوب کی اولاد، اس کی جلال کرو؛ اور اس سے ڈرو، اے سب اسرائیل کی نسل۔\n24۔ کیونکہ اس نے نہ تو مصیبت زدہ کو حقیر سمجھا اور نہ ہی نفرت کی؛ نہ ہی اس نے اپنا چہرہ اس سے چھپایا؛ لیکن جب اس نے اس سے رونا شروع کیا، تو اس نے سنا۔\n25. میری حمد آپ کی بڑی جماعت میں ہوگی: میں ان لوگوں کے سامنے اپنی قسمیں ادا کروں گا جو اس سے ڈرتے ہیں۔\n26. عاجز کھائیں گے اور مطمئن ہوں گے: وہ خداوند کی تعریف کریں گے جو اسے تلاش کرتا ہے: تمہارا دل ہمیشہ زندہ رہے گا۔\n27۔ دنیا کے تمام کنارے خداوند کو یاد کریں گے اور اس کی طرف رجوع کریں گے: اور اقوام کے تمام خاندان آپ کے سامنے عبادت کریں گے۔\n28. کیونکہ بادشاہی {ہے} خداوند کی: اور وہ {ہے} قوموں میں حکمران۔\n29۔ زمین پر جو بھی موٹے ہیں وہ کھائیں گے اور عبادت کریں گے: جو بھی مٹی میں جائے گا وہ اس کے سامنے سجدہ کرے گا: اور کوئی اپنی جان کو زندہ نہیں رکھ سکتا۔\n30۔ ایک بیج اس کی خدمت کرے گا؛ یہ ایک نسل کے لیے خداوند کے سامنے شمار ہوگا۔\n31۔ وہ آئیں گے، اور اس قوم کو اپنی راستبازی کا اعلان کریں گے جو پیدا ہوں گی، اور اس نے یہ کیا ہے۔","1. [داؤد کا زبور۔] خداوند میرا چرواہا ہے؛ مجھے کوئی کمی نہیں ہوگی۔\n2۔ وہ مجھے سبز چراگاہوں میں لٹاتا ہے: وہ مجھے پرسکون پانیوں کے کنارے لے جاتا ہے۔ {سبز...: عبرانی نرم گھاس کے چراگاہیں} {اب بھی...: عبرانی۔ خاموشی کے پانی}\n3۔ وہ میری روح کو بحال کرتا ہے: وہ مجھے اپنے نام کے لیے راستبازی کے راستوں پر لے جاتا ہے۔\n4۔ ہاں، چاہے میں موت کے سائے کی وادی سے گزروں، میں کسی برائی سے نہیں ڈروں گا: کیونکہ تو میرے ساتھ ہے؛ تیری چھڑی اور تمہاری چھڑی مجھے تسلی دیتی ہیں۔\n5۔ تو میرے دشمنوں کے سامنے میرے سامنے میز تیار کرتا ہے: تو میرے سر کو تیل سے مسح کرتا ہے؛ میرا پیالہ بھر گیا ہے۔ {اینونٹیسٹ: عبرانی۔ سب سے زیادہ موٹا بناتا ہے}\n6۔ یقینا نیکی اور رحمت میری زندگی کے تمام دنوں میں میرے ساتھ رہے گی: اور میں ہمیشہ خداوند کے گھر میں رہوں گا۔ {ہمیشہ کے لیے: عبرانی۔ دنوں کی لمبائی کے لیے}","1. [داؤد کا زبور۔] زمین {ہے} خداوند کی، اور اس کی بھرپوریت؛ دنیا، اور وہ جو اس میں رہتے ہیں۔\n2۔ کیونکہ اس نے اسے سمندروں پر قائم کیا ہے، اور اسے سیلابوں پر قائم کیا ہے۔\n3. خداوند کی پہاڑی پر کون چڑھے گا؟ یا کون اپنی مقدس جگہ پر کھڑا ہوگا؟\n4۔ جس کے ہاتھ صاف ہوں اور دل صاف ہو؛ جس نے اپنی روح کو غرور کی طرف نہیں اٹھایا، اور نہ ہی دھوکہ دہی سے قسم کھائی ہے۔ {وہ...: عبرانی۔ ہاتھوں کی صافی}\n5. اسے خداوند کی برکت ملے گی، اور خدا سے اپنی نجات کی راستبازی ملے گی۔\n6. یہ وہ نسل ہے جو اسے تلاش کرتے ہیں، جو تیرے چہرے کی تلاش میں ہیں، اے یعقوب۔ سیلہ۔ {اے یعقوب: یا، اے یعقوب کے خدا}\n7. اے دروازوں، اپنے سر اٹھاؤ؛ اور اے ہمیشہ کے دروازے اٹھاؤ؛ اور جلال کا بادشاہ آئے گا۔\n8. یہ جلال کا بادشاہ کون ہے؟ خداوند طاقتور اور طاقتور، خداوند جنگ میں طاقتور۔\n9. اے دروازوں، اپنے سر اٹھاؤ؛ یہاں تک کہ {ان} کو اوپر اٹھاؤ، اے ہمیشہ کے دروازے؛ اور جلال کا بادشاہ آئے گا۔\n10. یہ بادشاہ جلال کون ہے؟ لشکروں کا رب، وہ جلال کا بادشاہ ہے۔ سیلہ۔","1. [{داؤد کا زبور}] اے خداوند، میں اپنی جان تیرے پاس اٹھاتا ہوں۔\n2. اے میرے خدا، میں تجھ پر بھروسہ کرتا ہوں: مجھے شرمندہ نہ ہونے دو، میرے دشمن مجھ پر غالب نہ آئیں۔\n3۔ جی ہاں، جو تیری خدمت کرے وہ شرمندہ نہ ہو: وہ شرمندہ ہو جو بغیر وجہ کے گناہ کرتا ہے۔\n4. اے خداوند، مجھے اپنے راستے دکھاؤ؛ مجھے اپنے راستے سکھاؤ۔\n5. اپنی سچائی میں میری رہنمائی کر، اور مجھے سکھاؤ: کیونکہ تو میری نجات کا خدا ہے؛ میں سارا دن تمہارے انتظار میں ہوں۔\n6. اے خداوند، اپنی نرم رحمتوں اور اپنی محبت بھری مہربانیوں کو یاد رکھنا؛ کیونکہ وہ {ہمیشہ سے} پرانے رہے ہیں۔ {نرم...: عببری۔ آنتیں}\n7. میرے جوانی کے گناہ اور میرے گناہوں کو یاد نہ رکھو: اپنی رحمت کے مطابق مجھے اپنی بھلائی کے لیے یاد رکھنا، اے خداوند۔\n8. نیک اور سیدھا خداوند ہے: اسی لیے وہ گناہ گاروں کو راستہ سکھائے گا۔\n9۔ عاجز کو وہ فیصلے میں رہنمائی کرے گا: اور عاجز کو اپنا راستہ سکھائے گا۔\n10۔ خداوند کے تمام راستے ان لوگوں کے لیے رحمت اور سچائی ہیں جو اس کے عہد اور گواہیوں کو نبھاتے ہیں۔\n11۔ تیرے نام کے لیے، اے خداوند، میری گناہ کو معاف کر دے؛ کیونکہ یہ {ہے} عظیم۔\n12۔ وہ کون سا انسان ہے جو خداوند سے ڈرتا ہے؟ وہ اسے اس طریقے سے سکھائے گا جو وہ منتخب کرے گا۔\n13۔ اس کی روح سکون سے رہے گی؛ اور اس کی نسل زمین کی وارث ہوگی۔ {dwell...: عبرانی۔ نیکی میں ٹھہریں}\n14۔ خداوند کا راز ان لوگوں کے ساتھ ہے جو اس سے ڈرتے ہیں؛ اور وہ انہیں اپنا عہد دکھائے گا۔ {اور...: یا، اور اس کا عہد کہ وہ انہیں یہ بتائے}\n15. میری آنکھیں ہمیشہ خداوند کی طرف ہیں؛ کیونکہ وہ میرے پاؤں جال سے نکال لے گا۔ {پلک: عبوری۔ نکالو}\n16۔ میری طرف رجوع کرو، اور مجھ پر رحم کرو؛ کیونکہ میں ویران اور پریشان ہوں۔\n17. میرے دل کے دکھ اور بڑھ گئے ہیں: {O} مجھے میری پریشانیوں سے نکالو۔\n18۔ میری تکلیف اور میرے درد کو دیکھو؛ اور میرے تمام گناہوں کو معاف کر دو۔\n19. میرے دشمنوں کو سمجھو؛ کیونکہ وہ بہت ہیں؛ اور وہ مجھ سے سخت نفرت کرتے ہیں۔ {ظالم...: عبرانی۔ تشدد سے نفرت}\n20۔ اے میری روح کو محفوظ رکھ اور مجھے نجات دے: مجھے شرمندہ نہ ہونے دو؛ کیونکہ میں نے تم پر بھروسہ کیا ہے۔\n21۔ دیانت داری اور راستبازی مجھے محفوظ رکھے؛ کیونکہ میں تمہاری خدمت کرتا ہوں۔\n22. اے خدا، اسرائیل کو اس کی تمام مصیبتوں سے نجات دے۔","1. [{داؤد کا زبور}] اے خداوند، مجھے فیصلہ فرما؛ کیونکہ میں نے اپنی دیانت داری میں چلنا شروع کیا ہے: میں نے خداوند پر بھی بھروسہ کیا ہے؛ {لہٰذا} میں پھسلوں گا نہیں۔\n2. اے خداوند، مجھے پرکھ کر اور ثابت کرو؛ میرے دل اور لگام آزما کر دیکھیں۔\n3۔ کیونکہ تیری محبت میری آنکھوں کے سامنے ہے: اور میں تیرے سچائی میں چل پڑا ہوں۔\n4. میں نے خود پسند لوگوں کے ساتھ نہیں بیٹھی، اور نہ ہی دھوکہ دہی کرنے والوں کے ساتھ جاؤں گی۔\n5. میں نے برے لوگوں کی جماعت سے نفرت کی ہے؛ اور بدکاروں کے ساتھ نہیں بیٹھے گا۔\n6. میں اپنے ہاتھ معصومیت میں دھوؤں گا: اسی طرح میں تیرے قربان گاہ کو بھی دھوؤں گا، اے خداوند:\n7۔ تاکہ میں شکرگزاری کی آواز میں شائع کر سکوں، اور تمہارے تمام حیرت انگیز کاموں کی تفصیل بیان کر سکوں۔\n8۔ اے خداوند، میں نے تیرے گھر کی رہائش اور اس جگہ سے محبت کی ہے جہاں آپ کی عزت رہتی ہے۔ {کہاں...: عبرانی۔ تیری عزت کے خیمے کی}\n9. میری روح کو گناہ گاروں کے ساتھ نہ جمع کرو، نہ میری جان کو خونخوار لوگوں کے ساتھ: {جمع کرو...: یا، نہ لے جاؤ} {خونخوار...: عبرانی۔ خون کے مرد}\n10۔ جس کے ہاتھ میں شرارت ہے، اور اس کا دایاں ہاتھ رشوت سے بھرا ہوا ہے۔ {مکمل...: عببرانی۔ بھری ہوئی}\n11. لیکن جہاں تک میرا تعلق ہے، میں اپنی دیانتداری میں چلوں گا: مجھے نجات دے، اور میرے ساتھ رحم فرما۔\n12۔ میرا قدم ایک ہموار جگہ پر کھڑا ہے: میں جماعتوں میں خداوند کو برکت دوں گا۔","1. [{داؤد کا زبور}] خداوند میرا نور اور میری نجات ہے؛ کس سے ڈروں؟ خداوند میری زندگی کی طاقت ہے؛ کس سے ڈروں؟\n2۔ جب بدکار، {حتیٰ کہ} میرے دشمن اور میرے دشمن بھی، میرے جسم کو کھانے کے لیے مجھ پر آئے، تو وہ لڑکھڑائے اور گر گئے۔ {آیا...: عبوری۔ میرے خلاف آئے}\n3۔ اگرچہ ایک لشکر میرے خلاف خیمہ لگائے، میرا دل خوفزدہ نہیں ہوگا: چاہے جنگ میرے خلاف اٹھے، اس {ارادے} میں {ارادہ} پر اعتماد ہوں۔\n4. ایک {چیز} میں نے خداوند سے مانگی ہے، جس کی میں تلاش کروں گا؛ تاکہ میں اپنی زندگی کے تمام دن خداوند کے گھر میں رہ سکوں، خداوند کی خوبصورتی دیکھ سکوں، اور اس کے مندر میں پوچھ گچھ کروں۔ {خوبصورتی: یا، خوشی}\n5۔ کیونکہ مصیبت کے وقت وہ مجھے اپنے خیمے میں چھپائے گا: اپنے خیمے کے راز میں مجھے چھپائے گا؛ وہ مجھے ایک پتھر پر بٹھائے گا۔\n6۔ اور اب میرا سر میرے دشمنوں کے اوپر اٹھایا جائے گا، جو میرے ارد گرد ہیں: اس لیے میں اس کے خیمے میں خوشی کی قربانیاں پیش کروں گا؛ میں گاؤں گا، ہاں، میں خداوند کی حمد و ثنا گاؤں گا۔ {جوی: عبرانی۔ چیخنا}\n7۔ اے خداوند، سن جب، {جب} میں اپنی آواز میں پکاروں: مجھ پر بھی رحم فرما اور جواب دے۔\n8. {جب تم نے کہا}، میرا چہرہ تلاش کرو؛ میرے دل نے تم سے کہا، اے خداوند، تیرا چہرہ تلاش کروں گا۔ {جب...: یا، میرے دل نے تم سے کہا، میرا چہرہ تمہارا چہرہ تلاش کرے، وغیرہ}\n9۔ اپنا چہرہ مجھ سے دور مت چھپاؤ؛ اپنے خادم کو غصے میں نہ چھوڑو: تم نے میری مدد کی؛ مجھے نہ چھوڑو، نہ چھوڑو، اے میری نجات کے خدا۔\n10۔ جب میرے والد اور ماں مجھے چھوڑ دیں گے، تو خداوند مجھے اٹھا لے گا۔ {لے لو...: عببرانی۔ مجھے جمع کرو}\n11. اے خداوند، مجھے اپنا راستہ سکھاؤ، اور میرے دشمنوں کی وجہ سے مجھے سیدھے راستے پر لے چلا۔ {ایک سادہ...: عبرانی سادگی کا ایک طریقہ} {میرا...: عبرانی۔ جو مجھے دیکھتے ہیں}\n12۔ مجھے میرے دشمنوں کی مرضی کے حوالے نہ کرو، کیونکہ جھوٹے گواہ میرے خلاف اٹھے ہیں، اور جو ظلم کرتے ہیں۔\n13. {میں بے ہوش ہو گیا تھا}، جب تک کہ میں نے زندہ زمین میں خداوند کی بھلائی نہ دیکھی ہو۔\n14۔ خداوند کا انتظار کرو: اچھے بہادر رہو، اور وہ تمہارے دل کو مضبوط کرے گا: میں کہتا ہوں خدا پر انتظار کرو۔","1. [{داؤد کا زبور}] میں تجھ سے پکاروں گا، اے خداوند، میرا چٹان؛ میرے سامنے خاموش نہ رہو: ورنہ اگر تم مجھ سے خاموش رہو، تو میں ان لوگوں کی طرح ہو جاؤں گا جو گڑھے میں نیچے چلے جاتے ہیں۔ {میرے لیے: ہیب۔ میری طرف سے}\n2. میری دعاؤں کی آواز سنو، جب میں تم سے پکار رہا ہوں، جب میں اپنے ہاتھ تمہارے مقدس پیشگو کی طرف اٹھاتا ہوں۔ {تمہارا...: یا، تمہارے مقدس مقام کا پیش گو}\n3. مجھے بدکاروں اور بدکاروں کے ساتھ نہ لے جاؤ، جو اپنے پڑوسیوں کو امن کی بات کرتے ہیں، بلکہ ان کے دلوں میں شرارت ہے۔\n4۔ انہیں ان کے اعمال کے مطابق اور ان کی کوششوں کی برائی کے مطابق دیں: انہیں ان کے ہاتھوں کے کام کے بعد دیں؛ ان کے لیے ان کا صحرا چھوڑ دو۔\n5۔ کیونکہ وہ خداوند کے کاموں اور اس کے ہاتھوں کے عمل کو نہیں سمجھتے، وہ انہیں تباہ کرے گا، اور انہیں دوبارہ تعمیر نہیں کرے گا۔\n6۔ خداوند مبارک ہو، کیونکہ اس نے میری دعاؤں کی آواز سنی ہے۔\n7۔ خداوند میری طاقت اور میرا ڈھال ہے؛ میرا دل اس پر بھروسہ کرتا ہے، اور مجھے مدد ملتی ہے: اسی لیے میرا دل بہت خوش ہوتا ہے؛ اور اپنے گیت سے میں اس کی تعریف کروں گا۔\n8. خداوند ان کی طاقت ہے، اور وہ اپنے مسح شدہ کی نجات بخش طاقت ہے۔ {ان کا: یا، اس کا} {محفوظ کر رہا ہے...: عبرانی نجات کی طاقت}\n9۔ اپنے لوگوں کو بچاؤ، اور اپنی وراثت کو برکت دو: انہیں بھی کھلاؤ، اور ہمیشہ کے لیے اٹھاؤ۔ {feed: or, rule}","1. [داؤد کا زبور۔] اے طاقتور، خداوند کو عطا فرما، خداوند کو جلال اور طاقت عطا فرما۔ {ای مائٹی: ہیب۔ اے طاقتور بیٹو}\n2۔ خداوند کو اس کے نام کے حق دار جلال عطا فرما؛ پاکیزگی کی خوبصورتی میں خداوند کی عبادت کرو۔ {دی گلوری...: عبرانی اس کے نام کی عزت} {میں...: یا، اس کے شاندار مقدس مقام میں}\n3۔ خداوند کی آواز پانیوں پر ہے: جلال کا خدا گرجتا ہے: خداوند کئی پانیوں پر ہے۔ {بہت سے: یا، زبردست}\n4۔ خداوند کی آواز {ہے} طاقتور ہے؛ خداوند کی آواز {عظمت} سے بھری ہوئی ہے۔ {طاقتور: عبرانی۔ طاقت میں} {مکمل...: عبرانی ان میجسٹی}\n5۔ خداوند کی آواز دیودار کے درختوں کو توڑتی ہے؛ ہاں، خداوند لبنان کے دیودار توڑتا ہے۔\n6۔ وہ انہیں بھی بچھڑے کی طرح اچھلتا ہے؛ لبنان اور سیریون جیسے ایک نوجوان یونیکورن۔\n7۔ خداوند کی آواز آگ کی آگ کو تقسیم کرتی ہے۔ {تقسیم: عبرانی۔ کٹتھ آؤٹ}\n8۔ خداوند کی آواز بیابان کو ہلا دیتی ہے؛ خداوند قادیش کے بیابان کو ہلا دیتا ہے۔\n9۔ خداوند کی آواز ہرن کو بچھڑنے پر مجبور کرتی ہے، اور جنگلات کو دریافت کرتی ہے: اور اس کے مندر میں ہر کوئی اس کی جلال کی بات کرتا ہے۔ {بچھڑے کے لیے: یا، درد میں ہونا} {doth...: یا، اس کا ہر ذرہ ادا کرتا ہے، وغیرہ}\n10۔ خداوند سیلاب پر بیٹھا ہے؛ ہاں، خداوند ہمیشہ بادشاہ بیٹھا ہے۔\n11۔ خداوند اپنے لوگوں کو طاقت دے گا؛ خداوند اپنے لوگوں کو امن سے نوازے گا۔","1. [ایک زبور {اور} گیت {پر} داؤد خاندان کی تقدیس۔] اے خداوند، میں تیری تعریف کروں گا؛ کیونکہ تو نے مجھے اٹھایا ہے، اور میرے دشمنوں کو مجھ پر خوش نہیں کیا۔\n2. اے خداوند میرے خدا، میں نے تجھ سے پکارا اور تو نے مجھے شفا دی۔\n3۔ اے خداوند، تو نے میری روح کو قبر سے زندہ رکھا: تو نے مجھے زندہ رکھا تاکہ میں گڑھے میں نہ جاؤں۔\n4. اے خداوند کے مقدسوں، اس کے لیے گاؤ اور اس کی پاکیزگی کی یاد پر شکر ادا کرو۔ {پر...: یا، یادگار کی طرف}\n5۔ اس کے غصے کے لیے {جو ایک لمحے کے لیے برداشت کرتا ہے}؛ اس کے حق میں {ہے} زندگی: رونا ایک رات تک برداشت کر سکتا ہے، لیکن خوشی {آتی ہے} صبح کو۔ {اس کا غصہ...: عبرانی۔ اس کے غصے میں صرف ایک لمحہ ہوتا ہے} {ایک رات کے لیے: عبرانی۔ شام میں} {خوشی: عبرانی۔ گانا}\n6۔ اور اپنی خوشحالی میں میں نے کہا، میں کبھی متاثر نہیں ہوں گا۔\n7۔ اے خداوند، تیری رحمت سے تو نے میرا پہاڑ مضبوط کر دیا: تو نے اپنا چہرہ چھپا لیا، {اور} میں پریشان ہو گیا۔ {بنا...: عبرانی اپنے پہاڑ کے لیے مضبوط طاقت}\n8. اے خداوند، میں نے تجھ سے پکارا؛ اور میں نے خداوند سے دعا کی۔\n9. جب میں گڑھے میں جاؤں تو میرے خون میں کیا فائدہ ہے؟ کیا خاک تمہاری تعریف کرے گی؟ کیا یہ تمہاری سچائی کا اعلان کرے گا؟\n10. اے خداوند، سن اور مجھ پر رحم فرما: اے خداوند، تو میرا مددگار بنو۔\n11۔ تم نے میرے لیے میرے غم کو رقص میں بدل دیا: تم نے میرا کپڑا اتار دیا، اور مجھے خوشی سے سجایا ہے؛\n12. اس مقصد کے لیے کہ {میرا} جلال تمہاری تعریف کرے، اور خاموش نہ رہے۔ اے خداوند میرے خدا، میں ہمیشہ کے لیے تیرا شکر ادا کروں گا۔ {میری جلال: یعنی، میری زبان، یا، میری روح}","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے خداوند، میں تجھ پر بھروسہ کرتا ہوں؛ مجھے کبھی شرمندہ نہ ہونے دو: اپنی راستبازی میں مجھے نجات دے۔\n2۔ میرے سامنے اپنا کان جھک جاؤ؛ مجھے جلدی نجات دہ: میری مضبوط چٹان بنو، کیونکہ ایک دفاعی گھر مجھے بچا سکتا ہے۔ {میرا...: عبوری۔ میرے پاس طاقت کے پتھر کے لیے}\n3. کیونکہ تو میرا پتھر اور میرا قلعہ ہے؛ لہٰذا تیرے نام کے لیے مجھے رہنمائی فرما، اور رہنمائی فرما۔\n4. مجھے اس جال سے نکالو جو انہوں نے میرے لیے خاص طور پر رکھا ہے: کیونکہ تو میری طاقت ہے۔\n5۔ میں اپنی روح تیرے ہاتھ میں دیتا ہوں: تو نے مجھے نجات دی ہے، اے خداوند سچائی کے خدا۔\n6۔ میں نے ان لوگوں سے نفرت کی ہے جو جھوٹے باطلوں کو سمجھتے ہیں: لیکن میں خداوند پر بھروسہ رکھتا ہوں۔\n7۔ میں تیری رحمت میں خوش اور خوش ہوں گا: کیونکہ تم نے میری پریشانی پر غور کیا ہے؛ تم نے میری روح کو مشکلات میں جانا ہے؛\n8۔ اور مجھے دشمن کے ہاتھ میں بند نہیں کیا: تو نے میرے قدم ایک بڑے کمرے میں رکھ دیے۔\n9۔ اے خداوند، مجھ پر رحم فرما، کیونکہ میں مصیبت میں ہوں: میری آنکھ غم میں جل گئی ہے، {ہاں}، میری جان اور میرا پیٹ۔\n10۔ کیونکہ میری زندگی غم میں گزرتی ہے، اور میرے سال آہ بھرنے میں: میری طاقت میرے گناہوں کی وجہ سے کمزور ہو جاتی ہے، اور میری ہڈیاں ختم ہو جاتی ہیں۔\n11۔ میں اپنے تمام دشمنوں کے لیے ملامت تھا، خاص طور پر اپنے پڑوسیوں میں، اور میرے جاننے والوں کے لیے خوفزدہ تھا: جو مجھے بغیر دیکھے تھے وہ مجھ سے بھاگ گئے۔\n12. مجھے ایک مردہ انسان کے طور پر بھولا دیا گیا ہے: میں ایک ٹوٹے ہوئے برتن کی طرح ہوں۔ {ایک ٹوٹا ہوا...: عببرانی۔ ایک جہاز جو فنا ہو جاتا ہے}\n13۔ کیونکہ میں نے بہت سے لوگوں کی بدنامی سنی ہے: ہر طرف خوف تھا: جب وہ میرے خلاف مل کر مشورہ کر رہے تھے، تو انہوں نے میری جان چھیننے کی سازش کی۔\n14. لیکن میں نے تجھ پر بھروسہ کیا، اے خداوند: میں نے کہا، تو میرا خدا ہے۔\n15۔ میرے وقت تیرے ہاتھ میں ہیں: مجھے میرے دشمنوں کے ہاتھوں سے اور ان سے نجات دے جو مجھے ستاتے ہیں۔\n16۔ اپنا چہرہ اپنے خادم پر چمکاؤ: اپنی رحمت کے لیے مجھے بچاؤ۔\n17. اے خداوند، مجھے شرم نہ ہو؛ کیونکہ میں نے تم سے پکارا ہے: بدکاروں کو شرمندہ ہو، {اور} قبر میں خاموش رہو۔ {خاموش...: یا، بند ہو گیا}\n18۔ جھوٹے ہونٹ خاموش ہو جائیں؛ جو نیک لوگوں کے خلاف فخر اور حقارت سے بری باتیں کرتے ہیں۔ {سنجیدہ...: عبرانی۔ ایک مشکل کام ہے}\n19۔ {اوہ} تیری نیکی کتنی عظیم ہے، جو تم نے ان لوگوں کے لیے رکھی ہے جو تم سے ڈرتے ہیں؛ {جو} تم نے ان لوگوں کے لیے کیا ہے جو تم پر بھروسہ کرتے ہیں، انسانوں کے بیٹوں سے پہلے!\n20۔ تم انہیں اپنی موجودگی کے راز میں انسان کی غرور سے چھپاؤ گے: انہیں ایک پویلین میں زبانوں کے جھگڑے سے چھپاؤ گے۔\n21۔ خداوند مبارک ہو: کیونکہ اس نے مجھے ایک مضبوط شہر میں اپنی حیرت انگیز مہربانی دکھائی ہے۔ {مضبوط: یا، فینسڈ}\n22۔ کیونکہ میں نے جلدی میں کہا، میں تمہاری آنکھوں کے سامنے کٹ گیا ہوں، پھر بھی تم نے میری دعاؤں کی آواز سنی جب میں نے تمہیں پکارا۔\n23. اے خداوند سے محبت کرو، اے اس کے تمام مقدسین: {کیونکہ خداوند مومنوں کی حفاظت کرتا ہے، اور مغرور کرنے والوں کو بھرپور اجر دیتا ہے۔\n24۔ اچھے بہادر بنو، اور وہ تمہارے دل کو مضبوط کرے گا، جو خداوند پر امید رکھتے ہو۔","1. [{A زبور} داؤد، مشکیل۔] مبارک ہے {کیا وہ ہے} جس کی گناہ {معاف ہے}، {جس کی} گناہ {چھپ گئی ہے}۔ {ایک زبور...: یا، داؤد کا زبور جو تعلیم دیتا ہے}\n2. مبارک ہے وہ شخص جس پر خداوند گناہ کا الزام نہیں لگاتا، اور جس کی روح میں کوئی چال نہیں۔\n3. جب میں خاموش رہا، تو میری ہڈیاں سارا دن میری دہاڑ میں بوڑھی ہو گئیں۔\n4۔ دن رات تمہارا ہاتھ مجھ پر بھاری تھا: میری نمی گرمیوں کی خشک سالی میں بدل گئی ہے۔ سیلہ۔\n5۔ میں نے اپنے گناہ کو تم سے تسلیم کیا، اور اپنی گناہ چھپائی نہیں۔ میں نے کہا، میں اپنے گناہوں کا اعتراف خداوند کے سامنے کروں گا؛ اور تم نے میرے گناہ کی گناہ معاف کر دی۔ سیلہ۔\n6۔ کیونکہ ہر وہ خدا پرست جو آپ سے دعا کرے گا اس وقت جب آپ ملیں: یقینا بڑے پانیوں کے سیلاب میں وہ اس کے قریب نہیں آئیں گے۔ {جب...: عبرانی۔ آف فائنڈنگ}\n7. تو میری چھپنے کی جگہ ہو؛ تم مجھے مصیبت سے بچاؤ گے؛ تم مجھے نجات کے گیتوں سے گھیر لو گے۔ سیلہ۔\n8۔ میں تمہیں اس راستے کی تعلیم دوں گا جس پر تم جاؤ گے: میں اپنی آنکھ سے تمہیں رہنمائی کروں گا۔ {گائیڈ...: عبوری۔ تمہیں مشورہ دوں، میری نظر تم پر ہوگی}\n9۔ تم گھوڑے کی طرح مت بنو، {یا} خچر کی طرح، {جسے سمجھ نہیں آتی: جس کے منہ کو کاٹنے اور لگام سے روکنا ہوگا، ورنہ وہ تمہارے قریب آ جائیں گے۔\n10۔ بدکاروں کے لیے بہت سے غم ہوں گے: لیکن جو خداوند پر بھروسہ کرے گا، اس کے گرد رحمت اس کے گرد ہوگی۔\n11۔ خداوند میں خوش رہو، اور خوش ہو جاؤ، اے راستبازو، اور خوشی سے پکارو، جو دل میں سیدھے ہیں۔","1. اے راستبازو، خداوند میں خوشی مناؤ: {کیونکہ} نیک لوگوں کے لیے تعریف خوبصورت ہے۔\n2. خداوند کی تعریف ہارپ سے کرو: اسے زبور کے ساتھ {اور} دس تاروں کا ساز گاؤ۔\n3۔ اسے نیا گیت سناؤ؛ تیز آواز کے ساتھ مہارت سے کھیلیں۔\n4۔ خداوند کا کلام {ہے} کے لیے؛ اور اس کے تمام اعمال {سچائی میں} مکمل ہوئے۔\n5۔ وہ راستبازی اور انصاف سے محبت کرتا ہے: زمین خداوند کی بھلائی سے بھری ہوئی ہے۔ {اچھائی: یا، رحم کرو}\n6۔ خداوند کے کلام سے آسمان بنے؛ اور ان سب کی تعداد اس کے منہ کی سانس سے۔\n7۔ وہ سمندر کے پانیوں کو ایک ڈھیر کی طرح جمع کرتا ہے: وہ گہرائی کو گوداموں میں جمع کرتا ہے۔\n8۔ ساری زمین خداوند سے ڈرے: دنیا کے تمام باشندے اس سے خوف میں کھڑے ہوں۔\n9۔ کیونکہ اس نے بات کی، اور یہ {ہو گیا}؛ اس نے حکم دیا، اور وہ مضبوطی سے کھڑی رہی۔\n10۔ خداوند کافروں کی نصیحت کو بے اثر کر دیتا ہے: وہ لوگوں کی چالاکیوں کو بے اثر کر دیتا ہے۔ {bringeth: Hebrew. یہ مایوس کرتا ہے}\n11۔ خداوند کی نصیحت ہمیشہ قائم رہتی ہے، اس کے دل کے خیالات تمام نسلوں کے لیے۔ {سب کے لیے...: عبرانی۔ نسل اور نسل کے لیے}\n12. مبارک ہے وہ قوم جس کا خدا خداوند ہے؛ {اور} وہ لوگ جنہیں اس نے اپنی وراثت کے لیے چنا ہے۔\n13۔ خداوند آسمان سے دیکھتا ہے؛ وہ تمام انسانوں کے بیٹوں کو دیکھتا ہے۔\n14۔ اپنی رہائش گاہ سے وہ زمین کے تمام باشندوں کو دیکھتا ہے۔\n15۔ وہ ان کے دلوں کو ایک جیسا بناتا ہے؛ وہ ان کے تمام کاموں پر غور کرتا ہے۔\n16. کوئی بادشاہ لشکر کی کثرت سے بچایا نہیں جاتا: طاقتور آدمی زیادہ طاقت سے نجات نہیں پاتا۔\n17۔ گھوڑا حفاظت کے لیے فضول چیز ہے: نہ ہی وہ اپنی بڑی طاقت سے کسی کو نجات دے سکتا ہے۔\n18۔ دیکھو، خداوند کی نظر ان پر ہے جو اس سے ڈرتے ہیں، ان پر جو اس کی رحمت کی امید رکھتے ہیں؛\n19۔ ان کی روح کو موت سے بچانا، اور انہیں قحط میں زندہ رکھنا۔\n20۔ ہماری روح خداوند کا انتظار کرتی ہے: وہ ہمارا مدد اور ڈھال ہے۔\n21۔ کیونکہ ہمارا دل اس میں خوش ہوگا، کیونکہ ہم نے اس کے مقدس نام پر بھروسہ کیا ہے۔\n22. اے خداوند، تیری رحمت ہمارے اوپر ہو، جیسا ہم تجھ سے امید رکھتے ہیں۔","1۔ [{زبور} داؤد کا، جب اس نے ابیملک کے سامنے اپنا رویہ بدلا؛ جس نے اسے بھگا دیا اور وہ چلا گیا۔] میں ہمیشہ خداوند کو برکت دوں گا: اس کی حمد {ہمیشہ میرے منہ میں رہے گی}۔ {ابیملک: یا، اخیش}\n2۔ میری جان اسے خداوند میں فخر کرنے پر مجبور کرے گی: عاجز اس کی بات سنیں گے اور خوش ہوں گے۔\n3. اے میرے ساتھ خداوند کو جلال بخش، اور ہم مل کر اس کا نام بلند کریں۔\n4۔ میں نے خداوند کو تلاش کیا، اور اس نے مجھے سنا، اور مجھے میرے تمام خوف سے بچایا۔\n5۔ انہوں نے اس کی طرف دیکھا، اور ہلکے ہو گئے: اور ان کے چہرے شرمندہ نہیں ہوئے۔ {ہلکے ہو گئے: یا، وہ اس کی طرف بہتے ہیں}\n6۔ اس غریب آدمی نے پکارا، اور خداوند نے سنا اور اسے اس کی تمام مصیبتوں سے بچایا۔\n7۔ خداوند کا فرشتہ ان لوگوں کے گرد گھومتا ہے جو اس سے ڈرتے ہیں، اور انہیں نجات دیتا ہے۔\n8. چکھو اور دیکھو کہ خداوند {نیکا} ہے: مبارک {ہے} وہ شخص {جو اس پر بھروسہ کرتا ہے}۔\n9۔ اے خداوند سے ڈرو، اے اس کے مقدسین: کیونکہ جو لوگ اس سے ڈرتے ہیں ان میں کوئی کمی نہیں۔\n10۔ نوجوان شیر کمی محسوس کرتے ہیں، اور بھوک کا شکار ہوتے ہیں: لیکن جو خداوند کی تلاش کرتے ہیں وہ کوئی اچھی چیز نہیں چاہتے۔\n11۔ آؤ اے بچوں، میری بات سنو: میں تمہیں خداوند کا خوف سکھاؤں گا۔\n12. کون سا انسان ہے جو زندگی کی خواہش رکھتا ہے، {اور} {بہت} دنوں سے محبت کرتا ہے، تاکہ وہ اچھائی دیکھ سکے؟\n13۔ اپنی زبان کو برائی سے دور رکھو، اور اپنے ہونٹ چالاکی سے بچو۔\n14۔ برائی سے دور ہو جاؤ اور بھلائی کرو؛ سکون تلاش کریں، اور اس کا پیچھا کریں۔\n15۔ خداوند کی آنکھیں راستبازوں پر ہیں، اور اس کے کان ان کی پکار کے لیے کھلے ہیں۔\n16. خداوند کا چہرہ ان لوگوں کے خلاف ہے جو برے کرتے ہیں، تاکہ ان کی یاد زمین سے کاٹ دی جائے۔\n17. {راستباز} پکاریں، اور خداوند سن کر انہیں ان کی تمام مصیبتوں سے نجات دلاتا ہے۔\n18. خداوند ان لوگوں کے قریب ہے جو دل ٹوٹے ہوئے ہیں؛ اور ان لوگوں کو بچاتا ہے جو پشیمان ہوں۔ {ابھی...: عبرانی دل ٹوٹنے والوں کے لیے} {ایک پشیمان کی...: عبرانی۔ پچھتاوے کی روح}\n19۔ بہت سے راستبازوں کی مصیبتیں ہیں: لیکن خداوند اسے ان سب سے نجات دیتا ہے۔\n20۔ وہ اپنی تمام ہڈیاں رکھتا ہے: ان میں سے کوئی بھی ٹوٹی نہیں۔\n21۔ برائی بدکاروں کو مار ڈالے گی؛ اور جو نیک لوگوں سے نفرت کریں گے وہ ویران ہو جائیں گے۔ {ویران: یا، قصوروار}\n22. خداوند اپنے بندوں کی روح کو نجات دیتا ہے: اور جو اس پر بھروسہ کرتے ہیں ان میں سے کوئی بھی ویران نہیں ہوگا۔ {ویران: یا، قصوروار}","1. [{داؤد کا زبور}] اے خداوند، ان لوگوں سے جو میرے ساتھ لڑتے ہیں ان سے دعا فرما: ان کے خلاف لڑو جو میرے خلاف لڑتے ہیں۔\n2. ڈھال اور بکلر کو پکڑو، اور میری مدد کے لیے کھڑے ہو جاؤ۔\n3۔ نیزہ بھی نکالو، اور ان لوگوں کے خلاف راستہ روک دو جو مجھے ستاتے ہیں: میری جان سے کہو، میں تمہاری نجات ہوں۔\n4. جو میری روح کی تلاش میں ہیں وہ الجھن میں ہوں اور شرمندہ ہو جائیں: انہیں واپس پلٹ کر الجھن میں ڈال دیا جائے جو میرے درد کا سبب بنے۔\n5۔ انہیں ہوا کے سامنے بھوسے کی طرح بنے رہے: اور خداوند کا فرشتہ ان کا پیچھا کرے۔\n6۔ ان کا راستہ تاریک اور پھسلن والا ہو: اور خداوند کا فرشتہ انہیں ستائے۔ {ڈارک...: عبوری۔ اندھیرا اور پھسلن\n7۔ کیونکہ بغیر وجہ کے انہوں نے میرے لیے اپنا جال {ایک گڑھے میں} چھپا دیا ہے، {جو} انہوں نے بغیر وجہ کے میری روح کے لیے کھودا ہے۔\n8۔ تباہی اچانک اس پر آ جائے؛ اور اس کا جال جو اس نے چھپا رکھا ہے، خود کو پھنسنے دیا: اسی تباہی میں اسے گرنے دو۔ {پر...: عبرانی۔ جس کے بارے میں وہ نہیں جانتا}\n9۔ اور میری جان خداوند میں خوش ہوگی: وہ اس کی نجات پر خوش ہوگی۔\n10. میرے تمام ہڈیاں کہیں گی، اے خداوند، جو تجرا جیسا ہے، جو غریبوں کو اس سے بچاتا ہے جو اس کے لیے زیادہ طاقتور ہے، ہاں، غریب اور محتاجوں کو اس سے بچاتا ہے جو اسے خراب کرتا ہے؟\n11۔ جھوٹے گواہ واقعی اٹھ کھڑے ہوئے؛ انہوں نے مجھ پر {وہ چیزیں} رکھ دیں جو مجھے معلوم نہیں تھیں۔ {غلط...: عبرانی غلط کے گواہ} {وہ...: عبرانی۔ انہوں نے مجھ سے پوچھا}\n12. انہوں نے مجھے اچھائی کے بدلے برائی دی تاکہ میری روح کو برباد کیا جا سکے۔ {سپوائل کرتے ہوئے: عبوری۔ محروم کرنا}\n13. لیکن جب وہ بیمار تھے، تو میرا لباس تھیلا تھا: میں نے روزہ رکھ کر اپنی روح کو عاجز کیا؛ اور میری دعا میرے سینے میں واپس آ گئی۔ {عاجز: یا، مصیبت}\n14. میں نے ایسے برتاؤ کیا جیسے {و} میرا دوست {یا} بھائی تھا: میں نے بھاری جھک کر سجدہ کیا، جیسے کوئی اپنی ماں کے لیے سوگ منا رہا ہو۔ {اپنا رویہ درست کیا: عبرانی۔ چلتے ہوئے} {جیسے...: عبرانی ایک دوست کی طرح، میرے بھائی کی طرح}\n15۔ لیکن میرے مصیبت میں وہ خوش ہوئے، اور خود کو جمع کیا: {ہاں}، عاجزوں نے میرے خلاف خود کو جمع کیا، اور میں نہیں جانتا تھا؛ انہوں نے {مجھے} کو پھاڑا، اور بند نہیں کیا: {مصیبت: عبرانی۔ رک جاؤ}\n16۔ دعوتوں میں منافق مذاق اڑاتے تھے، وہ اپنے دانتوں سے مجھ پر کاٹتے تھے۔\n17۔ خداوند، تم کتنی دیر تک دیکھتے رہو گے؟ میری روح کو ان کی تباہی سے بچاؤ، میری جان شیروں سے۔ {پیارے: عبوری۔ صرف ایک}\n18۔ میں بڑی جماعت میں تمہارا شکر ادا کروں گا: میں بہت سے لوگوں میں تمہاری تعریف کروں گا۔ {مچ: عبوری۔ مضبوط}\n19۔ میرے دشمن جو ہیں وہ مجھ پر ناجائز طور پر خوش نہ ہوں: {نہ ہی} انہیں ان آنکھوں سے آنکھ مارنے دو جو بے وجہ مجھ سے نفرت کرتے ہیں۔ {غلط طور پر: عبرانی۔ جھوٹا}\n20۔ کیونکہ وہ امن کی بات نہیں کرتے: بلکہ وہ ان لوگوں کے خلاف دھوکہ دہی کرتے ہیں جو زمین میں خاموش ہیں۔\n21۔ ہاں، انہوں نے میرے خلاف منہ کھول دیا، {اور} کہا، آہا، آہا، ہماری آنکھ نے دیکھ لی ہے۔\n22. {یہ} تو نے دیکھا، اے خداوند: خاموش نہ رہو: اے خداوند، مجھ سے دور نہ ہو۔\n23. اپنے آپ کو متحرک کرو، اور میرے فیصلے کے لیے جاگ جا، {حتیٰ کہ} میرے مقصد کے لیے، میرے خدا اور میرے رب کے لیے۔\n24. اے خداوند میرے خدا، اپنی راستبازی کے مطابق میرا فیصلہ فرما؛ اور انہیں مجھ پر خوش نہ ہونے دو۔\n25۔ وہ اپنے دل میں نہ کہیں، آہ، ہم بھی ایسا ہی کریں گے: وہ نہ کہیں، ہم نے اسے نگل لیا ہے۔ {آہ...: عبرانی۔ آہ، آہ، ہماری روح}\n26۔ جو لوگ میرے دکھ پر خوش ہیں، شرمندہ ہوں اور ایک ساتھ الجھن میں مبتلا ہوں: انہیں شرم اور بے عزتی کے ساتھ ملبوس کیا جائے جو میرے خلاف خود کو بڑھا چڑھا کر پیش کرتے ہیں۔\n27۔ وہ خوشی سے پکاریں اور خوش ہوں، جو میرے راستباز مقصد کی حمایت کرتے ہیں: ہاں، وہ بار بار کہیں، خداوند کو جلال دے، جو اپنے بندے کی خوشحالی میں خوش ہے۔ {راستباز...: عبرانی۔ راستبازی}\n28۔ اور میری زبان سارا دن تیری راستبازی اور تیری تعریف کی بات کرے گی۔","1. [اہم موسیقار کے نام، {ایک زبور} داؤد کی جو خداوند کا خادم ہے۔] بدکاروں کی گناہ میرے دل میں کہتی ہے، {کہ} اس کی آنکھوں کے سامنے خدا کا خوف نہیں ہے۔\n2۔ کیونکہ وہ اپنی آنکھوں میں خود کو خوشامد کرتا ہے، یہاں تک کہ اس کی بدکاری نفرت انگیز ثابت ہو جائے۔ {جب تک...: عبرانی۔ اپنی بدکاری کو نفرت کرنے کے لیے تلاش کرنا}\n3۔ اس کے منہ کے الفاظ گناہی اور فریب ہیں: اس نے حکمت اور بھلائی کے لیے چھوڑ دیا ہے۔\n4۔ وہ اپنے بستر پر شرارت کی سازش کرتا ہے؛ وہ خود کو ایک ایسے طریقے سے سنبھالتا ہے {جو اچھا نہیں}؛ وہ برائی سے نفرت نہیں کرتا۔ {شرارت: یا، غرور}\n5. اے خداوند، تیری رحمت، {ہے} آسمانوں میں؛ {اور} تمہاری وفاداری {بادلوں تک پہنچتی ہے}۔\n6. تیری راستبازی {ہے} عظیم پہاڑوں کی طرح؛ تمہارے فیصلے بہت گہرے ہیں: اے خداوند، تو انسان اور جانور کی حفاظت کرتا ہے۔ {the...: عبرانی خدا کے پہاڑ}\n7. اے خدا، تیری محبت کی مہربانی کتنی عظیم ہے! لہٰذا انسانوں کے بچے تیرے پروں کے سائے میں اپنا بھروسہ رکھتے ہیں۔ {بہترین: عبوری۔ قیمتی}\n8۔ وہ تمہارے گھر کی موٹاپے سے بھرپور مطمئن ہوں گے؛ اور تم انہیں اپنی خوشیوں کے دریا سے پانی پلاؤ۔ {بہت زیادہ...: عبرانی۔ پانی دیا گیا}\n9۔ کیونکہ تیرے ساتھ زندگی کا چشمہ ہے: تیری روشنی میں ہم روشنی دیکھیں گے۔\n10۔ اپنی محبت ان لوگوں کے ساتھ جاری رکھو جو تمہیں جانتے ہیں؛ اور تیری راستبازی دل کے راستبازوں کے لیے۔ {جاری رکھیں: عبرانی۔ تفصیل سے کھینچیں}\n11۔ غرور کا قدم میرے خلاف نہ آئے، اور بدکاروں کا ہاتھ مجھے ہٹانے نہ دے۔\n12. یہ ہیں بدکاری کے مزدور گر گئے: وہ گر چکے ہیں، اور اٹھ نہیں سکیں گے۔","1. [{داؤد کا زبور}] بدکاروں کی وجہ سے خود کو پریشان نہ کرو، نہ ہی بدکاروں سے حسد کرو۔\n2۔ کیونکہ وہ جلد ہی گھاس کی طرح کاٹ دیے جائیں گے، اور سبز جڑی بوٹی کی طرح مرجھا جائیں گے۔\n3۔ خداوند پر بھروسہ کرو، اور نیکی کرو؛ {یوں} تم زمین میں رہو گے، اور یقینا تمہیں خوراک ملے گی۔ {واقعی: عبرانی۔ سچ میں، یا، استحکام میں}\n4. اپنے آپ کو خداوند میں بھی خوش کرو؛ اور وہ تمہیں تمہارے دل کی خواہشات دے گا۔\n5. اپنا راستہ خداوند کے سپرد کرو؛ اس پر بھی بھروسہ کرو؛ اور وہ {اسے} کو پورا کرے گا۔ {Commit...: Heb. اپنا راستہ لے جاؤ}\n6۔ اور وہ تمہاری راستبازی کو روشنی کے طور پر اور تمہارا فیصلہ دوپہر کے طور پر پیش کرے گا۔\n7۔ خداوند میں آرام کرو، اور اس کا صبر سے انتظار کرو: اپنے راستے میں کامیاب ہونے والے اس شخص کی وجہ سے فکر نہ کرو، کیونکہ وہ شخص جو برے کام لے آتا ہے۔ {عبرانی۔ خاموش رہو}\n8۔ غصے سے رک جاؤ، اور غصے کو ترک کرو: اپنے آپ کو کسی بھی طرح سے برائی کرنے کی فکر نہ کرو۔\n9۔ بدکاروں کو کاٹ دیا جائے گا: لیکن جو خداوند کا انتظار کریں گے، وہ زمین کے وارث ہوں گے۔\n10۔ ابھی تھوڑی دیر کے لیے، اور بدکار {نہیں ہوں گے}: ہاں، تم اس کی جگہ پر غور کرو گے، اور وہ {نہیں ہو گی}۔\n11۔ لیکن عاجز زمین کے وارث ہوں گے؛ اور امن کی فراوانی میں خوش ہوں گے۔\n12۔ بدکار نیک کے خلاف سازش کرتا ہے، اور اپنے دانتوں سے اس پر حملہ کرتا ہے۔ {پلاٹیتھ: یا، پریکٹستھ}\n13۔ خداوند اس پر ہنسے گا: کیونکہ وہ دیکھتا ہے کہ اس کا دن آ رہا ہے۔\n14. بدکاروں نے تلوار نکالی ہے، اور اپنا کمان جھکا دیا ہے تاکہ غریبوں اور محتاجوں کو گرا دیں، {اور} ان لوگوں کو مار ڈالیں جو نیک باتیں کرتے ہیں۔ {ایسا...: عبرانی۔ راستہ درست ہے}\n15۔ ان کی تلوار ان کے اپنے دل میں داخل ہو جائے گی، اور ان کے کمان ٹوٹ جائیں گے۔\n16. جو تھوڑا سا ایک نیک آدمی کے پاس ہے، وہ بہت سے بدکاروں کی دولت سے بہتر ہے۔\n17۔ کیونکہ بدکاروں کے بازو ٹوٹ جائیں گے: لیکن خداوند راستبازوں کی حمایت کرتا ہے۔\n18۔ خداوند راستبازوں کے دنوں کو جانتا ہے: اور ان کی میراث ہمیشہ رہے گی۔\n19۔ وہ برے وقت میں شرمندہ نہیں ہوں گے: اور قحط کے دنوں میں وہ مطمئن ہوں گے۔\n20۔ لیکن بدکار ہلاک ہو جائیں گے، اور خداوند کے دشمن بھیڑ کے چربی کی طرح ہوں گے: وہ کھا جائیں گے؛ وہ دھوئیں میں جل جائیں گے۔ {دی فیٹ: ہیب۔ قیمتی}\n21۔ بدکار قرض لیتا ہے، اور دوبارہ ادا نہیں کرتا، بلکہ نیک رحم دکھاتا ہے اور دیتا ہے۔\n22. کیونکہ {جو اس سے بابرکت ہو} زمین کا وارث ہوگا؛ اور جو اس پر لعنت زدہ ہوں گے انہیں کاٹ دیا جائے گا۔\n23۔ ایک {نیک} انسان کے قدم خداوند کے حکم پر ہوتے ہیں: اور وہ اپنے راستے میں خوش ہوتا ہے۔ {ترتیب شدہ: یا، قائم شدہ}\n24۔ اگرچہ وہ گر جائے، اسے مکمل طور پر نہیں گرایا جائے گا: کیونکہ خداوند اپنے ہاتھ سے اسے سہارا دیتا ہے۔\n25۔ میں جوان تھا، اور {اب} بوڑھا ہوں؛ پھر بھی میں نے راستبازوں کو ترک شدہ نہیں دیکھا، اور نہ ہی اس کی نسل کو روٹی مانگتے ہوئے۔\n26۔ {وہ} ہمیشہ رحم کرنے والا اور رحم کرنے والا ہے؛ اور اس کی نسل {بابرکت ہے}۔ {کبھی: عبرانی۔ سارا دن}\n27۔ برائی سے دور ہو جاؤ اور نیکی کرو؛ اور ہمیشہ کے لیے رہیں۔\n28۔ کیونکہ خداوند فیصلے سے محبت کرتا ہے، اور اپنے مقدسین کو نہیں چھوڑتا؛ وہ ہمیشہ کے لیے محفوظ ہیں: لیکن بدکاروں کا بیج کاٹ دیا جائے گا۔\n29۔ نیک لوگ زمین کے وارث ہوں گے اور ہمیشہ کے لیے وہاں رہیں گے۔\n30۔ راستبازوں کا منہ حکمت بولتا ہے، اور اس کی زبان فیصلے کی بات کرتی ہے۔\n31۔ اس کے خدا کا قانون {ہے} اس کے دل میں؛ اس کے کوئی قدم نہیں پھسلیں گے۔ {قدم: یا، جا رہا ہے}\n32۔ بدکار نیک کو دیکھتا ہے اور اسے مارنے کی کوشش کرتا ہے۔\n33. خداوند اسے اپنے ہاتھ میں نہیں چھوڑے گا، اور جب اس کا فیصلہ ہو تو اسے سزا نہیں دے گا۔\n34۔ خداوند کا انتظار کرو، اور اس کے راستے پر قائم رہو، اور وہ تمہیں زمین کا وارث بننے کے لیے بلند کرے گا: جب بدکاروں کو کاٹ دیا جائے گا، تو تم اسے دیکھو گے۔\n35۔ میں نے بدکاروں کو بڑی طاقت میں دیکھا ہے، اور وہ سبز خلیج کے درخت کی طرح خود کو پھیلا رہا ہے۔ {ایک سبز...: یا، ایک سبز درخت جو اپنی ہی زمین میں اگتا ہے}\n36۔ پھر بھی وہ فوت ہو گیا، اور دیکھو، وہ نہیں تھا: ہاں، میں نے اسے تلاش کیا، لیکن وہ نہیں ملا۔\n37. کامل {انسان} کو نشان زد کرو، اور دیکھو راست باز: کیونکہ {وہ} انسان {ہے} کے اختتام پر امن ہے۔\n38۔ لیکن مجرموں کو ایک ساتھ ختم کر دیا جائے گا: بدکاروں کا انجام کاٹ دیا جائے گا۔\n39۔ لیکن راستبازوں کی نجات {ہے} خداوند کی: {وہ} ان کی طاقت ہے مشکل وقت میں۔\n40۔ اور خداوند ان کی مدد کرے گا اور انہیں نجات دے گا: وہ انہیں بدکاروں سے بچائے گا اور بچا لے گا، کیونکہ وہ اس پر بھروسہ کرتے ہیں۔","1. [داؤد کا زبور، یاد میں لانے کے لیے۔] اے خداوند، مجھے اپنے غضب میں ملامت نہ کر: اپنی شدید ناراضگی میں مجھے سزا نہ دے۔\n2۔ کیونکہ تمہارے تیر مجھ میں جکڑ جاتے ہیں، اور تمہارا ہاتھ مجھے دکھ دیتا ہے۔\n3۔ {میرے جسم میں تمہارے غصے کی وجہ سے کوئی صحت نہیں؛ نہ ہی میرے گناہ کی وجہ سے میری ہڈیوں میں کوئی سکون نہیں۔ {آرام: عبرانی امن، یا، صحت}\n4۔ میرے گناہوں کے لیے میرے سر سے گزر جاتے ہیں: یہ بوجھ میرے لیے بہت بھاری ہیں۔\n5. میرے زخم بدبو دار ہیں {اور} میری حماقت کی وجہ سے خراب ہو گئے ہیں۔\n6. میں پریشان ہوں؛ میں بہت سر جھکا ہوا ہوں؛ میں سارا دن سوگ مناتی رہتی ہوں۔ {پریشان: عبوری۔ wried}\n7. کیونکہ میری کمر ایک نفرت انگیز {بیمار} سے بھری ہوئی ہے: اور {میرے جسم میں کوئی صحت نہیں}۔\n8۔ میں کمزور اور زخمی ہوں، ٹوٹا ہوا ہوں: میں اپنے دل کی بے چینی کی وجہ سے دہاڑا ہوں۔\n9۔ اے خداوند، میری ساری خواہشات {ہے} تیرے سامنے؛ اور میری کراہت تم سے چھپی نہیں۔\n10۔ میرا دل ہانپتا ہے، میری طاقت ختم ہو جاتی ہے: جہاں تک میری آنکھوں کی روشنی ہے، وہ بھی مجھ سے غائب ہے۔ {چلا گیا...: عبرانی۔ میرے ساتھ نہیں ہے}\n11۔ میرے عاشق اور میرے دوست میرے درد سے دور کھڑے رہتے ہیں؛ اور میرے رشتہ دار دور کھڑے ہیں۔ {درد: عبرانی۔ فالج} {میرے رشتہ دار: یا، میرے پڑوسی}\n12۔ جو لوگ میری جان کی تلاش میں ہیں وہ میرے لیے جال بچھاتے ہیں: اور جو میری تکلیف چاہتے ہیں وہ سارا دن شرارتی باتیں کرتے ہیں اور دھوکہ دہی کا تصور کرتے ہیں۔\n13. لیکن میں، ایک بہرا آدمی ہونے کے ناطے، نہیں سنا؛ اور {میں تھا} ایک بے وقوف آدمی کی طرح {جو} اپنا منہ نہیں کھولتا۔\n14. یوں میں ایک ایسے انسان کی طرح تھا جو سنتا نہیں، اور جس کے منہ میں کوئی سرزنش نہیں ہے۔\n15. کیونکہ اے خداوند، میں تیرے اندر امید کرتا ہوں: اے خداوند میرے خدا، تو سنو گے۔ {میں...: یا، میں تمہارا انتظار کرتا ہوں} {سنو: یا، جواب دو}\n16۔ کیونکہ میں نے کہا، {مجھے سنو}، ورنہ {ورنہ} وہ مجھ پر خوش ہوں گے: جب میرا قدم پھسل جائے تو وہ میرے خلاف خود کو بڑھا چڑھا کر پیش کرتے ہیں۔\n17. کیونکہ میں رکنے کے لیے تیار ہوں، اور میرا غم {ہے} مسلسل میرے سامنے ہے۔ {رکنے کے لیے: عبوری۔ رکنے کے لیے}\n18۔ کیونکہ میں اپنی غلطی کا اعلان کروں گا؛ میں اپنے گناہ پر معذرت کروں گا۔\n19. لیکن میرے دشمن زندہ دل ہیں، اور وہ مضبوط ہیں: اور جو مجھ سے غلط نفرت کرتے ہیں وہ بڑھ جاتے ہیں۔ {زندہ دل ہیں...: عبوری۔ زندہ رہنا، مضبوط ہوتے ہیں}\n20۔ جو لوگ برائی کو بھلائی کے لیے بدلتے ہیں وہ میرے دشمن ہیں؛ کیونکہ میں {اس چیز کی پیروی کرتا ہوں جو} اچھی {ہے}۔\n21. اے خداوند، مجھے ترک نہ کرو: اے میرے خدا، مجھ سے دور نہ ہو۔\n22. اے خداوند، میری نجات، میری مدد کے لیے جلدی کرو۔ {تو...: عبرانی میری مدد کے لیے}","1. [چیف موسیقار کے نام، {حتیٰ کہ} جدوتون کو، داؤد کا زبور۔] میں نے کہا، میں اپنے طریقوں کا خیال رکھوں گا، کہ میں اپنی زبان سے گناہ نہ کروں: میں اپنے منہ کو لگام سے رکھوں گا، جب تک بدکار میرے سامنے ہیں۔ {میرا منہ...: عبرانی۔ ایک لگام، یا میرے منہ کے لیے مزل}\n2. میں خاموشی سے بے وقوف تھا، میں خاموش رہا، {حتیٰ کہ} اچھائی سے بھی؛ اور میرا غم جاگ اٹھا۔ {ہلایا: عبرانی۔ پریشان}\n3. میرا دل میرے اندر گرم تھا، جب میں جلتی ہوئی آگ پر غور کر رہا تھا: {پھر} میں نے اپنی زبان سے کہا،\n4۔ خداوند، مجھے میرا انجام اور میرے دنوں کی پیمائش جاننے دے، تاکہ میں جان سکوں کہ میں کتنا کمزور ہوں۔ {کیسے...: یا، میرے پاس یہاں کیا وقت ہے}\n5۔ دیکھو، تو نے میرے دن کو ہاتھ کی چوڑائی بنا دیا ہے؛ اور میری عمر تمہارے سامنے کچھ بھی نہیں: واقعی ہر انسان اپنی بہترین حالت میں مکمل طور پر باطل ہے۔ سیلہ۔ {پر...: عبرانی۔ طے شد}\n6۔ یقینا ہر انسان بے مقصد چلتا ہے: یقینا وہ بے سود پریشان ہیں: وہ دولت جمع کرتا ہے، اور نہیں جانتا کہ انہیں کون جمع کرے گا۔ {ایک مغرور...: عبوری۔ ایک تصویر}\n7. اور اب، اے خداوند، میں کس چیز کا انتظار کر رہا ہوں؟ میری امید تم میں ہے۔\n8۔ مجھے میری تمام گناہوں سے نجات دے: مجھے بے وقوفوں کی ملامت نہ بناؤ۔\n9۔ میں بے وقوف تھا، میں نے منہ نہیں کھولا؛ کیونکہ تم نے یہ کیا۔\n10۔ اپنا وار مجھ سے دور کرو: میں تمہارے ہاتھ کے وار میں نگل گیا ہوں۔ {پھونک: عبوری۔ تنازعہ}\n11۔ جب تم سرزنش کے ذریعے انسان کو گناہوں پر اصلاح کرتے ہو، تو تم اس کی خوبصورتی کو پتنگوں کی طرح کھا جاتے ہو: یقینا ہر انسان خود غرض ہے۔ سیلہ۔ {اس کا...: عبرانی جو چیز اس میں چاہتی ہے وہ پگھل جائے}\n12. اے خداوند، میری دعا سنو اور میری پکار سنو؛ میرے آنسوؤں پر سکون نہ رکھو: کیونکہ میں تمہارے ساتھ اجنبی ہوں، اور ایک مسافر ہوں، جیسے میرے تمام باپ اجداد تھے۔\n13. اے مجھے بچا، تاکہ میں اپنی طاقت بحال کر سکوں، اس سے پہلے کہ میں یہاں سے جاؤں، اور مزید نہ رہوں۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] میں صبر سے خداوند کا انتظار کرتا رہا؛ اور وہ میری طرف جھکا، اور میری پکار سن لی۔ {میں نے انتظار کیا...: عبرانی۔ انتظار میں نے انتظار کیا}\n2۔ اس نے مجھے بھی ایک خوفناک گڑھے سے، کیچلی مٹی سے نکالا، اور میرے قدم ایک پتھر پر رکھے، {اور} میری راہ ہموار کی۔ {an...: عبرانی۔ شور کا گڑھا}\n3۔ اور اس نے میرے منہ میں نیا نغمہ رکھا ہے، {حتیٰ کہ} ہمارے خدا کی حمد بھی: بہت سے لوگ اسے دیکھیں گے، ڈریں گے، اور خداوند پر بھروسہ کریں گے۔\n4۔ مبارک ہے وہ انسان جو خداوند کو اپنا امانت دیتا ہے، اور نہ ہی مغرور لوگوں کی عزت کرتا ہے، نہ ہی جھوٹ کی طرف منہ موڑتے ہیں۔\n5۔ اے خداوند میرے خدا، بہت سے ہیں {جو آپ نے کیے ہیں} اور آپ کے خیالات {جو آپ کے لیے ہیں}: وہ آپ کے لیے ترتیب سے نہیں گنائے جا سکتے: {اگر} میں ان کا اعلان اور بات کرنا چاہوں، تو وہ گننے سے زیادہ ہیں۔ {وہ نہیں کر سکتے...: یا، کوئی انہیں تم پر حکم نہیں دے سکتا}\n6۔ قربانی اور نذرانہ جو تم نے نہیں چاہا؛ تم نے میرے کان کھول دیے: جلانے کی قربانی اور گناہ کی قربانی کی تمہیں ضرورت نہیں ہے۔ {کھولا گیا: عبوری۔ کھود گیا}\n7۔ پھر میں نے کہا، دیکھو، میں آ گیا ہوں: کتاب کی جلد میں {یہ میرے بارے میں لکھی گئی ہے}،\n8. اے میرے خدا، میں تیری مرضی پوری کرنے پر خوش ہوں: ہاں، تیرا قانون {ہے} میرے دل میں۔ {اندر...: عبرانی میرے آنتوں کے بیچ میں}\n9۔ میں نے بڑی جماعت میں راستبازی کی تبلیغ کی ہے: دیکھو، اے خداوند، تو جانتا ہے، میں نے اپنے ہونٹ چھپائے نہیں۔\n10. میں نے تمہاری راستبازی کو اپنے دل میں نہیں چھپایا؛ میں نے تیری وفاداری اور نجات کا اعلان کیا ہے: میں نے تمہاری محبت اور سچائی کو عظیم جماعت سے نہیں چھپایا۔\n11. اے خداوند، اپنی نرم رحمتیں مجھ سے نہ چھپاؤ: تیری محبت اور سچائی مجھے ہمیشہ محفوظ رکھے۔\n12۔ کیونکہ بے شمار برائیاں میرے گرد گھوم چکی ہیں: میری گناہوں نے مجھ پر قبضہ کر لیا ہے، یہاں تک کہ میں اوپر دیکھنے کے قابل نہیں ہوں؛ وہ میرے سر کے بالوں سے زیادہ ہیں: اس لیے میرا دل مجھے ناکام کر دیتا ہے۔ {فالیت: عبوری۔ فورسیکتھ}\n13. اے خداوند، مجھے نجات دینے میں خوش ہو: اے خداوند، جلدی کر میری مدد کرو۔\n14۔ جو میری روح کو تباہ کرنے کی کوشش کرتے ہیں، وہ سب مل کر شرمندہ اور الجھن میں مبتلا ہوں؛ انہیں پیچھے دھکیل دیا جائے اور شرمندہ کیا جائے جو مجھے برا چاہتے ہیں۔\n15. انہیں ان کی شرمندگی کے انعام کے لیے ویران کر دو جو مجھ سے کہیں، آہا، آہا۔\n16۔ جو بھی آپ کو تلاش کرتا ہے، وہ آپ پر خوش اور خوش ہو: جو تیری نجات سے محبت کرتا ہے وہ مسلسل کہے، خداوند بڑھا ہو۔\n17. لیکن میں غریب اور محتاج ہوں؛ {پھر بھی} خداوند مجھ پر غور کرتا ہے: تو میرا مددگار اور نجات دہندہ ہو؛ رکنا مت، اے میرے خدا۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] جو غریبوں پر غور کرتا ہے وہ مبارک ہے: خداوند اسے مشکل وقت میں نجات دے گا۔ {غریب: یا، کمزور، یا، بیمار} {وقت کے ساتھ...: عبرانی۔ برائی کے دن میں}\n2. خداوند اسے محفوظ رکھے گا، اور زندہ رکھے گا؛ {اور} وہ زمین پر برکت یافتہ ہوگا: اور تم اسے اس کے دشمنوں کی مرضی کے تابع نہیں کرو گے۔ {تم...: یا، تم نجات نہ دو}\n3. خداوند اسے سستی کے بستر پر مضبوط کرے گا: تو اس کی بیماری میں اس کا سارا بستر تیار کرو گے۔ {بنا: عبوری۔ ٹرن}\n4۔ میں نے کہا، اے خداوند، مجھ پر رحم فرما: میری جان کو شفا دے؛ کیونکہ میں نے تمہارے خلاف گناہ کیا ہے۔\n5۔ میرے دشمن میرے بارے میں برا کہتے ہیں، وہ کب مرے گا اور اس کا نام فنا ہو جائے گا؟\n6۔ اور اگر وہ مجھ سے ملنے آئے، تو وہ فضول باتیں کرتا ہے: اس کا دل بدکاری کو اپنے اندر جمع کر لیتا ہے؛ {جب} وہ بیرون ملک جاتا ہے، وہ بتاتا ہے۔\n7. جو سب مجھ سے نفرت کرتے ہیں وہ میرے خلاف سرگوشی کرتے ہیں: کیا وہ میرے درد کو بناتے ہیں۔ {میرا...: عبوری۔ میرے ساتھ برائی ہے}\n8۔ ایک بری بیماری، {وہ کہتے ہیں} اس سے چمٹ جاتی ہے: اور {اب} جب وہ لیٹتا ہے تو وہ دوبارہ نہیں اٹھے گا۔ {این...: عبرانی۔ بیلیال کی بات ہے}\n9۔ ہاں، میرا اپنا مانوس دوست، جس پر میں بھروسہ کرتا تھا، جس نے میری روٹی کھائی، اس نے میرے خلاف اپنا ایڑی اٹھا لی ہے۔ {میرا...: عبرانی۔ میرے امن کا آدمی} {اٹھایا گیا...: عبوری۔ بڑھا چڑھا کر}\n10۔ لیکن تو، اے خداوند، مجھ پر رحم فرما اور مجھے اٹھا دے، تاکہ میں ان کا بدلہ دوں۔\n11۔ اس سے میں جانتا ہوں کہ تم مجھ پر احسان کرتے ہو، کیونکہ میرا دشمن مجھ پر غالب نہیں آتا۔\n12۔ اور جہاں تک میرا تعلق ہے، تو مجھے میری پاکیزگی میں بلند کرے، اور ہمیشہ کے لیے اپنے چہرے کے سامنے مجھے آزما۔\n13۔ خداوند خدا اسرائیل کو ہمیشہ سے ہمیشہ کے لیے مبارک سمجھو۔ آمین، اور آمین۔","1. [چیف موسیقار، ماشیل، کورح کے بیٹوں کے لیے۔] جیسے ہرن پانی کے بہنے کے پیچھے ہانپتا ہے، ویسے ہی میری جان تیرے بعد آتی ہے، اے خدا۔ {مشکیل...: یا، ایک زبور جو بیٹوں کی تعلیم دیتا ہے، وغیرہ} {پینٹتھ: عبرانی۔ بریتھ}\n2. میری روح خدا کے لیے، زندہ خدا کے لیے پیاسی ہے: میں کب آؤں اور خدا کے سامنے ظاہر ہوں؟\n3. میرے آنسو دن رات میرا گوشت رہے ہیں، جبکہ وہ مسلسل مجھ سے کہتے ہیں، تیرا خدا کہاں ہے؟\n4۔ جب میں یہ {چیزیں} یاد کرتا ہوں، تو میں اپنی جان اپنے اندر بہا دیتا ہوں: کیونکہ میں ہجوم کے ساتھ گیا تھا، میں ان کے ساتھ خدا کے گھر گیا، خوشی اور حمد کی آواز کے ساتھ، اس ہجوم کے ساتھ جو مقدس دن رکھتی تھی۔\n5. اے میری جان، تو کیوں نیچے گر گئی ہو؟ اور {کیوں} تم مجھ میں بے چین ہو؟ خدا پر امید رکھو: کیونکہ میں پھر بھی اس کی عزت کروں گا {اس کے چہرے کی مدد کے لیے'۔ {کاسٹ: عبوری۔ جھک کر} {تعریف: یا، شکر ادا کرو} {اس کے لیے...: یا، اس کی موجودگی نجات ہے}\n6۔ اے میرے خدا، میری روح میرے اندر گر گئی ہے: اس لیے میں تمہیں اردن کی سرزمین سے اور ہرمونیوں سے، پہاڑ مزار سے یاد کروں گا۔ {پہاڑی...: یا، چھوٹی پہاڑی}\n7۔ گہرائی میں تمہارے پانی کے نالوں کی آواز پر گہرائی تک پکارتی ہے: تمہاری تمام لہریں اور تمہاری لہریں میرے اوپر سے گزر چکی ہیں۔\n8. {پھر بھی} خداوند دن میں اپنی محبت بھری مہربانی کا حکم دے گا، اور رات کو اس کا گیت {میرے ساتھ ہوگا}، {اور} میری زندگی کے خدا سے دعا کرے گا۔\n9. میں خدا سے کہوں گا میرا چٹان، تم مجھے کیوں بھول گئے؟ میں دشمن کے ظلم کی وجہ سے سوگ کیوں منا رہا ہوں؟\n10. {جیسا کہ} ہڈیوں میں تلوار کے ساتھ، میرے دشمن مجھے ملامت کرتے ہیں؛ جبکہ وہ روزانہ مجھ سے کہتے ہیں، تیرا خدا کہاں ہے؟ {تلوار: یا، مارنا}\n11. اے میری جان، تو کیوں نیچے گر گئی ہو؟ اور تم میرے اندر کیوں بے چین ہو؟ خدا پر امید رکھو: کیونکہ میں پھر بھی اس کی تعریف کروں گا، جو میرے چہرے کی صحت اور میرا خدا ہے۔","1. اے خدا، میرا فیصلہ فرما اور ایک بدکار قوم کے خلاف میرا مقدمہ چلا: اے مجھے دھوکہ باز اور ناانصافی والے انسان سے بچا۔ {بددین: یا، بے رحم} {دھوکہ باز...: عبرانی۔ دھوکہ دہی اور بدکاری کا آدمی}\n2۔ کیونکہ تو میری طاقت کے خدا ہو: تو مجھے کیوں چھوڑ دیتے ہو؟ میں دشمن کے ظلم کی وجہ سے سوگ کیوں منا رہا ہوں؟\n3. اے اپنی روشنی اور سچائی بھیجو: وہ مجھے رہنمائی دیں؛ انہیں مجھے تمہارے مقدس پہاڑ اور تمہارے خیموں تک لے جانے دو۔\n4۔ پھر میں خدا کے محراب پر جاؤں گا، خدا کے پاس اپنی بے پناہ خوشی کے ساتھ: ہاں، ہارپ پر میں تیری تعریف کروں گا، اے خدا میرے خدا۔ {میرا زیادہ...: عبرانی۔ میری خوشی کی خوشی}\n5. اے میری جان، تو کیوں نیچے گر گئی ہو؟ اور تم میرے اندر کیوں بے چین ہو؟ خدا پر امید رکھو: کیونکہ میں پھر بھی اس کی تعریف کروں گا، {جو میرے چہرے کی صحت ہے}، اور میرا خدا۔","1. [کورہ کے بیٹوں کے چیف موسیقار کو، ماشکیل کو۔] ہم نے اپنے کانوں سے سنا ہے، اے خدا، ہمارے آباؤ اجداد نے ہمیں بتایا ہے، {کیا کام کیا} تو نے ان کے زمانے میں، پرانے زمانے میں۔ {مشکل: یا، تعلیم کا}\n2. کیسے تم نے اپنے ہاتھ سے کافروں کو نکالا اور انہیں لگا دیا؛ تم نے لوگوں کو کیسے مصیبت دی اور انہیں نکال دیا۔\n3۔ کیونکہ انہوں نے اپنی تلوار سے زمین حاصل نہیں کی، نہ ہی ان کا اپنا بازو انہیں بچایا: سوائے تمہارا دایاں ہاتھ، تمہارا بازو اور تمہارے چہرے کی روشنی کے، کیونکہ تم نے ان پر احسان کیا۔\n4. اے خدا، تو میرے بادشاہ ہو: یعقوب کے لیے نجات کا حکم دے۔\n5۔ تیرے ذریعے ہم اپنے دشمنوں کو روند ڈالیں گے: تیرے نام کے ذریعے ہم ان کے سامنے قدم رکھیں گے جو ہمارے خلاف اٹھے۔\n6۔ کیونکہ میں اپنی کمان پر بھروسہ نہیں کروں گا، نہ ہی میری تلوار مجھے بچا سکے گی۔\n7۔ لیکن تو نے ہمیں ہمارے دشمنوں سے بچایا، اور ان لوگوں کو شرمندہ کیا جو ہم سے نفرت کرتے تھے۔\n8۔ ہم خدا میں سارا دن فخر کرتے ہیں اور ہمیشہ تیرے نام کی تعریف کرتے ہیں۔ سیلہ۔\n9۔ لیکن تم نے ہمیں شرمندہ کر دیا ہے؛ اور اپنی فوجوں کے ساتھ آگے نہ بڑھیں۔\n10۔ تو ہمیں دشمن سے پیچھے ہٹنے پر مجبور کرتا ہے: اور جو ہم سے نفرت کرتے ہیں وہ اپنے لیے لوٹ مار کرتے ہیں۔\n11۔ تو نے ہمیں گوشت کے لیے بھیڑ کی طرح دی ہے؛ اور ہمیں کافروں میں بکھیر دیا ہے۔ {جیسے...: عبرانی۔ گوشت کی بھیڑ کی طرح}\n12۔ تم اپنے لوگوں کو بے قیمت بیچتے ہو، اور اپنی دولت میں ان کی قیمت سے اضافہ نہیں کرتے۔ {for...: عبرانی۔ بغیر دولت کے}\n13۔ تم ہمیں ہمارے پڑوسیوں کے لیے ملامت کرتے ہو، ان کے لیے طنز اور طنز بناتے ہو جو ہمارے ارد گرد ہیں۔\n14۔ تو ہمیں کافروں میں ایک نعرہ بناتا ہے، لوگوں میں سر ہلانے والا بناتا ہے۔\n15. میری الجھن مسلسل میرے سامنے ہے، اور میرے چہرے کی شرمندگی نے مجھے ڈھانپ لیا ہے،\n16۔ اس کی آواز کے لیے جو ملامت اور کفر کرتا ہے؛ دشمن اور ایونجر کی وجہ سے۔\n17. یہ سب ہمارے اوپر آ گیا ہے؛ پھر بھی ہم نے تمہیں نہیں بھولا، اور نہ ہی تیری عہد میں جھوٹا سلوک کیا۔\n18۔ ہمارا دل پیچھے نہیں ہٹا، نہ ہی ہمارے قدم تیرے راستے سے ہٹے ہیں؛ {قدم: یا، جا رہا ہے}\n19۔ اگرچہ تم نے ہمیں اژدہوں کی جگہ توڑ دیا اور موت کے سائے میں ڈھانپ دیا۔\n20۔ اگر ہم نے اپنے خدا کا نام بھول گئے ہوں، یا کسی اجنبی خدا کی طرف ہاتھ بڑھائے ہوں؛\n21. کیا خدا اس کی تلاش نہیں کرے گا؟ کیونکہ وہ دل کے راز جانتا ہے۔\n22۔ جی ہاں، تیرے لیے ہم سارا دن مارے جاتے ہیں؛ ہمیں ذبح کے لیے بھیڑیں شمار کیا جاتا ہے۔\n23. جاگ جاؤ، اے خداوند، کیوں سو رہے ہو؟ اٹھو، ہمیں ہمیشہ کے لیے نہ چھوڑو۔\n24۔ کیوں تم اپنا چہرہ چھپاتے ہو، {اور} ہماری تکلیف اور ظلم کو بھول جاتے ہو؟\n25۔ کیونکہ ہماری روح خاک کے سامنے جھکی ہوئی ہے: ہمارا پیٹ زمین سے چمٹتا ہے۔\n26۔ ہماری مدد کے لیے اٹھو، اور اپنی رحمت کے لیے ہمیں نجات دے۔ {ہمارے...: عبرانی کے لیے۔ ہمارے لیے مدد}","1. [شوشنیم پر چیف موسیقار کے نام، کورہ کے بیٹوں کے لیے، مشکیل، محبت کا گیت۔] میرا دل ایک اچھا معاملہ کہہ رہا ہے: میں ان چیزوں کی بات کرتا ہوں جو میں نے بادشاہ کو چھو کر بنائی ہیں: میری زبان {ہے} ایک تیار مصنف کا قلم۔ {مشکل: یا، تعلیم کا} {شروع کر رہا ہے: عبوری۔ ابلتا ہے، یا، بلبلتا ہے}\n2۔ تم انسانوں کے بچوں سے زیادہ خوبصورت ہو: تمہارے ہونٹوں پر فضل ڈالا گیا ہے؛ اس لیے خدا نے تمہیں ہمیشہ کے لیے برکت دی ہے۔\n3. اپنی تلوار اپنے ران پر باندھ، اے {سب سے طاقتور}، اپنی شان اور عظمت کے ساتھ۔\n4۔ اور اپنی عظمت میں سچائی اور عاجزی کی وجہ سے خوش رہو؛ اور تمہارا دایاں ہاتھ تمہیں خوفناک باتیں سکھائے گا۔ {رائیڈ...: عبوری۔ خوش رہو، سواری کرو}\n5. تمہارے تیر بادشاہ کے دشمنوں کے دل میں تیز ہیں؛ {جس کے ذریعے} لوگ تمہارے ماتحت آ جاتے ہیں۔\n6. اے خدا، تیرا تخت {ہے} ہمیشہ ہمیشہ کے لیے: تیری بادشاہی کا عصا {ہے} ایک دائیں عصا۔\n7۔ تم راستبازی سے محبت کرتے ہو، اور برائی سے نفرت کرتے ہو: اس لیے خدا، تمہارا خدا، تمہیں اپنے ساتھیوں پر خوشی کے تیل سے مسح کیا ہے۔\n8۔ تمہارے تمام کپڑے مر، ایلو کی خوشبو سے آتے ہیں، {اور} کاسیا، ہاتھی دانت کے محلوں سے، جن سے تمہیں خوشی ملتی ہے۔\n9۔ بادشاہوں کی بیٹیاں آپ کی معزز عورتوں میں شامل تھیں: آپ کے دائیں ہاتھ پر اوفیر کی سونے کی ملکہ کھڑی تھی۔\n10۔ اے بیٹی، سنو اور غور کرو، اور اپنا کان جھکاؤ؛ اپنے لوگوں اور اپنے والد کے گھر کو بھی بھول جاؤ؛\n11۔ بادشاہ بھی تمہاری خوبصورتی کی بہت خواہش کرے گا: کیونکہ وہ تمہارا رب ہے؛ اور اس کی عبادت کرو۔\n12۔ اور صور کی بیٹی {وہاں ہوگی} ایک تحفہ کے ساتھ؛ حتیٰ کہ امیر لوگ بھی تمہاری عنایت کی درخواست کریں گے۔ {فیور: عبرانی۔ چہرہ}\n13۔ بادشاہ کی بیٹی اندر سے بہت شاندار ہے: اس کا لباس سونے کا ہے۔\n14۔ اسے سلائی کے لباس میں بادشاہ کے پاس لایا جائے گا: اس کے ساتھی جو اس کے پیچھے آئیں گے، وہ کنواریاں تمہارے پاس لائی جائیں گی۔\n15۔ خوشی اور خوشی کے ساتھ انہیں لایا جائے گا: وہ بادشاہ کے محل میں داخل ہوں گے۔\n16۔ تمہارے باپ دادا کی جگہ تمہارے بچے ہوں گے، جنہیں تم پوری زمین پر شہزادہ بنا سکتے ہو۔\n17۔ میں تیرا نام ہر نسل میں یاد رکھوں گا: اسی لیے لوگ ہمیشہ ہمیشہ تمہاری تعریف کریں گے۔","1. [کورہ کے بیٹوں کے چیف موسیقار کے نام، الموتھ پر ایک گیت۔] خدا ہماری پناہ گاہ اور طاقت ہے، مصیبت میں بہت حاضر مددگار۔ {for: or, of}\n2. لہٰذا ہم نہیں ڈریں گے، چاہے زمین ہٹا دی جائے، اور پہاڑ سمندر کے بیچ میں لے جایا جائے؛ {درمیان...: عبوری۔ سمندروں کا دل}\n3. {اگرچہ} اس کے پانی گرجتے ہیں {اور} پریشان ہوتے ہیں، {اگرچہ} پہاڑ اس کی لہروں سے ہلتے ہیں۔ سیلہ۔\n4۔ {ایک دریا ہے}، جس کے کنارے خدا کے شہر کو خوش کریں گے، جو سب سے بلند کے خیموں کی مقدس {جگہ} ہے۔\n5۔ خدا {ہے} اس کے درمیان؛ وہ متاثر نہیں ہوگی: خدا اس کی مدد کرے گا، {اور وہ بھی} بالکل جلدی۔ {اور...: عبرانی۔ جب صبح آتی ہے}\n6۔ کافر غصے میں آئے، سلطنتیں متاثر ہوئیں: اس نے اپنی آواز نکالی، زمین پگھل گئی۔\n7۔ رب لشکروں {ہے} ہمارے ساتھ؛ یعقوب کا خدا ہمارا پناہ گاہ ہے۔ سیلہ۔ {ہمارا...: عبرانی۔ ہمارے لیے ایک بلند مقام}\n8۔ آؤ، خداوند کے اعمال دیکھو، اس نے زمین میں کتنی بربادیاں کی ہیں۔\n9۔ وہ جنگیں زمین کے آخر تک ختم کرنے کے لیے تیار کرتا ہے؛ وہ کمان توڑتا ہے، اور نیزہ کو چیر پھاڑ کر کاٹتا ہے؛ وہ رتھ کو آگ میں جلا دیتا ہے۔\n10۔ خاموش رہو، اور جان لو کہ میں خدا ہوں: میں کافروں میں بلند ہوں گا، زمین پر بلند ہوں گا۔\n11۔ لشکروں کا رب {ہے} ہمارے ساتھ؛ یعقوب کا خدا ہمارا پناہ گاہ ہے۔ سیلہ۔","1. [اہم موسیقار کے نام، قارح کے بیٹوں کے لیے زبور۔] اے سب لوگو، تالیاں بجاؤ؛ فتح کی آواز کے ساتھ خدا کو پکار جاؤ۔ {for: or, of}\n2. کیونکہ خداوند سب سے بلند {ہے} خوفناک ہے؛ {وہ} زمین پر ایک عظیم بادشاہ ہے۔\n3۔ وہ ہمارے ماتحت لوگوں کو زیر کرے گا، اور قوموں کو جو ہمارے قدموں تلے ہیں۔\n4۔ وہ ہمارے لیے وراثت کا انتخاب کرے گا، یعقوب کی عظمت جس سے وہ محبت کرتا تھا۔ سیلہ۔\n5۔ خدا چیخ کے ساتھ اٹھتا ہے، خداوند ترمپٹ کی آواز کے ساتھ۔\n6. خدا کی حمد گاؤ، حمد و ثنا گاؤ: ہمارے بادشاہ کی حمد و ثنا گاؤ، حمد و ثنا گاؤ۔\n7۔ کیونکہ خدا {ہے} زمین کا بادشاہ: سمجھ بوجھ کے ساتھ حمد و ثنا گاؤ۔ {ساتھ: یا، ہر وہ شخص جس کے پاس ہے}\n8۔ خدا کافروں پر حکمرانی کرتا ہے: خدا اپنی پاکیزگی کے تخت پر بیٹھا ہے۔\n9۔ قوم کے شہزادے اکٹھے ہیں، {حتی} ابراہیم کے خدا کے لوگ بھی: کیونکہ زمین کی ڈھالیں {محفوظ} خدا کی ہیں: وہ بہت بلند ہے۔ {شہزادے...: یا، لوگوں کی رضاکارانہ رائے ابراہیم کے خدا کی قوم کے پاس جمع ہو جاتی ہے}","1. [ایک گیت {اور} زبور کورہ کے بیٹوں کے لیے۔] عظیم خداوند ہے، اور ہمارے خدا کے شہر میں، اس کی پاکیزگی کے پہاڑ میں بہت زیادہ تعریف کی جانی چاہیے۔ {for: or, of}\n2۔ حالات کے لیے خوبصورت، پوری زمین کی خوشی، {ہے} ماؤنٹ صیون پر، {شمال کے کناروں پر}، عظیم بادشاہ کا شہر۔\n3۔ خدا اس کے محلات میں پناہ گاہ کے طور پر جانا جاتا ہے۔\n4۔ کیونکہ دیکھو، بادشاہ جمع ہو گئے، وہ اکٹھے گزرے۔\n5۔ انہوں نے اسے دیکھا، اور اس لیے وہ حیران رہ گئے؛ وہ پریشان تھے، {اور} جلدی سے وہاں سے چلے گئے۔\n6۔ وہاں خوف نے ان پر قبضہ کر لیا، {اور} درد، جیسے ایک عورت کی تکلیف میں۔\n7۔ تو ترشیش کے جہازوں کو مشرقی ہوا سے توڑتا ہے۔\n8۔ جیسا کہ ہم نے سنا ہے، ویسے ہی ہم نے خداوند لشکروں کے شہر میں، ہمارے خدا کے شہر میں دیکھا ہے: خدا اسے ہمیشہ کے لیے قائم کرے گا۔ سیلہ۔\n9۔ اے خدا، تیری محبت بھری مہربانی کے بارے میں سوچا ہے، اے خدا، تیرے مندر کے بیچ۔\n10۔ تیرے نام کے مطابق، اے خدا، تیری تعریف زمین کے کونے تک ہے: تیرا دایاں ہاتھ راستبازی سے بھرا ہوا ہے۔\n11۔ کوہ صیون خوش ہو، یہوداہ کی بیٹیاں تمہارے فیصلوں کی وجہ سے خوش ہوں۔\n12۔ صہیون کے گرد گھومو، اور اس کے گرد گھومو: اس کے میناروں کو بتاؤ۔\n13۔ اس کی دیواروں کو اچھی طرح دیکھو، اس کے محلات پر غور کرو؛ تاکہ تم یہ بات آنے والی نسل کو بتا سکو۔ {مارک...: عبرانی۔ اپنا دل لگا لو} {غور کریں: یا، اٹھیں}\n14. کیونکہ یہ خدا {ہے} ہمارا خدا ہمیشہ ہمیشہ کے لیے: وہ ہمارا رہنما {حتی} موت تک ہوگا۔","1. [اہم موسیقار کے نام، قارح کے بیٹوں کے لیے زبور۔] یہ سنو، تمام لوگو؛ دنیا کے تمام باشندوں، سنو: {for: or, of}\n2۔ کم اور اعلیٰ دونوں، امیر اور غریب، ایک ساتھ۔\n3۔ میرا منہ حکمت کی بات کرے گا؛ اور میرے دل کی مراقبہ سمجھ بوجھ کی ہوگی۔\n4۔ میں اپنی کان ایک تمثیل کی طرف جھکاؤں گا: میں اپنی تاریک کہاوت ہارپ پر کھولوں گا۔\n5. برائی کے دنوں میں مجھے کیوں ڈرنا چاہیے، {جب} میرے قدموں کی گناہ مجھے گھیرے گی؟\n6۔ وہ جو اپنی دولت پر بھروسہ کرتے ہیں اور اپنی دولت کی کثرت پر فخر کرتے ہیں؛\n7. ان میں سے کوئی بھی اپنے بھائی کو کسی بھی طرح نجات نہیں دے سکتا، اور نہ ہی خدا کو اس کے بدلے تاوان دے سکتا ہے:\n8. (کیونکہ ان کی روح کی نجات قیمتی ہے، اور ہمیشہ کے لیے ختم ہو جاتی ہے:)\n9۔ کہ وہ ہمیشہ زندہ رہے، {اور} فساد نہ دیکھے۔\n10۔ کیونکہ وہ دیکھتا ہے کہ دانا مر جاتے ہیں، اسی طرح بیوقوف اور ظالم ہلاک ہو جاتے ہیں، اور اپنی دولت دوسروں کے لیے چھوڑ دیتے ہیں۔\n11۔ ان کا اندرونی خیال {یہ ہے} کہ ان کے گھر {ہمیشہ قائم رہیں گے}، {اور} ان کے مسکن تمام نسلوں تک؛ وہ اپنی زمینوں کو اپنے ہی ناموں پر پکارتے ہیں۔ {سب...: عبرانی۔ نسل اور نسل}\n12. پھر بھی انسان {عزت میں} قائم نہیں رہتا: وہ ان جانوروں کی مانند ہے جو مر جاتے ہیں۔\n13. یہ ان کا طریقہ ان کی حماقت ہے: پھر بھی ان کی نسلیں ان کے اقوال کی منظوری دیتی ہیں۔ سیلہ۔ {منظور...: عبرانی۔ ان کے منہ میں خوشی}\n14۔ بھیڑوں کی طرح انہیں قبر میں دفن کیا جاتا ہے؛ موت ان پر کھائے گی؛ اور سیدھے لوگ صبح ان پر حکمرانی کریں گے؛ اور ان کی خوبصورتی قبر میں ان کے گھر سے نگل جائے گی۔ {خوبصورتی: یا، طاقت} {قبر میں...: یا، قبر ہر ایک کے لیے رہائش گاہ ہے}\n15. لیکن خدا میری روح کو قبر کی طاقت سے نجات دے گا: کیونکہ وہ مجھے قبول کرے گا۔ سیلہ۔ {پاور: عبرانی ہاتھ} {قبر: یا، جہنم}\n16۔ جب کوئی امیر ہو جائے، جب اس کے گھر کی شان بڑھے تو نہ ڈرو؛\n17۔ کیونکہ جب وہ مرے گا تو کچھ بھی نہیں لے جائے گا: اس کی شان اس کے بعد نہیں آئے گی۔\n18۔ اگرچہ جب وہ زندہ رہا تو اس نے اپنی روح کو برکت دی: اور {لوگ} تمہاری تعریف کریں گے، جب تم اپنے لیے اچھا کرو گے۔ {جبکہ...: عبرانی۔ اپنی زندگی میں}\n19۔ وہ اپنے باپ و اجداد کی نسل میں جائے گا؛ وہ کبھی روشنی نہیں دیکھ سکیں گے۔ {وہ...: عبرانی۔ روح کرے گی}\n20۔ انسان {یعنی} عزت میں ہے، اور جو نہیں سمجھتا، ان جانوروں کی طرح ہے {جو} مر جاتے ہیں۔","1. [آساف کا زبور۔] عظیم خدا، {حتیٰ کہ} خداوند بھی، نے زمین کو سورج کے طلوع سے لے کر اس کے غروب ہونے تک بلایا اور بلایا ہے۔ {of...: یا، آساف کے لیے}\n2. صیون سے، خوبصورتی کی کمال، خدا چمکا ہے۔\n3۔ ہمارا خدا آئے گا، اور خاموش نہیں رہے گا: اس کے سامنے آگ جل جائے گی، اور اس کے ارد گرد بہت طوفانی ہوگی۔\n4۔ وہ آسمانوں کو اوپر سے اور زمین سے پکار گا، تاکہ وہ اپنے لوگوں کا فیصلہ کرے۔\n5. میرے مقدسین کو میرے پاس جمع کرو؛ وہ جنہوں نے قربانی کے ذریعے مجھ سے عہد کیا ہے۔\n6۔ اور آسمان اس کی راستبازی کا اعلان کرے گا: کیونکہ خدا خود فیصلہ کرتا ہے۔ سیلہ۔\n7۔ سنو، اے میرے لوگو، اور میں بولوں گا؛ اے اسرائیل، اور میں تیرے خلاف گواہی دوں گا: میں خدا ہوں، یہاں تک کہ تیرا خدا بھی۔\n8۔ میں تمہیں تمہاری قربانیوں یا جلانے کی قربانیوں پر ملامت نہیں کروں گا، {جو تم ہمیشہ میرے سامنے رہے}۔\n9۔ میں تمہارے گھر سے کوئی بیل نہیں نکالوں گا، {اور نہ ہی} وہ تمہارے کپڑوں سے بکرے گا۔\n10۔ جنگل کا ہر جانور {میرا} ہے، {اور} ہزار پہاڑیوں پر مویشی۔\n11۔ میں پہاڑوں کے تمام پرندوں کو جانتا ہوں: اور میدان کے جنگلی جانور میرے ہیں۔ {میرا: عبرانی۔ میرے ساتھ}\n12. اگر مجھے بھوک لگی ہوتی تو میں تمہیں نہ بتاتا: کیونکہ دنیا میری ہے، اور اس کی بھرپوریت بھی۔\n13. کیا میں بیلوں کا گوشت کھاؤں گا، یا بکریوں کا خون پیوں گا؟\n14۔ خدا کے سامنے شکر ادا کرنا؛ اور اپنے عہد سب سے بلند کو ادا کرو:\n15۔ اور مصیبت کے دن مجھے پکار: میں تمہیں نجات دوں گا، اور تم میری جلال بخشو گے۔\n16۔ لیکن بدکار خدا سے فرماتا ہے، تمہیں میرے قوانین کا اعلان کرنے کے لیے کیا کرنا ہے، یا {کہ} کہ تم میرا عہد اپنے منہ میں لے لو؟\n17۔ تم دیکھتے ہو کہ تم تعلیم سے محروم ہو رہے ہو، اور میرے الفاظ کو تمہارے پیچھے چھپا رہے ہو۔\n18۔ جب تم نے کسی چور کو دیکھا، تو تم نے اس سے رضامندی ظاہر کی، اور کے ساتھ شریک رہے ہو۔ {ہسٹ...: عببرانی۔ تمہارا حصہ ساتھ تھا}\n19۔ تو اپنا منہ برائی کے لیے دیتا ہے، اور تمہاری زبان دھوکہ دہی کو فریم کرتی ہے۔ {دیویسٹ: عبوری۔ بھیجیں}\n20۔ تم بیٹھے ہو {اور} اپنے بھائی کے خلاف بولتے ہو؛ تم اپنی ماں کے بیٹے کی بدنامی کرتے ہو۔\n21۔ یہ {کام} تم نے کیے ہیں، اور میں خاموش رہا؛ تم نے سوچا کہ میں تمہاری طرح مکمل طور پر {ایسا ہی} ہوں: {لیکن} میں تمہیں ڈانٹوں گا، اور {انہیں} کو تمہاری آنکھوں کے سامنے ترتیب دوں گا۔\n22. اب یہ سوچو، اے خدا کو بھول جاؤ، ورنہ میں تمہیں ٹکڑے ٹکڑے کر دوں گا، اور کوئی نہیں رہے گا جو نجات دے۔\n23۔ جو تعریف پیش کرے گا، وہ مجھے جلال بخشتا ہے: اور جو اس کی گفتگو کو درست کرے، اسے میں خدا کی نجات دکھاؤں گا۔ {وہ...: عببرانی۔ جو اس کے راستے پر قابو پاتا ہے}","1. [چیف موسیقار، زبور داؤد کے نام، جب ناتھن نبی اس کے پاس آیا، جب وہ بیت شبع چلا گیا تھا۔] اے خدا، اپنی محبت کے مطابق مجھ پر رحم فرما: تیری نرم رحمتوں کی کثرت کے مطابق میری گناہوں کو مٹا دے۔\n2. مجھے میری گناہوں سے مکمل طور پر دھو دو، اور میرے گناہ سے پاک کرو۔\n3۔ کیونکہ میں اپنی گناہوں کو تسلیم کرتا ہوں: اور میرا گناہ ہمیشہ میرے سامنے ہے۔\n4۔ صرف تمہارے خلاف، میں نے تمہارے سامنے گناہ کیا ہے، اور یہ برا کیا ہے، تاکہ تم بات کرتے وقت حق بجانب ہو سکو، اور جب تم فیصلہ کرو تو واضح ہو جاؤ۔\n5۔ دیکھو، میں گناہوں میں ڈھل گیا ہوں؛ اور گناہ میں میری ماں نے مجھے حاملہ کیا۔ {تصور کرو...: عبرانی۔ مجھے گرم کرو}\n6۔ دیکھو، تم اندرونی حصوں میں سچائی چاہتے ہو: اور پوشیدہ حصے میں تو مجھے حکمت سکھاؤ گی۔\n7۔ مجھے ہسپ سے صاف کرو، اور میں پاک ہو جاؤں گا: مجھے دھو لو، اور میں برف سے بھی زیادہ سفید ہو جاؤں گا۔\n8۔ مجھے خوشی اور خوشی سناؤ؛ {کہ} وہ ہڈیاں جو تم نے توڑ دی ہیں، خوش ہو جائیں۔\n9. اپنا چہرہ میرے گناہوں سے چھپا دے، اور میری تمام گناہوں کو مٹا دے۔\n10. اے خدا، میرے اندر صاف دل پیدا کر؛ اور اپنے اندر ایک صحیح روح کو تازہ کروں۔ {دائیں: یا، مستقل}\n11۔ مجھے اپنی موجودگی سے دور نہ کرو؛ اور اپنا روح القدس مجھ سے نہ چھیننا۔\n12۔ اپنی نجات کی خوشی مجھے واپس دے؛ اور مجھے اپنی آزاد روح سے سہارا دینا۔\n13. {پھر} میں گناہگاروں کو تمہارے طریقے سکھاؤں گا؛ اور گناہ گار تمہارے پاس تبدیل ہو جائیں گے۔\n14. اے خدا، اے میری نجات کے خدا، مجھے خونریزی سے بچا: اور میری زبان تیری راستبازی کا بلند آواز میں گائے گی۔ {خون کی گناہی: عبرانی۔ bloods}\n15. اے خداوند، میرے ہونٹ کھول؛ اور میرا منہ تمہاری تعریف کرے گا۔\n16۔ کیونکہ تم قربانی نہیں چاہتے؛ ورنہ میں دے دیتا: تم جلانے کی قربانی میں خوش نہیں ہوتا۔ {ورنہ...: یا، کہ مجھے کرنا چاہیے}\n17. خدا کی قربانیاں ایک ٹوٹی ہوئی روح ہیں: ٹوٹا ہوا اور پشیمان دل، اے خدا، تو اس سے نفرت نہیں کرو گے۔\n18۔ اپنی مرضی سے صیون کے لیے بھلائی کرو: یروشلم کی دیواریں تعمیر کرو۔\n19۔ پھر تم راستبازی کی قربانیوں، سلائی کی قربانی اور مکمل سوختی قربانی سے خوش ہو جاؤ گے: پھر وہ تمہارے مذبح پر بیل پیش کریں گے۔","1. [اہم موسیقار، ماشیل، {ایک زبور} داؤد کے لیے، جب ڈوگ دی ایڈومیٹ آیا اور ساؤل کو بتایا، اور اس سے کہا، داؤد اہیم لیک کے گھر آیا ہے۔] تم شرارتوں میں کیوں فخر کرتے ہو، اے طاقتور آدمی؟ خدا کی بھلائی {ہمیشہ برقرار رہتی ہے}۔ {مشکل: یا، تعلیم کا}\n2. تیری زبان شرارتیں کرتی ہے؛ جیسے کوئی تیز دھارا، دھوکہ دہی سے کام کر رہا ہو۔\n3۔ تم برائی سے بھلائی سے زیادہ محبت کرتے ہو؛ {اور} راستبازی کی بجائے جھوٹ بولنا۔ سیلہ۔\n4۔ تم تمام کھاتے ہوئے الفاظ سے محبت کرتے ہو، اے دھوکہ باز زبان۔ {اے تم...: یا، اور دھوکہ باز زبان}\n5۔ خدا بھی تمہیں ہمیشہ کے لیے تباہ کر دے گا، تمہیں لے جائے گا، تمہیں {تمہارے} گھر سے نکال لے گا، اور تمہیں زندوں کی سرزمین سے نکال دے گا۔ سیلہ۔ {تباہ کریں...: عببرانی۔ تم پر قابو پا لو}\n6۔ نیک لوگ بھی دیکھیں گے، ڈریں گے، اور اس پر ہنسیں گے:\n7. دیکھو، {یہ} وہ آدمی ہے {جس نے} خدا کو اپنی طاقت نہیں دی؛ لیکن اپنی دولت کی فراوانی پر بھروسہ کیا، {اور} اپنی برائی میں خود کو مضبوط کیا۔ {برائی: یا، مادہ}\n8. لیکن میں خدا کے گھر میں سبز زیتون کے درخت کی طرح ہوں: میں ہمیشہ کے لیے خدا کی رحمت پر بھروسہ کرتا ہوں۔\n9۔ میں ہمیشہ تمہاری تعریف کروں گا، کیونکہ تم نے یہ کیا ہے: اور میں تمہارے نام کا انتظار کروں گا؛ کیونکہ یہ تمہارے مقدسین کے سامنے اچھا ہے۔","1. [مہالات کے چیف موسیقار، مشکیل، {داؤد کا زبور} کے نام۔] بیوقوف نے اپنے دل میں کہا ہے، {کوئی خدا نہیں ہے}۔ وہ بدعنوان ہیں، اور انہوں نے گھناؤنا گناہ کیا ہے: کوئی بھی اچھا کام نہیں کرتا۔ {مشکل: یا، تعلیم کا}\n2۔ خدا نے آسمان سے انسانوں کے بچوں کو دیکھا، تاکہ دیکھے کہ کیا کوئی ایسا ہے جو سمجھتا ہے، خدا کی تلاش کرتا ہے۔\n3۔ ان میں سے ہر ایک واپس جا چکا ہے: وہ مکمل طور پر گندے ہو چکے ہیں؛ کوئی بھی اچھا کام نہیں کرتا، نہیں، کوئی بھی نہیں۔\n4. کیا بدکاری کے کارکنوں کو علم نہیں؟ جو میرے لوگوں کو اسی طرح کھاتے ہیں جیسے وہ روٹی کھاتے ہیں: انہوں نے خدا سے دعا نہیں کی۔\n5۔ وہ بہت خوفزدہ تھے، {جہاں} کوئی خوف نہیں تھا: کیونکہ خدا نے اس کی ہڈیاں بکھیر دی ہیں جو تمہارے خلاف خیمہ زن ہے: تم نے {ان} کو شرمندہ کر دیا ہے، کیونکہ خدا نے انہیں حقیر سمجھا ہے۔ {تھے...: عبرانی وہ خوف سے ڈرتے تھے}\n6۔ کاش اسرائیل کی نجات صیون سے نکل آتی! جب خدا اپنی قوم کی قید واپس لے آئے گا، یعقوب خوش ہوگا، اور اسرائیل خوش ہوگا۔ {اوہ وہ...: عبرانی۔ کون نجات دے گا، وغیرہ}","1. [نیگینوت کے چیف موسیقار، ماشیل، {زبور} داؤد کے لیے، جب زیفیم آئے اور ساؤل سے کہا، کیا داؤد ہمارے ساتھ چھپتا نہیں؟] اے خدا، اپنے نام سے مجھے بچا اور اپنی طاقت سے فیصلہ فرما۔ {چیف...: یا، نگران} {مشکل: یا، تعلیم کا}\n2. اے خدا، میری دعا سنو؛ میرے منہ کی باتوں کو سنو۔\n3۔ کیونکہ اجنبی میرے خلاف اٹھے ہیں، اور ظالم میری روح کی تلاش میں ہیں: انہوں نے خدا کو اپنے سامنے نہیں رکھا۔ سیلہ۔\n4۔ دیکھو، خدا {ہے} میرا مددگار: خداوند {ہے} ان لوگوں کے ساتھ جو میری روح کی حفاظت کرتے ہیں۔\n5۔ وہ میرے دشمنوں کو برائی کا بدلہ دے گا: انہیں اپنی سچائی میں کاٹ دے۔ {میرا...: عبرانی۔ جو مجھے دیکھتے ہیں}\n6۔ میں آپ کو آزادانہ طور پر قربانی دوں گا: اے خداوند، میں تیرے نام کی حمد کروں گا؛ کیونکہ {یہ} اچھا ہے۔\n7۔ کیونکہ اس نے مجھے ہر مصیبت سے بچایا؛ اور میری آنکھ نے میرے دشمنوں پر اس کی خواہش دیکھی۔","1. [نیگینوت کے چیف موسیقار، مشکیل، {داؤد کا زبور} کے نام۔] اے خدا، میری دعا کو سن لے؛ اور اپنی فریاد سے خود کو نہ چھپاؤ۔ {چیف...: یا، نگران} {مشکل: یا، تعلیم کا}\n2. میری خدمت کرو اور میری سنو: میں اپنی شکایت میں سوگ مناتا ہوں، اور شور کرتا ہوں؛\n3۔ دشمن کی آواز کی وجہ سے، بدکاروں کے ظلم کی وجہ سے: کیونکہ وہ مجھ پر ظلم کرتے ہیں، اور غصے میں مجھ سے نفرت کرتے ہیں۔\n4. میرا دل اندر سے درد میں ہے: اور موت کے خوف مجھ پر چھا گئے ہیں۔\n5۔ خوف اور کپکپاہٹ مجھ پر چھا گئی ہے، اور خوف نے مجھے اپنی لپیٹ میں لے لیا ہے۔ {مغلوب ہو کر: عبوری۔ کورڈ}\n6۔ اور میں نے کہا، اوہ کاش میرے پر کبوتر جیسے ہوتے! {تب بھی} میں اڑ جاؤں گا، اور آرام کروں گا۔\n7. دیکھو، {پھر} میں دور بھٹک جاؤں گا، {اور} جنگل میں ہی رہ جاؤں گا۔ سیلہ۔\n8. میں تیز ہوا کے طوفان {اور} طوفان سے اپنی فرار کو تیز کروں گا۔\n9۔ اے خداوند، ان کی زبانیں تقسیم کر دے: کیونکہ میں نے شہر میں تشدد اور کشمکش دیکھی ہے۔\n10۔ دن رات وہ اس کی دیواروں پر گھومتے ہیں: شرارت اور غم بھی اس کے بیچ میں ہیں۔\n11. اس کے بیچ میں بدی {ہے}: دھوکہ اور فریب اس کی گلیوں سے نہیں ہٹتے۔\n12۔ کیونکہ {یہ کوئی دشمن نہیں تھا {جس نے} مجھے ملامت کی؛ تب میں اسے برداشت کر سکتا تھا: نہ ہی وہ {وہ} جو مجھ سے نفرت کرتا تھا {جس نے} اپنے آپ کو میرے خلاف بڑھا چڑھا کر پیش کیا؛ تب میں خود کو اس سے چھپا لیتا:\n13. لیکن وہ تو تھا، میرا برابر آدمی، میرا رہنما اور میرا جاننے والا۔ {میرا برابر: عبرانی۔ میری رینک کے مطابق}\n14۔ ہم نے مل کر میٹھے مشورے لیے، {اور} خدا کے گھر کی طرف چلے۔ {ہم...: عبرانی۔ کس نے مشورے کو میٹھا کیا}\n15۔ موت ان پر قبضہ کر لے، {اور} انہیں جلدی جہنم میں لے جائے: کیونکہ ان کے گھروں میں برائی {اور} ان کے درمیان ہے۔ {جہنم: یا، قبر}\n16۔ جہاں تک میرا تعلق ہے، میں خدا کو پکاروں گا؛ اور خداوند مجھے بچائے گا۔\n17۔ شام، صبح، اور دوپہر کو، میں دعا کروں گا، اور بلند آواز میں پکاروں گا: اور وہ میری آواز سنے گا۔\n18۔ اس نے میری روح کو اس جنگ سے امن میں بچا لیا جو میرے خلاف تھی: کیونکہ میرے ساتھ بہت سے لوگ تھے۔\n19۔ خدا انہیں سنے گا، اور انہیں تکلیف دے گا، حتیٰ کہ پرانے زمانے کے رہنے والوں کو بھی۔ سیلہ۔ کیونکہ ان میں کوئی تبدیلی نہیں آتی، اس لیے وہ خدا سے نہیں ڈرتے۔ {کیونکہ...: یا، جس کے ساتھ بھی کوئی تبدیلی نہیں ہوتی، پھر بھی وہ}\n20۔ اس نے اپنے ہاتھ ان لوگوں کے خلاف اٹھائے جو اس کے ساتھ امن میں ہیں: اس نے اپنا عہد توڑ دیا ہے۔ {ٹوٹا ہوا: عبوری۔ بے حرمتی}\n21. {اس کے منہ کے الفاظ} مکھن کی طرح نرم تھے، لیکن جنگ {تھی} اس کے دل میں: اس کے الفاظ تیل سے نرم تھے، پھر بھی {تھے} تلواریں کھینچ رہے تھے۔\n22۔ اپنا بوجھ خداوند پر ڈال دو، اور وہ تمہیں سہارا دے گا: وہ کبھی نیک لوگوں کو متاثر نہیں ہونے دے گا۔ {بوجھ: یا، تحفہ}\n23. لیکن تو، اے خدا، انہیں تباہی کے گڑھے میں لے آؤ: خونخوار اور دھوکہ باز لوگ اپنی زندگی کا آدھا حصہ نہیں گزاریں گے؛ لیکن میں تم پر بھروسہ کروں گا۔ {خون آلود...: عببرانی۔ خون اور فریب کے لوگ} {ضرور...: عبرانی۔ آدھے دن بھی نہیں ہوں گے}","1. [یوناتھیلمرخوکیم کے چیف موسیقار کو، داؤد کے میختم کو، جب فلسطینیوں نے اسے گت میں لیا۔] اے خدا، مجھ پر رحم فرما: کیونکہ انسان مجھے نگل لے گا؛ وہ روزانہ لڑ رہا ہے اور مجھ پر ظلم کرتا ہے۔ {مچٹم...: یا، داؤد کا سنہری زبور}\n2. میرے دشمن روزانہ {مجھے} نگل جائیں گے: کیونکہ {وہ} بہت سے ہیں جو میرے خلاف لڑتے ہیں، اے سب سے بلند۔ {دشمن: عبرانی۔ مبصرین}\n3۔ جب میں ڈروں گا، میں تم پر بھروسہ کروں گا۔\n4۔ میں خدا پر اس کے کلام کی حمد کروں گا، خدا پر بھروسہ کیا ہے؛ میں نہیں ڈروں گا کہ گوشت میرے ساتھ کیا کر سکتا ہے۔\n5. ہر روز وہ میرے الفاظ چھین لیتے ہیں: ان کے سارے خیالات میرے خلاف ہیں کیونکہ وہ برائی کرتے ہیں۔\n6. وہ خود کو جمع کرتے ہیں، چھپتے ہیں، میرے قدم نشان زد کرتے ہیں، جب وہ میری روح کا انتظار کرتے ہیں۔\n7. کیا وہ بدکاری سے بچ نکلیں گے؟ اپنے غصے میں لوگوں کو گرا دو، اے خدا۔\n8۔ تم میری بھٹکیاں سناتے ہو: میرے آنسو اپنی بوتل میں ڈالو: {کیا وہ تمہاری کتاب میں نہیں ہیں؟'\n9۔ جب میں تجھ سے پکاروں گا، تو میرے دشمن پلٹ جائیں گے: یہ میں جانتا ہوں؛ کیونکہ خدا {ہے} میرے لیے۔\n10۔ خدا میں اس کے کلام کی حمد کروں گا: خداوند میں اس کے کلام کی تعریف کروں گا۔\n11۔ میں نے خدا پر بھروسہ کیا ہے: میں نہیں ڈروں گا کہ انسان میرے ساتھ کیا کر سکتا ہے۔\n12. اے خدا، تیری قسمیں مجھ پر ہیں: میں تجھے تعریف کروں گا۔\n13۔ کیونکہ تو نے میری جان کو موت سے بچا لیا ہے: کیا تم میرے قدموں کو گرنے سے نہیں بچاؤ گے، تاکہ میں زندہ کی روشنی میں خدا کے حضور چل سکوں؟","1. [چیف موسیقار، الٹاشتھ، داؤد کے میختم کو، جب وہ غار میں ساؤل سے بھاگ رہا تھا۔] اے خدا، مجھ پر رحم فرما، کیونکہ میری جان تم پر بھروسہ کرتی ہے: ہاں، تیرے پروں کے سائے میں میں پناہ لوں گا، جب تک {یہ} آفات ختم نہ ہو جائیں۔ {الٹاشیتھ: یا، تباہ نہ کرو} {میختم: یا، ایک سنہری زبور}\n2۔ میں بلند ترین خدا سے پکاروں گا؛ خدا کے لیے جو میرے لیے سب کچھ انجام دیتا ہے۔\n3۔ وہ آسمان سے بھیجے گا، اور مجھے اس ملامت سے بچا لے گا جو مجھے نگل جانا چاہتا ہے۔ سیلہ۔ خدا اپنی رحمت اور سچائی بھیجے گا۔ {سے...: یا، وہ اسے ملامت کرتا ہے کہ}\n4. میری روح {ہے} شیروں کے درمیان: {اور} میں {حتیٰ کہ} ان لوگوں کے درمیان بھی پڑا ہوں جنہیں آگ لگا دی جاتی ہے، {حتیٰ کہ} انسانوں کے بیٹے بھی، جن کے دانت {نیزے} اور تیر ہیں، اور ان کی زبان تیز تلوار ہے۔\n5. اے خدا، آسمانوں سے بلند ہو؛ {آؤ} کہ تیری شان {زمین سے اوپر} ہو۔\n6۔ انہوں نے میرے قدموں کے لیے جال تیار کیا ہے؛ میری روح جھکی ہوئی ہے: انہوں نے میرے سامنے ایک گڑھا کھود دیا ہے، جس کے بیچ وہ خود گر چکے ہیں۔ سیلہ۔\n7. میرا دل جڑا ہوا ہے، اے خدا، میرا دل جڑا ہوا ہے: میں گاؤں گا اور تعریف کروں گا۔ {مقررہ: یا، تیار ہے}\n8. جاگو، میری جلال؛ جاگو، زبور اور ہارپ: میں خود جلدی جاگ جاؤں گا۔\n9۔ اے خداوند، میں لوگوں میں تیرا شکر کروں گا: میں قوموں میں تجھے گانا گاؤں گا۔\n10. کیونکہ تیری رحمت آسمانوں کے لیے عظیم ہے، اور بادلوں کے لیے سچائی ہے۔\n11. اے خدا، آسمانوں سے بلند ہو: {آؤ} اپنی شان {ہو} گئی زمین سے اوپر۔","1. [چیف موسیقار، الٹاشتھ، میختم آف ڈیوڈ کے نام۔] کیا تم واقعی راستبازی کی بات کرتے ہو، اے جماعت؟ کیا تم انصاف سے فیصلہ کرتے ہو، اے انسانوں کے بیٹو؟ {الٹاشیتھ...: یا، تباہ نہ کرو} {میختم: یا، ایک سنہری زبور}\n2. ہاں، دل میں تم بدی کرتے ہو؛ تم اپنے ہاتھوں کی شدت کو زمین پر تولتے ہو۔\n3۔ بدکار رحم سے دور ہو جاتے ہیں: وہ پیدا ہوتے ہی گمراہ ہو جاتے ہیں، جھوٹ بولتے ہیں۔ {جیسے ہی...: عبرانی۔ پیٹ سے}\n4. ان کا زہر {ہے} سانپ کے زہر کی طرح: {وہ ہیں} جیسے بہرا ایڈر {جو} اس کے کان کو روکتا ہے؛ {زہر کی طرح: عبرانی۔ مماثلت وغیرہ کے مطابق} {adder: or, asp}\n5. جو دلکش لوگوں کی آواز نہیں سنتا، جو کبھی اتنی دانشمندی سے دلکش نہیں ہوتے۔ {دلکش...: یا، کبھی اتنے چالاک نہ بنو}\n6. اے خدا، ان کے منہ میں ان کے دانت توڑ دے: اے خداوند، نوجوان شیروں کے بڑے دانت نکال۔\n7. انہیں پانی کی طرح پگھلنے دو {جو مسلسل بہتے رہیں}: {جب} وہ {اپنا کمان موڑے} تاکہ تیر چلائے، تو وہ ٹکڑوں میں کٹے ہوئے ہوں۔\n8. جیسے گھونگھا {جو} پگھلتا ہے، {ان میں سے ہر ایک} کو گزر جائے: {ویسے} جیسے عورت کی غیر متوقع ولادت، {تاکہ} وہ سورج نہ دیکھ سکیں۔\n9۔ اس سے پہلے کہ تمہارے برتن کانٹے محسوس کریں، وہ انہیں ایک طوفان کی طرح لے جائے گا، زندہ اور اپنے غصے میں۔ {دونوں...: عبرانی۔ جیسے غصے کی طرح زندہ ہوں}\n10۔ نیک خوش ہوں گے جب وہ انتقام دیکھے گا: وہ اپنے پاؤں بدکاروں کے خون سے دھوئے گا۔\n11۔ تاکہ کوئی شخص کہے، \"راستبازوں کے لیے اجر ہے: یقینا وہ زمین پر فیصلہ کرنے والا خدا ہے۔ {ایک انعام...: عبرانی۔ پھل وغیرہ}","1. [داؤد کے بڑے موسیقار، الٹاشٹھ، میختم کے نام؛ جب ساؤل نے بھیجا، اور وہ گھر کی نگرانی کر رہے تھے کہ اسے مار دیں۔] اے میرے خدا، مجھے میرے دشمنوں سے نجات دے: مجھے ان سے بچا جو میرے خلاف اٹھ کھڑے ہیں۔ {الٹاشیتھ...: یا، تباہ نہ کرو} {میختم: یا، ایک سنہری زبور} {دفاع...: عببرانی۔ مجھے ہائی پر سیٹ کرو}\n2. مجھے بدکار مزدوروں سے نجات دے، اور خونخواروں سے بچا۔\n3۔ کیونکہ وہ میری روح کے انتظار میں ہیں: طاقتور میرے خلاف جمع ہیں؛ نہ میرے گناہ کے لیے، نہ میرے گناہ کے لیے، اے خداوند۔\n4. وہ بغیر کسی غلطی کے دوڑتے اور خود کو تیار کرتے ہیں: میری مدد کے لیے جاگتے ہیں، اور دیکھتے ہیں۔ {مدد: عبرانی ملاقات}\n5. تو، اے خداوند لشکروں کے خدا، اسرائیل کے خدا، تمام کافروں سے ملنے کے لیے جاگ جا: کسی بھی بدکار پر رحم نہ کرو۔ سیلہ۔\n6۔ وہ شام کو واپس آتے ہیں: کتے کی طرح شور کرتے ہیں اور شہر میں گھومتے ہیں۔\n7۔ دیکھو، وہ اپنے منہ سے ڈکار نکالتے ہیں: تلواریں {ہیں} ان کے ہونٹوں میں: {کہتے ہیں} کس کے لیے، وہ سنتے ہیں؟\n8. لیکن تو، اے خداوند، ان پر ہنسنا؛ تم تمام کافروں کا مذاق اڑاؤ گے۔\n9۔ {اس کی طاقت کی وجہ سے} میں تمہاری خدمت کروں گا: کیونکہ خدا {ہے} میرا دفاع ہے۔ {دفاع: عبرانی۔ اونچی جگہ}\n10. میری رحمت کا خدا مجھے روک دے گا: خدا مجھے اپنے دشمنوں پر {میری خواہش} دکھائے گا۔ {دشمن: عبرانی۔ مبصرین}\n11۔ انہیں نہ مارو، کہیں میرے لوگ بھول نہ جائیں: اپنی طاقت سے انہیں منتشر کر دو؛ اور انہیں گرا دے، اے خداوند، ہمارا ڈھال۔\n12. ان کے منہ کے گناہ اور ان کے ہونٹوں کے الفاظ کی وجہ سے وہ اپنے غرور میں بھی شامل ہو جائیں: اور لعنت اور جھوٹ بولنے کے لیے جو وہ بولتے ہیں۔\n13. غصے میں {ان} کو کھا لو، {ان} کھا لو، تاکہ وہ {نہ ہوں}: اور انہیں معلوم ہو کہ خدا یعقوب میں زمین کے کونے تک حکمرانی کرتا ہے۔ سیلہ۔\n14۔ اور شام کو انہیں واپس آنے دو؛ {اور} انہیں کتے کی طرح شور کرنے دو، اور شہر میں گھومنے دو۔\n15۔ انہیں گوشت کے لیے اوپر نیچے گھومنے دو، اور اگر وہ مطمئن نہ ہوں تو رنجش کرو۔ {گوشت کے لیے: عبوری۔ کھانے کے لیے} {اور رنجش...: یا، اگر وہ مطمئن نہ ہوں، تو وہ ساری رات رہیں گے}\n16. لیکن میں تیری طاقت کے بارے میں گاؤں گا؛ ہاں، میں صبح تمہاری رحمت کا بلند آواز میں گاؤں گا: کیونکہ تم میرے مصیبت کے دن میرا دفاع اور پناہ گاہ رہے ہو۔\n17۔ اے میری طاقت، میں تجھ کے لیے گاؤں گا: کیونکہ خدا میرا دفاع ہے، اور میری رحمت کا خدا ہے۔","1۔ [شوشنیدوت کے اہم موسیقار، داؤد کے میختم کو، سکھانے کے لیے؛ جب وہ آرامناہریم اور آرامزوبہ کے ساتھ جدوجہد کرے، جب یوآب واپس آیا، اور بارہ ہزار نمک کی وادی میں ایڈم پر حملہ کیا۔] اے خدا، تو نے ہمیں چھوڑ دیا، تو نے ہمیں منتشر کر دیا، تو ناراض ہو گئے؛ اے دوبارہ ہماری طرف رجوع کرو۔ {میختم: یا، ایک سنہری زبور} {بکھرا ہوا: عبوری۔ ٹوٹا ہوا}\n2۔ تو نے زمین کو ہلا دیا ہے؛ تم نے اسے توڑ دیا ہے: اس کی دراڑوں کو شفا دو؛ کیونکہ یہ کانپ رہا ہے۔\n3۔ تم نے اپنے لوگوں کو مشکل چیزیں دکھائی ہیں: تو نے ہمیں حیرت کی شراب پیائی ہے۔\n4۔ تم نے ان لوگوں کو ایک جھنڈا دیا ہے جو تم سے ڈرتے ہیں، تاکہ وہ سچائی کی وجہ سے ظاہر ہو سکے۔ سیلہ۔\n5. تاکہ تمہارا محبوب نجات پائے؛ اپنے دائیں ہاتھ سے بچاؤ، اور میری بات سنو۔\n6۔ خدا نے اپنی پاکیزگی میں بات کی ہے؛ میں خوش ہوں گا، شیکم کو تقسیم کروں گا، اور سکوت کی وادی کو تقسیم کروں گا۔\n7. گیلعاد {ہے} میرا، اور مناسی {ہے} میرا؛ افرائیم بھی میرے سر کی طاقت ہے؛ یہوداہ {ہے} میرا قانون ساز؛\n8. موآب {ہے} میرا واش پاٹ؛ ادوم پر میں اپنا جوتا پھینکوں گا: فلسطینیا، میری وجہ سے فتح حاصل کرو۔ {فتح...: یا، تم مجھ پر فتح حاصل کرو: (ایک طنزیہ بات سے}\n9. کون مجھے مضبوط شہر میں لے جائے گا؟ کون مجھے ایڈوم لے جائے گا؟ {مضبوط...: عبرانی۔ طاقت کا شہر؟}\n10. کیا تو، اے خدا، ہمیں چھوڑ کر نہیں چھوڑ دیتا؟ اور {تم}، اے خدا، {کون} ہماری فوجوں کے ساتھ باہر نہیں گیا؟\n11۔ ہمیں مصیبت سے مدد دو: کیونکہ انسان کی مدد بے سود ہے۔ {انسان کی مدد: عبرانی۔ نجات وغیرہ}\n12۔ خدا کے ذریعے ہم بہادری سے کام کریں گے: کیونکہ وہی ہے جو ہمارے دشمنوں کو روند ڈالے گا۔","1. [نگینہ کے چیف موسیقار کے نام، {ایک زبور} داؤد کا۔] اے خدا، میری فریاد سنو؛ میری دعا پر دھیان دو۔\n2۔ زمین کے کونے سے میں تم سے پکاروں گا، جب میرا دل مغلوب ہو جائے گا: مجھے اس چٹان تک لے چلا جو مجھ سے بلند ہے۔\n3۔ کیونکہ تم میرے لیے پناہ گاہ رہے ہو، {اور} دشمن سے ایک مضبوط برج بھی۔\n4۔ میں ہمیشہ تیرے خیمے میں رہوں گا: میں تیرے پروں کی چھپی ہوئی حفاظت پر بھروسہ کروں گا۔ سیلہ۔ {اعتماد: یا، میری پناہ گاہ بنا دو}\n5. کیونکہ تو، اے خدا، نے میری قسمیں سنی ہیں: تو نے مجھے ان لوگوں کی میراث دی ہے جو تیرے نام سے ڈرتے ہیں۔\n6. تم بادشاہ کی عمر کو طول دو گے: {اور} اس کی عمر کو کئی نسلوں تک۔ {تم...: عبرانی۔ تم بادشاہ کے دنوں میں دن شامل کرو گے} {جیسا کہ...: عبرانی۔ نسل اور نسل کے طور پر}\n7. وہ ہمیشہ کے لیے خدا کے حضور رہے گا: اے رحم اور سچائی تیار کرو، {جو} اسے محفوظ رکھے۔\n8. اسی طرح میں ہمیشہ تیرے نام کی تعریف کروں گا، تاکہ میں روزانہ اپنی قسمیں پوری کر سکوں۔","1. [چیف موسیقار، جدوتون کے نام، داؤد کا زبور۔] واقعی میری جان خدا کی منتظر ہے: اسی سے میری نجات آتی ہے۔ {واقعی: یا، صرف} {ویٹیتھ: ہیب۔ خاموش ہے}\n2. وہ صرف میرا سہارا اور میری نجات ہے؛ {وہ} میرا دفاع ہے؛ میں زیادہ متاثر نہیں ہوں گا۔ {دفاع: عبرانی۔ اونچی جگہ}\n3. آپ کتنی دیر تک کسی آدمی کے خلاف شرارت کا تصور کریں گے؟ تم سب مارے جاؤ گے: ایک جھکاؤ والی دیوار کی طرح، اور ایک لڑکھڑاتی باڑ کی طرح۔\n4۔ وہ صرف اس کی عظمت سے اسے نیچے اتارنے کی کوشش کرتے ہیں: وہ جھوٹ سے لطف اندوز ہوتے ہیں: وہ اپنے منہ سے برکت دیتے ہیں، لیکن اندر سے لعنت دیتے ہیں۔ سیلہ۔ {اندرونی طور پر: عبرانی۔ اپنے اندرونی حصوں میں}\n5۔ میری جان، تو صرف خدا کا انتظار کرو؛ کیونکہ میری توقع {ہے} اس سے۔\n6. وہ صرف میرا سہارا اور نجات ہے: وہ میرا دفاع ہے؛ میں متاثر نہیں ہوں گا۔\n7. خدا میں میری نجات اور جلال ہے: میری طاقت کی چٹان {اور} میری پناہ گاہ، {ہے} خدا میں۔\n8۔ ہر وقت اس پر بھروسہ کرو؛ {اے لوگو}، اپنا دل اس کے سامنے نکالو: خدا ہمارے لیے پناہ گاہ ہے۔ سیلہ۔\n9۔ یقینا کم درجے کے لوگ خود پسندی ہیں، اور اعلیٰ درجے کے لوگ جھوٹ ہیں: اگر توازن میں رکھا جائے تو وہ بالکل خود پسندی سے ہلکے ہیں۔ {مجموعا: یا، ایک جیسا}\n10۔ ظلم پر بھروسہ نہ کرو، اور لوٹ مار میں خود غرض نہ ہو: اگر دولت بڑھے تو اپنا دل اس پر نہ رکھو۔\n11۔ خدا نے ایک بار بات کی ہے؛ میں نے یہ دو بار سنا ہے؛ وہ طاقت {ہے} خدا کی۔ {طاقت: یا، طاقت}\n12۔ اے خداوند، بھی تیری رحمت ہے: کیونکہ تو ہر انسان کو اس کے کام کے مطابق عطا کرتا ہے۔","1. [داؤد کا زبور، جب وہ یہوداہ کے بیابان میں تھا۔] اے خدا، تو میرا خدا ہے؛ جلدی میں تمہیں تلاش کروں گا: میری روح تمہارے لیے پیاسی ہے، میرا جسم خشک اور پیاسی زمین میں تمہارے لیے ترستا ہے، جہاں پانی نہیں ہے؛ {تھرسٹی: عبوری۔ تھکا ہوا} {کہاں...: بغیر پانی کے}\n2۔ تیری طاقت اور جلال دیکھنا، جیسے میں نے تمہیں مقدس مقام میں دیکھا ہے۔\n3. کیونکہ تیری محبت کی مہربانی زندگی سے بہتر ہے، میرے ہونٹ تیری تعریف کریں گے۔\n4۔ اسی طرح میں تمہیں زندہ رہتے ہوئے برکت دوں گا: میں اپنے ہاتھ تیرے نام پر اٹھاؤں گا۔\n5. میری روح گودے اور موٹاپے کی طرح مطمئن ہوگی؛ اور میرا منہ خوشی سے تمہاری تعریف کرے گا: {گودا: عبرانی۔ موٹاپی}\n6. جب میں تمہیں اپنے بستر پر یاد کرتا ہوں، {اور} رات کی گھڑیوں میں تیرے بارے میں غور کرتا ہوں۔\n7۔ کیونکہ تم نے میری مدد کی، اس لیے میں تمہارے پروں کے سائے میں خوش ہوں گا۔\n8۔ میری جان تیری پیروی کرتی ہے: تیرا دایاں ہاتھ مجھے سہارا دیتا ہے۔\n9۔ لیکن جو {جو} میری روح کو تلاش کرتے ہیں، اسے تباہ کرنے کے لیے، وہ زمین کے نچلے حصوں میں جائیں گے۔\n10۔ وہ تلوار کے ہاتھوں مارے جائیں گے: وہ لومڑیوں کے لیے حصہ ہوں گے۔ {وہ گریں گے...: عبرانی۔ وہ اسے ہاتھوں پانی کی طرح بہا دیں گے}\n11. لیکن بادشاہ خدا پر خوش ہوگا؛ جو بھی اس کی قسم کھائے گا جلال پائے گا: لیکن جھوٹ بولنے والوں کا منہ بند ہو جائے گا۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے خدا، میری دعا میں میری آواز سنو: میری جان دشمن کے خوف سے بچاؤ۔\n2. مجھے بدکاروں کی خفیہ نصیحت سے چھپا دو؛ بدکاری کے مزدوروں کی بغاوت سے:\n3۔ جنہوں نے اپنی زبان تلوار کی طرح پھینکی، {اور} تیر چلانے کے لیے [اپنے کمانوں کو موڑا}، {حتیٰ کہ} تلخ الفاظ:\n4۔ کہ وہ خفیہ طور پر کامل پر گولی چلا سکتے ہیں: اچانک وہ اس پر گولی چلاتے ہیں، اور ڈر نہ لگیں۔\n5. وہ خود کو ایک برے کام میں مبتلا کرتے ہیں: وہ چالاکی سے جال بچھانے سے بات کرتے ہیں؛ وہ کہتے ہیں، کون انہیں دیکھے گا؟ {مادہ: یا، تقریر} {of...: عبرانی۔ اپنے جال چھپانے کے لیے}\n6۔ وہ گناہوں کی تلاش کرتے ہیں؛ وہ ایک محنتی تلاش کرتے ہیں: ہر ایک کا اندرونی {خیال} بھی، اور دل {گہرا} ہے۔ {وہ...: یا، ہم اس چیز میں ڈوب جاتے ہیں جسے انہوں نے گہرائی سے تلاش کیا ہے} {ایک محنتی...: عبرانی۔ تلاش کی گئی}\n7۔ لیکن خدا ان پر تیر سے فائر کرے گا؛ اچانک وہ زخمی ہو جائیں گے۔ {کیا وہ...: عبرانی۔ ان کا زخم ہوگا}\n8۔ تو وہ اپنی زبان خود پر گریں گے: جو انہیں دیکھے گا وہ بھاگ جائے گا۔\n9۔ اور سب لوگ ڈریں گے، اور خدا کے کام کا اعلان کریں گے؛ کیونکہ وہ اس کے عمل پر دانشمندی سے غور کریں گے۔\n10۔ نیک لوگ خداوند پر خوش ہوں گے، اور اس پر بھروسہ کریں گے؛ اور دل کے تمام نیک دل جلال پائیں گے۔","1. [چیف موسیقار کے نام، ایک زبور {اور} داؤد کا گیت۔] تعریف تیرے لیے منتظر ہے، اے خدا، سیون میں: اور تمہارے لیے قسم پوری کی جائے گی۔ {ویٹیتھ: ہیب۔ خاموش ہے}\n2۔ اے جو دعا سنتے ہو، تمام جسم تیرے پاس آئیں گے۔\n3. میرے خلاف گناہوں پر غالب آتی ہیں: {جہاں تک} ہماری گناہوں کا تعلق ہے، تو انہیں ختم کر دو۔ {بدکاریوں: عبرانی۔ الفاظ، یا، گناہوں کے معاملات}\n4۔ مبارک ہے {وہ آدمی} جسے تم چنتے ہو، اور جسے تمہارے قریب لاتا ہے {تاکہ وہ تمہارے درباروں میں رہ سکے}: ہم تیرے گھر کی بھلائی سے مطمئن ہوں گے، {حتیٰ کہ} تیرے مقدس مندر کی بھی۔\n5. {راستبازی میں} خوفناک چیزوں کی قسم، اے ہماری نجات کے خدا، تو ہمیں جواب دے گا؛ {جو زمین کے تمام کونے اور سمندر کے کنارے دور لوگوں کا اعتماد رکھتے ہیں:\n6۔ جو اپنی طاقت سے پہاڑوں کو مضبوط کرتا ہے؛ {طاقت سے لپٹا ہوا}:\n7۔ جو سمندروں کی آواز، ان کی لہروں کی آواز، اور لوگوں کے شور کو خاموش کر دیتا ہے۔\n8۔ جو لوگ دور دراز علاقوں میں رہتے ہیں وہ بھی تمہارے نشانات سے ڈرتے ہیں: تو صبح اور شام کے اخراجات کو خوشی منانے کے لیے بناتے ہو۔ {خوشی مناؤ: یا، گاؤ}\n9۔ تم زمین کا دورہ کرتے ہو، اور اسے پانی دیتے ہو: تم اسے خدا کے دریا سے بہت مالا مال کرتے ہو، جو پانی سے بھرا ہوا ہے: تم ان کے لیے اناج تیار کرتے ہو، جب تم نے اسے فراہم کیا ہو۔ {اور...: یا، جب تم نے بارش کی خواہش کی تھی}\n10۔ تم اس کی پہاڑیوں کو خوب پانی دیتے ہو، اس کی کھالوں کو صاف کرتے ہو، بارش سے نرم کرتے ہو، اور اس کے چشمے کو برکت دیتے ہو۔ {سیٹلسٹ: یا، بارش کا سبب بنیں} {makest...: ہیب۔ اسے تحلیل کریں}\n11۔ تو سال کو اپنی نیکی سے تاج پہناتا ہے؛ اور تمہارے راستے موٹاپے کو گرا دیتے ہیں۔ {ساتھ: عبرانی of}\n12۔ وہ جنگل کی چراگاہوں پر اترتے ہیں: اور چھوٹے پہاڑ ہر طرف خوش ہوتے ہیں۔ {خوش ہو...: عبرانی خوشی سے ملبوس ہیں}\n13۔ چراگاہیں ریوڑ سے ڈھکی ہوئی ہیں؛ وادیاں بھی مکئی سے ڈھکی ہوئی ہیں؛ وہ خوشی سے چیختے ہیں، وہ گاتے بھی ہیں۔","1. [چیف موسیقار کے نام، ایک گیت {یا} زبور۔] خدا کو خوشی سے آواز نکالو، اے تمام زمینوں: {سب...: عبرانی۔ ساری زمین}\n2. اس کے نام کی عزت کو گاؤ: اس کی تعریف کو جلال بخش۔\n3۔ خدا سے کہو، تم اپنے اعمال میں کتنے خوفناک ہو! تیری طاقت کی عظمت سے تمہارے دشمن خود کو تمہارے سامنے سر تسلیم تسلیم خم کریں گے۔ {سبمٹ...: یا، دکھاوے کی اطاعت قبول کرو: عبری۔ جھوٹ}\n4۔ ساری زمین تمہاری عبادت کرے گی، اور تمہیں گائے گی؛ وہ تمہارے نام کے لیے گائیں گے۔ سیلہ۔\n5. آؤ اور خدا کے اعمال دیکھو: {وہ} اپنے اعمال میں انسانوں کے بچوں کے لیے خوفناک ہے۔\n6۔ اس نے سمندر کو خشکی میں بدل دیا: وہ پیدل سیلاب سے گزرے: وہاں ہم اس پر خوش ہوئے۔\n7۔ وہ ہمیشہ اپنی طاقت سے حکومت کرتا ہے؛ اس کی آنکھیں قوموں کو دیکھتی ہیں: باغی خود کو بلند نہ کرے۔ سیلہ۔\n8. اے ہمارے خدا، اے لوگو، برکت فرما اور اس کی حمد کی آواز سنائی دے:\n9۔ جو ہماری روح کو زندگی میں تھامے رکھتا ہے، اور ہمارے قدموں کو حرکت دینے نہیں دیتا۔ {ہولڈتھ: عبوری۔ پٹیتھ}\n10۔ کیونکہ تو، اے خدا، نے ہمیں آزمایا ہے: تو نے ہمیں آزمایا ہے، جیسے چاندی آزمائی جاتی ہے۔\n11۔ تو نے ہمیں جال میں لایا؛ تم نے ہمارے جسم پر مصیبت ڈالی۔\n12۔ تو نے انسانوں کو ہمارے سروں پر سوار کر دیا؛ ہم آگ اور پانی سے گزرے: لیکن تو نے ہمیں ایک امیر جگہ میں لے آیا۔ {امیر: عبرانی۔ نمنا}\n13۔ میں تمہارے گھر میں جلانے والے نذرانہ لے کر جاؤں گا: میں تمہیں اپنی قسمیں دوں گا،\n14۔ جو میرے ہونٹوں نے کہے اور میرے منہ نے کہا جب میں مشکل میں تھا۔ {کہا: عبوری۔ کھولا گیا}\n15۔ میں تمہیں موٹے بچوں کی جلی ہوئی قربانیاں پیش کروں گا، مینڈوں کی خوشبو کے ساتھ؛ میں بکریوں کے ساتھ بیل پیش کروں گا۔ سیلہ۔ {فیٹلنگز: عبوری۔ میرو}\n16. آؤ اور سنو، اے خدا سے ڈرنے والے سب لوگ، اور میں اعلان کروں گا کہ اس نے میری روح کے لیے کیا کیا ہے۔\n17۔ میں نے اپنے منہ سے اس سے پکارا، اور میری زبان سے اس کی تعریف کی گئی۔\n18۔ اگر میں اپنے دل میں بدکاری کو دیکھوں، تو خداوند مجھے نہیں سنے گا:\n19. {لیکن} خدا نے {مجھ سے} سنا ہے؛ اس نے میری دعا کی آواز سنی۔\n20. مبارک ہو خدا ہو، جس نے میری دعا اور اپنی رحمت کو مجھ سے نہیں روکا۔","1. [نیگینوت کے چیف موسیقار کے نام، ایک زبور {یا} گیت۔] خدا ہم پر رحم کرے اور ہمیں برکت دے؛ {اور} اپنا چہرہ ہمارے اوپر چمکائے گا؛ سیلہ۔ {چیف...: یا، نگران} {اوپر: ہیب۔ with}\n2۔ تاکہ تمہارا راستہ زمین پر پہچانا جائے، تیری نجات بخش صحت تمام قوموں میں۔\n3. اے خدا، لوگ تیری تعریف کریں؛ سب لوگ تمہاری تعریف کریں۔\n4۔ قومیں خوش ہوں اور خوشی سے گاؤ: کیونکہ تو لوگوں کا انصاف کرو گے، اور زمین پر قوموں کی حکومت کرو گے۔ سیلہ۔ {گورنمنٹ: عبرانی۔ لیڈ}\n5. اے خدا، لوگ تیری تعریف کریں؛ سب لوگ تمہاری تعریف کریں۔\n6. {پھر} زمین اپنی بڑھوتری دے گی؛ {اور} خدا، {حتیٰ کہ} ہمارا اپنا خدا، ہمیں برکت دے گا۔\n7۔ خدا ہمیں برکت دے گا؛ اور زمین کے تمام کونے اس سے ڈریں گے۔","1. [چیف موسیقار کے نام، زبور {یا} داؤد کا گیت۔] خدا اٹھے، اس کے دشمن بکھر جائیں: جو اس سے نفرت کرتے ہیں وہ بھی اس کے سامنے بھاگ جائیں۔ {اس سے پہلے...: عبرانی۔ اس کے چہرے سے}\n2۔ جیسے دھواں بھگایا جاتا ہے، {ویسے} {انہیں} بھگا دو: جیسے موم آگ کے سامنے پگھلتا ہے، {ویسے} بدکاروں کو خدا کی موجودگی میں فنا ہو جائے۔\n3۔ لیکن نیک خوش ہوں؛ خدا کے حضور خوش ہوں: ہاں، وہ بے حد خوش ہوں۔ {انتہائی زیادہ...: عبرانی خوشی سے خوش رہو}\n4. خدا کے لیے گاؤ، اس کے نام کی حمد کرو: جو آسمان پر سوار ہے اس کے نام JAH سے تعریف کرو، اور اس کے سامنے خوشی مناؤ۔\n5۔ یتیم کا باپ، اور بیواؤں کا جج، اپنے مقدس گھر میں خدا ہے۔\n6۔ خدا تنہا لوگوں کو خاندانوں میں بٹھاتا ہے: وہ ان لوگوں کو نکالتا ہے جو زنجیروں میں بندھے ہوتے ہیں، لیکن باغی لوگ خشک زمین میں رہتے ہیں۔ {خاندانوں میں: عبرانی۔ ایک گھر میں}\n7. اے خدا، جب تم اپنے لوگوں کے سامنے نکلے، جب تم بیابان میں مارچ کرتے؛ سیلاہ:\n8۔ زمین ہل گئی، آسمان بھی خدا کی موجودگی میں گر گئے: {حتی} خود سینا بھی خدا، اسرائیل کے خدا کی موجودگی سے متاثر ہوا۔\n9۔ اے خدا، تو نے ایک بھرپور بارش بھیجی، جس سے تم نے اپنی میراث کی تصدیق کی، جب وہ تھک گئی۔ {بھیجیں: عبوری۔ شیک آؤٹ} {تصدیق: ہیب۔ تصدیق کریں}\n10۔ تمہاری جماعت نے وہاں قیام کیا: اے خدا، تو نے اپنی بھلائی کو غریبوں کے لیے تیار کیا ہے۔\n11۔ خداوند نے کلام دیا: عظیم {تھا} ان لوگوں کی صحبت جنہوں نے {it} شائع کیا۔ {کمپنی: ہیب۔ آرمی}\n12۔ فوجوں کے بادشاہ تیزی سے بھاگ گئے: اور جو گھر میں رکی ہوئی تھی اس نے مال تقسیم کیا۔ {کیا...: عبرانی۔ بھاگ گئے، بھاگ گئے}\n13۔ اگرچہ تم برتنوں کے درمیان پڑے ہو، {پھر بھی تم چاندی سے ڈھکے ہوئے کبوتر کے پروں کی طرح رہو گے، اور اس کے پر زرد سونے سے۔\n14۔ جب قادر مطلق نے بادشاہوں کو اس میں بکھیر دیا، تو وہ سالمون میں برف کی طرح سفید تھا۔ {اس میں...: یا، اس کے لیے، وہ}\n15۔ خدا کی پہاڑی بشن کی پہاڑی کی طرح ہے؛ ایک اونچی پہاڑی {جیسا کہ} باشان کی پہاڑی۔\n16. اے اونچی پہاڑیوں پر کیوں چھلانگ لگاتے ہو؟ {یہ} وہ پہاڑی {جس میں} خدا بسنا چاہتا ہے؛ ہاں، خداوند ہمیشہ کے لیے اس میں رہے گا۔\n17. خدا کے رتھ بیس ہزار، {حتیٰ کہ} ہزاروں فرشتے ہیں: خداوند {ہے} ان میں {یعنی} سیناء میں، مقدس {جگہ} میں۔ {حتی...: یا حتیٰ کہ ہزاروں بھی}\n18۔ تم بلند مقام پر چڑھ گئے، تم نے قید کو قید کیا: تم نے انسانوں کے لیے تحفے حاصل کیے؛ ہاں، {بغاوت کرنے والوں کے لیے} بھی، تاکہ خداوند خدا {ان کے درمیان} رہے۔ {مردوں کے لیے: عبرانی۔ ان دی مین}\n19. مبارک ہو خداوند ہو، {جو} روزانہ ہمیں {فوائد، حتیٰ کہ} ہماری نجات کے خدا پر بوجھ دیتا ہے۔ سیلہ۔\n20. {جو ہے} ہمارا خدا {ہے} نجات کا خدا؛ اور موت کے بعد کی اولاد خدا خداوند کے پاس ہے۔\n21. لیکن خدا اپنے دشمنوں کے سر کو زخمی کرے گا، {اور} اس شخص کے بالوں والے سر کو بھی زخمی کرے گا جو ابھی بھی اپنے قصوروں میں چلتا رہے۔\n22۔ خداوند نے فرمایا، میں باشان سے دوبارہ لاؤں گا، میں اپنے لوگوں کو سمندر کی گہرائیوں سے دوبارہ لاؤں گا:\n23۔ تاکہ تمہارا پاؤں {تمہارے} دشمنوں کے خون میں ڈبوئے، اور تمہارے کتوں کی زبان بھی اسی میں بھیگ جائے۔ {ڈپ کیا: یا، سرخ}\n24۔ اے خدا، انہوں نے تیرے راستے دیکھے ہیں؛ {حتیٰ کہ} میرے خدا، میرے بادشاہ کے حرکات بھی، مقدس مقام میں۔\n25۔ گلوکار پہلے گئے، سازوں پر بجانے والے {فالو} کے بعد؛ ان میں وہ لڑکیاں بھی تھیں جو ٹمبرلز کے ساتھ کھیل رہی تھیں۔\n26۔ خدا کو جماعتوں میں برکت دو، {حتیٰ کہ} خداوند کو، اسرائیل کے چشمے سے۔ {سے...: یا، تم جو اسرائیل کے چشمے سے ہو}\n27. وہاں چھوٹا بنیامین {ہے} ان کے حکمران، یہوداہ کے شہزادے {اور} ان کے مشیر، زبولون کے شہزادے، {اور} نفتالی کے شہزادے۔ {اور ان کے...: یا، ان کی صحبت کے ساتھ}\n28. تیرے خدا نے تیری طاقت کا حکم دیا ہے: اے خدا، جو کچھ تو نے ہمارے لیے کیا ہے اسے مضبوط کر۔\n29۔ یروشلم میں تمہارے مندر کی وجہ سے بادشاہ تمہیں تحفے دیں گے۔\n30۔ نیزہ بازوں کی جماعت، بیلوں کی کثرت، اور لوگوں کے بچھڑوں کو ملامت کرو، {یہاں تک کہ ہر کوئی چاندی کے ٹکڑے دے دے: جنگ میں خوش لوگوں کو منتشر کر دو۔ {کمپنی...: یا، سرکنڈے کے جانور} {بکھراؤ...: یا، وہ بکھرتا ہے}\n31۔ شہزادے مصر سے نکلیں گے؛ ایتھوپیا جلد ہی خدا کی طرف ہاتھ بڑھائے گا۔\n32. اے زمین کے بادشاہتوں کے لیے خدا کو گاؤ؛ اے خداوند کی حمد و ثنا گاؤ؛ سیلاہ:\n33۔ اس کے لیے جو آسمانوں کے آسمانوں پر سوار ہے، {جو پرانے زمانے کے تھے}؛ دیکھو، وہ اپنی آواز بھیجتا ہے، {اور وہ} ایک زبردست آواز ہے۔ {بھیجو...: عبرانی۔ دیں}\n34. طاقت خدا کو منسوب کرو: اس کی عظمت اسرائیل پر ہے، اور اس کی طاقت بادلوں میں ہے۔ {بادل: یا، آسمان}\n35. اے خدا، {تو} اپنے مقدس مقامات سے خوفناک ہے: اسرائیل کا خدا {وہ} ہے جو {اپنی} لوگوں کو طاقت اور طاقت دیتا ہے۔ خدا مبارک ہو۔","1. [شوشنیم پر چیف موسیقار کو، {داؤد کا زبور}] اے خدا، مجھے بچا؛ کیونکہ پانی میری روح میں داخل ہو چکا ہے۔\n2. میں گہرے کیچڑ میں ڈوب جاتا ہوں، جہاں {کھڑا نہیں}: میں گہرے پانیوں میں آتا ہوں، جہاں سیلاب مجھے بہا دیتا ہے۔ {گہرا کیچڑ: عبوری۔ گہرائی کی دلدل} {گہرے پانی: عبرانی۔ پانیوں کی گہرائی}\n3. میں اپنی رونے سے تھک چکا ہوں: میرا گلا خشک ہے: میری آنکھیں بند ہو جاتی ہیں جب میں اپنے خدا کا انتظار کرتا ہوں۔\n4۔ جو لوگ مجھ سے بے وجہ نفرت کرتے ہیں، وہ میرے سر کے بالوں سے بڑھ کر ہیں: جو مجھے تباہ کرنا چاہتے ہیں، {غلط} میرے دشمن ہیں، وہ طاقتور ہیں: پھر میں نے وہ چیز واپس کی جو میں نے نہیں چھینی۔\n5۔ اے خدا، تو میری حماقت کو جانتا ہے؛ اور میرے گناہ تم سے چھپے نہیں ہیں۔ {گناہ: عبرانی۔ قصوروار}\n6. اے خداوند لشکروں کے خدا، جو تیری خدمت کرتے ہیں وہ میرے لیے شرمندہ نہ ہوں: اے اسرائیل کے خدا، جو تیری تلاش کرتے ہیں وہ میرے لیے شرمندہ نہ ہوں۔\n7۔ کیونکہ تیرے لیے میں نے ملامت برداشت کی ہے؛ شرمندگی نے میرا چہرہ ڈھانپ لیا ہے۔\n8. میں اپنے بھائیوں کے لیے اجنبی اور اپنی ماں کے بچوں کے لیے اجنبی بن چکا ہوں۔\n9۔ کیونکہ تمہارے گھر کے جذبے نے مجھے کھا لیا ہے؛ اور جنہوں نے تمہیں ملامت کی، ان کی ملامت مجھ پر پڑی ہے۔\n10۔ جب میں رویا اور اپنی روح کو روزہ سے سزا دی، تو یہ میری ملامت تھی۔\n11۔ میں نے تھیلے کا کپڑا بھی اپنا لباس بنایا؛ اور میں ان کے لیے ایک کہاوت بن گیا۔\n12۔ جو دروازے پر بیٹھے ہیں وہ میرے خلاف بولتے ہیں؛ اور میں نشے میں دھت لوگوں کا گانا تھا۔ {نشے میں دھت لوگ: عبوری۔ طاقتور مشروبات پینے والے}\n13. لیکن جہاں تک میرا تعلق ہے، میری دعا تجھ سے ہے، اے خداوند، ایک قابل قبول وقت میں: اے خدا، اپنی رحمت کی کثرت میں مجھے اپنی نجات کی سچائی میں سن۔\n14. مجھے کیچڑ سے نکالو، اور مجھے ڈوبنے نہ دو: مجھے ان سے نجات دے جو مجھ سے نفرت کرتے ہیں، اور گہرے پانیوں سے بھی۔\n15۔ پانی کا سیلاب مجھے بہنے نہ دو، نہ گہرائی کو مجھے نگلنے دو، اور نہ ہی گڑھا میرے اوپر اپنا منہ بند کر دے۔\n16. اے خداوند، میری بات سنو؛ کیونکہ تیری محبت بھلائی ہے: اپنی نرم رحمتوں کی کثرت کے مطابق میری طرف رجوع کرو۔\n17۔ اور اپنے خادم سے اپنا چہرہ نہ چھپاؤ؛ کیونکہ میں مشکل میں ہوں: جلدی سنو۔ {سنیں...: عبوری۔ جلدی سنو}\n18. میری روح کے قریب آؤ، {اور} اسے نجات دو: میرے دشمنوں کی وجہ سے مجھے نجات دے۔\n19۔ تم نے میری ملامت دیکھی، میری شرمندگی اور میری بے عزتی دیکھی ہے: میرے دشمن سب تمہارے سامنے ہیں۔\n20۔ ملامت نے میرا دل توڑ دیا ہے؛ اور میں بوجھ سے بھرا ہوا ہوں: اور میں نے کچھ لوگوں کو رحم کرنے کی کوشش کی، لیکن کوئی نہیں تھا؛ اور کمفرٹر کے لیے، لیکن مجھے کوئی نہیں ملا۔ {لینے کے لیے...: عبرانی میرے ساتھ ماتم کرنا}\n21۔ انہوں نے مجھے میرے گوشت کے لیے پتے بھی دیے؛ اور میری پیاس میں انہوں نے مجھے سرکہ دیا کہ پیوں۔\n22. ان کی میز ان کے سامنے جال بن جائے: اور {جو ہونا چاہیے تھا} ان کی بھلائی کے لیے، {وہ جال} بن جائے۔\n23۔ ان کی آنکھیں گہری ہو جائیں تاکہ وہ نہ دیکھیں؛ اور اپنی کمر کو مسلسل ہلاتے رہے۔\n24۔ اپنا غصہ ان پر نکالو، اور اپنے غصے کو ان پر حاوی ہونے دو۔\n25۔ ان کی رہائش ویران ہو؛ {اور} کسی کو اپنے خیموں میں رہنے نہ دیں۔ {ان کی رہائش گاہ: عبرانی۔ ان کا محل} {کسی کو نہیں...: عبرانی کوئی رہنے والا نہ ہو}\n26۔ کیونکہ وہ اس پر ظلم کرتے ہیں جسے تم نے مارا ہے؛ اور وہ ان لوگوں کے غم سے بات کرتے ہیں جنہیں تم نے زخمی کیا ہے۔ {وہ...: عببرانی۔ تمہارے زخمی}\n27۔ ان کی بدکاری میں گناہ شامل کرو: اور انہیں تیری راستبازی میں نہ آنے دو۔ {بدکاری کے لیے...: یا، بدکاری کی سزا، وغیرہ}\n28۔ انہیں زندہ لوگوں کی کتاب سے مٹا دیا جائے، اور نیکوں کے ساتھ نہ لکھے جائیں۔\n29۔ لیکن میں غریب اور غمگین ہوں: اے خدا، تیری نجات مجھے بلند مقام دے۔\n30۔ میں خدا کے نام کی تعریف ایک گیت سے کروں گا، اور اسے شکرگزاری سے بڑھا دوں گا۔\n31۔ {یہ} بھی خداوند کو اس بیل {یا} بیل سے زیادہ خوش کرے گا جس کے سینگ اور کھر ہوں۔\n32۔ عاجز لوگ یہ دیکھیں گے، اور خوش ہوں گے: اور تمہارا دل زندہ رہے گا جو خدا کی تلاش میں ہے۔ {عاجز: یا، عاجز}\n33۔ کیونکہ خداوند غریبوں کو سنتا ہے، اور اپنے قیدیوں کو حقیر نہیں کرتا۔\n34۔ آسمان و زمین اس کی تعریف کریں، سمندروں کو، اور ہر اس چیز کی جو وہاں حرکت کرتی ہے۔ {مووتھ: عبوری۔ کریپتھ}\n35۔ کیونکہ خدا صیون کو بچا لے گا، اور یہوداہ کے شہر تعمیر کرے گا: تاکہ وہ وہاں رہیں اور اس پر قبضہ کر سکیں۔\n36۔ اس کے بندوں کی نسل بھی اس کی وارث ہوگی: اور جو اس کے نام سے محبت کریں گے وہ اس میں رہیں گے۔","1. [داؤد کے مرکزی موسیقار، {ایک زبور} کے نام، یاد میں لانے کے لیے۔] {جلدی کرو} اے خدا، مجھے بچانے کے لیے؛ اے خداوند، میری مدد کے لیے جلدی کرو۔ {مدد کے لیے...: عبرانی۔ میری مدد کے لیے}\n2۔ جو لوگ میری روح کی تلاش میں ہیں وہ شرمندہ اور پریشان ہوں: انہیں پیچھے کر کے الجھن میں ڈال دو، جو میری تکلیف چاہتے ہیں۔\n3. انہیں ان کی شرمندگی کے بدلے واپس بھیجنے دو جو کہتے ہیں، آہا، آہا۔\n4۔ جو بھی آپ کو تلاش کرتا ہے وہ آپ پر خوش اور خوش رہے: اور جو آپ کی نجات سے محبت کرتا ہے وہ مسلسل کہے، خدا کو بڑھا دیا جائے۔\n5. لیکن میں غریب اور محتاج ہوں: اے خدا، تو میری مدد اور نجات دہندہ ہو میرے پاس جلدی فرما؛ اے خداوند، دیر نہ کرو۔","1۔ اے خداوند، میں تم پر بھروسہ کرتا ہوں: مجھے کبھی الجھن میں نہ ڈالنا۔\n2. اپنی راستبازی میں مجھے نجات دے، اور مجھے بچا دے: اپنا کان میری طرف جھکا اور مجھے بچا۔\n3۔ میری مضبوط رہائش بنو، جہاں میں مسلسل رجوع کر سکوں: تو نے مجھے بچانے کا حکم دیا ہے؛ کیونکہ تو میری چٹان اور میرا قلعہ ہو۔ {ہو...: عبرانی۔ تو میرے لیے ایک چٹان کے لیے بنو}\n4. اے میرے خدا، مجھے بدکاروں کے ہاتھوں سے، بدکار اور ظالم انسان کے ہاتھوں سے بچا۔\n5۔ کیونکہ تو میری امید ہے، اے خداوند خدا: تو میری جوانی سے میری امانت ہے۔\n6۔ تیری قسم، میں رحم سے اٹھا ہوا ہوں: تو وہ ہو جس نے مجھے میری ماں کے آنتوں سے نکالا: میری حمد ہمیشہ تیرے لیے رہے گی۔\n7. میں بہت سے لوگوں کے لیے ایک عجوبہ ہوں؛ لیکن تم میری مضبوط پناہ گاہ ہو۔\n8. میرا منہ تمہاری تعریف سے بھر جائے {اور تمہاری عزت سے} سارا دن۔\n9. بڑھاپے کے وقت مجھے نہ چھوڑو؛ جب میری طاقت ختم ہو جائے تو مجھے چھوڑ کر نہ جاؤ۔\n10۔ کیونکہ میرے دشمن میرے خلاف بولتے ہیں؛ اور جو لوگ میری روح کا انتظار کر رہے ہیں وہ مل کر مشورہ کرتے ہیں، {lay...: عبرانی۔ دیکھو، یا، مشاہدہ کرو}\n11۔ کہتے ہوئے، خدا نے اسے چھوڑ دیا ہے: اسے ستاؤ اور لے لو؛ کیونکہ {کوئی نہیں} جو {اسے} کو دے سکے۔\n12. اے خدا، مجھ سے دور نہ ہو: اے میرے خدا، میری مدد کے لیے جلدی کرو۔\n13. جو میری روح کے مخالف ہیں، انہیں الجھا دیا جائے {اور} نگل جائے؛ انہیں ان ملامت اور بے عزتی سے ڈھانپ دیا جائے جو میری تکلیف چاہتی ہیں۔\n14. لیکن میں ہمیشہ امید رکھوں گا، اور تمہاری تعریف مزید کروں گا۔\n15. میرا منہ تمہاری راستبازی اور تمہاری نجات کو سارا دن ظاہر کرے گا؛ کیونکہ میں ان کے اعداد و شمار نہیں جانتا۔\n16۔ میں خداوند خدا کی طاقت میں جاؤں گا: میں تیری راستبازی کا ذکر کروں گا، {حتیٰ کہ} صرف تیری راہی۔\n17۔ اے خدا، تو نے مجھے بچپن سے سکھایا ہے: اور اب تک میں نے تیری حیرت انگیز کارناموں کا اعلان کیا ہے۔\n18. اب جب میں بوڑھا اور سفید بالوں والا ہو جاؤں گا، اے خدا، مجھے چھوڑ کر مت؛ جب تک میں تمہاری طاقت {اس} نسل کو دکھا دوں، {اور} تمہاری طاقت ہر آنے والے کو دوں۔ {جب...: عبرانی۔ بڑھاپے اور سفید بالوں تک} {تیری طاقت: عبرانی۔ تمہارا بازو}\n19۔ اے خدا، تیری راستبازی بھی بہت بلند ہے، جس نے عظیم کام کیے: اے خدا، جو تجرا جیسا ہے!\n20۔ {تو}، جس نے مجھے بڑی اور تکلیف دہ مشکلات دکھائی ہیں، مجھے دوبارہ زندہ کرو گے، اور مجھے زمین کی گہرائیوں سے دوبارہ زندہ کرو گے۔\n21. تو میری عظمت بڑھاؤ گے، اور مجھے ہر طرف سے تسلی دے گا۔\n22. میں بھی تمہاری سچائی کے ساتھ زبور کی تعریف کروں گا، اے میرے خدا: میں تمہارے لیے ہارپ کے ساتھ گاؤں گا، اے اسرائیل کے پاک۔ {دی زبور: عبرانی۔ زبور کا آلہ}\n23۔ جب میں تمہیں گاتا ہوں تو میرے ہونٹ بہت خوش ہوں گے؛ اور میری جان، جسے تم نے نجات دی ہے۔\n24۔ میری زبان بھی سارا دن تیری راستبازی کی بات کرے گی: کیونکہ وہ الجھن میں ہیں، کیونکہ وہ شرمندہ کیے جاتے ہیں، جو میری تکلیف چاہتے ہیں۔","1. [{ایک زبور} سلیمان کے لیے۔] اے خدا، بادشاہ کو اپنے فیصلے اور اپنی راستبازی بادشاہ کے بیٹے کو عطا فرما۔ {for: or, of}\n2۔ وہ تمہارے لوگوں کا انصاف کرے گا، اور تمہارے غریبوں کو انصاف سے۔\n3۔ پہاڑ لوگوں اور چھوٹے پہاڑوں کے لیے راستبازی سے امن لائیں گے۔\n4۔ وہ لوگوں کے غریبوں کا فیصلہ کرے گا، محتاجوں کے بچوں کو بچائے گا، اور ظالم کو ٹکڑے ٹکڑے کرے گا۔\n5. وہ تم سے ڈریں گے جب تک سورج اور چاند ہر نسل میں قائم رہیں۔\n6۔ وہ بارش کی طرح کٹی ہوئی گھاس پر گرے گا: جیسے بارش زمین کو پانی دیتی ہے۔\n7۔ اس کے زمانے میں نیک لوگ پھلیں پھلیں گے؛ اور جب تک چاند قائم ہے، امن کی فراوانی۔ {خدا حافظ...: عبرانی۔ جب تک چاند نہ ہو}\n8۔ اسے سمندر سے سمندر تک، اور دریا سے زمین کے کناروں تک بھی حکمرانی حاصل ہوگی۔\n9۔ جو لوگ بیابان میں رہتے ہیں وہ اس کے سامنے جھکیں گے؛ اور اس کے دشمن خاک چاٹیں گے۔\n10۔ ترشیش اور جزائر کے بادشاہ تحفے لائیں گے: سبا اور سبا کے بادشاہ تحفے پیش کریں گے۔\n11۔ ہاں، تمام بادشاہ اس کے سامنے جھکیں گے: تمام قومیں اس کی خدمت کریں گی۔\n12۔ کیونکہ وہ محتاجوں کو نجات دے گا جب وہ پکار رہا ہے؛ غریب بھی، اور {وہ} جس کے پاس کوئی مددگار نہیں۔\n13۔ وہ غریبوں اور محتاجوں کو بخش دے گا، اور محتاجوں کی روحوں کو بچائے گا۔\n14۔ وہ ان کی روح کو دھوکہ اور تشدد سے نجات دے گا: اور ان کا خون اس کی نظر میں قیمتی ہوگا۔\n15۔ اور وہ زندہ رہے گا، اور اسے سبا کے سونے سے دیا جائے گا: اس کے لیے بھی مسلسل دعا کی جائے گی؛ {اور} روزانہ اس کی تعریف کی جائے گی۔ {دیا جائے گا: عبرانی۔ ایک دے گا}\n16۔ زمین پر پہاڑوں کی چوٹی پر مکئی کا مٹھی ہوگی؛ اس کے پھل لبنان کی طرح لرزیں گے: اور شہر کے لوگ زمین کی گھاس کی طرح پھلیں گے۔\n17۔ اس کا نام ہمیشہ کے لیے قائم رہے گا: اس کا نام سورج تک برقرار رہے گا: اور {لوگ} اس میں برکت پائیں گے: تمام قومیں اسے مبارک کہیں گی۔ {برداشت کریں: عبرانی۔ be} {اس کا نام ہوگا...: عبرانی۔ وہ بیٹے کی طرح رہے گا جو ہمیشہ اپنے والد کے نام کو برقرار رکھے گا}\n18. مبارک ہو خداوند خدا، اسرائیل کا خدا، جو صرف حیرت انگیز کام کرتا ہے۔\n19۔ اور ہمیشہ کے لیے اس کے جلال والے نام پر مبارک ہو: اور پوری زمین اس کی شان سے بھر جائے؛ آمین، اور آمین۔\n20۔ یسوع کے بیٹے داؤد کی دعائیں ختم ہو جاتی ہیں۔","1. [آساف کا زبور۔] واقعی خدا اسرائیل کے لیے اچھا ہے، حتیٰ کہ صاف دل والوں کے لیے بھی۔ {of: or, for} {واقعی: یا، پھر بھی} {of...: عبرانی۔ دل سے پاک}\n2. لیکن میرے پاؤں تقریبا ختم ہو چکے تھے؛ میرے قدم تقریبا پھسل چکے تھے۔\n3۔ کیونکہ میں بے وقوفوں سے حسد کرتا تھا، {جب} میں نے بدکاروں کی خوشحالی دیکھی۔\n4۔ کیونکہ ان کی موت میں کوئی بندہ نہیں ہوتا: لیکن ان کی طاقت {مضبوط} ہے۔ {مضبوط: عبوری۔ موٹا}\n5. وہ {دوسرے} مردوں کی طرح مشکل میں نہیں ہیں؛ نہ ہی وہ {دوسرے} مردوں کی طرح پریشان ہیں۔ {میں...: عبرانی دوسرے مردوں کی مصیبت میں} {جیسے: عبرانی۔ with}\n6۔ اسی لیے غرور انہیں زنجیر کی طرح گھیرے ہوئے ہے؛ تشدد انہیں {ایک لباس کی طرح} ڈھانپتا ہے۔\n7. ان کی آنکھیں موٹاپے سے نمایاں ہوتی ہیں: ان میں دل کی خواہش سے کہیں زیادہ ہے۔ {have...: عبرانی دل کے خیالات پہنچاؤ}\n8۔ وہ بدعنوان ہیں، اور ظلم کے بارے میں بد نیتی سے بات کرتے ہیں: وہ بلند آواز میں بات کرتے ہیں۔\n9۔ وہ اپنا منہ آسمان کے خلاف رکھتے ہیں، اور ان کی زبان زمین پر چلتی ہے۔\n10۔ اس لیے اس کے لوگ یہاں واپس آتے ہیں: اور ان کے لیے ایک مکمل {پیالہ} کا پانی نچوڑا جاتا ہے۔\n11۔ اور وہ کہتے ہیں، خدا کیسے جانتا ہے؟ اور کیا سب سے بلند میں علم ہے؟\n12۔ دیکھو، یہ {ہیں} بددین، جو دنیا میں خوشحال ہیں؛ وہ دولت میں اضافہ کرتے ہیں۔\n13. واقعی میں نے اپنا دل بے سود پاک کیا اور معصومیت میں ہاتھ دھوئے۔\n14. سارا دن مجھے ہر صبح ستایا اور سزا دی گئی ہے۔ {نصیحت کے ساتھ: عبوری۔ میری سزا یہ تھی}\n15۔ اگر میں کہوں، تو میں یوں بولوں گا؛ دیکھو، میں تمہارے بچوں کی نسل کو ناراض کر دوں گا۔\n16. جب میں نے یہ جاننے کا سوچا، تو یہ میرے لیے بہت تکلیف دہ تھا؛ {بہ...: عبرانی۔ میری آنکھوں میں محنت}\n17. جب تک میں خدا کے مقدس مقام میں نہیں گیا؛ {پھر} ان کے انجام کو سمجھ گیا۔\n18۔ یقینا تم نے انہیں پھسلنے والی جگہوں پر رکھا: تم نے انہیں تباہی میں پھینک دیا۔\n19. انہیں کیسے {ویرانیوں میں} لایا جاتا ہے، جیسے ایک لمحے میں! وہ مکمل طور پر خوفناک ماحول میں مبتلا ہیں۔\n20. ایک خواب کی طرح جب {ایک} جاگتا ہے؛ {تو} اے خداوند، جب تم جاگو گے، تو ان کی شبیہ کو حقیر سمجھو گے۔\n21. یوں میرا دل غمگین ہوا، اور میری لگام میں چبھ گیا۔\n22. میں اتنا بے وقوف اور جاہل تھا: میں تمہارے سامنے ایک درندہ تھا۔ {لاعلم: عبرانی۔ مجھے معلوم نہیں تھا} {عبرانی سے پہلے. with}\n23. پھر بھی میں ہمیشہ تیرے ساتھ ہوں: تو نے مجھے میرے دائیں ہاتھ سے تھام لیا ہے۔\n24. تو اپنی نصیحت سے میری رہنمائی کر، اور بعد میں مجھے جلال کے لیے قبول کرو۔\n25۔ میرے پاس آسمان میں کون ہے {سوائے تمہار}؟ اور {زمین پر} کوئی نہیں ہے {جسے میں تمہارے سوا چاہتا ہوں}۔\n26. میرا جسم اور دل ناکام ہو جاتے ہیں: {لیکن} خدا {ہے} میرے دل کی طاقت ہے، اور ہمیشہ کے لیے میرا حصہ۔ {طاقت: عبرانی۔ راک}\n27۔ کیونکہ جو تم سے دور ہیں وہ فنا ہو جائیں گے: تم نے سب کو تباہ کر دیا ہے جو تم سے بدکاری کرتے ہیں۔\n28۔ لیکن میرے لیے خدا کے قریب جانا اچھا ہے: میں نے خداوند خدا پر بھروسہ کیا ہے تاکہ میں تیرے تمام اعمال کا اعلان کر سکوں۔","1. [آساف کا مشکیل] اے خدا، تو نے ہمیشہ کے لیے ہمیں کیوں چھوڑ دیا؟ {کیوں} تمہارا غصہ تمہاری چراگاہ کی بھیڑوں پر دھواں اٹھاتا ہے؟ {مشکیل...: یا، اساف کے لیے ایک زبور تاکہ وہ ہدایت دے}\n2۔ اپنی جماعت کو یاد رکھو، {جو} نے پرانی خریداری کی ہے؛ تمہاری وراثت کی چھڑی، {جو} تم نے چھڑا دی؛ یہ پہاڑ صیون ہے، جہاں تم رہتی ہو۔ {راڈ: یا، قبیلہ}\n3. اپنے پاؤں ہمیشہ کی ویرانی کی طرف اٹھا دو؛ {حتیٰ کہ} دشمن نے مقدس مقام میں جو کچھ بھی برا کیا ہے۔\n4۔ تمہارے دشمن تمہاری جماعتوں کے درمیان دھاڑتے ہیں؛ انہوں نے اپنے اینسائنز {for} نشانات لگایا۔\n5۔ {ایک آدمی} مشہور تھا کیونکہ اس نے گھنے درختوں پر کلہاڑیاں اٹھا رکھی تھیں۔\n6۔ لیکن اب وہ اس کے کندہ شدہ کام کو ایک ساتھ کلہاڑیوں اور ہتھوڑوں سے توڑ دیتے ہیں۔\n7۔ انہوں نے تیرے مقدس مقام میں آگ لگا دی ہے، انہوں نے {تمہارے نام کے گھر کو زمین پر گرا کر} ناپاک کیا ہے۔ {انہوں نے کاسٹ کیا ہے...: عبوری۔ انہوں نے تمہاری پناہ گاہ کو آگ میں بھیج دیا ہے}\n8۔ انہوں نے اپنے دلوں میں کہا، آؤ ہم انہیں مل کر تباہ کریں: انہوں نے زمین پر خدا کی تمام عبادت گاہیں جلا دی ہیں۔ {تباہ کریں: عبرانی۔ بریک}\n9۔ ہم اپنی نشانیاں نہیں دیکھتے: {اب کوئی نبی نہیں} اور نہ ہی ہمارے درمیان کوئی ایسا ہے جو جانتا ہے کہ کب تک ہے۔\n10. اے خدا، مخالف کب تک ملامت کرے گا؟ کیا دشمن ہمیشہ کے لیے تمہارے نام کی توہین کرے گا؟\n11۔ تم اپنا ہاتھ کیوں ہٹاتے ہو، یہاں تک کہ اپنا دایاں ہاتھ بھی؟ اسے اپنے سینے سے نکالو۔\n12۔ کیونکہ خدا میرا پرانے بادشاہ ہے، زمین کے بیچ نجات کے لیے کام کر رہا ہے۔\n13۔ تو نے اپنی طاقت سے سمندر کو تقسیم کیا: تو نے پانیوں میں اژدہوں کے سر توڑ دیے۔ {تقسیم: عبدی۔ بریک} {ڈریگن: یا، وہیلز}\n14۔ تو لیویاتھن کے سروں کو ٹکڑوں میں توڑتے ہو، {اور} اسے بیابان میں رہنے والے لوگوں کے لیے گوشت دیتی ہو۔\n15۔ تم نے چشمہ اور سیلاب کو چیر دیا: تو نے عظیم ندیاں خشک کیں۔ {mighty...: عبرانی طاقت کی ندیاں}\n16. دن {ہے} تمہارا ہے، رات بھی {ہے} تیری: تو نے روشنی اور سورج کو تیار کیا ہے۔\n17۔ تو نے زمین کی تمام سرحدیں مقرر کی ہیں: تو نے گرمیوں اور سردیوں کو بنایا ہے۔ {بنایا: عبرانی۔ انہیں بنایا}\n18۔ یاد رکھو کہ دشمن نے ملامت کی ہے، اے خداوند، اور یہ کہ بے وقوف لوگوں نے تیرے نام کی توہین کی ہے۔\n19۔ اپنے کچھوے کی کبوتر کی روح کو بدکاروں کی اکثریت کے حوالے نہ کرنا: ہمیشہ کے لیے اپنے غریبوں کی جماعت کو نہ بھولنا۔\n20۔ عہد کا احترام کرو: کیونکہ زمین کے تاریک علاقے ظلم کے مسکن سے بھرے ہوئے ہیں۔\n21. اے مظلوم شرمندہ ہو کر واپس نہ آئیں: غریب اور محتاج تیرا نام تعریف کریں۔\n22. اے خدا، اٹھو، اپنی مرضی کی وکالت کرو: یاد رکھو کہ بے وقوف انسان روزانہ تمہیں ملامت کرتا ہے۔\n23۔ اپنے دشمنوں کی آواز کو نہ بھولو: جو لوگ تمہارے خلاف اٹھتے ہیں ان کا ہنگامہ مسلسل بڑھتا جا رہا ہے۔ {اضافہ: عبرانی۔ عروج","1. [چیف موسیقار، الٹاشتھ کے نام، ایک زبور {یا} آساف کا گیت۔] اے خدا، ہم تیرے شکر ادا کرتے ہیں، {تجھ سے} ہم شکر ادا کرتے ہیں: کیونکہ {کہ} تیرا نام تمہارے حیرت انگیز اعمال کے قریب ہے۔ {الٹاشیتھ: یا، تباہ نہ کرو} {of: or, for}\n2. جب میں جماعت کو قبول کروں گا تو میں درست فیصلہ کروں گا۔ {وصول کریں...: یا، ایک مقررہ وقت لیں}\n3۔ زمین اور اس کے تمام باشندے تحلیل ہو چکے ہیں: میں اس کے ستون اٹھاتا ہوں۔ سیلہ۔\n4۔ میں نے بیوقوفوں سے کہا، بے وقوفی نہ کرو؛ اور بدکاروں سے سینگ نہ اٹھاؤ:\n5. اپنے سینگ کو اونچا نہ اٹھاؤ: سخت گردن سے بات نہ کرو۔\n6۔ ترقی کے لیے {آتا ہے} نہ مشرق سے، نہ مغرب سے، نہ جنوب سے۔ {جنوب: عبوری۔ صحرا}\n7. لیکن خدا منصف ہے: وہ ایک کو نیچے رکھتا ہے اور دوسرا بٹھاتا ہے۔\n8۔ کیونکہ خداوند کے ہاتھ میں ایک پیالہ ہے، اور شراب سرخ ہے؛ یہ آمیزش سے بھرا ہوا ہے؛ اور وہ اسی سے نکالتا ہے: لیکن اس کے ملبے کو زمین کے تمام بدکار نچوڑیں گے، {اور} انہیں پیئیں گے۔\n9۔ لیکن میں ہمیشہ کے لیے اعلان کروں گا؛ میں یعقوب کے خدا کی حمد و ثنا گاؤں گا۔\n10۔ میں بدکاروں کے تمام سینگ بھی کاٹوں گا؛ {لیکن} راستبازوں کے سینگ بلند ہوں گے۔","1. [نیگینوت کے چیف موسیقار کے نام، ایک زبور {یا} آساف کا گیت۔] یہوداہ میں خدا کو معلوم ہے: اس کا نام اسرائیل میں عظیم ہے۔ {چیف...: یا، نگران} {of: or, for}\n2۔ سیلم میں اس کا خیمہ اور صیہون میں رہائش گاہ بھی ہے۔\n3۔ وہاں وہ کمان، ڈھال، تلوار اور جنگ کے تیر توڑ دیتا ہے۔ سیلہ۔\n4۔ تم شکار کے پہاڑوں سے زیادہ شاندار اور بہترین ہو۔\n5. دلیر خراب ہو جاتے ہیں، وہ اپنی نیند سو چکے ہوتے ہیں: اور کسی بھی مرد کو اپنے ہاتھ نہیں مل پاتے۔\n6. اے یعقوب کے خدا، تیری سرزنش پر، رتھ اور گھوڑا دونوں مردہ نیند میں چلے جاتے ہیں۔\n7. تم، حتیٰ کہ تم، ڈرنا چاہیے: اور جب تم غصے میں ہو تو کون تمہاری نظر میں کھڑا ہو سکتا ہے؟\n8۔ تو نے آسمان سے فیصلہ سنانے پر مجبور کیا؛ زمین خوفزدہ تھی، اور ساکت تھی،\n9۔ جب خدا نے فیصلہ کیا، زمین کے تمام عاجزوں کو بچانے کے لیے۔ سیلہ۔\n10. یقینا انسان کا غضب تمہیں سراہے گا: باقی قہر کو تم روکنا گے۔\n11۔ عہد کرو اور اپنے خدا کو ادا کرو: اس کے ارد گرد جو لوگ ہیں وہ اس کے لیے تحفے لائیں جن سے ڈرنا چاہیے۔ {اس کے لیے...: عبرانی۔ خوفزدہ ہونا}\n12. وہ شہزادوں کی روح کو کاٹ دے گا: {وہ} زمین کے بادشاہوں کے لیے خوفناک ہے۔","1. [چیف موسیقار کے نام، یدوتون کے نام، آساف کا زبور۔] میں نے اپنی آواز سے خدا سے پکارا، {حتیٰ کہ} اپنی آواز سے خدا سے بھی؛ اور اس نے میری بات سنی۔ {of: or, for}\n2۔ اپنی مصیبت کے دن میں نے خداوند کی تلاش کی: میرا زخم رات کو دوڑتا رہا، اور رکا نہیں: میری روح نے تسلی دینے سے انکار کر دیا۔ {درد: عبوری۔ ہاتھ}\n3۔ میں نے خدا کو یاد کیا، اور پریشان ہوا: میں نے شکایت کی، اور میرا دل مغلوب ہو گیا۔ سیلہ۔\n4۔ تو میری آنکھوں کو جاگتے ہوئے دیکھتا ہے: میں اتنا پریشان ہوں کہ بول نہیں سکتا۔\n5۔ میں نے پرانے زمانے اور قدیم زمانے کے سالوں پر غور کیا ہے۔\n6. میں رات کو اپنے گیت کو یاد کرنے کو پکار رہا ہوں: میں اپنے دل سے رابطہ کرتا ہوں: اور میری روح نے محنت سے تلاش کی۔\n7. کیا خداوند ہمیشہ کے لیے چھوڑ دے گا؟ اور کیا وہ اب پسندیدہ نہیں رہے گا؟\n8. کیا اس کی رحمت ہمیشہ کے لیے ختم ہو گئی ہے؟ کیا اس کا وعدہ ہمیشہ کے لیے ناکام ہو جائے گا؟ {ہمیشہ کے لیے: عبرانی۔ نسل اور نسل کے لیے؟}\n9۔ کیا خدا نے مہربانی کرنا بھول گیا ہے؟ کیا اس نے غصے میں اپنی نرم رحمتیں بند کر دیں؟ سیلہ۔\n10۔ اور میں نے کہا، یہ میری کمزوری ہے: {لیکن میں سب سے اعلیٰ کے دائیں ہاتھ کے سالوں کو یاد رکھوں گا}۔\n11۔ میں خداوند کے اعمال کو یاد رکھوں گا: یقینا میں تیرے قدیم عجائبات کو یاد رکھوں گا۔\n12۔ میں تمہارے تمام کاموں پر بھی غور کروں گا، اور تمہارے اعمال کے بارے میں بات کروں گا۔\n13. اے خدا، تیرا راستہ {ہے} مقدس معبد میں: کون {ہمارا} خدا جیسا عظیم خدا ہے؟\n14۔ تو وہ خدا ہو جو عجائبات کرتا ہے: تو نے اپنی طاقت لوگوں میں ظاہر کی ہے۔\n15. تو نے اپنے بازو سے اپنے لوگ، یعقوب اور یوسف کے بیٹوں کو نجات دی ہے۔ سیلہ۔\n16. پانیوں نے تمہیں دیکھا، اے خدا، پانیوں نے تمہیں دیکھا؛ وہ خوفزدہ تھے: گہرائیاں بھی پریشان تھیں۔\n17۔ بادل پانی بہا رہے تھے: آسمان نے آواز نکالی: تمہارے تیر بھی باہر نکل گئے۔ {ڈال کر...: عبرانی۔ پانی کے ساتھ بہایا گیا}\n18۔ تیرے گرج کی آواز آسمان میں تھی: بجلی نے دنیا کو روشن کیا: زمین لرز رہی تھی اور ہل رہی تھی۔\n19۔ تیری راہ سمندر میں ہے، اور تیری راہ عظیم پانیوں میں، اور تمہارے قدموں کے نشان معلوم نہیں۔\n20. تو اپنے لوگوں کو موسیٰ اور ہارون کے ہاتھوں ریوڑ کی طرح لے جاتا ہے۔","1. [آساف کا مشکیل] اے میرے لوگو، میرے قانون کو سنو: میرے منہ کی باتوں کی طرف اپنے کان جھکاؤ۔ {مشکیل...: یا، اساف کے لیے ایک زبور تاکہ وہ ہدایت دے}\n2۔ میں ایک تمثیل میں اپنا منہ کھولوں گا: میں پرانے سیاہ اقوال کہوں گا:\n3۔ جو ہم نے سنا اور جانا ہے، اور ہمارے آباؤ اجداد نے ہمیں بتایا ہے۔\n4۔ ہم ان کے بچوں سے انہیں نہیں چھپائیں گے، آنے والی نسلوں کو خداوند کی حمد، اس کی طاقت، اور اس کے شاندار کاموں کو دکھائیں گے۔\n5۔ کیونکہ اس نے یعقوب میں گواہی قائم کی، اور اسرائیل میں ایک قانون مقرر کیا، جسے اس نے ہمارے آباؤ اجداد کو حکم دیا کہ وہ اپنے بچوں کو یہ بیان کریں:\n6۔ تاکہ آنے والی نسلیں {انہیں، حتیٰ کہ} ان بچوں کو بھی جان سکیں جو پیدا ہونے چاہئیں؛ {کون} اٹھیں اور اپنے بچوں کو اعلان کریں:\n7۔ تاکہ وہ خدا پر امید رکھیں، اور خدا کے اعمال کو نہ بھولیں، بلکہ اس کے احکامات کی پاسداری کریں:\n8۔ اور وہ اپنے باپ کی طرح نہیں ہو سکتے، جو ضدی اور باغی نسل تھی؛ ایک ایسی نسل {جو} نے اپنا دل درست نہیں کیا، اور جس کی روح خدا کے ساتھ مضبوط نہیں تھی۔ {وہ...: عببرانی۔ جس نے ان کے دل کو تیار نہیں کیا}\n9۔ افرائیم کے بچے، {مسلح} ہو کر، {اور} کمانیں اٹھائے ہوئے، جنگ کے دن واپس پلٹ گئے۔ {لے کر چلتے ہوئے: عبوری۔ آگے پھینکنا}\n10۔ انہوں نے خدا کے عہد کی پاسداری نہیں کی، اور اس کے قانون پر چلنے سے انکار کیا؛\n11۔ اور اپنے کاموں اور عجائبات کو بھول گیا جو اس نے انہیں دکھایا۔\n12. اس نے اپنے آباؤ اجداد کی نظر میں، مصر کی سرزمین میں، زوآن کے میدان میں حیرت انگیز کام کیے۔\n13۔ اس نے سمندر کو تقسیم کیا، اور انہیں گزرنے پر مجبور کیا؛ اور اس نے پانی کو ایک ڈھیر کی طرح کھڑا کر دیا۔\n14۔ دن کے وقت بھی وہ انہیں بادل کے ساتھ اور ساری رات آگ کی روشنی کے ساتھ رہنمائی کرتا۔\n15۔ اس نے جنگل میں چٹانوں کو کاٹا، اور {ان} کو {گہرائیوں سے} کی طرح پانی دیا۔\n16۔ اس نے چٹان سے ندی نالے بھی نکالے، اور پانی کو دریاوں کی طرح بہایا۔\n17۔ اور انہوں نے اس کے خلاف مزید گناہ کیا کیونکہ انہوں نے سب سے بلند کو ویرانے میں بھڑکایا۔\n18۔ اور انہوں نے اپنے دل میں خدا کو اپنی ہوس کے لیے گوشت مانگ کر آزمایا۔\n19۔ ہاں، انہوں نے خدا کے خلاف بات کی؛ انہوں نے کہا، کیا خدا جنگل میں میز فراہم کر سکتا ہے؟ {فرنش: عبوری۔ آرڈر}\n20۔ دیکھو، اس نے چٹان کو مارا، پانی بہہ نکلا، اور ندیاں بہنے لگیں؛ کیا وہ روٹی بھی دے سکتا ہے؟ کیا وہ اپنے لوگوں کے لیے گوشت فراہم کر سکتا ہے؟\n21. اسی لیے خداوند نے یہ سنا اور غصے میں آ گیا: یوں یعقوب پر آگ بھڑک اٹھی اور اسرائیل پر بھی غصہ بھڑک اٹھا؛\n22۔ کیونکہ وہ خدا پر ایمان نہیں رکھتے تھے، اور اس کی نجات پر بھروسہ نہیں کرتے تھے:\n23۔ اگرچہ اس نے اوپر سے بادلوں کو حکم دیا تھا، اور آسمان کے دروازے کھولے،\n24۔ اور ان پر منا برسائے کہ وہ کھائیں، اور انہیں آسمان کے اناج سے دیا۔\n25۔ انسان نے فرشتوں کا کھانا کھایا: اس نے انہیں بھرپور گوشت بھیجا۔ {آدمی...: یا، ہر کوئی طاقتوروں کی روٹی کھاتا تھا}\n26۔ اس نے آسمان میں مشرقی ہوا چلائی: اور اپنی طاقت سے جنوبی ہوا لے آیا۔ {پھونکنے کے لیے: عببرانی۔ جانے کے لیے}\n27۔ اس نے ان پر گوشت بھی مٹی کی طرح برسایا، اور پرندوں کو سمندر کی ریت کی طرح برسایا: {پروں والا...: عبرانی۔ پرندوں کا پرندہ}\n28۔ اور اس نے اسے ان کے کیمپ کے بیچ، ان کے گھروں کے ارد گرد گرنے دیا۔\n29۔ تو انہوں نے کھانا کھایا اور خوب بھر گئے: کیونکہ اس نے انہیں ان کی اپنی خواہش دی؛\n30۔ وہ اپنی ہوس سے دور نہیں تھے۔ لیکن جب ان کا گوشت ابھی ان کے منہ میں تھا،\n31۔ خدا کا غضب ان پر نازل ہوا، ان میں سے سب سے موٹے کو مار ڈالا، اور اسرائیل کے منتخب لوگوں کو شکست دی۔ {سموٹ...: ہیب۔ جھکنے پر مجبور کیا گیا} {منتخب شدہ...: یا، نوجوان مرد}\n32۔ ان سب کے لیے انہوں نے اب بھی گناہ کیا، اور اس کے حیرت انگیز اعمال پر یقین نہیں کیا۔\n33۔ اسی لیے اس نے ان کے دن بے خودی میں گزارے، اور ان کے سال مصیبت میں۔\n34۔ جب اس نے انہیں قتل کیا، تو وہ اس کی تلاش میں تھے: اور وہ واپس آئے اور خدا سے جلد پوچھے۔\n35۔ اور انہوں نے یاد رکھا کہ خدا ان کا پتھر ہے، اور اعلیٰ خدا ان کا نجات دہندہ۔\n36۔ پھر بھی انہوں نے اپنے منہ سے اس کی خوشامد کی، اور اپنی زبانوں سے اس سے جھوٹ بولا۔\n37۔ کیونکہ ان کا دل اس کے ساتھ ٹھیک نہیں تھا، اور نہ ہی وہ اس کے عہد میں مضبوطی سے قائم نہیں تھے۔\n38۔ لیکن وہ، جو رحم سے بھرا ہوا تھا، نے ان کی غلطی معاف کی، اور انہیں تباہ نہیں کیا: ہاں، کئی بار اس نے اپنا غصہ دور کر دیا، اور اپنا سارا غصہ نہیں بھڑکایا۔\n39۔ کیونکہ اسے یاد تھا کہ وہ صرف جسم تھے؛ ایک ہوا جو گزر جاتی ہے، اور دوبارہ نہیں آتی۔\n40۔ کتنی بار انہوں نے اسے صحرا میں اشتعال دلایا، {اور} صحرا میں اس کا غم منایا! {اشتعال: یا، بغاوت کریں}\n41۔ ہاں، انہوں نے پلٹ کر خدا کو آزمایا، اور اسرائیل کے مقدس وجود کو محدود کیا۔\n42۔ انہوں نے اس کے ہاتھ کو یاد نہیں کیا، نہ ہی اس دن کو جب اس نے انہیں دشمن سے بچایا۔ {سے...: یا، مصیبت سے}\n43۔ اس نے مصر میں اپنے نشانات کیسے بنائے، اور زوان کے میدان میں اپنے عجائبات: {لکھا: عبرانی۔ سیٹ}\n44۔ اور ان کی ندیوں کو خون میں بدل دیا؛ اور ان کے سیلاب، جنہیں وہ پی نہیں سکتے تھے۔\n45۔ اس نے ان کے درمیان مختلف قسم کی مکھیاں بھیجیں، جو انہیں کھا گئیں؛ اور مینڈک، جنہوں نے انہیں تباہ کر دیا۔\n46۔ اس نے ان کا اضافہ بھی کیٹرپلر کو دے دیا، اور ان کی محنت ٹڈی دل کو۔\n47۔ اس نے ان کی بیلوں کو اولے سے تباہ کیا، اور ان کے چاپلوس کے درختوں کو برف سے تباہ کیا۔ {تباہ شدہ: عبرانی۔ مارے گئے} {فراسٹ: یا، عظیم اولے پتھر}\n48۔ اس نے ان کے مویشی بھی اولے کے حوالے کر دیے، اور ان کے ریوڑ کو گرم بجلی کے جھٹکوں کے حوالے کر دیا۔ {دیا گیا...: عببرانی۔ چپ ہو جاؤ} {گرم...: یا، بجلی}\n49۔ اس نے اپنے غصے، غضب، غصے اور مصیبت کی شدت ان پر ڈالی، اور ان میں برے فرشتے بھیجے۔\n50۔ اس نے اپنے غصے کی طرف راستہ بنایا؛ اس نے ان کی روح کو موت سے نہیں بخشا، بلکہ ان کی جان وبا کے حوالے کر دی؛ {اس نے بنایا...: عبرانی۔ اس نے ایک راستہ تول کر لیا} {زندگی...: یا، جانور مرین کی طرف}\n51۔ اور مصر کے تمام پہلے بچوں کو مارو؛ ہام کے خیموں میں {ان} کی طاقت کے سردار:\n52. بلکہ اس نے اپنے لوگوں کو بھیڑوں کی طرح باہر نکلنے پر مجبور کیا، اور انہیں بیابان میں ریوڑ کی طرح رہنمائی کی۔\n53۔ اور اس نے انہیں محفوظ طریقے سے آگے بڑھایا، تاکہ وہ خوفزدہ نہ ہوں: لیکن سمندر نے ان کے دشمنوں کو مغلوب کر دیا۔ {مغلوب ہو کر: عبوری۔ کورڈ}\n54۔ اور اس نے انہیں اپنے مقدس مقام کی سرحد تک پہنچایا، {یہاں تک کہ} اس پہاڑ تک بھی، {جو} اس کے دائیں ہاتھ نے خریدا تھا۔\n55۔ اس نے کافروں کو بھی ان کے سامنے نکال دیا، انہیں وراثت میں تقسیم کیا، اور اسرائیل کے قبائل کو ان کے خیموں میں آباد کیا۔\n56۔ پھر بھی انہوں نے سب سے بلند خدا کو آزمایا اور اکسایا، اور اس کی گواہی نہ رکھی:\n57۔ لیکن پلٹ گئے، اور اپنے باپوں کی طرح بے وفائی سے پیش آئے: انہیں دھوکہ دہی کی طرح پیچھے ہٹا دیا گیا۔\n58۔ کیونکہ انہوں نے اپنے اعلیٰ عہدوں سے اسے غصہ دلایا، اور اپنے کندہ شدہ مجسموں سے اسے حسد میں مبتلا کر دیا۔\n59۔ جب خدا نے یہ سنا تو وہ غصے میں آ گیا اور اسرائیل سے شدید نفرت کرنے لگا:\n60۔ اس لیے اس نے شیلوہ کے خیمے کو چھوڑ دیا، جو اس نے انسانوں کے درمیان لگایا تھا؛\n61۔ اور اپنی طاقت کو قید میں لے آیا، اور اپنی شان دشمن کے ہاتھ میں۔\n62۔ اس نے اپنے لوگوں کو بھی تلوار کے حوالے کر دیا؛ اور اپنی وراثت پر غصے میں تھا۔\n63۔ آگ نے ان کے نوجوانوں کو جلا دیا؛ اور ان کی کنواریوں کو شادی کے لیے نہیں دیا گیا۔ {دیا گیا...: عبرانی۔ تعریف}\n64۔ ان کے پادری تلوار سے مارے گئے؛ اور ان کی بیواؤں نے کوئی افسوس نہیں کیا۔\n65۔ پھر خداوند نیند سے ایک کی طرح جاگا، {اور} ایک طاقتور آدمی کی طرح جو شراب کی وجہ سے چیختا ہے۔\n66۔ اور اس نے اپنے دشمنوں کو پچھلے حصوں پر مارا: انہیں ہمیشہ ملامت میں ڈال دیا۔\n67۔ اس کے علاوہ اس نے یوسف کے خیمے کو قبول کرنے سے انکار کر دیا، اور افریم کے قبیلے کو منتخب نہیں کیا:\n68۔ لیکن اس نے یہوداہ کے قبیلے کو چنا، وہ پہاڑ صیون جس سے وہ محبت کرتا تھا۔\n69۔ اور اس نے اپنا مقدس مقام بلند محلوں کی طرح بنایا، جیسے وہ زمین جو اس نے ہمیشہ کے لیے قائم کی ہے۔ {قائم: عبرانی۔ قائم شدہ}\n70۔ اس نے داؤد کو بھی اپنا خادم منتخب کیا، اور اسے بھیڑوں کے باغات سے نکالا:\n71۔ بڑی بھیڑوں کی پیروی کرتے ہوئے اس نے اسے یعقوب کو اس کے لوگوں کو کھلانے اور اسرائیل کو اس کی میراث دینے کے لیے لایا۔ {فالونگ: عببرانی۔ بعد میں}\n72۔ تو اس نے اپنے دل کی سالمیت کے مطابق انہیں کھلایا؛ اور اپنے ہاتھوں کی مہارت سے انہیں رہنمائی دی۔","1. [آساف کا زبور۔] اے خدا، کافر تیری وراثت میں آ گئے ہیں؛ تیرے مقدس مندر کو انہوں نے آلودہ کیا؛ انہوں نے یروشلم کو ڈھیر کر دیا ہے۔ {of: or, for}\n2۔ تمہارے بندوں کے مردہ جسموں نے آسمان کے پرندوں کو گوشت دیا ہے، تیری مقدسین کا گوشت زمین کے جانوروں کو۔\n3۔ ان کا خون یروشلم کے ارد گرد پانی کی طرح بہایا گیا ہے؛ اور {وہاں کوئی نہیں تھا جسے {ان} دفن کیا جا سکے۔\n4۔ ہم اپنے پڑوسیوں کے لیے ملامت بن چکے ہیں، ان کے لیے جو ہمارے ارد گرد ہیں ان کے لیے حقارت اور طنز۔\n5. کتنی لمبی، خداوند؟ کیا تم ہمیشہ کے لیے ناراض رہو گے؟ کیا تمہاری حسد آگ کی طرح جلے گی؟\n6۔ اپنا غضب ان کافروں پر ڈال دو جو تمہیں نہیں جانتے، اور ان سلطنتوں پر جو تیرے نام کو نہیں پکارتے۔\n7۔ کیونکہ انہوں نے یعقوب کو نگل لیا ہے، اور اس کا مسکن تباہ کر دیا ہے۔\n8. اے ہمارے خلاف سابقہ گناہوں کو یاد نہ رکھو: تمہاری نرم رحمتیں ہمیں جلدی روک لیں: کیونکہ ہم بہت نیچا دکھا چکے ہیں۔ {سابقہ...: یا، ان گناہوں کی جو ہم سے پہلے تھے}\n9. اے خدا، ہماری نجات کے خدا، اپنے نام کی شان کے لیے ہماری مدد فرما: اور ہمیں نجات دے، اور ہمارے گناہوں کو اپنے نام کے لیے پاک کر۔\n10۔ کافر کیوں کہیں، ان کا خدا کہاں ہے؟ اسے ہمارے سامنے کافروں میں پہچانا جائے {تمہارے بندوں کے خون کے بدلے سے} جو بہایا گیا ہے۔ {انتقام: عبوری۔ انتقام}\n11۔ قیدی کی آہ تمہارے سامنے آ جائے؛ اپنی طاقت کی عظمت کے مطابق ان لوگوں کو محفوظ رکھو جنہیں مرنے کے لیے مقرر کیا گیا ہے؛ {تمہاری...: عببری۔ تمہارا بازو} {محفوظ...: عبرانی۔ موت کے بچوں کو محفوظ رکھو}\n12۔ اور ہمارے پڑوسیوں کو ان کی ملامت سات گنا ان کے سینے میں دے دو، جس سے انہوں نے تمہیں ملامت کی ہے، اے خداوند۔\n13. تو ہم تیرے لوگ اور تیری چراگاہ کی بھیڑیں ہمیشہ کے لیے تمہارا شکر ادا کریں گے: ہم تمام نسلوں تک تیری تعریف کریں گے۔ {سب کے لیے...: عبرانی۔ نسل اور نسل کے لیے}","1. [شوشانی میدوتھ پر چیف موسیقار کے نام، آساف کا زبور۔] اے اسرائیل کے چرواہے، تم سنو جو یوسف کو ریوڑ کی طرح رہنمائی کرتے ہو؛ تم جو کروبیوں کے درمیان رہتا ہے، چمکو۔ {of: or, for}\n2۔ اس سے پہلے کہ افرائیم، بنیامین اور منسی اپنی طاقت کو جگائے، اور آ کر ہمیں بچانے آئیں۔ {آؤ...: عبرانی۔ نجات کے لیے ہمارے پاس آؤ}\n3. اے خدا، ہمیں دوبارہ پلٹ کر اور اپنا چہرہ روشن کر؛ اور ہم نجات پائیں گے۔\n4. اے خداوند، لشکروں کے خدا، تم اپنے لوگوں کی دعا پر کتنی دیر تک غصے میں رہو گے؟ {be...: عبرانی۔ دھواں\n5۔ تو انہیں آنسوؤں کی روٹی سے کھلاتے ہو؛ اور انہیں بڑی مقدار میں آنسو پینے کے لیے دے دیں۔\n6۔ تو ہمیں ہمارے پڑوسیوں کے لیے جھگڑا بناتی ہے: اور ہمارے دشمن آپس میں ہنستے ہیں۔\n7. اے لشکروں کے خدا، ہمیں دوبارہ پلٹ کر اور اپنا چہرہ روشن کر؛ اور ہم نجات پائیں گے۔\n8۔ تم نے مصر سے ایک بیل نکالی: تو نے کافروں کو نکال دیا اور اسے بویا۔\n9۔ تو نے اس کے سامنے جگہ تیار کی، اور اسے گہرائی سے جڑ پکڑا، اور اس نے زمین کو بھر دیا۔\n10۔ پہاڑیاں اس کے سائے میں ڈھکی ہوئی تھیں، اور ان کی شاخیں خوبصورت دیودار کی مانند تھیں۔ {اچھا...: عبوری۔ خدا کے دیودار}\n11۔ اس نے اپنی شاخیں سمندر میں اور اپنی شاخیں دریا کی طرف بھیجیں۔\n12. تو پھر تم نے اس کی باڑیں کیوں توڑ دیں، تاکہ جو لوگ راستے سے گزرتے ہیں وہ اسے توڑ دیں؟\n13۔ جنگل سے نکلا ہوا سور اسے ضائع کر دیتا ہے، اور میدان کا جنگلی جانور اسے کھا جاتا ہے۔\n14. ہم تجھ سے التجا کرتے ہیں، اے لشکروں کے خدا، واپس آؤ: آسمان سے نیچے دیکھو، اور دیکھو، اور اس انگور کو دیکھو؛\n15۔ اور وہ انگور کا باغ جو تمہارے دائیں ہاتھ نے لگایا ہے، اور وہ شاخ جو تم اپنے لیے مضبوط ہو۔\n16۔ {یہ} آگ سے جلایا گیا، {یہ} کاٹ دیا گیا: وہ تیری حالت کی سرزنش پر مر جاتے ہیں۔\n17۔ اپنا ہاتھ اپنے دائیں ہاتھ کے آدمی پر رکھو، اس انسان کے بیٹے پر جسے تم اپنے لیے مضبوطی سے دیوانے ہو۔\n18. تو ہم تم سے واپس نہیں جائیں گے: ہمیں زندہ کر، اور ہم تیرے نام کو پکاریں گے۔\n19۔ اے خداوند، لشکروں کے خدا، ہمیں دوبارہ پلٹاؤ، اپنا چہرہ روشن کر؛ اور ہم نجات پائیں گے۔","1. [گتیتھ پر چیف موسیقار کے نام، {اے زبور} آف آساف۔] خدا کو ہماری طاقت سے بلند آواز میں گاؤ: یعقوب کے خدا کے لیے خوشی سے آواز نکالو۔ {آساف کا: یا، آساف کے لیے}\n2۔ ایک زبور لیں، اور یہاں ٹمبرل، خوشگوار ہارپ لے آئیں جس میں زبور ہے۔\n3۔ نئے چاند پر، مقررہ وقت پر، ہمارے باوقار تہوار کے دن بجانا۔\n4۔ کیونکہ یہ {تھا} اسرائیل کے لیے ایک قانون تھا، {اور} یعقوب کے خدا کا قانون۔\n5۔ یہ اس نے یوسف میں {بطور} گواہی مقرر کی، جب وہ مصر کی سرزمین سے نکلا: {جہاں} میں نے ایک ایسی زبان سنی {جو میں نہیں سمجھ سکا}۔ {ذریعہ: یا، خلاف}\n6۔ میں نے اس کے کندھے کو بوجھ سے ہٹایا: اس کے ہاتھ برتنوں سے نکال دیے گئے۔ {تھے...: عبرانی انتقال کر گئے}\n7۔ تم نے مصیبت میں بلایا، اور میں نے تمہیں نجات دی؛ میں نے تمہیں گرج کی خفیہ جگہ پر جواب دیا: میں نے تمہیں مریبہ کے پانیوں میں ثابت کیا۔ سیلہ۔ {میریبا: یا، جھگڑا}\n8۔ اے میرے لوگ، سن لو، اور میں تم پر گواہی دوں گا: اے اسرائیل، اگر تم میری بات سنو؛\n9۔ تم میں کوئی اجنبی خدا نہیں ہوگا؛ نہ ہی تم کسی اجنبی خدا کی عبادت کرو گے۔\n10. میں خداوند ہوں، تیرا خدا، جس نے تمہیں مصر کی سرزمین سے نکالا: اپنا منہ کھول دے، اور میں اسے بھر دوں گا۔\n11۔ لیکن میرے لوگ میری آواز نہیں سنتے؛ اور اسرائیل مجھ سے کچھ نہیں کرے گا۔\n12. تو میں نے انہیں ان کے اپنے دل کی ہوس کے حوالے کر دیا: {اور} وہ اپنی ہی نصیحتوں میں چلتے رہے۔ {تو...: یا، ان کے دلوں کی سختی کو، یا، تخیل کے لیے}\n13. اے کاش میرے لوگ میری بات سنتے، {اور} اسرائیل میرے راستے پر چلتا!\n14. مجھے جلد ہی ان کے دشمنوں کو زیر کر لینا چاہیے تھا، اور اپنے ہاتھ کو ان کے مخالفین کے خلاف کرنا چاہیے تھا۔\n15۔ خداوند کے مخالفین کو چاہیے تھا کہ وہ اس کے سامنے سر تسلیم خم کرتے: لیکن ان کا وقت ہمیشہ کے لیے قائم رہنا چاہیے تھا۔ {submitted...: یا، دکھاوے میں اطاعت قبول کیا: عبرانی۔ جھوٹ بولا}\n16۔ اسے انہیں بہترین گندم بھی کھلانی چاہیے تھی: اور پتھر سے شہد بھی کھلانا چاہیے تھا اگر میں تمہیں مطمئن کر لیتا۔ {بہترین...: عبرانی گندم کی چکنائی}","1. [آساف کا زبور۔] خدا طاقتوروں کی جماعت میں کھڑا ہے؛ وہ دیوتاؤں میں فیصلہ کرتا ہے۔ {آساف کا: یا، آساف کے لیے}\n2. آپ کتنی دیر تک ناانصافی سے فیصلہ کریں گے، اور بدکاروں کو قبول کریں گے؟ سیلہ۔\n3۔ غریبوں اور یتیم لوگوں کا دفاع کریں: مظلوموں اور محتاجوں کے ساتھ انصاف کریں۔ {دفاع: عبرانی۔ جج}\n4۔ غریبوں اور محتاجوں کو آزاد کرو: انہیں بدکاروں کے ہاتھوں سے آزاد کرو۔\n5. وہ نہ جانتے ہیں، نہ ہی سمجھیں گے؛ وہ اندھیرے میں چلتے ہیں: زمین کی تمام بنیادیں ظاہر ہے کہ ختم ہو چکی ہیں۔ {باہر...: عببرانی۔ منتقل ہو گیا}\n6۔ میں نے کہا ہے، تم خدا ہو؛ اور تم سب سب اعلیٰ کے بچے ہو۔\n7۔ لیکن تم انسانوں کی طرح مرو گے، اور شہزادوں کی طرح گرو گے۔\n8۔ اے خدا، اٹھو، زمین کا فیصلہ کرو: کیونکہ تم تمام قوموں کا وارث بنو گے۔","1. [آساف کا ایک گیت {یا} زبور۔] اے خدا، خاموش نہ رہو، اور خاموش نہ رہو، اے خدا۔ {آساف کا: یا، آساف کے لیے}\n2۔ کیونکہ دیکھو، تمہارے دشمن ہنگامہ کرتے ہیں: اور جو تم سے نفرت کرتے ہیں انہوں نے سر اٹھا لیا ہے۔\n3۔ انہوں نے تمہارے لوگوں کے خلاف چالاک مشورے دیے ہیں، اور تمہارے پوشیدہ لوگوں کے خلاف مشورہ کیا ہے۔\n4۔ انہوں نے کہا ہے، آؤ، اور ہم انہیں قوم بننے سے کاٹ دیں؛ تاکہ اسرائیل کا نام یاد میں نہ رہے۔\n5۔ کیونکہ انہوں نے ایک رضامندی کے ساتھ مل کر مشورہ کیا ہے: وہ آپ کے خلاف متحد ہیں: {رضامندی: عبرانی۔ دل}\n6۔ ادوم کے خیمے اور اسماعیلیہ؛ موآب اور ہاگرینز کے؛\n7۔ جبل، اور آمون، اور امالیک؛ فلسطینیوں کے ساتھ صور کے باشندے؛\n8۔ اسور بھی ان کے ساتھ شامل ہو جاتا ہے: انہوں نے لوط کے بچوں کو گود میں لے لیا ہے۔ سیلہ۔ {ہولپن: عبوری۔ میں نے بھی مدد کی ہے}\n9۔ ان کے ساتھ ویسا ہی سلوک کرو جیسا مدیانیوں کے ساتھ ہوتا ہے؛ بطور {ٹو} سیسرا، بطور {ٹو} جابین، کسون کی ندی پر:\n10۔ {جو} اینڈور میں ہلاک ہو گئے: وہ زمین کے لیے {گوبر کی طرح} بن گئے۔\n11۔ ان کے اشرافیہ کو عرب کی طرح اور زیب کی طرح بنا دو: ہاں، ان کے تمام شہزادوں کو زباہ اور زلمنا کے طور پر:\n12۔ جس نے کہا، آؤ ہم اپنے پاس خدا کے گھر لے لیں جو مالک ہیں۔\n13۔ اے میرے خدا، انہیں ایک پہیہ کی طرح بنا دے؛ جیسے ہوا سے پہلے کی داڑھی۔\n14۔ جیسے آگ لکڑی کو جلا دیتی ہے، اور جیسے شعلہ پہاڑوں کو آگ میں جلا دیتی ہے؛\n15۔ تو اپنے طوفان سے انہیں ستا، اور اپنے طوفان سے انہیں خوفزدہ کر دے۔\n16۔ ان کے چہروں کو شرمندگی سے بھر دو؛ تاکہ وہ تیرا نام تلاش کریں، اے خداوند۔\n17۔ انہیں ہمیشہ کے لیے الجھن اور پریشان رہنے دو؛ ہاں، انہیں شرمندہ کر کے فنا ہو جائے:\n18. تاکہ {انسان} جان سکیں کہ تو، جس کا نام صرف {ہے} یہوواہ ہے، {زمینوں پر سب سے بلند} ہے۔","1. [گتیتھ پر چیف موسیقار کے نام، قارح کے بیٹوں کے لیے زبور۔] تیرے خیمے کتنے خوش اخلاق ہیں، اے لشکروں کے رب! {بیٹوں کے لیے: یا، بیٹوں کے لیے}\n2۔ میری جان خدا کے درباروں کے لیے بے ہوش بھی ہو جاتی ہے: میرا دل اور جسم زندہ خدا کے لیے پکار رہے ہیں۔\n3۔ ہاں، چڑیا نے گھر ڈھونڈ لیا ہے، اور وہ اپنے لیے گھونسلہ بنا چکی ہے، جہاں وہ اپنے بچوں کو رکھ سکتی ہے، {حتیٰ کہ} تیرے قربان گاہوں، اے لشکروں کے رب، میرے بادشاہ اور میرے خدا۔\n4۔ مبارک ہوں وہ جو تیرے گھر میں رہتے ہیں: وہ اب بھی آپ کی تعریف کریں گے۔ سیلہ۔\n5. مبارک ہے وہ شخص جس کی طاقت تمہارے اندر ہے؛ جس کے دل میں ان کے طریقے ہیں۔\n6۔ {جو} وادی باکا سے گزرتے ہوئے اسے کنواں بناتے ہیں؛ بارش بھی تالابوں کو بھر دیتی ہے۔ {باکا...: یا، شہتوت کے درخت اسے کنواں بناتے ہیں، وغیرہ} {فلتھ: عبرانی۔ کووریتھ}\n7۔ وہ طاقت سے طاقت میں جاتے ہیں، {ان میں سے ہر ایک} صیہون میں خدا کے سامنے ظاہر ہوتا ہے۔ {طاقت سے...: یا، کمپنی سے کمپنی}\n8. اے خداوند، لشکروں کے خدا، میری دعا سن: اے یعقوب کے خدا کی سنو۔ سیلہ۔\n9. اے خدا، ہمارا ڈھال دیکھو، اور اپنے مسح شدہ کے چہرے کو دیکھو۔\n10۔ تمہارے درباروں میں ایک دن ہزار سے بہتر ہے۔ میں اپنے خدا کے گھر میں دربان بننا پسند کرتا تھا، بجائے اس کے کہ برائی کے خیموں میں رہوں۔ {میرے پاس...: عبرانی میں چاہوں گا کہ دروازے پر بیٹھوں}\n11۔ کیونکہ خداوند خدا سورج اور ڈھال ہے: خداوند فضل اور جلال دے گا: وہ ان لوگوں سے کوئی بھلائی نہیں روک سکتا جو سیدھے چلتے ہیں۔\n12۔ اے لشکروں کے رب، مبارک ہے وہ آدمی جو تم پر بھروسہ کرتا ہے۔","1. [اہم موسیقار کے نام، قارح کے بیٹوں کے لیے زبور۔] اے خداوند، تو نے اپنی زمین پر مہربانی کی ہے: تو نے یعقوب کی قید واپس لائی ہے۔ {بیٹوں کے لیے: یا، بیٹوں کے لیے} {موافق: یا، خوش ہوں}\n2۔ تم نے اپنے لوگوں کی گناہوں کو معاف کر دیا ہے، تم نے ان کے تمام گناہوں کو چھپا دیا ہے۔ سیلہ۔\n3۔ تم نے اپنا سارا غصہ دور کر دیا ہے: تم نے اپنے غصے کی شدت سے خود کو روک لیا ہے۔ {تمہارا خود...: یا، تمہارا غصہ گرم ہونے کی وجہ سے}\n4. اے خداوند، ہمیں ہماری نجات سے آزاد کر اور اپنے غصے کو ہم پر ختم کر دے۔\n5. کیا تم ہمیشہ ہم سے ناراض رہو گے؟ کیا تم اپنا غصہ تمام نسلوں تک پہنچاؤ گے؟\n6۔ کیا تم ہمیں دوبارہ زندہ نہیں کرو گے: تاکہ تمہارے لوگ تم پر خوش ہوں؟\n7. اے خداوند، اپنی رحمت دکھاؤ اور ہمیں اپنی نجات عطا فرما۔\n8۔ میں وہی سنوں گا جو خدا خداوند بولے گا: کیونکہ وہ اپنے لوگوں اور مقدسین سے امن کی بات کرے گا: لیکن وہ دوبارہ حماقت کی طرف نہ مڑیں۔\n9۔ یقینا اس کی نجات ان لوگوں کے قریب ہے جو اس سے ڈرتے ہیں؛ تاکہ جلال ہمارے ملک میں بسے۔\n10۔ رحم اور سچائی ایک ساتھ ملتی ہے؛ راستبازی اور امن نے ایک دوسرے کو چوم لیا ہے۔\n11۔ سچائی زمین سے پھوٹے گی؛ اور راستبازی آسمان سے نیچے دیکھے گی۔\n12. ہاں، خداوند {جو اچھا ہے} دے گا؛ اور ہماری زمین اس میں اضافہ کرے گی۔\n13۔ راستبازی اس کے سامنے جائے گی؛ اور ہمیں اس کے قدموں کے راستے میں لے آئے گا۔","1. [داؤد کی دعا۔] اے خداوند، اپنا کان جھکا دے، میری سنو: کیونکہ میں غریب اور محتاج ہوں۔ {ایک دعا...: یا، ایک دعا، جو داؤد کا زبور ہے}\n2. میری روح کو محفوظ رکھو؛ کیونکہ میں مقدس ہوں: اے میرے خدا، اپنے اس بندے کو بچا جو تم پر بھروسہ کرتا ہے۔ {مقدس: یا، جسے تم پسند کرتے ہو}\n3. اے خداوند، میرے ساتھ رحم فرما: کیونکہ میں روزانہ تجھ سے پکار رہا ہوں۔ {روزانہ: یا، سارا دن}\n4۔ اپنے بندے کی روح کو خوش کرو: کیونکہ اے خداوند، میں تیری طرف اپنی جان اٹھاتا ہوں۔\n5۔ کیونکہ تو، اے خداوند، نیک اور معاف کرنے کے لیے تیار ہو؛ اور ان سب کے لیے جو تمہیں پکار رہے ہیں، ان پر بہت زیادہ رحمت ہے۔\n6. اے خداوند، میری دعا کو سنو؛ اور میری دعاؤں کی آواز سنو۔\n7۔ اپنی مصیبت کے دن میں تم سے پکاروں گا: کیونکہ تم مجھے جواب دو گے۔\n8. اے خداوند، دیوتاؤں میں تیرے جیسا کوئی نہیں؛ نہ ہی {کوئی کام ہے} جو تیری کارناموں جیسا ہو۔\n9۔ تمام قومیں جنہیں تو نے بنایا ہے، وہ آ کر تیرے سامنے عبادت کریں گی، اے خداوند؛ اور تمہارے نام کی جلال بخشوں گا۔\n10۔ کیونکہ تو عظیم ہو، اور حیرت انگیز کام کرتا ہے: تو صرف خدا ہی ہو۔\n11. اے خداوند، مجھے اپنا راستہ سکھاؤ؛ میں تیرے سچائی میں چلوں گا: اپنے دل کو متحد کر کے تیرے نام سے ڈرتا ہوں۔\n12. اے خداوند میرے خدا، میں پورے دل سے تیری حمد کروں گا، اور ہمیشہ کے لیے تیرا نام جلال بخشوں گا۔\n13۔ کیونکہ تیری رحمت میرے لیے بہت بڑی ہے: اور تو نے میری جان کو سب سے نچلے جہنم سے بچا لیا۔ {جہنم: یا، قبر}\n14۔ اے خدا، مغرور لوگ میرے خلاف اٹھ کھڑے ہوئے ہیں، اور پرتشدد لوگوں کی جماعتیں میری روح کی تلاش میں آئی ہیں؛ اور میں نے تمہیں ان کے سامنے پیش نہیں کیا۔ {پرتشدد: عبرانی۔ خوفناک}\n15. لیکن تو، اے خداوند، ایک خدا ہے جو رحم سے بھرا ہوا، مہربان، صبر کرنے والا، اور رحمت اور سچائی میں فراوان ہے۔\n16۔ اے میری طرف رجوع کرو، اور مجھ پر رحم کرو؛ اپنی طاقت اپنے خادم کو دو، اور اپنی خادمہ کے بیٹے کو بچاؤ۔\n17۔ مجھے بھلائی کے لیے ایک نشان دکھاؤ؛ تاکہ جو لوگ مجھ سے نفرت کرتے ہیں وہ دیکھ سکیں اور شرمندہ ہوں: کیونکہ تو، اے خداوند، نے مجھے تھام لیا اور تسلی دی۔","1. [زبور {یا} کورہ کے بیٹوں کے لیے گیت۔] اس کی بنیاد مقدس پہاڑوں میں ہے۔ {بیٹوں کے لیے: یا، بیٹوں کے لیے}\n2۔ خداوند صیہون کے دروازوں سے یعقوب کے تمام گھروں سے زیادہ محبت کرتا ہے۔\n3۔ اے خدا کے شہر، تیرے بارے میں شاندار باتیں بیان کی جاتی ہیں۔ سیلہ۔\n4۔ میں ان لوگوں کے سامنے راحاب اور بابل کا ذکر کروں گا جو مجھے جانتے ہیں: دیکھو فلسطینیہ اور صور، ایتھوپیا کے ساتھ؛ یہ {آدمی} وہاں پیدا ہوا تھا۔\n5۔ اور صیون کے بارے میں کہا جائے گا، یہ اور وہ مرد اس میں پیدا ہوا: اور سب سے اعلیٰ خود اسے قائم کرے گا۔\n6۔ خداوند جب لوگوں کو لکھتا ہے تو گنتا ہے کہ یہ {انسان} وہاں پیدا ہوا تھا۔ سیلہ۔\n7۔ جیسے گلوکار اور سازوں پر بجانے والے {وہاں ہوں گے}: میرے تمام چشمے {ہیں} تیرے اندر۔","1. [ایک گیت {یا} زبور کورہ کے بیٹوں کے لیے، مہالات لینوتھ کے چیف موسیقار، ہیمان عزراہیت کے مشکیل کے نام۔] اے خداوند، میری نجات کے خدا، میں نے تیرے سامنے دن {اور}رات پکارا ہے: {بیٹوں کے لیے: یا، بیٹوں کے لیے} {مشکیل...: یا، ہیمان عزراہیت کا زبور، جو تعلیم دیتا ہے}\n2۔ میری دعا تمہارے سامنے آئے: میرے پکار کو سنو؛\n3۔ کیونکہ میری روح پریشانیوں سے بھری ہوئی ہے: اور میری زندگی قبر کے قریب ہے۔\n4۔ میں ان لوگوں میں شمار ہوں جو گڑھے میں نیچے جاتے ہیں: میں ایک ایسے انسان کی طرح ہوں جس میں طاقت نہیں:\n5۔ مردوں میں آزاد ہو جاؤ، جیسے وہ مارے گئے جو قبر میں پڑے ہیں، جنہیں تم اب یاد نہیں رکھتے: اور وہ تمہارے ہاتھ سے کاٹ دیے جاتے ہیں۔ {سے: یا، بائی}\n6۔ تو نے مجھے سب سے نچلے گڑھے میں، اندھیرے میں، گہرائیوں میں دفن کر دیا۔\n7۔ تمہارا غضب مجھ پر سخت ہے، اور تم نے اپنی تمام لہروں سے مجھے تکلیف دی ہے۔ سیلہ۔\n8۔ تم نے میری محبت کو مجھ سے دور چھپا دیا ہے؛ تم نے مجھے ان کے لیے مکروہ بنا دیا ہے: {میں} چپ ہوں، اور میں باہر نہیں آ سکتا۔\n9۔ میری آنکھ مصیبت کی وجہ سے ماتم کرتی ہے: اے خداوند، میں روزانہ تجھ سے پکار رہا ہوں، میں نے اپنے ہاتھ تیرے لیے بڑھائے ہیں۔\n10. کیا تم مردوں کو عجائبات دکھاؤ گے؟ کیا مردے اٹھیں گے {اور} تیری تعریف کریں گے؟ سیلہ۔\n11. کیا آپ کی محبت کی مہربانی قبر میں ظاہر کی جائے گی؟ {یا} تباہی میں تمہاری وفاداری؟\n12. کیا تمہارے عجائبات اندھیرے میں معلوم ہوں گے؟ اور بھول جانے کی سرزمین میں تمہاری راستبازی؟\n13۔ لیکن میں نے تجھ سے پکارا ہے، اے خداوند؛ اور صبح میری دعا تمہیں روک دے گی۔\n14. اے خداوند، تو میری روح کیوں چھین لیتے ہو؟ {کیوں} اپنا چہرہ مجھ سے چھپاتی ہو؟\n15. میں {مصیبت} میں ہوں اور اپنی جوانی سے مرنے کے لیے تیار ہوں: {جب} میں تمہارے خوف برداشت کر رہا ہوں اور میں منتشر ہوں۔\n16. تیرا شدید غضب مجھ پر نازل ہوتا ہے؛ تمہارے خوف نے مجھے کاٹ دیا ہے۔\n17۔ وہ روزانہ میرے ارد گرد پانی کی طرح آتے؛ وہ دونوں میرے ارد گرد گھومتے رہے۔ {روزانہ: یا، سارا دن}\n18۔ محبوب اور دوست نے مجھ سے دور کر دیا ہے، {اور} میرے جاننے والے کو تاریکی میں ڈال دیا ہے۔","1. [ایتھن عزراہیت کا مشکیل۔] میں ہمیشہ خداوند کی رحمتوں کے بارے میں گاؤں گا: اپنے منہ سے تیری وفاداری سب نسلوں تک پہنچاؤں گا۔ {مشکیل...: یا، ایتھن عزراہی کے لیے زبور، ہدایت دینے کے لیے} {سب کے لیے...: عبرانی۔ نسل اور نسل کے لیے}\n2۔ کیونکہ میں نے کہا ہے، رحمت ہمیشہ کے لیے قائم ہوگی: تیری وفاداری تو آسمانوں میں قائم کرے گی۔\n3۔ میں نے اپنے منتخب کردہ سے عہد کیا ہے، میں نے اپنے خادم داؤد سے قسم کھائی ہے،\n4۔ میں تیری نسل کو ہمیشہ قائم کروں گا، اور تیری تخت کو تمام نسلوں کے لیے تعمیر کروں گا۔ سیلہ۔\n5۔ اور آسمان تیرے عجائبات کی تعریف کرے گا، اے خداوند: تیری وفاداری مقدسین کی جماعت میں بھی۔\n6۔ کیونکہ آسمان میں خدا سے کون موازنہ کیا جا سکتا ہے؟ {قدرتمندوں کے بیٹوں میں سے کون خدا سے تشبیہ دی جا سکتی ہے؟'\n7۔ خدا سے مقدسین کی مجلس میں بہت خوف کیا جانا چاہیے، اور اس کے ارد گرد موجود تمام لوگوں کی عزت میں ہونا چاہیے۔\n8. اے خداوند، لشکروں کے خدا، کون ہے جو تمہارے جیسا طاقتور رب ہے؟ یا تمہارے ارد گرد تمہاری وفاداری کے لیے؟\n9۔ تو سمندر کی طوفانی لہروں پر حکمرانی کرتے ہو: جب اس کی لہریں اٹھتی ہیں، تو انہیں خاموش کر دیتے ہو۔\n10۔ تو نے راحاب کو ٹکڑوں میں توڑ دیا، جیسے کہ ایک مارا گیا؛ تم نے اپنے طاقتور بازو سے اپنے دشمنوں کو منتشر کر دیا ہے۔ {رحاب: یا، مصر} {تمہاری...: عببری۔ تیری طاقت کا بازو}\n11۔ آسمان {ہیں} تیرے، زمین بھی {ہے} تیری: {جہاں تک} دنیا اور اس کی تکمیل کا تعلق ہے، تو نے انہیں قائم کیا ہے۔ {مکمل پن...: یا، اس میں موجود سب کچھ}\n12۔ شمال اور جنوب کو تو نے پیدا کیا ہے: تابور اور حرمون تیرے نام پر خوش ہوں گے۔\n13۔ تمہارا بازو طاقتور ہے: تمہارا ہاتھ مضبوط ہے، اور تمہارا دایاں ہاتھ بلند ہے۔ {a...: عبرانی ایک بازو جس میں طاقت ہے}\n14. انصاف اور فیصلہ تیری تخت کی رہائش ہیں: رحمت اور سچائی تمہارے سامنے آئیں گی۔ {رہائش گاہ: یا، قیام}\n15. مبارک ہے وہ لوگ جو خوشی کی آواز جانتے ہیں: اے خداوند، وہ تیرے چہرے کی روشنی میں چلیں گے۔\n16۔ وہ آپ کے نام پر سارا دن خوش ہوں گے: اور تیری راستبازی میں وہ بلند ہوں گے۔\n17۔ کیونکہ تو ان کی طاقت کی شان ہے: اور تیری عنایت میں ہمارا سینگ بلند ہوگا۔\n18۔ کیونکہ خداوند ہمارا دفاع ہے؛ اور اسرائیل کا مقدس {ہے} ہمارا بادشاہ۔ {خداوند...: یا، ہمارا ڈھال خداوند کا ہے، اور ہمارا بادشاہ اسرائیل کے مقدس ہستی کا ہے}\n19۔ پھر تم نے خواب میں اپنے مقدس سے بات کی، اور کہا، میں نے {ایک طاقتور پر مدد دی ہے}؛ میں نے لوگوں میں سے {ایک} کو بلند کیا ہے۔\n20. میں نے ڈیوڈ کو اپنا خادم پا لیا ہے؛ میں نے اپنے مقدس تیل سے اسے مسح کیا ہے:\n21۔ جس کے ساتھ میرا ہاتھ قائم ہوگا: میرا بازو بھی اسے مضبوط کرے گا۔\n22۔ دشمن اس پر حملہ نہیں کرے گا؛ نہ ہی برائی کا بیٹا اسے تکلیف دیتا ہے۔\n23۔ اور میں اس کے دشمنوں کو اس کے سامنے شکست دوں گا، اور ان لوگوں کو ستاوں گا جو اس سے نفرت کرتے ہیں۔\n24۔ لیکن میری وفاداری اور میری رحمت اس کے ساتھ ہوگی: اور میرے نام پر اس کا سینگ بلند ہوگا۔\n25۔ میں اس کا ہاتھ بھی سمندر میں رکھوں گا، اور اس کا دایاں ہاتھ دریاؤں میں۔\n26۔ وہ مجھ سے پکارے گا، تو میرا باپ، میرا خدا اور میری نجات کی چٹان ہے۔\n27. اور میں اسے {اپنی} سب سے بڑا بناؤں گا، زمین کے بادشاہوں سے بلند۔\n28۔ میں اپنی رحمت ہمیشہ کے لیے اس کے لیے رکھوں گا، اور میرا عہد اس کے ساتھ مضبوط رہے گا۔\n29۔ اس کی نسل کو میں ہمیشہ کے لیے قائم رکھوں گا، اور اس کا تخت آسمان کے دنوں کی طرح۔\n30۔ اگر اس کے بچے میرے قانون کو چھوڑ دیں اور میرے فیصلوں میں نہ چلیں؛\n31۔ اگر وہ میرے قوانین توڑیں اور میرے احکامات پر عمل نہ کریں؛ {وقفہ: عبوری۔ گستاخ}\n32. پھر میں ان کی گناہ کو چھڑی سے اور ان کی گناہ کو دھاریوں سے دیکھوں گا۔\n33. پھر بھی میں اپنی محبت بھری مہربانی اس سے مکمل طور پر نہیں چھینوں گا، اور نہ ہی اپنی وفاداری کو ناکام ہونے دوں گا۔ {ول...: عبرانی۔ میں اس سے خالی نہیں بناؤں گا} {گرنے کے لیے: عبرانی۔ جھوٹ بولنا}\n34۔ میرا عہد میں نہ توڑوں گا، نہ ہی اس چیز کو بدلوں گا جو میرے منہ سے نکل چکی ہے۔\n35۔ ایک بار میں نے اپنی پاکیزگی کی قسم کھائی ہے کہ میں داؤد سے جھوٹ نہیں بولوں گا۔ {وہ...: عببرانی۔ اگر میں جھوٹ بولوں}\n36۔ اس کی نسل ہمیشہ قائم رہے گی، اور اس کا تخت میرے سامنے سورج کی طرح ہوگا۔\n37۔ یہ ہمیشہ کے لیے چاند کی طرح قائم ہوگا، اور آسمان میں وفادار گواہ ہوگا۔ سیلہ۔\n38۔ لیکن تم نے چھوڑ دیا اور نفرت کی، تم اپنے مسح شدہ سے غصے میں آ گئے۔\n39۔ تم نے اپنے خادم کے عہد کو منسوخ کر دیا: تم نے اس کے تاج کو زمین پر پھینک کر بے حرمتی کی۔\n40۔ تو نے اس کی تمام جھاڑیاں توڑ دی ہیں؛ تم نے اس کے قلعے تباہ کر دیے ہیں۔\n41۔ جو بھی راستے سے گزرتا ہے وہ اسے بگاڑ دیتا ہے: وہ اپنے پڑوسیوں کے لیے ایک ملامت ہے۔\n42. تو نے اس کے مخالفین کا دایاں ہاتھ قائم کر دیا ہے؛ تم نے اس کے تمام دشمنوں کو خوش کر دیا ہے۔\n43۔ تم نے اس کی تلوار کی دھار بھی گھما دی، اور اسے جنگ میں کھڑا نہیں کیا۔\n44۔ تو نے اس کی شان کو روک دیا اور اس کا تخت زمین پر گرا دیا۔ {جلال: عبرانی۔ برائٹنس}\n45۔ تم نے اس کی جوانی کے دن کم کر دیے ہیں: تم نے اسے شرمندگی میں ڈھانپ دیا ہے۔ سیلہ۔\n46۔ کتنی دیر سے، خداوند؟ کیا تم ہمیشہ کے لیے خود کو چھپاؤ گے؟ کیا تمہارا غصہ آگ کی طرح جلتا رہے گا؟\n47۔ یاد رکھو میرا وقت کتنا مختصر ہے: کیوں تم نے سب انسانوں کو بے فائدہ بنا دیا؟\n48. کون سا انسان ہے جو زندہ ہے اور موت نہیں دیکھے گا؟ کیا وہ اپنی روح کو قبر کے ہاتھ سے بچا لے گا؟ سیلہ۔\n49۔ اے خداوند، تیری پچھلی محبت کہاں ہیں، {جنی} تو اپنی سچائی میں داؤد کے سامنے دکھاتا ہے؟\n50. اے خداوند، اپنے بندوں کی ملامت کو یاد رکھو؛ {کیسے} میرے سینے میں تمام طاقتور لوگوں کی ملامت ہے؛\n51۔ جس سے تیرے دشمنوں نے ملامت کی ہے، اے خداوند؛ جس سے انہوں نے تیرے مسح شدہ کے قدموں کو ملامت کی ہے۔\n52۔ ہمیشہ کے لیے خداوند مبارک ہو۔ آمین، اور آمین۔","1. [موسیٰ خدا کے آدمی کی دعا۔] اے خداوند، تو ہماری تمام نسلوں میں رہائش گاہ رہا ہے۔ {ایک دعا...: یا، ایک دعا، جو موسیٰ کا زبور ہے} {میں...: عبرانی نسل اور نسل میں}\n2. پہاڑوں کے نکالے جانے سے پہلے، یا جب تک کہ تم نے زمین اور دنیا کو ہمیشہ سے ابدی تک بنایا ہو، تو خدا ہو۔\n3۔ تو انسان کو تباہی کی طرف لے جاتی ہو؛ اور کہتے ہیں، اے انسانوں کے بچوں، واپس آؤ۔\n4. ہزار سال تمہاری نظر میں {صرف} کل کی طرح ہیں جب وہ گزر چکا ہے، اور {راتوں میں پہرہ کی طرح}۔ {جب...: یا، جب وہ ان کے پاس سے گزر چکا ہو}\n5۔ تو انہیں سیلاب کی طرح لے جاتے ہو؛ وہ {نیند کی طرح} ہیں: صبح کے وقت {وہ گھاس کی طرح ہیں {جو} اگتی ہے۔ {groweth...: or, بدل گیا ہے}\n6۔ صبح کے وقت یہ پھلتا پھولتا ہے اور اوپر اٹھتا ہے؛ شام کو یہ کاٹ دیا جاتا ہے، اور مرجھا جاتا ہے۔\n7۔ کیونکہ ہم تیرے غصے میں جل چکے ہیں، اور تیرے غصے سے ہم پریشان ہیں۔\n8۔ تو نے ہمارے گناہوں کو اپنے سامنے پیش کیا ہے، ہمارے راز {گناہ} اپنے چہرے کی روشنی میں۔\n9۔ کیونکہ ہمارے تمام دن تیرے غضب میں گزر جاتے ہیں: ہم اپنی عمر ایک کہانی کی طرح گزارتے ہیں {جو سنائی جاتی ہے}۔ {گزر گیا...: عبرانی۔ منہ موڑ لیا} {ایک...: یا، مراقبہ کے طور پر}\n10. ہمارے سالوں کے دن {ہیں} تین سو سال اور دس؛ اور اگر طاقت کی وجہ سے وہ چالیس سال کے ہوں، پھر بھی ان کی طاقت محنت اور غم ہے؛ کیونکہ یہ جلد ہی کٹ جاتا ہے، اور ہم اڑ جاتے ہیں۔ {دن...: عبرانی۔ جہاں تک ہمارے سالوں کے دنوں کا تعلق ہے، ان میں ستر سال ہیں}\n11. کون جانتا ہے کہ تمہارے غصے کی طاقت کیا ہے؟ تمہارے خوف کے مطابق بھی، تمہارا غصہ بھی ہے۔\n12. تو *ہمیں} سکھاؤ کہ اپنے دن گنیں، تاکہ ہم اپنے دلوں کو حکمت پر لاگو کر سکیں۔ {اطلاق: عبوری۔ آنے والا مقصد}\n13. اے خداوند، کتنی دیر تک واپس آؤ؟ اور وہ تمہارے بندوں کے بارے میں توبہ کرے۔\n14. اے اپنی رحمت سے ہمیں جلدی مطمئن کرو؛ تاکہ ہم اپنی زندگی بھر خوش اور خوش رہیں۔\n15۔ ہمیں ان دنوں کے مطابق خوش کر جنہیں تم نے ہمیں مصیبت دی، اور ان سالوں کے مطابق جن میں ہم نے برائی دیکھی۔\n16۔ تمہارا کام اپنے بندوں پر ظاہر ہو، اور اپنی شان ان کے بچوں پر ظاہر ہو۔\n17۔ اور خداوند ہمارے خدا کی خوبصورتی ہم پر ہو: اور ہمارے ہاتھوں کے کام کو ہم پر قائم کرو؛ ہاں، ہمارے ہاتھوں کا کام اسے قائم کرتا ہے۔","1۔ جو سب سے بلند کی خفیہ جگہ میں رہتا ہے، وہ قادر مطلق کے سائے میں رہتا ہے۔ {پابندی کریں: عبرانی۔ لاج}\n2۔ میں خداوند کے بارے میں کہوں گا، {وہ} میرا پناہ اور میرا قلعہ ہے: میرا خدا؛ میں اس پر بھروسہ کروں گا۔\n3. یقینا وہ تمہیں شکاری کے جال سے بچا لے گا، {اور} اس خوفناک وبا سے۔\n4۔ وہ تمہیں اپنے پروں سے ڈھانپے گا، اور اس کے پروں کے نیچے تم بھروسہ کرو گے: اس کی سچائی تمہاری ڈھال اور بکلر ہوگی۔\n5۔ رات کے خوف سے نہ ڈرو؛ {اور نہیں} اس تیر کے لیے جو دن میں اڑتا ہے؛\n6۔ {نہ ہی} اس وبا کے لیے {جو} اندھیرے میں چلتی ہے؛ {اور نہ ہی} اس تباہی کے لیے جو دوپہر کو ضائع ہو جاتی ہے۔\n7۔ ایک ہزار تمہارے ساتھ گریں گے، اور دس ہزار تمہارے دائیں ہاتھ پر؛ {لیکن} یہ تمہارے قریب نہیں آئے گا۔\n8۔ صرف اپنی آنکھوں سے تم بدکاروں کا انعام دیکھو اور دیکھو گے۔\n9۔ کیونکہ تو نے خداوند کو، جو میرا پناہ گاہ ہے، {حتیٰ کہ} سب سے بلند جگہ بنایا ہے؛\n10۔ تمہیں کوئی برائی نہیں پہنچے گی، نہ ہی کوئی آفت تمہارے گھر کے قریب آئے گی۔\n11۔ کیونکہ وہ اپنے فرشتوں کو آپ پر ذمہ داری دے گا، تاکہ وہ آپ کی تمام راہوں میں آپ کی حفاظت کریں۔\n12۔ وہ تمہیں اپنے ہاتھوں میں اٹھائیں گے، ورنہ تم اپنا پاؤں پتھر سے ٹکرا دو گے۔\n13۔ تم شیر اور آڈر پر قدم رکھو گے: نوجوان شیر اور اژدہا تمہیں پاؤں تلے روندو گے۔ {ایڈر: یا، اے ایس پی}\n14۔ چونکہ اس نے اپنی محبت مجھ پر رکھی ہے، اس لیے میں اسے نجات دوں گا: میں اسے بلند کروں گا، کیونکہ اس نے میرا نام جانا ہے۔\n15۔ وہ مجھ سے پکارے گا، اور میں اس کا جواب دوں گا: میں اس کے ساتھ مصیبت میں ہوں گا؛ میں اسے نجات دوں گا، اور اس کی عزت کروں گا۔\n16. لمبی عمر کے ساتھ میں اسے مطمئن کروں گا، اور اپنی نجات دکھاؤں گا۔ {لمبا...: عبرانی۔ دنوں کی طوالت}","1. [سبت کے دن کے لیے زبور {یا} گانا۔] {خداوند کا شکر ادا کرنا اور تیرے نام کی حمد گانا اچھا ہے، اے اعلیٰ ترین:\n2. صبح اپنی محبت دکھانا، اور ہر رات اپنی وفاداری ظاہر کرنا، {ہر...: عبرانی۔ راتوں میں}\n3۔ دس تاروں والے ساز پر، اور زبور پر؛ ہارپ پر سنجیدہ آواز کے ساتھ۔ {ہارپ...: یا، ہارپ کے ساتھ سنجیدہ آواز} {ایک سنجیدہ...: عبرانی۔ ہگیون}\n4۔ کیونکہ تو، اے خداوند، نے اپنے کام سے مجھے خوش کیا: میں تیرے ہاتھوں کے کاموں میں کامیاب ہوں گا۔\n5. اے خداوند، تیرے اعمال کتنے عظیم ہیں! {اور} تمہارے خیالات بہت گہرے ہیں۔\n6۔ ظالم آدمی نہیں جانتا؛ اور کوئی بے وقوف بھی یہ نہیں سمجھتا۔\n7۔ جب بدکار گھاس کی طرح بہتا ہے، اور جب بدکاری کے تمام مزدور پھلتے پھولتے ہیں؛ {یہ ہے} کہ وہ ہمیشہ کے لیے تباہ ہو جائیں گے:\n8. لیکن تو، اے خداوند، ہمیشہ کے لیے سب سے بلند ہے۔\n9۔ کیونکہ اے خداوند، تیرے دشمن فنا ہو جائیں گے؛ تمام بدکار مزدور بکھر جائیں گے۔\n10۔ لیکن میرا سینگ تو ایک یونیکورن کے سینگ کی طرح بلند کرو گے: مجھے تازہ تیل سے مسح کیا جائے گا۔\n11۔ میری آنکھ بھی {میری خواہش} کو اپنے دشمنوں پر دیکھے گی، {اور} میرے کان {میری خواہش} کو ان بدکاروں کی سنیں گے جو میرے خلاف اٹھ کھڑے ہیں۔\n12۔ نیک لوگ کھجور کے درخت کی طرح پھلیں گے: وہ لبنان میں دیودار کی طرح اگیں گے۔\n13۔ جو لوگ خداوند کے گھر میں لگائے جائیں گے، وہ ہمارے خدا کے درباروں میں پھلیں گے۔\n14۔ وہ بڑھاپے میں بھی پھل دیں گے؛ وہ موٹے اور خوشحال ہوں گے؛ {پھلتا پھولنا: عبرانی۔ سبز}\n15. دکھانا کہ خداوند {راست} ہے: {وہ} میرا پتھر ہے، اور {اس میں کوئی ناانصافی نہیں}۔","1۔ خداوند بادشاہ ہے، وہ عظمت میں ملبوس ہے؛ خداوند اس طاقت سے ملبوس ہے، {جس سے} اس نے خود کو تیار کیا ہے: دنیا بھی مستحکم ہے، کہ اسے حرکت نہیں دی جا سکتی۔\n2. تیرے تخت {پرانے} سے قائم ہے: تو {ازل} سے ہو۔ {پرانے: عبرانی۔ تب سے}\n3. اے خداوند، سیلاب اٹھ گئے ہیں، سیلاب نے اپنی آواز بلند کر دی ہے؛ سیلاب ان کی لہروں کو بلند کر دیتے ہیں۔\n4. بلند خداوند {ہے} بہت سے پانیوں کی شور سے زیادہ طاقتور، {ہاں، سمندر کی عظیم لہروں سے زیادہ}۔\n5. تیری گواہی بہت پختہ ہے: پاکیزگی تیرا گھر بن جاتی ہے، اے خداوند، ہمیشہ کے لیے۔ {ہمیشہ کے لیے: عبرانی۔ دنوں کی لمبائی کے لیے}","1. اے خداوند خدا، جس کا انتقام ہے؛ اے خدا، جس کا بدلہ ہے، خود کو ظاہر کرو۔ {خدا...: عبرانی۔ بدلوں کا خدا} {دکھاؤ...: عبرانی چمکیں}\n2. اپنے آپ کو اٹھاؤ، اے زمین کا جج: مغرور لوگوں کو انعام دے۔\n3۔ اے خداوند، بدکار کب تک کامیاب رہیں گے؟\n4. {کب تک} وہ سخت باتیں کریں گے؟ {اور} تمام بدکاری کے مزدور اپنے آپ کو فخر کرتے ہیں؟\n5. اے خداوند، وہ تیرے لوگوں کو ٹکڑے ٹکڑے کر دیتے ہیں اور تیرے وراثت کو تکلیف دیتے ہیں۔\n6۔ وہ بیوہ اور اجنبی کو قتل کرتے ہیں، اور یتیم کو قتل کرتے ہیں۔\n7. پھر بھی وہ کہتے ہیں، خداوند نہیں دیکھے گا، اور نہ ہی یعقوب کا خدا اسے دیکھے گا۔\n8۔ سمجھو، اے لوگوں میں سے ظالم: اور احمقوں، تم کب عقلمند بنو گے؟\n9۔ جس نے کان لگایا، کیا وہ نہیں سنے؟ جس نے آنکھ بنائی، کیا وہ نہیں دیکھتا؟\n10۔ جو کافروں کو سزا دیتا ہے، کیا وہ درست نہیں کرتا؟ جو انسان کو علم سکھاتا ہے، {کیا وہ نہیں جانتا}؟\n11۔ خداوند انسان کے خیالات کو جانتا ہے، کہ وہ باطل ہیں۔\n12. مبارک ہے وہ شخص جسے تو پاکدامن بناتا ہے، اے خداوند، اور اسے اپنی شریعت سے سکھاتا ہے؛\n13۔ تاکہ تم اسے مصیبت کے دنوں سے آرام دے سکو، جب تک کہ بدکاروں کے لیے گڑھا کھود نہ دیا جائے۔\n14۔ کیونکہ خداوند اپنے لوگوں کو نہیں چھوڑے گا، نہ ہی اپنی وراثت کو چھوڑے گا۔\n15۔ لیکن فیصلہ راستبازی کی طرف لوٹے گا: اور تمام نیک دل والے اس کی پیروی کریں گے۔ {بعد میں آئے گا...: عبرانی۔ اس کے پیچھے ہوں گے}\n16. کون میرے لیے بدکاروں کے خلاف اٹھے گا؟ {یا} کون میرے حق میں بدکاری کے مزدوروں کے خلاف کھڑا ہوگا؟\n17۔ جب تک خداوند میری مدد نہ کر رہا ہو، میری روح تقریبا خاموشی میں رہتی تھی۔ {تقریبا: یا، جلدی}\n18۔ جب میں نے کہا، میرا پاؤں پھسل؛ اے خداوند، تیری رحمت نے مجھے سہارا دیا۔\n19۔ میرے اندر موجود خیالات کی کثرت میں تیری تسلی میری روح کو خوش کرتی ہے۔\n20. کیا گناہ کا تخت تمہارے ساتھ رفاقت کرے گا، جو قانون کے ذریعے شرارت کرتا ہے؟\n21. وہ نیک لوگوں کی روح کے خلاف اکٹھے ہو جاتے ہیں اور معصوم خون کی مذمت کرتے ہیں۔\n22. لیکن خداوند میرا دفاع ہے؛ اور میرا خدا میری پناہ گاہ کی چٹان ہے۔\n23۔ اور وہ ان پر ان کی اپنی گناہوں پر نازل کرے گا، اور ان کی اپنی برائی میں انہیں کاٹ دے گا؛ {ہاں}، خداوند ہمارا خدا انہیں کاٹ دے گا۔","1۔ آؤ، خداوند کے لیے گاؤ: اپنی نجات کی چٹان پر خوشی کی آواز نکالیں۔\n2۔ آئیے اس کے حضور شکرگزاری کے ساتھ آئیں، اور زبور کے ساتھ خوشی کی آواز نکالیں۔ {آؤ...: عبرانی۔ اس کے چہرے کو روکیں}\n3۔ کیونکہ خداوند ایک عظیم خدا ہے، اور تمام دیوتاؤں سے بڑھ کر عظیم بادشاہ ہے۔\n4۔ اس کے ہاتھ میں زمین کی گہری جگہیں ہیں: پہاڑوں کی طاقت بھی اس کی ہے۔ {میں...: عبرانی کس میں} {طاقت...: یا، پہاڑوں کی بلندیاں اس کی ہیں}\n5۔ سمندر {ہے} اس کا ہے، اور اس نے اسے بنایا: اور اس کے ہاتھوں نے خشک {زمین} بنایا۔ {سمندر...: عبرانی۔ جس کا سمندر ہے}\n6۔ آؤ، عبادت کریں اور سجدہ کریں: خداوند کے سامنے گھٹنے ٹیکیں۔\n7۔ کیونکہ وہ ہمارا خدا ہے؛ اور ہم اس کے چراگاہ کے لوگ ہیں، اور اس کے ہاتھ کی بھیڑیں۔ آج اگر تم اس کی آواز سنو گے،\n8. اپنے دل کو سخت نہ کرو، جیسے اشتعال انگیزی میں، {اور} جیسے {میں} جنگل میں آزمائش کے دن: {اشتعال: عبرانی۔ تنازعہ}\n9۔ جب تمہارے آباؤ اجداد نے مجھے آزمایا، ثابت کیا، اور میرا کام دیکھا۔\n10۔ چالیس سال تک میں اس نسل کے ساتھ غمگین رہا، اور کہا، یہ وہ لوگ ہیں جو اپنے دل میں غلطی کرتے ہیں، اور انہوں نے میرے طریقے نہیں دیکھے:\n11۔ جن سے میں اپنے غصے میں قسم کھاتا ہوں کہ وہ میری آرام میں داخل نہ ہوں۔ {کہ...: عبرانی اگر وہ میرے آرام میں داخل ہو جائیں}","1. اے خداوند کے لیے نیا گیت گاؤ: خداوند کو گاؤ، ساری زمین۔\n2. خداوند کے لیے گاؤ، اس کا نام برکت دے؛ روز بہ دن اپنی نجات دکھاتا ہے۔\n3۔ کافروں میں اپنی شان و شوکت کا اعلان کرو، اس کے عجائبات سب لوگوں میں ظاہر کرو۔\n4۔ کیونکہ خداوند {عظیم} ہے، اور بہت زیادہ تعریف کے لائق ہے: وہ تمام دیوتاؤں سے بڑھ کر خوفزدہ ہے۔\n5۔ قوموں کے تمام دیوتا بت ہیں: لیکن خداوند نے آسمان بنایا۔\n6. عزت اور عظمت اس کے سامنے ہیں: طاقت اور خوبصورتی اس کے مقدس مقام میں ہیں۔\n7. اے قوم کے رشتہ داروں، خداوند کو جلال اور طاقت دو۔\n8. خداوند کو اس کے نام کی شان عطا کرو: نذرانہ پیش کرو اور اس کے درباروں میں آؤ۔ {وجہ سے...: عبرانی۔ اس کے نام سے}\n9. اے پاکیزگی کی خوبصورتی میں خداوند کی عبادت کرو: اس کے سامنے، پوری زمین سے ڈرو۔ {میں...: یا، شاندار پناہ گاہ میں}\n10۔ کافروں میں کہو کہ خداوند حکمرانی کرتا ہے: دنیا بھی قائم ہو جائے گی کہ اسے حرکت نہیں دی جائے گی: وہ لوگوں کا انصاف کرے گا۔\n11۔ آسمان خوش ہوں، اور زمین خوش ہو؛ سمندر کو گرجنے دو، اور اس کی بھرپوریت کو۔ {مکمل پن...: یا، اس میں موجود سب کچھ}\n12۔ میدان خوش ہو، اور اس میں جو کچھ بھی ہے، تب جنگل کے تمام درخت خوش ہوں گے\n13۔ خداوند کے سامنے: کیونکہ وہ آتا ہے، کیونکہ وہ زمین کا فیصلہ کرنے آتا ہے: وہ دنیا کو راستبازی سے اور لوگوں کو اپنی سچائی سے فیصلہ کرے گا۔","1. خداوند بادشاہت کرتا ہے؛ زمین خوش ہو؛ جزیروں کی کثرت خوش رہے۔ {کثیر...: عبرانی۔ بہت سے، یا عظیم جزیرے}\n2. بادل اور تاریکی اس کے ارد گرد ہیں: راستبازی اور فیصلے اس کے تخت کی رہائش ہیں۔ {رہائش گاہ: یا، قیام}\n3۔ اس کے سامنے آگ دوڑتی ہے، اور اس کے دشمنوں کو جلا دیتی ہے۔\n4۔ اس کی بجلی نے دنیا کو روشن کیا: زمین نے دیکھا، اور کانپ گئی۔\n5۔ پہاڑ خداوند کی موجودگی میں، زمین کے رب کی موجودگی میں موم کی طرح پگھل گئے۔\n6۔ آسمان اس کی راستبازی کا اعلان کرتا ہے، اور سب لوگ اس کی شان دیکھتے ہیں۔\n7. وہ سب لوگ جو کندہ شدہ مجسموں کی خدمت کرتے ہیں، جو بتوں پر فخر کرتے ہیں، وہ سب حیران ہوں: اس کی عبادت کرو، تمام دیوتاؤں۔\n8۔ زایون نے سنا اور خوش ہوا؛ اور یہوداہ کی بیٹیوں نے تیرے فیصلوں پر خوشی منائی، اے خداوند۔\n9۔ کیونکہ تو، اے خداوند، زمین سے بلند ہے: تو تمام دیوتاؤں سے بہت بلند ہے۔\n10۔ جو خداوند سے محبت کرتے ہیں، برائی سے نفرت کرتے ہیں: وہ اپنے مقدسین کی روحوں کو محفوظ رکھتا ہے؛ وہ انہیں بدکاروں کے ہاتھوں سے آزاد کراتا ہے۔\n11۔ راستبازوں کے لیے روشنی بوئی جاتی ہے، اور دل کے راستبازوں کے لیے خوشی۔\n12. اے راستبازو، خداوند میں خوشی مناؤ؛ اور ان کی پاکیزگی کی یاد پر شکر ادا کریں۔ {پر...: یا، یادگار کی طرف}","1. [ایک زبور۔] اے خداوند کے لیے نیا گیت گاؤ؛ کیونکہ اس نے حیرت انگیز کام کیے ہیں: اس کا دایاں ہاتھ اور اس کا مقدس بازو اسے فتح دلائی ہے۔\n2۔ خداوند نے اپنی نجات ظاہر کی ہے: اس کی راستبازی نے کافروں کے سامنے کھل کر دکھائی۔ {کھل کر...: یا، ظاہر ہو گیا}\n3۔ اس نے اپنی رحمت اور اسرائیل کے گھر کے لیے اپنی سچائی کو یاد کیا ہے: زمین کے تمام کونے ہمارے خدا کی نجات دیکھ چکے ہیں۔\n4. خداوند کے لیے خوشی کی آواز نکالو، زمین بھر میں: زور سے شور مچاؤ، خوشی مناؤ، اور تعریف کرو۔\n5. ہارپ کے ساتھ خداوند کے لیے گاؤ؛ ہارپ کے ساتھ، اور زبور کی آواز کے ساتھ۔\n6۔ ترمپٹ اور کارنیٹ کی آواز کے ساتھ خداوند بادشاہ کے سامنے خوشی کی آواز نکالو۔\n7۔ سمندر کو گرجنے دو، اور اس کی بھرپوریت کو بھی؛ دنیا، اور وہ جو اس میں رہتے ہیں۔ {مکمل پن...: یا، اس میں موجود سب کچھ}\n8۔ سیلاب اپنے ہاتھوں پر تالیاں بجائیں: پہاڑوں کو مل کر خوشی سے بھر دیں\n9۔ خداوند کے سامنے؛ کیونکہ وہ زمین کا فیصلہ کرنے آیا ہے: وہ راستبازی کے ساتھ دنیا اور لوگوں کا انصاف کرے گا۔","1. خداوند بادشاہت کرتا ہے؛ لوگوں کو کانپنے دو: وہ کروبیوں کے درمیان بیٹھتا ہے؛ زمین کو ہلانے دو۔ {حرکت میں: عبرانی۔ سٹگر}\n2۔ خداوند صیون میں عظیم ہے؛ اور وہ سب سے بلند ہے۔\n3۔ وہ تیرے عظیم اور خوفناک نام کی تعریف کریں؛ {کیونکہ} یہ {ہے} مقدس۔\n4۔ بادشاہ کی طاقت بھی فیصلے سے محبت کرتی ہے؛ تم انصاف قائم کرتے ہو، تم یعقوب میں فیصلہ اور راستبازی انجام دیتے ہو۔\n5. خداوند ہمارے خدا کی تعریف کرو، اور اس کے پاؤں کے پاؤں پر عبادت کرو؛ {کیونکہ} وہ {ہے} مقدس۔ {وہ ہے...: یا، یہ مقدس ہے}\n6۔ موسیٰ اور ہارون اس کے کاہنوں میں شامل ہیں، اور سموئیل ان میں شامل ہیں جو اس کے نام کو پکارتے ہیں؛ انہوں نے خداوند کو پکارا، اور اس نے ان کا جواب دیا۔\n7۔ اس نے ان سے ابر آلود ستون میں بات کی: انہوں نے اس کی گواہی اور وہ فرمان جو اس نے انہیں دیا تھا، محفوظ رکھا۔\n8۔ تو نے ان کا جواب دیا، اے خداوند ہمارے خدا: تو ایک ایسا خدا تھا جس نے انہیں معاف کر دیا، چاہے تم نے ان کی تخلیقات کا بدلہ لیا۔\n9۔ ہمارے خدا کو جلال دو، اور اس کے مقدس پہاڑ پر عبادت کرو؛ کیونکہ خداوند ہمارا خدا {ہے} مقدس۔","1. [تعریف کا زبور۔] اے خداوند کے لیے خوشی کی آواز نکالو، اے تمام زمینوں۔ {تعریف: یا، تھینکس گیونگ} {سب...: عبرانی۔ ساری زمین}\n2۔ خداوند کی خدمت خوشی سے کرو: اس کی موجودگی میں گانے کے ساتھ آؤ۔\n3. جان لو کہ خداوند ہی خدا ہے: وہی ہے جس نے ہمیں بنایا ہے، نہ کہ ہم نے؛ ہم اس کے لوگ ہیں، اور اس کے چراگاہ کی بھیڑیں۔ {اور نہیں...: یا، اور اس کے ہم ہیں}\n4۔ اس کے دروازے میں شکر گزاری کے ساتھ داخل ہو، {اور} اس کے درباروں میں تعریف کے ساتھ داخل ہو: اس کا شکر ادا کرو، {اور} اس کا نام برکت دو۔\n5۔ کیونکہ خداوند {ہے} بھلا؛ اس کی رحمت {ہے} ابدی ہے؛ اور اس کی سچائی {تمام نسلوں تک قائم رہتی ہے}۔ {سب کے لیے...: عبرانی۔ نسل اور نسل کے لیے}","1. [داؤد کا زبور۔] میں رحمت اور فیصلے کا گاؤں گا: اے خداوند، میں تجھ کے لیے گاؤں گا۔\n2. میں خود کو دانشمندی سے اور بہترین طریقے سے پیش آؤں گا۔ اے تم کب میرے پاس آؤ گے؟ میں اپنے گھر میں کامل دل کے ساتھ چلوں گا۔\n3. میں اپنی آنکھوں کے سامنے کوئی برا چیز نہیں رکھوں گا: میں ان کے کام سے نفرت کرتا ہوں جو منہ موڑ لیتے ہیں؛ {یہ} مجھ سے چمٹے نہیں گا۔ {شرارتی...: عبرانی۔ بیلیال کی چیز}\n4. ایک ضدی دل مجھ سے دور ہو جائے گا: میں کسی بدکار کو نہیں جانوں گا۔\n5۔ جو بھی اپنے پڑوسی کی بے عزتی کرے، میں اسے کاٹ دوں گا: جس کی نظر بلند ہے اور دل مغرور ہے، میں برداشت نہیں کروں گا۔\n6۔ میری آنکھیں زمین کے وفاداروں پر ہوں گی، تاکہ وہ میرے ساتھ رہیں: جو کامل طریقے سے چلتا ہے، وہ میری خدمت کرے گا۔ {ایک...: یا، بہترین انداز میں}\n7۔ جو دھوکہ دے گا وہ میرے گھر میں نہیں رہے گا: جو جھوٹ بولے گا وہ میری نظر میں نہیں رہے گا۔ {دیر نہ کرے: عبرانی۔ قائم نہیں کیا جائے گا}\n8۔ میں جلد ہی زمین کے تمام بدکاروں کو ختم کر دوں گا؛ تاکہ میں خداوند کے شہر سے تمام بدکاروں کو کاٹ سکوں۔","1. [مظلوم کی دعا، جب وہ مغلوب ہو جائے اور اپنی شکایت خداوند کے سامنے نازل کرے۔] اے خداوند، میری دعا سنو اور میری پکار تیرے تک پہنچے۔ {of: or, for}\n2. اپنے چہرے کو مجھ سے نہ چھپاؤ اس دن جب میں مشکل میں ہوں؛ اپنا کان میری طرف جھکاؤ: دن {جب} میں پکارتا ہوں، جلدی جواب دو۔\n3. کیونکہ میرے دن دھوئیں کی طرح جل جاتے ہیں، اور میری ہڈیاں آگ کی طرح جل جاتی ہیں۔ {جیسے...: یا، (جیسا کہ کچھ لوگ پڑھتے ہیں) دھوئیں میں بدل جانا}\n4. میرا دل محبت میں مبتلا ہے، اور گھاس کی طرح مرجھا ہوا ہے؛ تاکہ میں اپنی روٹی کھانا بھول جاؤں۔\n5. میری کراہنے کی آواز کی وجہ سے میری ہڈیاں میری جلد سے چپک جاتی ہیں۔ {جلد: یا، گوشت}\n6. میں جنگل کے پیلیکن کی طرح ہوں: میں صحرا کے الو کی طرح ہوں۔\n7. میں دیکھتا ہوں، اور ایک چڑیا کی طرح گھر کی چھت پر اکیلا ہوں۔\n8. میرے دشمن سارا دن مجھے ملامت کرتے ہیں؛ {اور} جو مجھ سے ناراض ہیں وہ میرے خلاف قسم کھاتے ہیں۔\n9۔ کیونکہ میں نے راکھ روٹی کی طرح کھا لی ہے، اور اپنی شراب کو رونے کے ساتھ ملا دیا ہے،\n10۔ تیری ناراضگی اور غصے کی وجہ سے: کیونکہ تو نے مجھے اٹھایا اور نیچے گرایا۔\n11. میرے دن {ہیں} ایک سائے کی طرح جو زوال پذیر ہوتا ہے؛ اور میں گھاس کی طرح مرجھا ہوا ہوں۔\n12. لیکن تو، اے خداوند، ہمیشہ قائم رہو گا؛ اور تیری یاد سب نسلوں کے لیے۔\n13۔ تم اٹھو گے، {اور} صیون پر رحم کرو، کیونکہ اس کی طرف رجوع کرنے کا وقت، ہاں، مقررہ وقت آ گیا ہے۔\n14۔ کیونکہ تمہارے خادم اس کے پتھروں سے لطف اندوز ہوتے ہیں اور ان کی خاک کو ترجیح دیتے ہیں۔\n15۔ تو غیر مسلم خداوند کے نام سے ڈریں گے، اور زمین کے تمام بادشاہوں سے تیری شان سے ڈریں گے۔\n16۔ جب خداوند صیون کو تعمیر کرے گا، تو وہ اپنی شان میں ظاہر ہوگا۔\n17۔ وہ محتاجوں کی دعا کو قبول کرے گا، اور ان کی دعا کو حقیر نہیں کرے گا۔\n18۔ یہ آنے والی نسل کے لیے لکھا جائے گا: اور جو لوگ پیدا ہوں گے وہ خداوند کی تعریف کریں گے۔\n19۔ کیونکہ اس نے اپنے مقدس مقام کی بلندی سے نیچے دیکھا ہے؛ خداوند نے آسمان سے زمین کو دیکھا؛\n20۔ قیدی کی کراہت سننا؛ موت کے لیے مقرر کیے گئے افراد کو چھوڑ دینا؛ {وہ...: عببرانی۔ موت کے بچے}\n21۔ صیون میں خداوند کے نام کا اعلان کرنا، اور یروشلم میں اس کی تعریف کرنا؛\n22۔ جب لوگ اور بادشاہتیں اکٹھی ہوں تاکہ خداوند کی خدمت کریں۔\n23. اس نے میری طاقت کو کمزور کر دیا؛ اس نے میرے دن کم کر دیے۔ {کمزور: عبرانی۔ متاثر ہوئے}\n24۔ میں نے کہا، اے میرے خدا، مجھے میرے دنوں کے بیچ میں نہ لے جا: تیری عمر تمام نسلوں میں ہے۔\n25۔ تو نے قدیم زمانے میں زمین کی بنیاد رکھی ہے: اور آسمان تمہارے ہاتھوں کا کام ہیں۔\n26۔ وہ مر جائیں گے، لیکن تم برداشت کرو گے: ہاں، وہ سب ایک لباس کی طرح بوڑھے ہو جائیں گے؛ تم انہیں لباس کی طرح بدلو گے، اور وہ بدلے جائیں گے: {برداشت کرو: عبرانی۔ کھڑے ہو جاؤ}\n27. لیکن تم بھی وہی ہو، اور تمہارے سال ختم نہیں ہوں گے۔\n28۔ تمہارے بندوں کے بچے جاری رہیں گے، اور ان کی نسل تمہارے سامنے قائم ہوگی۔","1. [{داؤد کا زبور}] اے میری جان، خداوند کو برکت دے: اور جو کچھ میرے اندر ہے، اس کے مقدس نام کو برکت دے۔\n2. اے میری جان، خداوند کو برکت دے اور اس کے تمام فوائد نہ بھولو:\n3۔ جو تمہارے تمام گناہوں کو معاف کرتا ہے؛ جو تیری تمام بیماریاں شفا دیتا ہے؛\n4۔ جو اپنی زندگی کو تباہی سے بچاتا ہے؛ جو تمہیں محبت اور نرمی سے تاج پہناتا ہے؛\n5۔ جو تمہارے منہ کو نیکی سے مطمئن کرتا ہے؛ تاکہ تیری جوانی عقاب کی طرح تازہ ہو جائے۔\n6۔ خداوند ان سب کے لیے راستبازی اور انصاف کرتا ہے جو مظلوم ہیں۔\n7۔ اس نے موسیٰ کو اپنے راستے اور اپنے اعمال بنی اسرائیل کے سامنے ظاہر کیے۔\n8. خداوند رحم دل اور مہربان ہے، غصہ کرنے میں سست ہے، اور رحمت میں فراوان ہے۔ {بہت زیادہ...: عبوری۔ رحمت میں عظیم}\n9. وہ ہمیشہ ڈانٹتا نہیں: نہ ہی وہ ہمیشہ کے لیے اپنے غصے کو چھپائے گا۔\n10۔ اس نے ہمارے گناہوں کے بعد ہمارے ساتھ معاملہ نہیں کیا؛ اور نہ ہی ہمیں ہمارے گناہوں کے مطابق انعام دیا۔\n11۔ جیسے آسمان زمین سے بلند ہے، ویسے ہی اس کی رحمت ان لوگوں کے لیے بہت بڑی ہے جو اس سے ڈرتے ہیں۔ {یعنی...: عبرانی آسمان کی بلندی کے مطابق}\n12۔ جتنا مشرق مغرب سے دور ہے، {اتنی ہی دور} اس نے ہماری گناہوں کو ہم سے دور کر دیا ہے۔\n13. جیسے باپ اپنے بچوں پر ترس کھاتا ہے، ویسے ہی خداوند ان لوگوں پر ترس کھاتا ہے جو اس سے ڈرتے ہیں۔\n14۔ کیونکہ وہ ہمارے جسم کو جانتا ہے؛ وہ یاد رکھتا ہے کہ ہم خاک ہیں۔\n15۔ {جہاں تک} انسان کا تعلق ہے، اس کے دن {گھاس کی طرح ہیں}: کھیت کے پھول کی طرح، وہ بھی پھلتا پھولتا ہے۔\n16۔ کیونکہ ہوا اس پر سے گزرتی ہے، اور وہ چلی جاتی ہے؛ اور اس کی جگہ کو اب معلوم نہیں ہوگا۔ {یہ ہے...: عبرانی۔ ایسا نہیں ہے}\n17. لیکن خداوند کی رحمت ان لوگوں پر ہمیشہ سے ہمیشہ تک ہے جو اس سے ڈرتے ہیں، اور اس کی راستبازی بچوں کے بچوں کے لیے ہے؛\n18۔ ان لوگوں کے لیے جو اس کے عہد کی پاسداری کرتے ہیں، اور جو اس کے احکامات کو یاد رکھتے ہیں کہ وہ انہیں پورا کریں۔\n19۔ خداوند نے آسمانوں میں اپنا تخت تیار کیا ہے؛ اور اس کی سلطنت سب پر حکمرانی کرتی ہے۔\n20. اے خداوند کو برکت دو، اے اس کے فرشتوں، جو طاقت میں ماہر ہیں، جو اس کے احکامات پر عمل کرتے ہیں اور اس کے کلام کی آواز سنتے ہیں۔ {جو ایکسیل...: عبرانی طاقت میں طاقتور}\n21. خداوند کو برکت دے، اس کے تمام لشکروں کو؛ {تم لوگ} اس کے وزیر، جو اس کی خوشی کرتے ہیں۔\n22. خداوند کو اس کے تمام اعمال کو اس کی سلطنت کے ہر مقام پر برکت دے: اے میری جان، خداوند کو برکت دے۔","1. اے میری جان، خداوند کو برکت دے۔ اے خداوند، میرے خدا، تو بہت عظیم ہے؛ تم عزت اور عظمت سے ملبوس ہو۔\n2۔ جو {اپنے آپ کو} روشنی سے {لباس} کی طرح ڈھانپتا ہے: جو آسمان کو پردے کی طرح پھیلا دیتا ہے:\n3۔ جو اپنے کمرے کی شعاعیں پانی میں رکھتا ہے: جو بادلوں کو اپنی رتھ بناتا ہے، جو ہوا کے پروں پر چلتا ہے:\n4۔ جو اپنے فرشتوں کو روح بناتا ہے؛ اس کے وزیروں نے ایک جلتی ہوئی آگ:\n5۔ {جس نے} زمین کی بنیادیں رکھی ہیں، {کہ} اسے ہمیشہ کے لیے ہٹایا نہیں جانا چاہیے۔ {کون...: عبرانی۔ اس نے زمین کو اس کی بنیادوں پر قائم کیا ہے}\n6۔ تو نے اسے گہرائی سے ڈھانپ دیا جیسے {کپڑ} سے: پانی پہاڑوں کے اوپر کھڑا تھا۔\n7۔ تمہاری سرزنش پر وہ بھاگ گئے؛ تمہاری گرج کی آواز پر وہ فورا روانہ ہو گئے۔\n8۔ وہ پہاڑوں کے راستے جاتے ہیں؛ وہ وادیوں کے راستے اس جگہ پر جاتے ہیں جو تم نے ان کے لیے قائم کی ہے۔ {وہ اوپر جاتے ہیں...: یا، پہاڑ چڑھتے ہیں، وادیاں نیچے اترتی ہیں}\n9۔ تو نے ایک پابندی مقرر کی ہے کہ وہ عبور نہ کر سکیں؛ کہ وہ دوبارہ زمین کو ڈھانپنے کے لیے نہ مڑیں۔\n10۔ وہ وادیوں میں چشمے بھیجتا ہے، {جو} پہاڑوں کے درمیان بہتے ہیں۔ {وہ: عبرانی۔ کون} {رن: عبرانی۔ چلیں}\n11۔ وہ کھیت کے ہر جانور کو پانی دیتے ہیں: جنگلی گدھے اپنی پیاس بجھاتے ہیں۔ {quench: عبوری۔ بریک}\n12۔ ان کے ذریعے آسمان کے پرندے اپنی رہائش پائیں گے، {جو} شاخوں کے درمیان گاتے ہیں۔ {گانا: عبوری۔ آواز دو}\n13۔ وہ اپنے کمروں سے پہاڑوں کو پانی دیتا ہے: زمین تمہارے اعمال کے پھل سے مطمئن ہے۔\n14۔ وہ مویشیوں کے لیے گھاس اگاتا ہے اور انسان کی خدمت کے لیے جڑی بوٹیاں، تاکہ وہ زمین سے خوراک نکال سکے؛\n15۔ اور شراب {جو} انسان کے دل کو خوش کرتی ہے، {اور} تیل جو {اس} کا چہرہ چمکاتا ہے، اور روٹی {جو} انسان کے دل کو مضبوط کرتی ہے۔ {تیل...: عبرانی تاکہ اس کا چہرہ تیل سے چمکے، یا تیل سے زیادہ}\n16۔ خداوند کے درخت رس سے بھرے ہوئے ہیں؛ لبنان کے دیودار، جو اس نے لگائے ہیں؛\n17۔ جہاں پرندے اپنے گھونسلے بناتے ہیں: {جہاں تک} اسٹورک کا تعلق ہے، فر کے درخت {ہیں} اس کا گھر۔\n18۔ اونچی پہاڑیاں جنگلی بکریوں کے لیے پناہ گاہ ہیں؛ {اور} کونیز کے لیے پتھر۔\n19۔ اس نے چاند کو موسموں کے لیے مقرر کیا: سورج جانتا ہے کہ وہ غروب ہو رہا ہے۔\n20۔ تو اندھیرا پیدا کرتے ہو، اور رات ہے: جس میں جنگل کے تمام جانور رینگتے ہوئے نکلتے ہیں۔ {درندے...: عبرانی۔ اس کے جانور جنگل پر روندتے ہیں}\n21۔ نوجوان شیر اپنے شکار کے پیچھے دھاڑتے ہیں اور خدا سے اپنا گوشت تلاش کرتے ہیں۔\n22۔ سورج طلوع ہوتا ہے، وہ خود کو جمع کرتے ہیں اور اپنے ٹھکانے میں لٹا دیتے ہیں۔\n23۔ انسان شام تک اپنے کام اور محنت کی طرف نکلتا ہے۔\n24. اے خداوند، تیرے اعمال کتنے مختلف ہیں! حکمت میں تو نے سب کو بنایا ہے: زمین تیری دولت سے بھری ہوئی ہے۔\n25۔ {اسی طرح} یہ عظیم اور وسیع سمندر، جس میں {ہے} بے شمار چیزیں رینگتی ہوئی ہیں، چھوٹے اور بڑے جانور دونوں۔\n26۔ وہ جہاز جا رہے ہیں: {وہاں} وہ لیویاتھن ہے، {جسے تم نے وہاں کھیلنے کے لیے بنایا ہے۔ {بنایا: عبرانی۔ تشکیل دی}\n27۔ یہ سب تمہارے انتظار میں ہیں؛ تاکہ تم انہیں ان کا گوشت وقت پر دے سکو۔\n28۔ {یہ} تو انہیں دیتے ہو، وہ جمع کرتے ہیں: جب تم اپنا ہاتھ کھولتے ہو، وہ بھلائی سے بھرے ہوتے ہیں۔\n29۔ تم اپنا چہرہ چھپا لیتے ہو، وہ پریشان ہیں: تم ان کی سانس لیتے ہو، وہ مر جاتے ہیں اور اپنی خاک میں واپس چلے جاتے ہیں۔\n30۔ تو اپنی روح بھیجتے ہو، وہ پیدا ہوئے: اور تو زمین کے چہرے کو دوبارہ زندہ کرتے ہو۔\n31۔ خداوند کی شان ہمیشہ قائم رہے گی: خداوند اپنے اعمال میں خوش ہوگا۔ {برداشت کریں: عبرانی۔ be}\n32۔ وہ زمین کو دیکھتا ہے، اور وہ کانپتی ہے: وہ پہاڑوں کو چھوتا ہے، اور وہ دھواں نکالتے ہیں۔\n33۔ میں جتنا زندہ ہوں خداوند کے لیے گاتا رہوں گا: جب تک میرا وجود ہے، میں اپنے خدا کی تعریف کروں گا۔\n34۔ میری اس پر غور و فکر میٹھا ہوگا: میں خداوند میں خوش ہوں گا۔\n35۔ گناہ گاروں کو زمین سے ختم کر دیا جائے، اور بدکار اب نہ رہیں۔ اے میری جان، خداوند کو برکت دے۔ خداوند کی تعریف ہو۔","1۔ خداوند کا شکر ادا کرو؛ اس کے نام کو پکارو: اس کے اعمال کو عوام میں ظاہر کرو۔\n2. اس کے لیے گاؤ، اس کے لیے زبور گاؤ: اس کے تمام حیرت انگیز کاموں کی بات کرو۔\n3۔ اس کے مقدس نام میں جلال فرما: خداوند کی تلاش کرنے والوں کے دل خوش ہوں۔\n4. خداوند اور اس کی طاقت کی تلاش کرو: ہمیشہ اس کا چہرہ تلاش کرو۔\n5۔ اس کے شاندار کاموں کو یاد رکھو جو اس نے کیے؛ اس کے عجائبات، اور اس کے منہ کے فیصلے؛\n6۔ اے ابراہیم کی نسل جو اس کا بندہ ہے، اے یعقوب کے چنے ہوئے بیٹے۔\n7. وہ خداوند ہمارا خدا ہے: اس کے فیصلے پوری زمین پر ہیں۔\n8۔ اس نے اپنے عہد کو ہمیشہ کے لیے یاد رکھا ہے، وہ لفظ {جو اس نے ہزار نسلوں تک حکم دیا تھا۔\n9۔ کون سا {معاہدہ} اس نے ابراہیم سے کیا، اور اسحاق سے اس کی قسم؛\n10۔ اور یہی بات یعقوب کو قانون کے طور پر تصدیق کی، {اور} اسرائیل کو {ایک دائمی عہد کے لیے}:\n11۔ کہتا ہوں، میں تمہیں کنعان کی زمین دوں گا، تمہاری میراث کا حصہ: {لوٹ: عبرانی۔ کورڈ}\n12۔ جب وہ {لیکن} چند مرد تھے؛ ہاں، بہت کم، اور اجنبی بھی۔\n13۔ جب وہ ایک قوم سے دوسری قوم، ایک سلطنت سے دوسری قوم میں گئے؛\n14۔ اس نے کسی کو ان کے ساتھ ظلم کرنے کی اجازت نہیں دی: ہاں، اس نے بادشاہوں کو ان کی خاطر ملامت کی؛\n15. {کہا}، میرے مسح شدہ کو ہاتھ نہ لگاؤ، اور میرے نبیوں کو نقصان نہ پہنچاؤ۔\n16۔ اس کے علاوہ اس نے زمین پر قحط کا اعلان کیا: اس نے پورا روٹی کا عصا توڑ دیا۔\n17۔ اس نے ان کے سامنے ایک آدمی بھیجا، {حتیٰ کہ} یوسف کو، {جو} ایک خادم کے بدلے بیچ دیا گیا:\n18۔ جس کے پاؤں کو زنجیروں سے دبا دیا گیا: اسے لوہے میں ڈال دیا گیا: {وہ...: عبرانی۔ اس کی روح لوہے میں بدل گئی}\n19۔ جب تک اس کا کلام نہ آیا: خداوند کا کلام اسے آزمایا۔\n20۔ بادشاہ نے اسے بھیجا اور آزاد کر دیا؛ {حتیٰ کہ} لوگوں کا حکمران بھی، اور اسے آزاد چھوڑ دو۔\n21۔ اس نے اسے اپنے گھرانے کا مالک اور اس کے تمام وسائل کا حکمران بنایا: {مادہ: عبرانی۔ قبضہ}\n22۔ اپنے شہزادوں کو اپنی مرضی سے باندھنا؛ اور اپنے سینیٹرز کو حکمت سکھائیں۔\n23۔ اسرائیل بھی مصر میں آیا؛ اور یعقوب نے ہام کی سرزمین میں قیام کیا۔\n24۔ اور اس نے اپنے لوگوں کو بہت بڑھا دیا؛ اور انہیں اپنے دشمنوں سے زیادہ طاقتور بنا دیا۔\n25۔ اس نے ان کے دل کو اپنے لوگوں سے نفرت کرنے کی طرف موڑ دیا، تاکہ اپنے خادموں کے ساتھ نرمی سے پیش آئیں۔\n26۔ اس نے موسیٰ کو اپنا خادم بھیجا؛ {اور} آرون، جسے اس نے چنا تھا۔\n27۔ انہوں نے ان میں اس کے نشانات دکھائے اور ہام کی سرزمین میں عجائبات دکھائے۔ {اس کا...: عبرانی اس کے اشاروں کے الفاظ}\n28۔ اس نے تاریکی بھیجی، اور اسے تاریک کر دیا؛ اور انہوں نے اس کے کلام کے خلاف بغاوت نہیں کی۔\n29۔ اس نے ان کے پانی کو خون میں بدل دیا، اور ان کی مچھلیاں مار ڈالیں۔\n30۔ ان کی زمین نے اپنے بادشاہوں کے کمروں میں کثرت سے مینڈک پیدا کیے۔\n31۔ اس نے بات کی، اور ان کے تمام ساحلوں پر مختلف قسم کی مکھیاں اور جوئیں آ گئیں۔\n32۔ اس نے انہیں بارش کے بدلے اولے دیے، {اور} ان کی زمین میں آگ لگا دی۔ {وہ...: عبرانی۔ ان کی بارش کی اولہ}\n33۔ اس نے ان کی بیلوں اور انجیر کے درختوں کو بھی مارا؛ اور ان کے ساحلوں کے درختوں کو توڑ دیں۔\n34۔ اس نے بات کی، اور ٹڈی دل آئے، اور کیٹرپلرز، اور وہ بے شمار،\n35۔ اور انہوں نے اپنی زمین کی تمام جڑی بوٹیاں کھا لیں، اور اپنی زمین کے پھل کھا لیے۔\n36۔ اس نے ان کی زمین کے تمام پہلے بیٹوں کو بھی مارا، جو ان کی تمام طاقت کا سب سے بڑا تھا۔\n37۔ اس نے انہیں چاندی اور سونے کے ساتھ بھی لایا اور ان کے قبیلوں میں ایک بھی کمزور شخص نہیں تھا۔\n38۔ مصر خوش ہوا جب وہ روانہ ہوئے: کیونکہ ان کا خوف ان پر چھا گیا۔\n39۔ اس نے ایک بادل بچھایا تاکہ پردہ ہو؛ اور رات کو روشنی دینے کے لیے آگ۔\n40۔ {لوگ} نے پوچھا، اور اس نے بٹیر لائے، اور انہیں جنت کی روٹی سے مطمئن کیا۔\n41۔ اس نے پتھر کھولا، اور پانی باہر نکل آیا؛ وہ خشک جگہوں پر بہتے تھے {جیسے} دریا کی طرح۔\n42۔ کیونکہ اس نے اپنا مقدس وعدہ یاد کیا، {اور} ابراہیم اس کا بندہ۔\n43. اور اس نے اپنی قوم کو خوشی سے پیش کیا، {اور} اپنے منتخب لوگوں کو خوشی سے پیش کیا: {خوشی: عبرانی۔ گانا}\n44۔ اور انہیں کافروں کی زمینیں دی: اور انہوں نے لوگوں کی محنت وراثت میں حاصل کی؛\n45۔ تاکہ وہ اس کے قوانین کی پابندی کریں اور اس کے قوانین کی پاسداری کریں۔ خداوند کی تعریف ہو۔ {تعریف...: عبرانی۔ الحمد للہ}","1. خداوند کی تعریف کرو۔ اے خداوند کا شکر ادا کرو؛ کیونکہ {وہ} اچھا ہے: اس کی رحمت {ہمیشہ قائم رہے گی}۔ {تعریف...: عبرانی۔ الحمد للہ}\n2. کون خداوند کے عظیم اعمال بیان کر سکتا ہے؟ {کون} اپنی ساری تعریف دکھا سکتا ہے؟\n3۔ بابرکت ہیں وہ جو فیصلہ کرتے ہیں، {اور} وہ جو ہر وقت نیکی کرتا ہے۔\n4. اے خداوند، مجھے اپنے لوگوں پر دی گئی رحمت سے یاد رکھ: اپنی نجات مجھے عطا فرما؛\n5. تاکہ میں تیرے منتخب کردہ لوگوں کی بھلائی دیکھ سکوں، تاکہ میں تمہاری قوم کی خوشی میں خوش ہو سکوں، تاکہ میں تمہاری میراث سے جلال حاصل کر سکوں۔\n6۔ ہم نے اپنے باپ اپ کے ساتھ گناہ کیا ہے، ہم نے گناہ کیا ہے، ہم نے برے کام کیے ہیں۔\n7۔ ہمارے آباؤ اجداد نے مصر میں تمہارے عجائبات کو نہیں سمجھا؛ انہوں نے تیری بے شمار رحمتوں کو یاد نہیں کیا؛ لیکن اس نے سمندر میں {اسے} کو بھڑکایا، {حتیٰ کہ} کہ بحیرہ احمر پر بھی۔\n8۔ پھر بھی اس نے انہیں اپنے نام کی خاطر محفوظ رکھا، تاکہ اپنی عظیم طاقت کو ظاہر کر سکے۔\n9۔ اس نے بحیرہ احمر کو بھی ملامت کی، اور وہ خشک ہو گیا: اس لیے اس نے انہیں گہرائیوں سے گزارا، جیسے بیابان میں۔\n10۔ اور اس نے انہیں اس کے ہاتھ سے بچایا جو ان سے نفرت کرتا تھا، اور دشمن کے ہاتھوں سے نجات دی۔\n11۔ اور پانی نے ان کے دشمنوں کو ڈھانپ لیا: ان میں سے کوئی باقی نہ رہا۔\n12۔ پھر انہوں نے اس کے الفاظ پر یقین کیا؛ انہوں نے اس کی تعریف کی۔\n13۔ وہ جلد ہی اس کے کاموں کو بھول جاتے ہیں؛ انہوں نے اس کی نصیحت کا انتظار نہیں کیا: {وہ جلد ہی...: عبرانی۔ انہوں نے جلدی کی، بھول گئے}\n14۔ لیکن بیابان میں بے حد خواہش مند رہا، اور صحرا میں خدا کو آزمایا۔ {ہوس کے ساتھ...: عبرانی ہوس میں مبتلا تھا}\n15۔ اور اس نے انہیں ان کی درخواست دی؛ لیکن اس نے ان کی روح میں دبلا پن ڈال دیا۔\n16۔ وہ موسیٰ سے بھی حسد کرتے تھے جو اس کیمپ میں تھا، {اور} خداوند کے مقدس ہارون سے۔\n17۔ زمین کھل گئی اور داتھان کو نگل گیا، اور ابیرام کی جماعت کو ڈھانپ لیا۔\n18۔ اور ان کے ساتھ آگ بھڑک اٹھی؛ شعلہ بدکاروں کو جلا دیتا تھا۔\n19۔ انہوں نے ہورب میں بچھڑا بنایا، اور پگھلے ہوئے مجسمے کی عبادت کی۔\n20. یوں انہوں نے اپنی شان و شوکت کو ایک بیل کی طرح بدل دیا جو گھاس کھاتا ہے۔\n21۔ انہوں نے اپنے نجات دہندہ خدا کو بھلا دیا، جس نے مصر میں عظیم کام کیے تھے؛\n22۔ ہام کی سرزمین میں حیرت انگیز کام، {اور} بحیرہ احمر کے کنارے خوفناک چیزیں۔\n23۔ اس لیے اس نے کہا کہ وہ انہیں تباہ کر دے گا، اگر اس کا منتخب موسیٰ اس کے سامنے دراڑ میں کھڑا نہ ہوتا، تاکہ اس کا غصہ دور ہو جائے، کہیں وہ انہیں تباہ نہ کر دے۔\n24۔ ہاں، وہ خوشگوار زمین سے نفرت کرتے تھے، انہوں نے اس کے کلام پر یقین نہیں کیا: {خوشگوار...: عبرانی۔ خواہشات کی سرزمین}\n25۔ لیکن اپنے خیموں میں سرگوشی کی، {اور} خداوند کی آواز کو نہیں سنا۔\n26۔ اس لیے اس نے ان کے خلاف ہاتھ اٹھایا، انہیں بیابان میں گرانے کے لیے: {الٹانے کے لیے: عبرانی۔ تاکہ وہ گر جائیں}\n27۔ ان کی نسل کو قوموں میں بھی ختم کرنا، اور انہیں زمینوں میں بکھیر دینا۔ {اوور کرنے کے لیے: عبرانی۔ تاکہ وہ گر جائیں}\n28۔ وہ بھی بعلپور کے ساتھ مل گئے، اور مردوں کی قربانیاں کھاتے تھے۔\n29۔ یوں انہوں نے اپنی ایجادات سے اسے غصہ دلایا: اور وبا ان پر طاری ہو گئی۔\n30۔ پھر فینیحا کھڑا ہوا اور فیصلہ کیا: اور {یوں} طاعون کو روک دیا گیا۔\n31۔ اور یہ اس کے لیے ہمیشہ کے لیے تمام نسلوں کے لیے راستبازی کے لیے شمار کیا گیا۔\n32۔ انہوں نے {اسے} کو بھی تنازعے کے پانیوں پر غصہ دلایا، یہاں تک کہ ان کے لیے موسیٰ کے ساتھ برا ہو گیا:\n33۔ کیونکہ انہوں نے اس کی روح کو ابھار دیا، جس کی وجہ سے وہ بے دھیانی میں اپنے ہونٹوں سے بولنے لگا۔\n34۔ انہوں نے ان قوموں کو تباہ نہیں کیا جن کے بارے میں خداوند نے انہیں حکم دیا:\n35۔ لیکن وہ کافروں کے درمیان گھل مل گئے، اور ان کے کام سیکھے۔\n36۔ اور انہوں نے اپنے بتوں کی خدمت کی، جو ان کے لیے ایک جال تھے۔\n37۔ ہاں، انہوں نے اپنے بیٹوں اور بیٹیوں کو شیطانوں کے حوالے کر دیا،\n38۔ اور معصوموں کا خون بہائیں، {حتیٰ کہ اپنے بیٹوں اور بیٹیوں کا خون، جنہیں انہوں نے کنعان کے بتوں کے لیے قربان کیا: اور زمین خون سے آلودہ ہو گئی۔\n39۔ یوں وہ اپنی تخلیقات سے بدنام ہوئے، اور اپنی ایجادات کے ساتھ بدکاری میں مبتلا ہو گئے۔\n40۔ اسی لیے خداوند کا غضب اس کے لوگوں پر بھڑک اٹھا، یہاں تک کہ وہ اپنی وراثت سے نفرت کرتا تھا۔\n41۔ اور اس نے انہیں کافروں کے ہاتھ میں دے دیا؛ اور جو لوگ ان سے نفرت کرتے تھے وہ ان پر حکمرانی کرتے تھے۔\n42۔ ان کے دشمنوں نے بھی ان پر ظلم کیا، اور انہیں ان کے ہاتھوں زیر کر لیا گیا۔\n43۔ اس نے انہیں کئی بار پیش کیا؛ لیکن انہوں نے اپنی نصیحت سے اسے اکسایا اور اپنی گناہوں کی سزا میں نیچا دکھایا۔ {لایا...: یا، غریب، یا، کمزور}\n44۔ پھر بھی اس نے ان کی تکلیف دیکھی، جب اس نے ان کی پکار سنی:\n45۔ اور اس نے ان کے لیے اپنا عہد یاد کیا، اور اپنی بے شمار رحمتوں کے مطابق توبہ کی۔\n46۔ اس نے انہیں ان سب کے لیے بھی قابل رحم بنایا جو انہیں قید کرتے تھے۔\n47. اے خداوند ہمارے خدا، ہمیں بچا اور ہمیں کافروں میں سے جمع کر، تاکہ تیرے مقدس نام کا شکر ادا کریں، {اور} تیری تعریف میں فتح حاصل کریں۔\n48۔ خداوند اسرائیل کے خدا کو ہمیشہ سے ہمیشہ تک مبارک ہو: اور سب لوگ کہیں، آمین۔ خداوند کی تعریف ہو۔ {تعریف...: عبرانی۔ الحمد للہ}","1۔ خداوند کا شکر ادا کرو، کیونکہ {وہ} اچھا ہے: اس کی رحمت {ہمیشہ قائم ہے}۔\n2۔ خداوند کے نجات پانے والے کہے {تو}، جسے اس نے دشمن کے ہاتھ سے نجات دی ہے؛\n3۔ اور انہیں زمینوں سے جمع کیا، مشرق سے، مغرب سے، شمال سے، اور جنوب سے۔ {جنوب: عبوری۔ سمندر}\n4۔ وہ تنہا ویرانے میں گھومتے رہے؛ انہیں رہنے کے لیے کوئی شہر نہیں ملا۔\n5۔ بھوکے اور پیاسے، ان کی روح ان میں بے ہوش ہو گئی۔\n6۔ پھر انہوں نے اپنی مصیبت میں خداوند سے پکارا، {اور} اس نے انہیں ان کی مصیبتوں سے نجات دلائی۔\n7۔ اور اس نے انہیں صحیح راستے پر لے جایا تاکہ وہ کسی رہائشی شہر کی طرف جا سکیں۔\n8۔ اے کہ {لوگ} خداوند کی تعریف کریں {اس کی بھلائی کے لیے}، اور {انسانوں کے بچوں کے لیے اس کے شاندار کاموں کے لیے!''\n9۔ کیونکہ وہ خواہش مند روح کو تسکین دیتا ہے، اور بھوکی روح کو بھلائی سے بھر دیتا ہے۔\n10۔ وہ جو اندھیرے میں اور موت کے سائے میں بیٹھے ہیں، {وجود} مصیبت اور لوہے میں بندھے ہوئے؛\n11۔ کیونکہ انہوں نے خدا کے کلام سے بغاوت کی، اور سب سے بلند کی نصیحت کو رد کیا:\n12۔ اس لیے اس نے محنت سے ان کے دل گرا دیے؛ وہ گر گئے، اور کوئی مدد کرنے والا نہیں تھا۔\n13۔ پھر انہوں نے اپنی مصیبت میں خداوند سے پکارا، {اور} اس نے انہیں ان کی مصیبتوں سے بچایا۔\n14۔ اس نے انہیں اندھیرے اور موت کے سائے سے نکالا، اور ان کی پٹیوں کو توڑ دیا۔\n15. اے کہ {انسان} خداوند کی تعریف کریں {اس کی بھلائی کے لیے}، اور {انسانوں کے بچوں کے لیے اس کے شاندار کارناموں کے لیے!''\n16۔ کیونکہ اس نے پیتل کے دروازے توڑے ہیں، اور لوہے کی سلاخیں ٹکڑوں میں کاٹ دی ہیں۔\n17۔ بے وقوف اپنی گناہوں اور گناہوں کی وجہ سے متاثر ہوتے ہیں۔\n18۔ ان کی روح ہر قسم کے گوشت سے نفرت کرتی ہے؛ اور وہ موت کے دروازوں کے قریب پہنچتے ہیں۔\n19۔ پھر وہ اپنی مصیبت میں خداوند سے پکارتے ہیں، {اور} وہ انہیں ان کی مصیبتوں سے نجات دیتا ہے۔\n20۔ اس نے اپنا کلام بھیجا، انہیں شفا دی، اور ان کی تباہی سے نجات دلائی۔\n21. اے کاش {انسان} خداوند کی حمد کریں {اس کی بھلائی کے لیے}، اور {انسانوں کے بچوں کے لیے اس کے شاندار کارناموں کے لیے!''\n22۔ اور وہ شکر گزاری کی قربانیاں قربان کریں، اور خوشی سے اس کے اعمال کا اعلان کریں۔ {خوشی سے: عبرانی۔ گانا}\n23۔ وہ جو جہازوں میں سمندر کی طرف جاتے ہیں، جو بڑے پانیوں میں کاروبار کرتے ہیں؛\n24۔ یہ خداوند کے کام اور اس کے عجائبات کو دیکھتے ہیں۔\n25۔ کیونکہ وہ حکم دیتا ہے، اور طوفانی ہوا کو اٹھاتا ہے، جو اس کی لہروں کو اٹھاتی ہے۔ {raiseth: عبرانی۔ کھڑا ہونے پر مجبور کریں}\n26۔ وہ آسمان کی طرف چڑھتے ہیں، پھر دوبارہ گہرائیوں میں جاتے ہیں: ان کی روح مصیبت کی وجہ سے پگھل جاتی ہے۔\n27۔ وہ ادھر ادھر گھومتے ہیں، نشے میں دھت آدمی کی طرح لڑکھڑاتے ہیں، اور بالکل بے بس ہو جاتے ہیں۔ {آر...: عبرانی ان کی ساری حکمت نگل لی جاتی ہے}\n28۔ پھر وہ اپنے مصیبت میں خداوند سے پکارتے ہیں، اور وہ انہیں ان کی مصیبتوں سے نکالتا ہے۔\n29۔ وہ طوفان کو پرسکون کرتا ہے، تاکہ اس کی لہریں ساکت رہیں۔\n30۔ تو وہ خوش ہوتے ہیں کیونکہ وہ خاموش رہتے ہیں؛ اسی لیے وہ انہیں ان کی پسندیدہ پناہ گاہ میں لے جاتا ہے۔\n31. اے کاش {انسان} خداوند کی حمد کریں {اس کی بھلائی کے لیے}، اور {انسانوں کے بچوں کے لیے اس کے شاندار کارناموں کے لیے!''\n32۔ وہ اسے عوام کی جماعت میں بھی بلند کریں، اور بزرگوں کی مجلس میں اس کی تعریف کریں۔\n33۔ وہ دریاؤں کو ویرانے میں بدل دیتا ہے، اور چشموں کو خشک زمین بناتا ہے؛\n34۔ ایک زرخیز زمین جو بنجر ہو جاتی ہے، ان کی بدی کی وجہ سے جو وہاں بستے ہیں۔ {بانجھ پن: عبرانی۔ نمکین}\n35۔ وہ بیابان کو کھڑا پانی اور خشک زمین کو چشموں میں بدل دیتا ہے۔\n36۔ اور وہاں وہ بھوکوں کو آباد کرتا ہے تاکہ وہ رہائش کے لیے شہر تیار کر سکیں؛\n37۔ اور کھیت بوئیں، اور انگور کے باغات لگائیں، جو زیادہ پھل دے سکیں۔\n38۔ وہ انہیں بھی برکت دیتا ہے، تاکہ وہ بہت زیادہ بڑھ جائیں؛ اور اپنے مویشیوں کو کم ہونے نہیں دیتے۔\n39۔ دوبارہ، وہ ظلم، مصیبت، اور غم کے ذریعے تباہ اور نیچا دکھائے جاتے ہیں۔\n40۔ وہ شہزادوں پر حقارت کرتا ہے، اور انہیں بیابان میں بھٹکنے پر مجبور کرتا ہے، {جہاں کوئی راستہ نہیں}۔ {وائلڈرنیس: یا، خالی جگہ}\n41۔ پھر بھی وہ غریبوں کو مصیبت سے بلند مقام پر رکھتا ہے، اور اپنے خاندان کو بھیڑ کی طرح بناتا ہے۔ {سے: یا، بعد میں}\n42. نیک لوگ دیکھیں گے اور خوش ہوں گے: اور تمام گناہوں سے اس کا منہ بند ہو جائے گا۔\n43. جو بھی دانا ہے اور ان چیزوں کی پابندی کرے گا، وہ بھی خداوند کی محبت بھری مہربانی کو سمجھے گا۔","1. [ایک گیت {یا} داؤد کا زبور۔] اے خدا، میرا دل ٹھیک ہو گیا ہے؛ میں گاؤں گا اور تعریف کروں گا، اپنی شان کے باوجود۔\n2. جاگو، زبور اور ہارپ: میں خود جلدی جاگ جاؤں گا۔\n3۔ اے خداوند، میں لوگوں میں تیری تعریف کروں گا، اور قوموں میں تیری تعریف کروں گا۔\n4۔ کیونکہ تیری رحمت آسمانوں سے بلند ہے: اور تیری سچائی بادلوں تک پہنچتی ہے۔ {بادل: یا، آسمان}\n5. اے خدا، تو آسمانوں سے بلند ہو جا، اور تیری جلال زمین سے بلند ہو؛\n6. تاکہ تمہارا محبوب نجات دے: اپنے دائیں ہاتھ سے بچاؤ، اور مجھے جواب دو۔\n7۔ خدا نے اپنی پاکیزگی میں بات کی ہے؛ میں خوش ہوں گا، شیکم کو تقسیم کروں گا، اور سکوت کی وادی کو تقسیم کروں گا۔\n8. گلیڈ {ہے} میرا؛ مناسہ {ہے} میرا؛ افرائیم بھی میرے سر کی طاقت ہے؛ یہوداہ {ہے} میرا قانون ساز؛\n9۔ موآب میرا واش پاٹ ہے؛ ایڈم پر میں اپنا جوتا پھینکوں گا؛ فلسطینیوں پر میں فتح حاصل کروں گا۔\n10. مجھے مضبوط شہر میں کون لے جائے گا؟ کون مجھے ایڈوم لے جائے گا؟\n11. {کیا تم} نہیں کرو گے، اے خدا، {جس نے} ہمیں چھوڑ دیا؟ اور کیا تو، اے خدا، ہماری فوجوں کے ساتھ باہر نہیں جاؤ گے؟\n12۔ ہمیں مصیبت سے مدد دو: کیونکہ انسان کی مدد بے سود ہے۔\n13. خدا کے ذریعے ہم بہادری سے کام کریں گے: کیونکہ وہی ہے جو ہمارے دشمنوں کو روند ڈالے گا۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے میری تعریف کے خدا، خاموش نہ رہو؛\n2۔ کیونکہ بدکاروں کا منہ اور دھوکہ دینے والوں کا منہ میرے خلاف کھلے ہیں: انہوں نے میرے خلاف جھوٹی زبان سے بات کی ہے۔ {دھوکہ بازوں کی: عبرانی۔ دھوکہ دہی} {کھلے: عبرانی۔ خود کو کھول چکے ہیں}\n3۔ انہوں نے مجھے نفرت بھرے الفاظ سے گھیر لیا؛ اور بغیر کسی وجہ کے میرے خلاف لڑے۔\n4۔ میری محبت کے لیے وہ میرے دشمن ہیں: لیکن میں خود کو دعا کے لیے وقف کرتا ہوں۔\n5۔ اور انہوں نے مجھے اچھائی کے بدلے برائی اور میری محبت کے لیے نفرت کا صلہ دیا۔\n6۔ اس پر ایک بدکار آدمی کو بٹھا دو: اور شیطان کو اس کے دائیں ہاتھ پر کھڑا کر دو۔ {شیطان: یا، ایک مخالف}\n7۔ جب اس کا فیصلہ کیا جائے تو اسے سزا دی جائے: اور اس کی دعا گناہ بن جائے۔ {مذمت: عبرانی۔ مجرم یا بدکار ہو کر باہر جاؤ}\n8۔ اس کے دن کم ہوں؛ {اور} کسی اور کو اپنا دفتر لینے دیا۔ {دفتر: یا، چارج}\n9۔ اس کے بچے یتیم ہوں، اور اس کی بیوی بیوہ۔\n10۔ اس کے بچے مسلسل آوارہ رہیں اور بھیک مانگیں: انہیں بھی اپنی روٹی تلاش کرے، اپنے ویران مقامات سے۔\n11۔ رشوت خور کو جو کچھ بھی ہے وہ پکڑنے دو؛ اور اجنبیوں کو اس کی محنت خراب کرنے دو۔\n12۔ کوئی اس پر رحم کرنے والا نہ ہو، نہ ہی کوئی اس کے یتیم بچوں کی طرف مائل ہو۔\n13۔ اس کی اولاد کو کاٹ دیا جائے؛ {اور} اگلی نسل میں ان کا نام مٹا دیا جائے۔\n14. اس کے باپ اجداد کی گناہوں کو خداوند کے ساتھ یاد رکھا جائے؛ اور اپنی ماں کے گناہ کو مٹانے نہ دیں۔\n15۔ انہیں ہمیشہ خداوند کے سامنے رہے، تاکہ وہ ان کی یاد زمین سے مٹا دے۔\n16۔ کیونکہ اس نے یاد رکھا کہ رحم نہیں کرے گا، بلکہ غریب اور محتاج لوگوں کو ستاتا ہے، تاکہ وہ دل شکستہ لوگوں کو بھی مار سکے۔\n17۔ جیسے وہ لعنت سے محبت کرتا تھا، ویسے ہی اسے یہ آ جائے: جیسے وہ برکت میں خوش نہیں تھا، ویسے ہی وہ اس سے دور ہو۔\n18۔ جیسے اس نے اپنے لباس کی طرح لعنتوں میں ملبوس کیا، ویسے ہی وہ اس کے آنتوں میں پانی کی طرح اور تیل کی طرح اس کی ہڈیوں میں۔ {اس کے آنتوں میں: ہیب۔ اس کے اندر}\n19۔ یہ اس کے لیے اس لباس کی طرح ہو جو اسے ڈھانپتا ہے، اور ایک بیلٹ کے لیے جس سے وہ مسلسل بندھا ہوتا ہے۔\n20۔ {آؤ} یہ {ہو} میرے مخالفین کا اجر ہو جو خداوند کی طرف سے ہے، اور ان کے لیے جو میری روح کے خلاف برا بولتے ہیں۔\n21. لیکن اے خداوند، میرے لیے کام کرو، اپنے نام کے لیے: کیونکہ تیری رحمت اچھی ہے، تو مجھے بچا۔\n22. کیونکہ میں غریب اور محتاج ہوں، اور میرا دل میرے اندر زخمی ہے۔\n23۔ میں سایہ کی طرح غائب ہو جاتا ہوں جب وہ زوال پذیر ہوتا ہے: مجھے ٹڈی دل کی طرح اوپر نیچے اچھالا جاتا ہے۔\n24۔ میرے گھٹنے روزہ رکھنے کی وجہ سے کمزور ہیں؛ اور میرا جسم موٹاپے سے محروم ہو جاتا ہے۔\n25۔ میں ان کے لیے بھی ملامت بن گیا: {جب} انہوں نے مجھے دیکھا تو سر ہلا دیا۔\n26. اے خداوند میرے خدا، میری مدد فرما: اے اپنی رحمت کے مطابق مجھے بچا:\n27۔ تاکہ وہ جان سکیں کہ یہ تمہارا ہاتھ ہے؛ {یہ} تو، خداوند، نے کر دکھایا۔\n28۔ انہیں لعنت دے، لیکن تو دعا فرما: جب وہ اٹھیں تو شرمندہ ہوں؛ لیکن اپنے بندے کو خوشی ہو۔\n29۔ میرے مخالفین کو شرمندگی میں ملبوس ہونے دو، اور انہیں اپنی الجھن میں ڈھانپنے دو، جیسے چادر کے ساتھ۔\n30۔ میں اپنے منہ سے خداوند کی بہت تعریف کروں گا؛ ہاں، میں اس کی تعریف کروں گا، سب کے درمیان۔\n31۔ کیونکہ وہ غریبوں کے دائیں ہاتھ پر کھڑا ہوگا، تاکہ {اسے} کو ان لوگوں سے بچائے جو اس کی روح کو سزا دیتے ہیں۔ {وہ...: عببرانی۔ دی ججز آف}","1. [داؤد کا زبور۔] خداوند نے میرے رب سے فرمایا، میرے دائیں ہاتھ پر بیٹھو، جب تک میں تمہارے دشمنوں کو تمہارا سہارا نہ بنا دوں۔\n2. خداوند اپنی طاقت کی چھڑی صیہون سے بھیجے گا: اپنے دشمنوں کے درمیان حکومت کرو۔\n3. تمہارے لوگ تمہاری طاقت کے دن، صبح کے رحم سے پاکیزگی کی خوبصورتی میں رضامند ہوں گے: تمہارے پاس تمہاری جوانی کی شبنم ہے۔ {سے...: یا، صبح کے رحم سے زیادہ: تمہیں ملے گا، وغیرہ}\n4۔ خداوند نے قسم کھائی ہے، اور توبہ نہیں کرے گا، کہ تو ملک صادق کے حکم کے بعد ہمیشہ کے لیے پادری ہو۔\n5. خداوند تمہارے دائیں ہاتھ پر بادشاہوں کو اپنے غضب کے دن مارے گا۔\n6۔ وہ کافروں میں فیصلہ کرے گا، مردہ جسموں سے جگہوں کو بھر دے گا؛ وہ کئی ملکوں کے سر کو زخمی کرے گا۔ {بہت سے: یا، زبردست}\n7۔ وہ راستے میں موجود ندی سے پیے گا: اس لیے وہ سر اٹھائے گا۔","1. خداوند کی تعریف کرو۔ میں اپنے پورے دل سے، راستوں کی جماعت میں، اور جماعت میں خداوند کی حمد کروں گا۔ {تعریف ہو...: عبرانی۔ الحمد للہ}\n2۔ خداوند کے اعمال عظیم ہیں، جو ان سب میں سے تلاش کیے جاتے ہیں جو ان میں خوشی حاصل کرتے ہیں۔\n3۔ اس کا کام قابل عزت اور جلال ہے: اور اس کی راستبازی ہمیشہ قائم رہتی ہے۔\n4۔ اس نے اپنے شاندار کاموں کو یاد رکھنے کے لیے بنایا ہے: خداوند مہربان اور ہمدردی سے بھرپور ہے۔\n5۔ اس نے ان لوگوں کو گوشت دیا ہے جو اس سے ڈرتے ہیں: وہ ہمیشہ اپنے عہد کا خیال رکھے گا۔ {گوشت: عبرانی۔ شکار}\n6۔ اس نے اپنے لوگوں کو اپنے اعمال کی طاقت دکھائی ہے تاکہ وہ انہیں کافروں کی میراث دے سکے۔\n7۔ اس کے ہاتھوں کے کام {ہیں} صداقت اور حکم؛ اس کے تمام احکامات درست ہیں۔\n8. وہ ہمیشہ ہمیشہ کے لیے مضبوط ہیں، {اور سچائی اور راستبازی میں کیے گئے ہیں}۔ {کھڑے ہو جاؤ...: عبرانی۔ قائم ہیں}\n9۔ اس نے اپنی قوم کو نجات بھیجی: اس نے ہمیشہ کے لیے اپنے عہد کا حکم دیا ہے: مقدس اور معزز اس کا نام ہے۔\n10. خداوند کا خوف {حکمت کی ابتداء} ہے: جو بھی اس کے احکامات کرتا ہے، اسے اچھی سمجھ ہو: اس کی حمد ہمیشہ قائم رہتی ہے۔ {ایک اچھا...: یا، اچھی کامیابی} {اس کے احکامات: عبرانی۔ وہ}","1. خداوند کی تعریف کرو۔ مبارک ہے وہ شخص جو خداوند سے ڈرتا ہے، جو اس کے احکامات میں بہت خوش ہوتا ہے۔ {تعریف...: عبرانی۔ الحمد للہ}\n2. اس کی نسل زمین پر طاقتور ہوگی: راستوں کی نسل بابرکت ہوگی۔\n3۔ دولت اور دولت اس کے گھر میں ہوگی: اور اس کی راستبازی ہمیشہ قائم رہتی ہے۔\n4۔ راستوں کے لیے اندھیرے میں روشنی اٹھتی ہے: {وہ} مہربان، ہمدردی سے بھرپور اور راستباز ہے۔\n5۔ ایک اچھا آدمی فضل اور قرض دیتا ہے: وہ اپنے معاملات کو احتیاط سے چلائے گا۔ {صوابدیت: عبرانی۔ فیصلہ}\n6۔ یقینا وہ ہمیشہ کے لیے نہیں ہلائے گا: نیک ہمیشہ یاد میں رہیں گے۔\n7۔ وہ بری خبر سے نہیں ڈرے گا: اس کا دل مستحکم ہے، خداوند پر بھروسہ کرتا ہے۔\n8۔ اس کا دل {قائم ہے}، وہ نہیں ڈرے گا، جب تک کہ وہ اپنے دشمنوں پر {اپنی خواہش} نہ دیکھے۔\n9۔ اس نے بکھر دیا، غریبوں کو دیا ہے؛ اس کی راستبازی ہمیشہ قائم رہتی ہے؛ اس کا سینگ عزت کے ساتھ بلند کیا جائے گا۔\n10۔ بدکار دیکھے گا اور غمگین ہوگا؛ وہ اپنے دانت پیسے گا، اور پگھل جائے گا: بدکاروں کی خواہش ختم ہو جائے گی۔","1. خداوند کی تعریف کرو۔ اے خداوند کے بندوں، تعریف کرو، خداوند کے نام کی تعریف کرو۔ {تعریف ہو...: عبرانی۔ الحمد للہ}\n2۔ خداوند کا نام اس وقت سے اور ہمیشہ کے لیے مبارک ہو۔\n3۔ سورج کے طلوع سے لے کر غروب ہونے تک، خداوند کا نام تعریف کے لائق ہے۔\n4۔ خداوند تمام قوموں سے بلند ہے، اور اس کی جلال آسمانوں سے بلند ہے۔\n5. جو {ہے} خداوند ہمارے خدا کی طرح، جو بلند مقام پر بستا ہے، {بستا ہے...: عبرانی۔ اپنے آپ کو آباد کرنے کے لیے بلند کرتا ہے}\n6۔ جو خود کو جھکتا ہے تاکہ آسمان اور زمین میں موجود چیزیں دیکھ سکے!\n7۔ وہ غریبوں کو مٹی سے اٹھاتا ہے، {اور} محتاجوں کو گوبر کے ڈھیر سے نکالتا ہے؛\n8۔ تاکہ وہ اپنے لوگوں کے شہزادوں کے ساتھ تعلقات قائم کرے، حتیٰ کہ اپنے لوگوں کے شہزادوں کے ساتھ۔\n9۔ وہ بانجھ عورت کو گھر سنبھالنے اور بچوں کی خوش ماں بنانے کے لیے بناتا ہے۔ خداوند کی تعریف ہو۔ {برقرار رکھنے کے لیے...: عبرانی۔ گھر میں رہنے کے لیے}","1۔ جب اسرائیل مصر سے باہر نکلا، یعقوب کا گھر، ایک عجیب زبان کی قوم سے؛\n2۔ یہوداہ اس کا پناہ گاہ تھا، {اور} اسرائیل اس کا حکمرانی تھا۔\n3۔ سمندر نے دیکھا اور بھاگ گیا: اردن کو پیچھے دھکیل دیا گیا۔\n4۔ پہاڑ مینڈوں کی طرح اچھلتے رہے، {اور} چھوٹے پہاڑ بھیڑوں کی طرح۔\n5. اے سمندر، تمہیں کیا تکلیف ہوئی ہے کہ تم بھاگ گئے؟ اے اردن، {کہ} تمہیں پیچھے دھکیل دیا گیا؟\n6۔ اے پہاڑ، {جسے} تم نے مینڈوں کی طرح چھلانگ لگائی؛ {اور} تم چھوٹے پہاڑیاں، جیسے بکری؟\n7. اے زمین، خداوند کی حضور، یعقوب کے خدا کی موجودگی میں کانپ جا؛\n8۔ جس نے چٹان کو کھڑا پانی، چقماق کو پانی کے چشمے میں بدل دیا۔","1. ہمارے لیے نہیں، اے خداوند، ہمارے لیے نہیں، بلکہ اپنے نام کو جلال عطا فرما، تیری رحمت کے لیے، {اور} اپنی سچائی کے لیے۔\n2. کافر کیوں کہیں، ان کا خدا کہاں ہے؟\n3. لیکن ہمارا خدا آسمانوں میں ہے: اس نے جو چاہا کیا۔\n4۔ ان کے بت چاندی اور سونے کے ہیں، جو انسانوں کے ہاتھوں کا کام ہیں۔\n5۔ ان کے منہ ہیں، لیکن وہ بولتے نہیں: آنکھیں ہیں، لیکن وہ نہیں دیکھتیں:\n6۔ ان کے کان ہوتے ہیں، لیکن وہ سنتے نہیں: ناکوں میں ہوتے ہیں، لیکن وہ سونگھتے نہیں:\n7۔ ان کے ہاتھ ہیں، لیکن وہ نہیں سنبھالتے: پاؤں رکھتے ہیں، لیکن وہ چلتے نہیں: نہ ہی وہ گلے سے بولتے ہیں۔\n8۔ جو انہیں بناتے ہیں وہ ان جیسے ہوتے ہیں؛ {اسی طرح} ہر وہ شخص جو ان پر بھروسہ کرتا ہے۔\n9۔ اے اسرائیل، خداوند پر بھروسہ کرو: وہ ان کی مدد اور ڈھال ہے۔\n10. اے ہارون خاندان پر، خداوند پر بھروسہ کرو: وہ ان کی مدد اور ڈھال ہے۔\n11۔ جو خداوند سے ڈرتے ہیں، خداوند پر بھروسہ کریں: وہ ان کی مدد اور ڈھال ہے۔\n12. خداوند نے ہمارا خیال رکھا ہے: وہ ہمیں برکت دے گا؛ وہ اسرائیل کے گھر کو برکت دے گا؛ وہ ہارون کے گھر کو برکت دے گا۔\n13۔ وہ ان لوگوں کو برکت دے گا جو خداوند سے ڈرتے ہیں، {چھوٹے اور بڑے} دونوں۔ {اور: عبرانی۔ with}\n14. خداوند تمہیں اور تمہارے بچوں کو اور تمہیں مزید بڑھائے گا۔\n15. تم خداوند کی طرف سے بابرکت ہو جس نے آسمان اور زمین بنایا۔\n16۔ آسمان، {حتی} آسمان بھی، خداوند کے ہیں: لیکن زمین نے انسانوں کے بچوں کو دی ہے۔\n17۔ مردے خدا کی تعریف نہیں کرتے، نہ ہی خاموش رہنے والوں کی۔\n18۔ لیکن ہم اس وقت سے اور ہمیشہ کے لیے خداوند کو برکت دیں گے۔ خدا کا شکر ہے۔","1. میں خداوند سے محبت کرتا ہوں، کیونکہ اس نے میری آواز اور میری دعائیں سنی ہیں۔\n2۔ چونکہ اس نے میری طرف کان لگا لیا ہے، اس لیے میں جتنا زندہ ہوں {ان} کو پکاروں گا۔ {جتنا لمبا...: عبرانی میرے زمانے میں}\n3. موت کے غم نے مجھے گھیر لیا، اور جہنم کے درد نے مجھے گھیر لیا: میں نے مصیبت اور غم پایا۔ {گاٹ...: عبرانی۔ مجھے ڈھونڈ لیا}\n4۔ پھر میں نے خداوند کے نام پر پکارا؛ اے خداوند، میں تجھ سے التجا کرتا ہوں، میری جان کو بچا۔\n5۔ مہربان خداوند ہے، اور راستباز ہے؛ ہاں، ہمارا خدا رحم کرنے والا ہے۔\n6۔ خداوند سادہ کو محفوظ رکھتا ہے: مجھے نیچا دکھایا گیا، اور اس نے میری مدد کی۔\n7. اے میری جان، اپنی آرام کی طرف لوٹ جاؤ؛ کیونکہ خداوند نے تمہارے ساتھ بھلا سلوک کیا ہے۔\n8۔ کیونکہ تو نے میری جان کو موت سے بچایا، میری آنکھوں کو آنسوؤں سے، اور میرے پاؤں گرنے سے بچایا۔\n9. میں زندہ زمین میں خداوند کے سامنے چلوں گا۔\n10۔ میں نے ایمان لایا، اس لیے میں نے کہا: میں بہت پریشان ہوا:\n11۔ میں نے جلدی میں کہا، تمام انسان جھوٹے ہیں۔\n12. میں خداوند کو اس کے تمام فوائد کے لیے کیا دوں؟\n13۔ میں نجات کا پیالہ لوں گا، اور خداوند کے نام پر پکاروں گا۔\n14. میں اب خداوند کو اس کے تمام لوگوں کی موجودگی میں اپنی قسمیں ادا کروں گا۔\n15۔ خداوند کی نظر میں قیمتی اس کے مقدسین کی موت ہے۔\n16. اے خداوند، واقعی میں تیرا بندہ ہوں؛ میں تمہارا خادم ہوں، اور تمہاری خادمہ کا بیٹا: تم نے میری بندھن کھول دیے ہیں۔\n17۔ میں تمہیں شکر گزاری کی قربانی پیش کروں گا، اور خداوند کے نام کو پکاروں گا۔\n18۔ میں اب خداوند کے سامنے اس کے تمام لوگوں کی موجودگی میں اپنی قسمیں ادا کروں گا،\n19۔ خداوند کے گھر کے صحن میں، تیرے بیچ میں، اے یروشلم۔ خداوند کی تعریف ہو۔","1. اے خداوند کی حمد کرو، اے تمام قوموں: اس کی تعریف کرو، اے سب لوگ۔\n2. کیونکہ اس کی مہربان مہربانی ہمارے لیے عظیم ہے: اور خداوند کی سچائی ہمیشہ قائم رہتی ہے۔ خداوند کی تعریف ہو۔","1۔ خداوند کا شکر ادا کرو؛ کیونکہ {وہ} اچھا ہے: کیونکہ اس کی رحمت {ہمیشہ قائم رہتی ہے}۔\n2. اب اسرائیل کہے کہ اس کی رحمت ہمیشہ قائم رہے گی۔\n3۔ اب ہارون کا گھر کہے کہ اس کی رحمت ہمیشہ قائم رہے گی۔\n4۔ اب جو لوگ خداوند سے ڈرتے ہیں وہ کہیں کہ اس کی رحمت ہمیشہ قائم رہے گی۔\n5۔ میں نے مصیبت میں خداوند سے پکارا: خداوند نے مجھے جواب دیا، {اور مجھے ایک بڑے مقام پر رکھا}۔ {پریشانی میں: عبوری۔ پریشانی سے باہر}\n6۔ خداوند {ہے} میرے ساتھ؛ میں نہیں ڈروں گا: انسان میرے ساتھ کیا کر سکتا ہے؟ {پر...: عبرانی۔ میرے لیے}\n7. خداوند میرا حصہ ان لوگوں کے ساتھ لیتا ہے جو میری مدد کرتے ہیں: اسی لیے میں ان پر {میری خواہش} دیکھوں گا جو مجھ سے نفرت کرتے ہیں۔\n8. {خداوند پر بھروسہ کرنا انسان پر بھروسہ کرنے سے بہتر ہے۔\n9. شہزادوں پر بھروسہ کرنے سے بہتر ہے کہ خداوند پر بھروسہ کیا جائے۔\n10۔ تمام قوموں نے میرے گرد گھیرا ہوا تھا: لیکن خداوند کے نام پر میں انہیں تباہ کروں گا۔ {تباہ کریں...: عببرانی۔ انہیں کاٹ دو}\n11۔ انہوں نے مجھے گھیر لیا؛ ہاں، انہوں نے مجھے گھیر لیا: لیکن خداوند کے نام پر میں انہیں تباہ کر دوں گا۔\n12۔ وہ مجھے شہد کی مکھیوں کی طرح گھیرے ہوئے تھے؛ وہ کانٹوں کی آگ کی طرح بجھ جاتے ہیں: کیونکہ خداوند کے نام پر میں انہیں تباہ کر دوں گا۔ {تباہ کریں: عبرانی۔ کٹ ڈاؤن}\n13. تو نے مجھ پر غصہ کیا کہ میں گر جاؤں: لیکن خداوند نے میری مدد کی۔\n14. خداوند میری طاقت اور گیت ہے، اور وہ میری نجات بن گیا ہے۔\n15۔ خوشی اور نجات کی آواز {راستبازوں کے خیموں میں ہے}: خداوند کا دایاں ہاتھ بہادری سے کام کرتا ہے۔\n16۔ خداوند کا دایاں ہاتھ بلند ہے: خداوند کا دایاں ہاتھ بہادری سے کام کرتا ہے۔\n17۔ میں نہیں مروں گا، بلکہ زندہ رہوں گا، اور خداوند کے اعمال کا اعلان کروں گا۔\n18۔ خداوند نے مجھے سخت سزا دی ہے، لیکن اس نے مجھے موت کے حوالے نہیں کیا۔\n19۔ میرے لیے راستبازی کے دروازے کھولو: میں ان میں داخل ہوں گا، {اور} خداوند کی تعریف کروں گا:\n20۔ یہ خداوند کا دروازہ، جس سے نیک لوگ داخل ہوں گے۔\n21. میں تیری تعریف کروں گا: کیونکہ تو نے میری بات سنی ہے، اور تم میری نجات بن گئی ہو۔\n22۔ وہ پتھر {جسے معماروں نے مسترد کیا} کونے کا سر {پتھر} بن گیا۔\n23. یہ خداوند کا کام ہے؛ یہ ہماری نظر میں حیرت انگیز ہے۔ {خداوند کے...: عبرانی زبان۔ خداوند کی طرف سے}\n24. یہ وہ دن ہے {جو} خداوند نے بنایا ہے؛ ہم اس میں خوش ہوں گے اور خوش ہوں گے۔\n25۔ اب بچاؤ، میں تم سے التجا کرتا ہوں، اے خداوند: اے خداوند، میں تم سے التجا کرتا ہوں، اب خوشحالی بھیج۔\n26. مبارک ہو وہ جو خداوند کے نام پر آتا ہے: ہم نے تمہیں خداوند کے گھر سے برکت دی ہے۔\n27. خدا {ہے} خداوند ہے، جس نے ہمیں روشنی دی ہے: قربانی کو رسیوں سے باندھ دو، {حتیٰ کہ} قربان گاہ کے سینگوں تک۔\n28. تو میرا خدا ہے، اور میں تیری تعریف کروں گا: {تو میرا خدا} ہے، میں تمہیں بلند کروں گا۔\n29۔ خداوند کا شکر ادا کرو؛ کیونکہ {وہ} اچھا ہے: اس کی رحمت {ہمیشہ قائم رہے گی}۔","1. الف۔ خوش نصیب ہیں وہ لوگ جو راستے میں بے عیب ہیں، جو خداوند کے قانون میں چلتے ہیں۔ {غیر آلود: یا، کامل، یا، مخلص}\n2. مبارک ہیں وہ لوگ جو اس کی گواہی رکھتے ہیں، {اور جو} پورے دل سے اسے تلاش کرتے ہیں۔\n3۔ وہ کوئی گناہ نہیں کرتے: وہ اس کے راستے پر چلتے ہیں۔\n4۔ تم نے {ہمیں} حکم دیا ہے کہ اپنے اصولوں کی سختی سے پاسداری کریں۔\n5۔ کاش میرے طریقے تیری قوانین کی پاسداری کے لیے ہدایت دیے جائیں!\n6۔ تو پھر میں شرمندہ نہیں ہوں گا، جب میں تمہارے تمام احکامات کا احترام کروں گا۔\n7۔ میں تمہاری سچائی دل کے ساتھ تمہاری تعریف کروں گا، جب میں تمہارے راستباز فیصلے سیکھ لوں گا۔ {تمہاری...: عببری۔ تیری راستبازی کے فیصلے}\n8۔ میں تمہارے قوانین کی پاسداری کروں گا: اے مجھے مکمل طور پر ترک نہ کرنا۔\n9۔ بیتھ۔ ایک نوجوان اپنے راستے کو کس طرح پاک کرے گا؟ اپنے کلام کے مطابق اس پر عمل کر کے۔\n10۔ میں نے پورے دل سے تمہیں تلاش کیا ہے: اے مجھے تمہارے احکامات سے بھٹکنے نہ دو۔\n11۔ میں نے تیرا کلام اپنے دل میں چھپا لیا ہے تاکہ میں تمہارے خلاف گناہ نہ کروں۔\n12. مبارک {آر} تو، اے خداوند: مجھے اپنے قوانین سکھاؤ۔\n13۔ میں نے اپنے ہونٹوں سے تیرے منہ کے تمام فیصلے بیان کیے ہیں۔\n14. میں نے تمہاری گواہی کے راستے میں اتنا ہی خوش ہوا ہے جتنا کہ ہر دولت میں۔\n15. میں تمہارے احکامات میں غور کروں گا، اور تمہارے طریقوں کا احترام کروں گا۔\n16. میں تمہارے قوانین سے خوش ہوں گا: میں تمہارا کلام نہیں بھولوں گا۔\n17۔ گمیل۔ اپنے خادم کے ساتھ خوب سلوک کرو، {تاکہ} میں زندہ رہوں اور تمہارا وعدہ پورا کروں۔\n18۔ میری آنکھیں کھولو، تاکہ میں تمہارے قانون سے حیرت انگیز چیزیں دیکھ سکوں۔ {کھولو: عبوری۔ ظاہر کریں}\n19. میں زمین پر اجنبی ہوں: اپنے احکامات مجھ سے مت چھپو۔\n20. میری روح ہر وقت تمہارے فیصلوں کی خواہش کے لیے ٹوٹ جاتی ہے۔\n21. تو نے ان مغرور لوگوں کو ملامت کی ہے جو تمہارے احکامات سے غلطی کرتے ہیں۔\n22۔ مجھ سے ملامت اور حقارت ہٹا دیں؛ کیونکہ میں نے تمہاری گواہی رکھی ہے۔\n23۔ شہزادے بھی بیٹھ کر میرے خلاف بولے: لیکن تیرے خادم نے تمہارے قوانین میں غور کیا۔\n24۔ تیری گواہیاں بھی میری خوشی ہیں {اور} میرے مشیروں کے لیے۔ {میرے مشیر: عبرانی۔ میرے مشورے کے لوگ}\n25۔ ڈیلیتھ۔ میری روح مٹی سے چمٹ جاتی ہے: اپنے کلام کے مطابق مجھے زندہ کر دے۔\n26۔ میں نے اپنے طریقے بیان کیے ہیں، اور تو نے مجھے سنا: مجھے اپنے قوانین سکھاؤ۔\n27۔ مجھے تمہارے احکامات کا راستہ سمجھاؤ: اسی طرح میں تمہارے حیرت انگیز اعمال کے بارے میں بات کروں گا۔\n28۔ میری روح بھاری ہونے کے لیے پگھلتی ہے: اپنے کلام کے مطابق مجھے مضبوط بنا۔ {melteth: Heb. ڈراپتھ}\n29۔ مجھ سے جھوٹ کا راستہ ہٹا دو: اور اپنی شریعت کو مہربانی سے عطا کرو۔\n30۔ میں نے سچائی کا راستہ چنا ہے: تمہارے فیصلے میں نے اپنے سامنے رکھے ہیں۔\n31۔ میں نے تیری گواہیوں پر قائم رہنا جاری رکھا ہے: اے خداوند، مجھے شرمندہ نہ کر۔\n32. میں تمہارے احکامات کے راستے پر چلوں گا، جب تم میرا دل وسیع کرو گے۔\n33۔ وہ۔ اے خداوند، مجھے اپنے قوانین کا راستہ سکھاؤ؛ اور میں اسے {آخر} تک رکھوں گا۔\n34۔ مجھے سمجھ دو، اور میں تمہارا قانون نبھاؤں گا؛ ہاں، میں اسے پورے دل سے دیکھوں گا۔\n35۔ مجھے اپنے احکامات کے راستے پر چلنے پر مجبور کرو؛ کیونکہ اسی میں مجھے خوشی ہوتی ہے۔\n36. میرا دل اپنی گواہوں کی طرف جھکاؤ، نہ کہ لالچ کی طرف۔\n37۔ میری نظریں غرور سے ہٹا لیں؛ {اور} اپنی راہ میں مجھے زندہ کرو۔ {مڑو...: عبرانی گزر جاؤ}\n38. اپنے بندے کے لیے اپنا کلام قائم کرو، جو تمہارے خوف کے لیے وقف ہے۔\n39۔ میری ملامت کو جو میں ڈرتا ہوں، دور کر دو: کیونکہ تمہارے فیصلے اچھے ہیں۔\n40۔ دیکھو، میں تمہارے احکامات کا انتظار کر رہا ہوں: اپنی راستبازی میں مجھے زندہ کرو۔\n41. VAU۔ اے خداوند، تیری رحمتیں بھی میرے پاس آئیں، تیری نجات بھی، تیرے کلام کے مطابق۔\n42. اسی طرح میرے پاس اس کا جواب دینے کی صلاحیت ہوگی جو مجھے ملامت کرتا ہے: کیونکہ میں تیرے کلام پر بھروسہ کرتا ہوں۔ {تو...: یا، اسی طرح میں اس کا جواب دوں جو مجھے کسی چیز میں ملامت کرتا ہے}\n43۔ اور میرے منہ سے سچائی کا کلام مکمل طور پر مت نکالو؛ کیونکہ میں نے تمہارے فیصلوں میں امید کی ہے۔\n44۔ اسی طرح میں تیری شریعت ہمیشہ ہمیشہ کے لیے برقرار رکھوں گا۔\n45۔ اور میں آزادی کے ساتھ چلوں گا: کیونکہ میں تمہارے احکامات چاہتا ہوں۔ {آزاد ہے: عبرانی۔ آزاد}\n46۔ میں بادشاہوں کے سامنے بھی تمہاری گواہی کے بارے میں بات کروں گا، اور شرمندہ نہیں ہوں گا۔\n47۔ اور میں تمہارے احکامات میں خوش ہوں گا، جن سے میں نے محبت کی ہے۔\n48۔ میں اپنے ہاتھ بھی تمہارے احکامات کی طرف اٹھاؤں گا، جن سے میں نے محبت کی ہے؛ اور میں تمہارے قوانین میں غور کروں گا۔\n49۔ زین۔ اپنے خادم کے لیے اس کلام کو یاد رکھو، جس پر تم نے مجھے امید دی ہے۔\n50۔ یہ میری تکلیف میں میری تسلی ہے: کیونکہ تیرے کلام نے مجھے زندہ کیا ہے۔\n51. مغرور لوگوں نے مجھے بہت طنز میں ڈالا: {ابھی} میں نے تیرے قانون سے انکار نہیں کیا۔\n52. اے خداوند، میں نے تیرے پرانے فیصلے یاد کیے؛ اور خود کو تسلی دی ہے۔\n53. میرے خلاف خوف نے ان بدکاروں کی وجہ سے جو تیری شریعت کو چھوڑ دیتے ہیں، اس لیے مجھ پر دہشت طاری ہو گئی ہے۔\n54. تیری تحریریں میرے زیارت کے گھر میں میرے گیت ہیں۔\n55۔ اے خداوند، میں نے رات کے وقت تیرا نام یاد رکھا اور تیری شریعت کی پاسداری کی۔\n56۔ یہ میرے پاس تھا، کیونکہ میں نے تمہارے اصولوں کو پورا کیا۔\n57۔ چیتھ۔ {تو} میرا حصہ ہے، اے خداوند: میں نے کہا ہے کہ میں تیرے الفاظ کو پورا کروں گا۔\n58۔ میں نے پورے دل سے تیری عنایت کی درخواست کی ہے: اپنے کلام کے مطابق میرے ساتھ رحم فرما۔ {فیور: عبرانی۔ چہرہ}\n59۔ میں نے اپنے راستوں پر غور کیا، اور تیری گواہوں کی طرف قدم موڑ لیے۔\n60۔ میں نے جلدی کی، اور تمہارے احکامات پر عمل کرنے میں تاخیر کی۔\n61۔ بدکاروں کے گروہوں نے مجھے لوٹا: {لیکن} میں نے تمہارا قانون نہیں بھولا۔ {بینڈز: یا کمپنیاں}\n62۔ آدھی رات کو میں تمہارے نیک فیصلوں کی وجہ سے تمہارا شکر ادا کرنے کے لیے اٹھوں گا۔\n63. میں ان سب کا ساتھی ہوں جو تم سے ڈرتے ہیں، اور جو تمہارے اصولوں کی پاسداری کرتے ہیں۔\n64۔ اے خداوند، زمین تیری رحمت سے بھری ہوئی ہے: مجھے اپنے قوانین سکھاؤ۔\n65۔ ٹیتھ۔ اے خداوند، تو نے اپنے بندے کے ساتھ اپنے کلام کے مطابق اچھا سلوک کیا ہے۔\n66۔ مجھے اچھا فیصلہ اور علم سکھاؤ: کیونکہ میں نے تمہارے احکامات پر ایمان رکھا ہے۔\n67۔ اس سے پہلے کہ میں مصیبت میں مبتلا ہوا تھا، میں گمراہ ہو گیا: لیکن اب میں نے تیرے وعدے کو پورا کر لیا ہے۔\n68۔ تم نیک ہو، اور نیکی کرتے ہو؛ مجھے اپنے قوانین سکھاؤ۔\n69۔ مغرور لوگوں نے میرے خلاف جھوٹ گھڑ لیا ہے: {لیکن} میں تمہارے اصولوں کو پورے دل سے نبھاؤں گا۔\n70۔ ان کا دل تیل کی طرح موٹا ہے؛ {لیکن} میں تمہارے قانون میں خوش ہوں۔\n71. {یہ میرے لیے اچھا ہے} کہ میں مبتلا ہوں؛ تاکہ میں تمہارے قوانین سیکھ سکوں۔\n72. تیرے منہ کا قانون میرے لیے ہزاروں سونے اور چاندی سے بہتر ہے۔\n73۔ جوڈ۔ تیرے ہاتھوں نے مجھے بنایا اور بنایا ہے: مجھے سمجھ دو، تاکہ میں تمہارے احکامات سیکھ سکوں۔\n74۔ جو لوگ تم سے ڈرتے ہیں وہ مجھے دیکھ کر خوش ہوں گے؛ کیونکہ میں نے تیرے کلام میں امید کی ہے۔\n75۔ اے خداوند، میں جانتا ہوں کہ تیری رائے درست ہے، اور تو نے وفاداری میں مجھے تکلیف دی ہے۔ {دائیں: عبوری۔ راستبازی}\n76۔ میں تم سے دعا کرتا ہوں کہ تمہاری مہربانی میرے سکون کے لیے ہو، جیسا کہ تمہارے کلام کے مطابق اپنے خادم کے لیے ہے۔ {for...: عبرانی۔ مجھے تسلی دینے کے لیے}\n77۔ تمہاری نرم رحمتیں میرے پاس آئیں، تاکہ میں زندہ رہ سکوں: کیونکہ تیری شریعت میری خوشی ہے۔\n78. مغرور شرمندہ ہوں؛ کیونکہ انہوں نے میرے ساتھ بے وجہ سلوک کیا: {لیکن} میں تمہارے اصولوں میں غور کروں گا۔\n79۔ جو لوگ تم سے ڈرتے ہیں وہ میری طرف رجوع کریں، اور جو تیری گواہی جانتے ہیں۔\n80۔ میرا دل تمہارے قوانین میں صحت مند ہو؛ کہ میں شرمندہ نہیں ہوں۔\n81۔ کیف۔ میری جان تیری نجات کے لیے بے ہوش ہوتی ہے: {لیکن} میں تیرے کلام میں امید رکھتا ہوں۔\n82۔ میری آنکھیں تیرے کلام کے لیے بند ہو جاتی ہیں، کہتا ہوں، کب تم مجھے تسلی دو گے؟\n83۔ کیونکہ میں دھوئیں میں بوتل کی طرح بن گیا ہوں؛ {ابھی} میں تمہارے قوانین نہیں بھولتا۔\n84۔ تیرے خادم کے کتنے دن ہیں؟ تم کب ان لوگوں پر فیصلہ کرو گے جو مجھے ستاتے ہیں؟\n85۔ مغرور لوگوں نے میرے لیے گڑھے کھود دیے ہیں، جو تیرے قانون کے مطابق نہیں ہیں۔\n86. تیرے تمام احکامات وفادار ہیں: وہ مجھے غلط طریقے سے ستاتے ہیں؛ میری مدد کرو۔ {وفادار: عبرانی۔ وفاداری}\n87۔ وہ مجھے زمین پر تقریبا نگل چکے تھے؛ لیکن میں نے تمہارے اصولوں کو ترک نہیں کیا۔\n88. اپنی محبت کے بعد مجھے زندہ کر؛ اسی طرح میں تمہاری زبان کی گواہی رکھوں گا۔\n89۔ لنگڑ۔ ہمیشہ کے لیے، اے خداوند، تیرا کلام آسمان میں طے پا گیا ہے۔\n90۔ تیری وفاداری تمام نسلوں کے لیے ہے: تو نے زمین کو قائم کیا ہے، اور وہ قائم رہتی ہے۔ {ابھی...: عبرانی نسل و نسل کے لیے} {پابندی: عبرانی۔ اسٹینڈتھ}\n91۔ وہ آج کے دن آپ کے احکامات کے مطابق جاری ہیں: کیونکہ سب آپ کے خادم ہیں۔\n92. اگر تیری شریعت میری خوشیاں نہ ہوتی، تب میں اپنی مصیبت میں مر جاتا۔\n93۔ میں تمہارے اصولوں کو کبھی نہیں بھولوں گا: کیونکہ انہی سے تو نے مجھے زندہ کیا ہے۔\n94۔ میں تمہارا ہوں، مجھے بچاؤ؛ کیونکہ میں نے تمہارے احکامات مانگے ہیں۔\n95. بدکاروں نے انتظار کیا کہ میں مجھے تباہ کروں: {لیکن} میں تمہاری گواہیوں پر غور کروں گا۔\n96۔ میں نے تمام کمال کا اختتام دیکھا ہے: {لیکن} تمہارا حکم {ہے} حد سے زیادہ وسیع ہے۔\n97۔ میم۔ اے میں تیرے قانون سے کتنی محبت کرتا ہوں! یہ میرا سارا دن مراقبہ ہے۔\n98۔ تو نے اپنے احکامات کے ذریعے مجھے میرے دشمنوں سے زیادہ دانا بنایا ہے: کیونکہ وہ ہمیشہ میرے ساتھ ہیں۔ {وہ...: عبرانی۔ یہ ہمیشہ میرے ساتھ ہے}\n99۔ میں اپنے تمام اساتذہ سے زیادہ سمجھدار ہوں: کیونکہ تیری گواہی میری مراقبہ ہے۔\n100۔ میں قدیم لوگوں سے زیادہ سمجھتا ہوں، کیونکہ میں تمہارے اصولوں پر عمل کرتا ہوں۔\n101۔ میں نے ہر برائی سے اپنے قدم روکے، تاکہ میں تیرے کلام کو پورا کر سکوں۔\n102۔ میں تمہارے فیصلوں سے نہیں ہٹا، کیونکہ تو نے مجھے سکھایا ہے۔\n103۔ تمہارے الفاظ میرے ذائقے کے لیے کتنے میٹھے ہیں! {ہاں، میرے منہ میں شہد سے بھی زیادہ میٹھی}! {ذائقہ: ہیب۔ ذائقہ}\n104۔ تیری تعلیمات کے ذریعے مجھے سمجھ آتی ہے: اس لیے میں ہر غلط راستے سے نفرت کرتا ہوں۔\n105۔ نن۔ تیرا کلام میرے قدموں کے لیے چراغ ہے، اور میرے راستے کے لیے روشنی۔ {لیمپ: یا، موم بتی}\n106۔ میں نے قسم کھائی ہے، اور میں اس پر عمل کروں گا، کہ میں تمہارے راستباز فیصلے نبھاؤں گا۔\n107۔ میں بہت تکلیف میں ہوں: اے خداوند، اپنے کلام کے مطابق مجھے زندہ کر۔\n108۔ اے خداوند، میں تم سے التجا کرتا ہوں کہ میرے منہ کی آزادانہ پیشکشیں قبول کر، اور مجھے اپنے فیصلے سکھاؤ۔\n109۔ میری روح {ہمیشہ ہے} میرے ہاتھ میں: پھر بھی میں تیرے قانون کو نہیں بھولتا۔\n110۔ بدکاروں نے میرے لیے جال بچھا دیا ہے: پھر بھی میں نے تمہارے احکامات سے غلطی نہیں کی۔\n111۔ تیری گواہیوں کو میں نے ہمیشہ کے لیے وراثت کے طور پر لیا ہے: کیونکہ وہ میرے دل کی خوشی ہیں۔\n112۔ میں نے اپنے دل کو ہمیشہ تیری شریعت پوری کرنے کی طرف مائل کیا ہے، {یہاں تک} کہ آخر تک۔ {پرفارم کرنے کے لیے: عبرانی۔ کرنے کے لیے}\n113۔ سامیچ۔ میں {فضول} خیالات سے نفرت کرتا ہوں: لیکن میں تمہارے قانون سے محبت کرتا ہوں۔\n114۔ تو میری پناہ گاہ اور میری ڈھال ہو: میں تیرے کلام میں امید رکھتا ہوں۔\n115۔ اے بدکاروں کو مجھ سے دور ہو جاؤ، کیونکہ میں اپنے خدا کے احکامات کی پاسداری کروں گا۔\n116۔ اپنے کلام کے مطابق مجھے سہارا دے، تاکہ میں زندہ رہ سکوں: اور اپنی امید پر شرمندہ نہ ہوں۔\n117۔ مجھے تھامے رکھو، اور میں محفوظ رہوں گا: اور میں ہمیشہ تمہارے قوانین کا احترام کروں گا۔\n118۔ تم نے ان سب کو روند دیا ہے جو تمہارے قوانین سے غلط ہیں: کیونکہ ان کی فریب جھوٹ ہے۔\n119۔ تو زمین کے تمام برے لوگوں کو {ویسے} فضول چیز سے دور کر دیتا ہے: اسی لیے میں تمہاری گواہی سے محبت کرتا ہوں۔ {puttest...: عبرانی رکنے کی وجہ}\n120۔ میرا جسم تمہارے خوف سے کانپ رہا ہے؛ اور میں تمہارے فیصلوں سے ڈرتا ہوں۔\n121۔ عین۔ میں نے فیصلہ اور انصاف کیا ہے: مجھے ظلم کرنے والوں کے لیے نہ چھوڑو۔\n122۔ اپنے بندے کے لیے بھلائی کے لیے ضمانت بنو: مغرور مجھے ظلم نہ کرے۔\n123۔ میری آنکھیں تیری نجات اور تیری راستبازی کے کلام کے لیے بند ہو جاتی ہیں۔\n124۔ اپنے خادم کے ساتھ اپنی رحمت کے مطابق پیش آؤ، اور مجھے اپنے قوانین سکھاؤ۔\n125۔ میں تمہارا خادم ہوں؛ مجھے سمجھ دو، تاکہ میں تمہاری گواہی جان سکوں۔\n126. {اب وقت آ گیا ہے {تو} کے لیے، اے خداوند، کہ تم کام کرو: {کیونکہ} انہوں نے تیری شریعت کو منسوخ کر دیا ہے۔\n127۔ اس لیے میں تمہارے احکامات کو سونے سے زیادہ پسند کرتا ہوں؛ جی ہاں، عمدہ سونے سے اوپر۔\n128۔ اسی لیے میں تمام {تیرے} اصولوں {کے بارے میں} تمام {چیزیں} کو درست سمجھتا ہوں؛ {اور} مجھے ہر غلط طریقہ سے نفرت ہے۔\n129۔ PE۔ تمہاری گواہیاں شاندار ہیں: اسی لیے میری روح انہیں سنبھالتی ہے۔\n130۔ تیرے الفاظ کا داخلہ روشنی دیتا ہے؛ یہ سادہ چیزوں کو سمجھ بوجھ دیتا ہے۔\n131۔ میں نے منہ کھولا اور ہانپنے لگا: کیونکہ میں تمہارے احکامات کی خواہش رکھتا تھا۔\n132۔ مجھ پر نظر رکھو اور میرے ساتھ رحم کرو، جیسے تم اپنے نام سے محبت کرنے والوں کے ساتھ کرتے ہو۔ {جیسا کہ آپ...: عبرانی۔ ان کے ساتھ رواج کے مطابق، وغیرہ}\n133۔ اپنے کلام میں میرے قدموں کو ترتیب دو: اور کسی بھی گناہ کو مجھ پر حاوی نہ ہونے دو۔\n134۔ مجھے انسان کے ظلم سے نجات دے: اسی طرح میں تمہارے اصولوں کی پاسداری کروں گا۔\n135۔ اپنا چہرہ اپنے خادم پر چمکاؤ؛ اور مجھے اپنے قوانین سکھاؤ۔\n136۔ پانی کی ندیاں میری آنکھوں سے بہتی ہیں، کیونکہ وہ تمہارے قانون کی پابندی نہیں کرتے۔\n137۔ تزدی۔ اے خداوند، تو نیک ہو اور اپنے فیصلے سیدھے ہو۔\n138۔ تیری گواہی {جو} نے حکم دی ہے {وہ راستباز اور بہت وفادار ہیں}۔ {راستباز: عبرانی۔ راستبازی} {وفادار: عبرانی۔ وفاداری}\n139۔ میرا جوش مجھے نگل گیا ہے، کیونکہ میرے دشمن تیرے الفاظ بھول گئے ہیں۔ {استعمال شدہ...: عببرانی۔ مجھے کاٹ دو}\n140۔ تیرا کلام {بہت پاک} ہے: اسی لیے تیرے بندے کو یہ پسند ہے۔ {خالص: عبرانی۔ کوشش کی، یا، نفیس}\n141۔ میں چھوٹا اور حقیر ہوں: پھر بھی میں تمہارے اصولوں کو نہیں بھولتا۔\n142۔ تیری راستبازی ایک دائمی راستبازی ہے، اور تیری شریعت سچائی ہے۔\n143۔ مصیبت اور اذیت نے مجھ پر قبضہ کر لیا ہے: {پھر بھی} تیرے احکامات {ہیں} میری خوشیاں۔ {لیا گیا...: عببرانی۔ مجھے ڈھونڈ لیا}\n144۔ تیری گواہیوں کی راستبازی ہمیشہ کے لیے ہے: مجھے سمجھ دو، اور میں زندہ رہوں گا۔\n145۔ کوف۔ میں پورے دل سے روئی؛ میری بات سنو، اے خداوند: میں تیرے قوانین کی پاسداری کروں گا۔\n146۔ میں نے تم سے پکارا؛ مجھے بچاؤ، اور میں تمہاری گواہی برقرار رکھوں گا۔ {اور میں...: یا، تاکہ میں رکھ سکوں}\n147۔ میں نے صبح کے طلوع ہونے کو روکا، اور پکارا: میں تیرے کلام میں امید رکھتا تھا۔\n148۔ میری آنکھیں {رات} کی نگرانی کو روکتی ہیں، تاکہ میں تیرے کلام میں مراقبہ کر سکوں۔\n149۔ اپنی محبت کے مطابق میری آواز سنو: اے خداوند، اپنے فیصلے کے مطابق مجھے زندہ کر۔\n150۔ وہ قریب آتے ہیں جو شرارت کے بعد آتے ہیں: وہ تیرے قانون سے بہت دور ہیں۔\n151۔ اے خداوند، تو قریب ہے؛ اور تمہارے تمام احکامات سچائی ہیں۔\n152۔ تمہاری شہادتوں کے بارے میں، میں پرانا جانتا ہوں کہ تم نے انہیں ہمیشہ کے لیے قائم کیا ہے۔\n153۔ رش۔ میری مصیبت پر غور کرو اور مجھے نجات دو، کیونکہ میں تیری شریعت نہیں بھولتا۔\n154۔ میرا مقصد بیان کرو، اور مجھے نجات دو: اپنے کلام کے مطابق مجھے زندہ کرو۔\n155۔ نجات {ہے} بدکاروں سے بہت دور: کیونکہ وہ تمہارے قوانین نہیں چاہتے۔\n156۔ اے خداوند، تیری نرم رحمتیں عظیم ہیں: مجھے اپنے فیصلوں کے مطابق زندہ کر دے۔ {عظیم: یا، بہت سے}\n157۔ میرے بہت سے {ہیں} میرے ظلم کرنے والے اور میرے دشمن؛ {ابھی} میں تمہاری گواہی سے انکار نہیں کرتا۔\n158۔ میں نے مجرموں کو دیکھا اور غمگین ہوا؛ کیونکہ انہوں نے تیرے وعدے پر عمل نہیں کیا۔\n159۔ دیکھو کہ میں تیری ہدایات سے محبت کرتا ہوں: اے خداوند، اپنی محبت کے مطابق مجھے زندہ کر۔\n160۔ تیرا کلام {شروع سے} سچ ہے: اور تیرے ہر نیک فیصلے {ہمیشہ قائم رہتا ہے}۔ {تیرے کلام...: عبرانی۔ تیرے کلام کی ابتدا سچی ہے}\n161۔ سن۔ شہزادوں نے مجھے بغیر کسی وجہ کے ستایا ہے: لیکن میرا دل تیری بات پر خوفزدہ ہے۔\n162۔ میں تیرے کلام پر خوش ہوں، جیسا کہ وہ عظیم مال حاصل کرتا ہے۔\n163۔ میں جھوٹ سے نفرت اور نفرت کرتا ہوں: {لیکن} میں تمہارے قانون سے محبت کرتا ہوں۔\n164۔ میں دن میں سات بار تمہاری نیک فیصلوں کی وجہ سے تمہاری تعریف کرتا ہوں۔\n165۔ جو تیرے قانون سے محبت کرتے ہیں انہیں عظیم امن ملے، اور انہیں کچھ بھی ناراض نہیں کرے گا۔ {کچھ نہیں...: عبوری۔ انہیں کوئی رکاوٹ نہیں آئے گی}\n166۔ اے خداوند، میں نے تیری نجات کی امید کی ہے، اور تیری احکام پوری کیں۔\n167۔ میری روح نے تمہاری گواہیاں محفوظ رکھی ہیں؛ اور میں انہیں بے حد پسند کرتا ہوں۔\n168۔ میں نے تمہارے احکامات اور شہادتیں برقرار رکھی ہیں: کیونکہ میرے تمام طریقے تمہارے سامنے ہیں۔\n169۔ TAU۔ اے خداوند، میری پکار تیرے سامنے قریب آ جائے: مجھے اپنے کلام کے مطابق سمجھ دے۔\n170۔ میری دعا تمہارے سامنے آئے: اپنے کلام کے مطابق مجھے نجات د۔\n171۔ میرے ہونٹ تعریف کریں گے، جب تم نے مجھے اپنے قوانین سکھائے ہیں۔\n172۔ میری زبان تیرے کلام کی بات کرے گی: کیونکہ تیرے تمام احکامات راستبازی ہیں۔\n173۔ اپنا ہاتھ میری مدد کرے؛ کیونکہ میں نے تمہارے اصولوں کا انتخاب کیا ہے۔\n174۔ اے رب، میں تیری نجات کی خواہش رکھتا ہوں؛ اور تمہارا قانون میری خوشی ہے۔\n175۔ میری روح کو زندہ رہنے دو، اور وہ تیری تعریف کرے گی؛ اور تیری رائے میری مدد کرے۔\n176۔ میں گمراہ بھیڑ کی طرح بھٹک گیا ہوں؛ اپنے بندے کی تلاش کرو؛ کیونکہ میں تمہارے احکامات نہیں بھولتا۔","1. [اے سانگ آف ڈگریز۔] اپنی تکلیف میں میں نے خداوند سے پکارا، اور اس نے مجھے سن لیا۔\n2. اے خداوند، میری جان کو جھوٹے ہونٹوں سے بچا، {اور} دھوکہ باز زبان سے۔\n3۔ تمہیں کیا دیا جائے گا؟ یا تمہارے ساتھ کیا کیا جائے گا، اے جھوٹی زبان؟ {کیا دیا جائے گا...: یا، دھوکہ باز زبان تمہیں کیا دے گی؟ یا، تمہیں کیا فائدہ ہوگا؟} {مکمل: عبرانی۔ شامل کیا گیا}\n4۔ طاقتور کے تیز تیر، جن میں جونیپر کے کوئلے تھے۔ {تیز...: یا، یہ طاقتور آدمی کے تیز تیر کی طرح ہے، جن میں جونیپر کے انگارے ہیں}\n5. افسوس کہ میں میسک میں ٹھہرا ہوں، {کہ} میں کیدار کے خیموں میں رہتا ہوں!\n6۔ میری روح طویل عرصے سے اس کے ساتھ رہی ہے جو امن سے نفرت کرتا ہے۔\n7. میں امن کے حق میں ہوں: لیکن جب میں بولتا ہوں، تو وہ جنگ کے حق میں ہیں۔ {امن کے لیے: یا، امن کا آدمی}","1. [اے سانگ آف ڈگریز۔] میں اپنی آنکھیں پہاڑوں کی طرف اٹھاؤں گا، جہاں سے میری مدد آئے گی۔ {میں کروں گا...: یا، کیا میں اپنی آنکھیں پہاڑوں کی طرف اٹھاؤں؟ میری مدد کہاں سے آئے گی؟}\n2۔ میری مدد {آتی ہے} خداوند کی طرف سے، جس نے آسمان اور زمین بنایا۔\n3۔ وہ تمہارے پاؤں کو حرکت میں نہیں آنے دے گا: جو تمہیں سنبھالے گا وہ نیند میں نہیں جائے گا۔\n4۔ دیکھو، جو اسرائیل کی حفاظت کرتا ہے وہ نہ سوتا ہے نہ سوتا۔\n5۔ خداوند تمہارا محافظ ہے: خداوند تمہارا سایہ تیرے دائیں ہاتھ پر ہے۔\n6۔ سورج دن میں تمہیں نہیں مارے گا، نہ رات کو چاند۔\n7۔ خداوند تمہیں ہر برائی سے بچائے گا: وہ تیری جان کی حفاظت کرے گا۔\n8۔ خداوند تمہارے جانے اور تمہارے آنے کو اس وقت سے اور ہمیشہ کے لیے محفوظ رکھے گا۔","1. [اے سیت آف ڈگریز آف ڈیوڈ۔] مجھے خوشی ہوئی جب انہوں نے مجھ سے کہا، آؤ خداوند کے گھر میں چلیں۔\n2. اے یروشلم، ہمارے قدم تیرے دروازوں کے اندر کھڑے ہوں گے۔\n3۔ یروشلم ایک ایسے شہر کے طور پر تعمیر کیا گیا ہے جو ایک ساتھ مضبوط ہے:\n4۔ جہاں قبائل اوپر جاتے ہیں، خداوند کے قبائل، اسرائیل کی گواہی کے لیے، خداوند کے نام کا شکر ادا کرنے کے لیے۔\n5۔ کیونکہ فیصلے کے تخت مقرر ہیں، جو داؤد کے گھرانے کے تخت ہیں۔ {آر...: عبرانی بیٹھو}\n6۔ یروشلم کے امن کے لیے دعا کرو: وہ لوگ جو تم سے محبت کرتے ہیں، وہ کامیاب ہوں گے۔\n7۔ تمہاری دیواروں میں امن ہو، اور تمہارے محلات میں خوشحالی ہو۔\n8۔ اپنے بھائیوں اور ساتھیوں کی خاطر، میں اب کہوں گا، تیرے اندر امن ہو۔\n9. خداوند ہمارے خدا کے گھر کی وجہ سے میں تیری بھلائی تلاش کروں گا۔","1. [اے سانگ آف ڈگریز۔] میں اپنی آنکھیں تیرے طرف اٹھا دیتا ہوں، اے آسمانوں میں بسنے والے۔\n2. دیکھو، جیسے خادموں کی آنکھیں اپنے مالکان کے ہاتھ کو دیکھتی ہیں، {اور} جیسے ایک دوشیزہ کی آنکھیں اپنی مالکن کے ہاتھ پر دیکھتی ہیں؛ تو ہماری آنکھیں خداوند ہمارے خدا پر {انتظار کریں}، جب تک کہ وہ ہم پر رحم نہ کرے۔\n3. اے خداوند، ہم پر رحم فرما، ہم پر رحم فرما: کیونکہ ہم بے حد حقارت سے بھرے ہوئے ہیں۔\n4۔ ہماری روح ان لوگوں کی حقارت سے بھری ہوئی ہے جو آرام دہ ہیں، {اور} مغرور لوگوں کی حقارت سے۔","1. [اے سیت آف ڈگریز آف ڈیوڈ۔] اگر وہ خداوند نہ ہوتا جو ہمارے ساتھ ہوتا، تو اب اسرائیل کہے؛\n2. اگر {یہ خداوند} نہ ہوتا جو ہمارے ساتھ تھا، جب لوگ ہمارے خلاف اٹھے:\n3۔ پھر انہوں نے ہمیں جلدی نگل لیا، جب ان کا غصہ ہم پر بھڑک اٹھا:\n4۔ پھر پانی نے ہمیں ڈھانپ لیا، ندی ہماری روح پر چھا گئی:\n5۔ پھر فخر کا پانی ہماری روح پر چھا گیا۔\n6۔ مبارک ہو خداوند کو، جس نے ہمیں ان کے دانتوں کا شکار نہیں دیا۔\n7. ہماری روح پرندے کی طرح فاولرز کے جال سے نکل جاتی ہے: جال ٹوٹ جاتا ہے، اور ہم فرار ہو جاتے ہیں۔\n8۔ ہماری مدد {ہے} خداوند کے نام پر، جس نے آسمان اور زمین بنائی۔","1. [اے سانگ آف ڈگریز۔] جو لوگ خداوند پر بھروسہ کرتے ہیں {وہ صیون پہاڑ کی طرح ہوں گے}، {جو} کو ہٹایا نہیں جا سکتا، {لیکن} ہمیشہ قائم رہیں گے۔\n2. جیسے یروشلم کے گرد پہاڑ ہیں، ویسے ہی خداوند {ہے} اپنے لوگوں کے گرد ہمیشہ کے لیے۔\n3۔ کیونکہ بدکاروں کی چھڑی نیکوں کی قسمت پر نہیں رکھی گی؛ تاکہ نیک لوگ بدکاری کی طرف نہ اٹھائیں۔ {بدکار: عبرانی۔ برائی}\n4. اے خداوند، ان کے لیے بھلائی کر، اور ان کے لیے جو اپنے دلوں میں سیدھے ہیں۔\n5۔ جو لوگ اپنی راہ سے مڑ جائیں گے، خداوند انہیں بدکاروں کے ساتھ لے جائے گا: {لیکن} اسرائیل پر سلامتی ہو۔","1. [اے سانگ آف ڈگریز۔] جب خداوند نے دوبارہ صیون کی قید کو پلٹا، ہم بھی ان کی طرح تھے جو خواب دیکھتا ہے۔ {مڑا...: عبوری۔ واپس آ گیا}\n2۔ پھر ہمارا منہ ہنسی سے بھر گیا، اور ہماری زبان گانے سے بھر گئی: تو انہوں نے کافروں میں کہا، خداوند نے ان کے لیے عظیم کام کیے ہیں۔ {hath...: عبرانی۔ ان کے ساتھ بڑا کر دیا گیا ہے}\n3۔ خداوند نے ہمارے لیے عظیم کام کیے ہیں؛ {جس پر} ہم خوش ہیں۔\n4. اے خداوند، ہماری قید کو دوبارہ موڑ دو، جیسے جنوب میں ندی نالیں۔\n5۔ جو آنسوؤں میں بوتے ہیں وہ خوشی سے کاٹیں گے۔ {جوی: یا، گانا}\n6۔ جو قیمتی بیج لے کر باہر نکلے گا اور روئے گا، وہ یقینا خوشی کے ساتھ واپس آئے گا، اپنے گتھے لے کر آئے گا۔ {قیمتی...: یا، بیج کی ٹوکری}","1. [سلیمان کے لیے ڈگریوں کا گیت۔] سوائے اس کے کہ خداوند نے گھر بنایا، وہ بے سود محنت کرتے ہیں جو اسے بناتے ہیں: جب تک خداوند شہر کو سنبھالے، پہرہ دار جاگتا ہے {لیکن} بے سود۔ {for...: یا، سلیمان کا} {وہ...: عببرانی۔ جو اس میں اسے بنانے والے ہیں}\n2. یہ بے سود ہے کہ تم جلدی اٹھو، دیر تک جاگنا، غم کی روٹی کھانا: کیونکہ وہ اپنی محبوبہ کو نیند دیتا ہے۔\n3. دیکھو، بچے خداوند کی وراثت ہیں: اور رحم کا پھل اس کا اجر ہے۔\n4۔ جیسے تیر ایک طاقتور انسان کے ہاتھ میں ہوں؛ اسی طرح نوجوانوں کے بچے بھی ہیں۔\n5. خوش باش وہ آدمی ہے جس کے پاس ان سے بھرا ہوا ہے: وہ شرمندہ نہیں ہوں گے، بلکہ دروازے پر دشمنوں سے بات کریں گے۔ {اس کا...: عبرانی اپنے کوئور کو ان سے بھر دیا} {بولو...: یا، زیر کرو، یا، تباہ کرو}","1. [اے سانگ آف ڈگریز۔] مبارک ہر وہ شخص ہے جو خداوند سے ڈرتا ہے؛ جو اس کے راستے پر چلتا ہے۔\n2۔ کیونکہ تم اپنے ہاتھوں کی محنت کھاؤ گے: خوش رہو {رہو گے}، اور {یہ تمہارے لیے اچھا ہوگا}۔\n3۔ تمہاری بیوی تمہارے گھر کے کنارے ایک پھلدار بیل کی طرح ہوگی: تمہارے بچے زیتون کے پودوں کی طرح تمہارے دسترخوان کے گرد ہوں گے۔\n4۔ دیکھو، اس طرح خداوند سے ڈرنے والا انسان بابرکت ہوگا۔\n5۔ خداوند تمہیں صیون سے برکت دے گا: اور تم اپنی زندگی کے تمام دنوں یروشلم کی بھلائی دیکھو گے۔\n6. ہاں، تو اپنے بچوں کے بچوں کو دیکھو گے، {اور} اسرائیل پر سلام۔","1. [اے سانگ آف ڈگریز۔] انہوں نے مجھے بچپن سے کئی بار ستایا، اب اسرائیل کہے: {بہت...: یا، بہت زیادہ}\n2۔ انہوں نے مجھے بچپن سے کئی بار پریشان کیا ہے، پھر بھی وہ مجھ پر غالب نہیں آ سکے۔ {بہت سے...: یا، بہت زیادہ}\n3۔ ہل چلانے والوں نے میری پیٹھ پر ہل چلایا: انہوں نے لمبی شکنیں بنا لیں۔\n4۔ خداوند راستباز ہے: اس نے بدکاروں کی رسی کاٹ دی ہے۔\n5. ان سب کو جو صہیون سے نفرت کرتے ہیں، حیران کر دیں اور واپس پلٹ جائیں۔\n6. انہیں گھروں کی چھتوں پر گھاس کی طرح رکھیں، جو اگنے سے پہلے مرجھا جاتی ہے:\n7۔ جس سے گھاس کاٹنے والا اپنا ہاتھ نہیں بھرتا؛ نہ ہی وہ جو باندھتا ہے، اس کا سینہ باندھتا ہے۔\n8۔ نہ ہی جو لوگ گزرتے ہیں وہ کہتے ہیں، خداوند کی برکت تم پر ہو: ہم تمہیں خداوند کے نام پر برکت دیتے ہیں۔","1. [اے سانگ آف ڈگریز۔] اے خداوند، میں نے گہرائیوں سے تجھ سے پکارا ہے۔\n2۔ اے خداوند، میری آواز سن: تیرا کان میری دعاؤں کی آواز سنے۔\n3. اے خداوند، اگر تو، اے خداوند، گناہوں کو نشان زد کرے، تو کون کھڑا ہوگا؟\n4. لیکن تمہارے ساتھ معافی ہے، تاکہ تم سے خوف آ سکے۔\n5۔ میں خداوند کا انتظار کرتا ہوں، میری روح انتظار کرتی ہے، اور اس کے کلام میں امید کرتا ہوں۔\n6. میری جان خداوند کے لیے ان سب سے زیادہ انتظار کرتی ہے جو صبح کا انتظار کرتے ہیں: {میں کہتا ہوں، ان سے زیادہ} جو صبح کا انتظار کرتے ہیں۔ {میں کہتا ہوں...: یا، جو دیکھ رہا ہے}\n7۔ اسرائیل خداوند میں امید رکھے: کیونکہ خداوند کے ساتھ رحمت ہے، اور اس کے ساتھ فراوان نجات ہے۔\n8۔ اور وہ اسرائیل کو اپنی تمام گناہوں سے نجات دے گا۔","1. [اے سیت آف ڈگریز آف ڈیوڈ۔] اے خداوند، میرا دل مغرور نہیں، میری آنکھیں بلند نہیں؛ نہ ہی میں بڑے کاموں میں خود کو استعمال کرتا ہوں، نہ ہی اپنے لیے بہت اونچی چیزوں میں۔ {ورزش...: عبرانی چلو} {اونچا: عبرانی شاندار}\n2. یقینا میں نے ایک بچے کی طرح جو اپنی ماں سے دودھ چھڑاتا ہے اور خود کو خاموش کیا ہے: میری روح {ہے} یہاں تک کہ ایک دودھ چھڑانے والے بچے کی طرح۔ {میں خود: عبرانی۔ میری روح}\n3۔ اسرائیل آئندہ سے اور ہمیشہ کے لیے خداوند میں امید رکھے۔ {آئندہ: عبرانی۔ اب}","1. ڈگریوں کا گیت۔ اے خداوند، داؤد کو یاد رکھ، {اور} اس کی تمام مصیبتوں کو:\n2. کیسے اس نے خداوند سے قسم کھائی، {اور} یعقوب کے عظیم {خدا} سے عہد کیا؛\n3. یقینا میں اپنے گھر کے خیمے میں نہیں آؤں گا، نہ ہی اپنے بستر میں جاؤں گا؛\n4. میں اپنی آنکھوں کو نیند نہیں دوں گا، {یا} اپنی پلکوں کو نیند نہیں دوں گا،\n5. جب تک میں خداوند کے لیے جگہ نہ ڈھونڈ لوں، یعقوب کے عظیم {خدا} کے لیے ایک رہائش گاہ۔ {ایک آبادی: عبرانی۔ رہائش گاہیں\n6۔ دیکھو، ہم نے ایفراتا میں اس کے بارے میں سنا: ہم نے اسے جنگل کے کھیتوں میں پایا۔\n7۔ ہم اس کے خیمے میں جائیں گے: اس کے پاؤں کے اسٹول پر عبادت کریں گے۔\n8. اے خداوند، اپنے آرام میں اٹھو؛ تو، اور تیری طاقت کا صندوق۔\n9۔ تمہارے پادری راستبازی میں ملبوس ہوں؛ اور تمہارے مقدسین خوشی سے پکاریں۔\n10۔ اپنے خادم داؤد کی خاطر، اپنے مسح شدہ چہرے کو نہ موڑنا۔\n11۔ خداوند نے داؤد سے سچائی کی قسم کھائی ہے؛ وہ اس سے منہ نہیں موڑے گا؛ تیرے جسم کے پھل سے میں تیرے تخت پر رکھوں گا۔ {جسم: عبوری۔ پیٹ}\n12۔ اگر تمہارے بچے میرا عہد اور میری گواہی کو پورا کریں گے جو میں انہیں سکھاؤں گا، تو ان کے بچے بھی ہمیشہ کے لیے تیرے تخت پر بیٹھے رہیں گے۔\n13۔ کیونکہ خداوند نے صیون کو چنا ہے؛ اس نے اپنی رہائش کے لیے اس کی خواہش کی ہے۔\n14. یہ میرا ہمیشہ کے لیے آرام ہے: یہاں میں رہوں گا؛ کیونکہ میں نے اسے چاہا ہے۔\n15. میں اس کی فراوانی سے رزق دوں گا: میں اس کے غریبوں کو روٹی سے مطمئن کروں گا۔ {بہت زیادہ: یا، یقینا}\n16. میں اس کے پادریوں کو نجات سے بھی ملبوس کروں گا: اور اس کے مقدس خوشی کے لیے بلند آواز میں پکاریں گے۔\n17۔ وہاں میں داؤد کے سینگ کو نوک دوں گا: میں نے اپنے لیے ایک چراغ مسح شدہ مقرر کیا ہے۔ {لیمپ: یا، موم بتی}\n18۔ اس کے دشمنوں کو میں شرم سے پہناؤں گا: لیکن اس کا تاج اس پر پھلے گا۔","1. [اے سیت آف ڈگریز آف ڈیوڈ۔] دیکھو، بھائیوں کے لیے اتحاد میں رہنا کتنا اچھا اور خوشگوار ہے! {اکٹھے...: عبرانی۔ یہاں تک کہ ساتھ بھی}\n2. {یہ} اس قیمتی مرہم کی طرح ہے جو سر پر بہہ رہا تھا، جو داڑھی پر بہتا تھا، {حتیٰ کہ} ہارون کی داڑھی پر بھی: جو اس کے لباس کے کناروں تک جاتا تھا؛\n3۔ جیسے حرمون کی شبنم، {اور شبنم کی طرح} جو صیہون کے پہاڑوں پر نازل ہوئی: کیونکہ وہاں خداوند نے برکت کا حکم دیا، {حتیٰ کہ} زندگی ہمیشہ کے لیے۔","1. [اے سانگ آف ڈگریز۔] دیکھو، خداوند کو برکت دو، اے خداوند کے تمام بندوں کو، جو رات کو خداوند کے گھر میں کھڑے ہیں۔\n2. اپنے ہاتھ مقدس مقام میں اٹھاؤ، اور خداوند کو برکت دو۔ {مقدس مقام: یا، پاکیزگی}\n3۔ وہ خداوند جس نے آسمان اور زمین بنائے، صیون سے تمہیں برکت دے۔","1. خداوند کی تعریف کرو۔ خداوند کے نام کی تعریف کرو؛ اس کی تعریف کرو، اے خداوند کے بندوں۔\n2۔ وہ لوگ جو خداوند کے گھر میں کھڑے ہیں، ہمارے خدا کے گھر کے صحنوں میں،\n3۔ خداوند کی حمد کرو؛ کیونکہ خداوند {ہے} بھلا: اس کے نام کی حمد گاؤ؛ کیونکہ {یہ} خوشگوار ہے۔\n4۔ کیونکہ خداوند نے یعقوب کو اپنے لیے چنا ہے، {اور} اسرائیل کو اس کے منفرد خزانے کے لیے۔\n5۔ کیونکہ میں جانتا ہوں کہ خداوند {عظیم} ہے، اور {کہ} ہمارا رب {ہے} تمام دیوتاؤں سے بالاتر۔\n6۔ جو کچھ خداوند نے چاہا، {وہ} نے آسمان، زمین، سمندروں اور تمام گہرے مقامات پر کیا۔\n7۔ وہ زمین کے کناروں سے بخارات کو اوپر اٹھاتا ہے؛ وہ بارش کے لیے بجلی بناتا ہے؛ وہ اپنے خزانے سے ہوا نکالتا ہے۔\n8۔ جس نے مصر کے پہلے بچے کو، انسان اور جانور دونوں کو، مارا۔ {دونوں...: عبرانی۔ انسان سے درندے تک}\n9۔ {جس نے} اے مصر، فرعون اور اس کے تمام بندوں پر تیرے بیچ میں نشانیاں اور عجائبات بھیجے۔\n10۔ جس نے عظیم قوموں کو شکست دی، اور طاقتور بادشاہوں کو قتل کیا؛\n11۔ اموری کے بادشاہ سیہون، باشان کا بادشاہ اوگ، اور کنعان کی تمام سلطنتیں:\n12. اور انہوں نے اپنی زمین {لیے} وراثت دی، ایک وراثت جو اسرائیل کو اس کی قوم کے لیے تھی۔\n13. اے خداوند، تیرا نام {ہمیشہ قائم رہو}؛ {اور} تیرے یادگار، اے خداوند، تمام نسلوں کے لیے۔ {پورے وقت...: عبرانی۔ نسل اور نسل کے لیے}\n14۔ کیونکہ خداوند اپنے لوگوں کا فیصلہ کرے گا، اور وہ اپنے بندوں کے بارے میں توبہ کرے گا۔\n15۔ کافروں کے بت چاندی اور سونا ہیں، جو انسانوں کے ہاتھوں کا کام ہیں۔\n16۔ ان کے منہ ہوتے ہیں، لیکن وہ بات نہیں کرتے؛ آنکھیں ہیں، لیکن وہ نہیں دیکھتیں؛\n17۔ ان کے کان ہیں، لیکن وہ سنتے نہیں؛ نہ ہی ان کے منہ میں کوئی سانس آتی ہے۔\n18۔ جو انہیں بناتے ہیں وہ ان جیسے ہیں: {ویسے} ہر وہ شخص جو ان پر بھروسہ کرتا ہے۔\n19۔ اے اسرائیل کے گھرانے خداوند کو برکت دے: اے ہارون خاندان خداوند کو برکت دے:\n20. اے لاوی خاندان خداوند کو برکت دے: جو خدا سے ڈرتے ہیں، خداوند کو برکت دے۔\n21. خداوند صیون سے بابرکت ہو، جو یروشلم میں بستا ہے۔ خداوند کی تعریف ہو۔","1۔ خداوند کا شکر ادا کرو؛ کیونکہ {وہ} اچھا ہے: اس کی رحمت {ہمیشہ قائم رہے گی}۔\n2. خداوں کے خدا کا شکر ادا کرو: اس کی رحمت {ہمیشہ قائم رہے}۔\n3۔ خداوند کا شکر ادا کرو: اس کی رحمت {ہمیشہ قائم رہے}۔\n4۔ اس کے لیے جو اکیلا عظیم عجائبات کرتا ہے: کیونکہ اس کی رحمت ہمیشہ قائم رہتی ہے۔\n5۔ اس کے لیے جس نے حکمت سے آسمان بنائے: کیونکہ اس کی رحمت ہمیشہ قائم رہتی ہے۔\n6۔ اس کے لیے جس نے زمین کو پانیوں کے اوپر پھیلایا: اس کی رحمت {ہمیشہ قائم رہے}۔\n7۔ اس کے لیے جس نے عظیم روشنیاں بنائیں: اس کی رحمت {ہمیشہ قائم رہے}:\n8۔ سورج دن میں حکمرانی کرے گا: اس کی رحمت {ہمیشہ قائم رہے گی}: {حکمرانی...: عبرانی۔ دن کے لحاظ سے فیصلوں کے لیے}\n9۔ چاند اور ستارے رات کے وقت حکومت کریں گے: کیونکہ اس کی رحمت ہمیشہ قائم رہے گی۔\n10۔ اس کے لیے جس نے مصر کو ان کے پہلے بیٹے میں مارا: اس کی رحمت {ہمیشہ قائم ہے}:\n11۔ اور اسرائیل کو ان میں سے نکالا: اس کی رحمت {ہمیشہ قائم رہے گی}:\n12۔ مضبوط ہاتھ سے، اور پھیلائے ہوئے بازو سے: اس کی رحمت {ہمیشہ قائم رہے گی}۔\n13۔ اس کے لیے جس نے بحیرہ احمر کو حصوں میں تقسیم کیا: اس کی رحمت {ہمیشہ قائم ہے}:\n14۔ اور اسرائیل کو اس کے بیچ سے گزرنے پر مجبور کیا: کیونکہ اس کی رحمت ہمیشہ قائم رہے گی:\n15۔ لیکن اس نے فرعون اور اس کے لشکر کو بحر احمر میں شکست دی: کیونکہ اس کی رحمت ہمیشہ قائم رہے گی۔ {الٹا: عبرانی۔ جھٹک گیا}\n16۔ اس کے لیے جس نے اپنی قوم کو بیابان میں لے جایا: کیونکہ اس کی رحمت ہمیشہ قائم رہے گی۔\n17۔ اس کے لیے جس نے عظیم بادشاہوں کو مارا: اس کی رحمت {ہمیشہ قائم رہے}:\n18۔ اور مشہور بادشاہوں کو قتل کیا: اس کی رحمت {ہمیشہ قائم رہے گی}:\n19۔ اموریوں کے بادشاہ سیہون: اس کی رحمت {ہمیشہ کے لیے} کے لیے:\n20. اور اوگ، باشان کا بادشاہ: اس کی رحمت کے لیے {ہمیشہ قائم ہے}:\n21۔ اور انہوں نے اپنی زمین وراثت کے طور پر دی: اس کی رحمت {ہمیشہ قائم رہے} کے لیے:\n22. {حتیٰ کہ} اسرائیل کے لیے ایک وراثت، اس کا بندہ: اس کی رحمت {ہمیشہ قائم رہے گی}۔\n23۔ جس نے ہمیں ہماری پست حیثیت میں یاد کیا: اس کی رحمت {ہمیشہ قائم ہے}:\n24۔ اور اس نے ہمیں ہمارے دشمنوں سے نجات دی: کیونکہ اس کی رحمت ہمیشہ قائم رہے گی۔\n25. جو ہر جسم کو خوراک دیتا ہے: اس کی رحمت {ہمیشہ قائم ہے}۔\n26. آسمان کے خدا کا شکر ادا کرو: اس کی رحمت {ہمیشہ قائم رہے}۔","1۔ بابل کی ندیوں کے کنارے، ہم وہاں بیٹھے تھے، ہاں، ہم روئے، جب ہم نے صیون کو یاد کیا۔\n2. ہم نے ان کے درمیان بید کے درختوں پر اپنی ہارپ لٹکا دی۔\n3۔ کیونکہ وہیں جنہوں نے ہمیں قید میں لے جایا، انہوں نے ہم سے ایک گیت طلب کی؛ اور جنہوں نے ہمیں ضائع کیا {انہوں نے ہم سے خوشی کا مطالبہ کیا}، {کہا}، ہمیں صیون کے گیتوں میں سے {ایک} گائیں۔ {ایک گانا: عبرانی۔ ایک گانے کے الفاظ} {ضائع ہو چکا ہے...: عبرانی۔ ہمیں بہت زیادہ گرا دیا}\n4. ہم اجنبی زمین میں خداوند کا گیت کیسے گائیں گے؟ {عجیب...: عبرانی۔ ایک اجنبی کی زمین؟}\n5. اگر میں تمہیں بھول جاؤں، اے یروشلم، تو میرا دایاں ہاتھ {اس کی چالاکی} کو بھول جائے۔\n6۔ اگر میں تمہیں یاد نہ کروں، تو میری زبان میرے منہ کی چھت سے چپک جائے؛ اگر میں اپنی خوشی پر یروشلم کو ترجیح دوں۔ {میرا چیف...: عببرانی۔ میری خوشی کا سر}\n7. اے خداوند، یروشلم کے زمانے میں ادوم کے بچوں کو یاد رکھنا؛ جس نے کہا، اس کی بنیاد تک پھینک دو۔ {اسے جھاڑو: عبوری۔ ننگا ہو جاؤ}\n8۔ اے بابل کی بیٹی، جو تباہ ہونے والی ہے؛ خوش نصیب {کیا وہ ہوگا}، جو تمہیں ویسا ہی انعام دیتا ہے جیسا تم نے ہماری خدمت کی۔ {تباہ شدہ: عبرانی۔ ضائع ہو گیا} {rewardeth...: عبرانی تمہیں تمہارے کیے گئے کام کا بدلہ دوں گا}\n9۔ خوش نصیب {کیا وہ ہوگا}، جو تمہارے چھوٹے بچوں کو پتھروں کے خلاف لے کر تباہ کرتا ہے۔ {دی اسٹونز: عبرانی۔ دی راک}","1. [{داؤد کا زبور}] میں پورے دل سے تمہاری حمد کروں گا: دیوتاؤں کے سامنے تمہاری حمد گاؤں گا۔\n2۔ میں تیرے مقدس مندر کی طرف عبادت کروں گا، اور تیری محبت اور سچائی کے لیے تیرا نام سراہوں گا: کیونکہ تو نے اپنے کلام کو اپنے نام سے بلند کیا ہے۔\n3۔ جس دن میں نے رویا تو نے مجھے جواب دیا، {اور} میری روح میں طاقت سے مجھے مضبوط کیا۔\n4. اے خداوند، زمین کے تمام بادشاہ تیری تعریف کریں گے، اے خداوند، جب وہ تیرے منہ کی باتیں سنیں گے۔\n5۔ ہاں، وہ خداوند کے راستوں میں گائیں گے: کیونکہ خداوند کی عظمت عظیم ہے۔\n6۔ اگرچہ خداوند بلند ہے، پھر بھی وہ نچلے لوگوں کی عزت کرتا ہے: لیکن مغرور کو وہ دور سے جانتا ہے۔\n7۔ چاہے میں مصیبت میں چلوں، تم مجھے زندہ کرو گے: تم میرے دشمنوں کے غضب کے خلاف اپنا ہاتھ بڑھاؤ گے، اور تمہارا دایاں ہاتھ مجھے بچا لے گا۔\n8. خداوند میرے تعلق کو مکمل کرے گا: تیری رحمت، اے خداوند، ہمیشہ کے لیے قائم رہے: اپنے ہاتھوں کے اعمال کو ترک نہ کرنا۔","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے خداوند، تو نے مجھے تلاش کیا اور مجھے جان لیا۔\n2۔ تم میری نشست اور میری بغاوت کو جانتے ہو، تم میرے خیالات کو دور سے سمجھتے ہو۔\n3۔ تو میرے راستے اور میرے لیٹے ہوئے راستے کو گھیر لیتے ہو، اور میرے تمام راستوں سے واقف ہو۔ {کمپاسیسٹ: یا، وینوویسٹ}\n4۔ کیونکہ {میرے زبان میں} کوئی لفظ نہیں، {لیکن}، اے خداوند، تو اسے مکمل طور پر جانتا ہے۔\n5۔ تم نے مجھے پیچھے اور پہلے گھیر لیا اور اپنا ہاتھ مجھ پر رکھا۔\n6. {ایسا عہد} میرے لیے بہت حیرت انگیز ہے؛ یہ بلند ہے، میں اسے حاصل نہیں کر سکتا۔\n7۔ میں تمہاری روح سے کہاں جاؤں؟ یا میں تمہاری موجودگی سے کہاں بھاگوں؟\n8. اگر میں جنت میں چڑھوں، تو تم وہاں ہو: اگر میں اپنا بستر جہنم میں بناؤں، دیکھو، تم {وہاں ہو}۔\n9. {اگر} میں صبح کے پر لے لوں، {اور} سمندر کے دور دراز حصوں میں رہوں؛\n10۔ وہاں تیرا ہاتھ مجھے لے جائے گا، اور تمہارا دایاں ہاتھ مجھے تھامے گا۔\n11۔ اگر میں کہوں، یقینا اندھیرا مجھے ڈھانپے گا؛ رات بھی میرے گرد ہلکی ہوگی۔\n12۔ ہاں، تاریکی تم سے نہیں چھپتی؛ لیکن رات دن کی طرح چمکتی ہے: تاریکی اور روشنی دونوں ایک جیسے ہیں {تمہارے لیے}۔ {چھپ کر...: عبرانی۔ اندھیرا نہیں کرتا} {تاریکی اور...: عبرانی جیسے اندھیرا ہے، ویسے ہی روشنی بھی ہے}\n13۔ کیونکہ تم نے میری لگام اپنے قبضے میں رکھی ہے: تو نے مجھے میری ماں کے پیٹ میں ڈھانپ لیا ہے۔\n14. میں تمہاری تعریف کروں گا؛ کیونکہ میں خوفزدہ ہو کر {اور} حیرت انگیز طور پر بنایا گیا ہوں: تمہارے اعمال حیرت انگیز ہیں؛ اور {یہ} میری روح اچھی طرح جانتی ہے۔ {دائیں...: عبوری۔ بہت زیادہ}\n15. میرا وجود تم سے چھپایا نہیں گیا، جب مجھے خفیہ طور پر بنایا گیا، {اور} زمین کے نچلے حصے میں عجیب طریقے سے تخلیق کیا گیا۔ {مادہ: یا، طاقت، یا، جسم}\n16۔ تیری آنکھوں نے میرا وجود دیکھا، لیکن وہ کامل نہیں تھا؛ اور تیری کتاب میں تمام {میرے ارکان} لکھے گئے، {جو} مسلسل تشکیل دیے گئے، جبکہ {ابھی تک} ان میں سے کوئی نہیں تھا۔ {سب...: عبرانی۔ سب کچھ} {کون سے...: یا، کن دنوں میں انہیں بنانا چاہیے}\n17. اے خدا، تیرے خیالات میرے لیے کتنے قیمتی ہیں! ان کا مجموعہ کتنا عظیم ہے!\n18۔ {اگر} میں انہیں گنوں، تو وہ ریت سے بھی زیادہ ہیں: جب میں جاگتا ہوں، تو میں اب بھی تیرے ساتھ ہوتا ہوں۔\n19. یقینا تم بدکاروں کو قتل کرو گے، اے خدا: اس لیے مجھ سے دور ہو جاؤ، اے خونخوار لوگو۔\n20۔ کیونکہ وہ تمہارے خلاف برا بولتے ہیں، {اور} تمہارے دشمن {تمہارا نام} بے فائدہ لیتے ہیں۔\n21. اے خداوند، کیا میں ان سے نفرت نہیں کرتا جو تجھ سے نفرت کرتے ہیں؟ اور کیا میں ان لوگوں سے غمگین نہیں ہوں جو تمہارے خلاف اٹھتے ہیں؟\n22۔ میں انہیں مکمل نفرت سے نفرت کرتا ہوں: میں انہیں اپنے دشمن سمجھتا ہوں۔\n23. اے خدا، مجھے تلاش کر، اور میرے دل کو جان: مجھے آزما، اور میرے خیالات کو جان:\n24۔ اور دیکھو کہ کیا مجھ میں کوئی برا راستہ ہے، اور مجھے ہمیشہ کے لیے راستہ دکھا۔ {شرارتی...: عبرانی۔ درد کا طریقہ، یا، غم}","1. [چیف موسیقار، اے زبور آف ڈیوڈ کے نام۔] اے خداوند، مجھے برے انسان سے بچا: مجھے ظالم آدمی سے بچا؛ {پرتشدد...: عبرانی۔ تشدد کا آدمی}\n2۔ جو اپنے دل میں شرارتوں کا تصور کرتے ہیں؛ وہ مسلسل جنگ کے لیے اکٹھے ہوتے ہیں۔\n3۔ انہوں نے اپنی زبانیں سانپ کی طرح تیز کر دی ہیں؛ ایڈرز کا زہر ان کے ہونٹوں کے نیچے ہے۔ سیلہ۔\n4. اے خداوند، مجھے بدکاروں کے ہاتھوں سے بچا؛ مجھے پرتشدد آدمی سے بچاؤ؛ جو میرے معاملات کو الٹنے کا ارادہ رکھتے ہیں۔\n5۔ مغرور لوگوں نے میرے لیے ایک جال اور رسیاں چھپا دی ہیں؛ انہوں نے ایک جال سڑک کے کنارے بچھا دیا ہے؛ انہوں نے میرے لیے جن سیٹ کیے ہیں۔ سیلہ۔\n6۔ میں نے خداوند سے کہا، تو میرے خدا ہو: اے خداوند، میری دعاؤں کی آواز سن۔\n7. اے خداوند، میری نجات کی طاقت سے، تو نے جنگ کے دن میرا سر ڈھانپ لیا۔\n8. اے خداوند، بدکاروں کی خواہشات نہ مانگے: اس کے برے طریقے کو مزید نہ مانو؛ {ورنہ وہ خود کو بلند کر دیں۔' سیلہ۔ {ورنہ ...: یا، انہیں بلند نہ کیا جائے}\n9. {جہاں تک} ان لوگوں کے سر کا تعلق ہے جو میرے گرد ہیں، ان کے اپنے ہونٹوں کی شرارت ان پر چھا جائے۔\n10۔ جلتے ہوئے کوئلے ان پر گرے: انہیں آگ میں پھینک دیا جائے؛ گہرے گڑھوں میں، تاکہ وہ دوبارہ اٹھ نہ سکیں۔\n11۔ زمین پر کوئی برا بولنے والا قائم نہ ہو: برائی ظالم آدمی کا شکار کرے گی تاکہ اسے گرا سکے۔ {an...: یا، ایک برے بولنے والا (عبرانی۔ ایک زبان والا آدمی)، ایک ظالم آدمی، زمین پر قائم ہو: اسے شکار کر کے اس کے تختہ الٹنے کا شکار کیا جائے}\n12. میں جانتا ہوں کہ خداوند مصیبت زدہ لوگوں کے حق اور غریبوں کے حق کی حفاظت کرے گا۔\n13۔ یقینا نیک لوگ تیرے نام کا شکر ادا کریں گے: نیک لوگ تیرے حضور میں رہیں گے۔","1. [داؤد کا زبور۔] اے خداوند، میں تجھ سے پکارتا ہوں: جلدی کرو؛ جب میں تمہیں پکارتا ہوں تو میری آواز سنو۔\n2. میری دعا تمہارے سامنے پیش کی جائے {بغیر} کی طرح؛ {اور} میرے ہاتھوں کو اٹھانا {شام کی قربانی کے طور پر۔ {سیٹ...: عبوری۔ ہدایتکار}\n3. اے خداوند، میرے منہ کے سامنے پہرہ رکھو؛ دروازہ میرے ہونٹوں سے دور رکھو۔\n4۔ میرا دل کسی بھی برے کام کی طرف مائل نہ ہو، اور ان لوگوں کے ساتھ برے کام نہ کروں جو بدکاری کرتے ہیں: اور میں ان کی لذیذ چیزوں سے نہ کھاؤں۔\n5. نیک لوگ مجھے سزا دیں؛ {یہ ایک مہربانی ہوگی}: اور وہ مجھے ڈانٹے؛ {یہ ایک عمدہ تیل ہوگا}، {جو} میرا سر نہیں توڑے گا: کیونکہ پھر بھی میری دعا ان کی مصیبتوں میں {رہے گی}۔ {میں؛ یہ ہوگا...: یا، میں مہربانی سے، اور مجھے ملامت کرو؛ ان کا قیمتی تیل نہ ٹوٹنے دو، وغیرہ}\n6۔ جب ان کے جج پتھریلی جگہوں پر گرا دیے جائیں گے، تو وہ میرے الفاظ سنیں گے؛ کیونکہ وہ میٹھے ہیں۔\n7۔ ہماری ہڈیاں قبر کے منہ پر بکھری ہوئی ہیں، جیسے کوئی زمین پر لکڑی کاٹتا اور کاٹتا ہے۔\n8. لیکن میری آنکھیں تیری طرف ہیں، اے خداوند: میرا بھروسہ تیرے پر ہے؛ میری روح کو بے بس نہ چھوڑو۔ {چھوڑیں...: عبوری۔ میری روح کو بے پردہ نہ کرو}\n9. مجھے ان جالوں سے بچاؤ جو انہوں نے میرے لیے بچھا دیے ہیں، اور بدکاری کے مزدوروں کے جنوں سے۔\n10۔ بدکاروں کو ان کے جالوں میں پھنسنے دو، جبکہ میں بچ نکلوں گا۔ {ایسکیپ: عبوری۔ پاس اوور}","1. [داؤد کا مشکیل؛ ایک دعا جب وہ غار میں تھا۔] میں نے اپنی آواز میں خداوند سے پکارا؛ میں نے اپنی آواز سے خداوند کے لیے دعا کی۔ {مشکیل...: یا، داؤد کا زبور، ہدایت دینا}\n2۔ میں نے اپنی شکایت ان کے سامنے کھل گئی؛ میں نے اس کے سامنے اپنی پریشانی دکھائی۔\n3۔ جب میری روح میرے اندر مغلوب ہو گئی، تو تم نے میرا راستہ جان لیا۔ جس طرح میں چلتا تھا، انہوں نے میرے لیے جال بچھایا ہے۔\n4. میں نے {اپنی} دائیں ہاتھ پر دیکھا، اور دیکھا، لیکن {کوئی آدمی} نہیں تھا جو مجھے جانتا ہو: پناہ نے مجھے ناکام کر دیا؛ کسی نے میری روح کی پرواہ نہیں کی۔ {میں نے دیکھا...: یا، دائیں ہاتھ دیکھو، اور دیکھو} {ناکام...: عبوری۔ مجھ سے فنا ہو گیا} {پرواہ...: عبرانی۔ تلاش شدہ}\n5. اے خداوند، میں نے تجھ سے پکارا: میں نے کہا، تو میری پناہ گاہ ہے اور زندہ لوگوں کی سرزمین میں میرا حصہ ہے۔\n6. میری پکار سنو؛ کیونکہ میں بہت نیچے گرا ہوا ہوں: مجھے میرے ستکاروں سے نجات دے؛ کیونکہ وہ مجھ سے زیادہ طاقتور ہیں۔\n7۔ میری روح کو قید سے نکال، تاکہ میں تیرے نام کی تعریف کر سکوں: نیک لوگ میرے گرد گھیرے جائیں گے؛ کیونکہ تم میرے ساتھ خوب سلوک کرو گے۔","1. [داؤد کا زبور۔] اے خداوند، میری دعا سن، میری دعائیں سن: اپنی وفاداری میں میری سن، {اور} اپنی راستبازی میں۔\n2۔ اور اپنے بندے کے ساتھ انصاف نہ کرو، کیونکہ تیری نظر میں کوئی زندہ شخص راستباز نہیں ہوگا۔\n3۔ کیونکہ دشمن نے میری روح کو ستایا ہے؛ اس نے میری زندگی کو زمین بوس کر دیا ہے؛ اس نے مجھے اندھیرے میں بٹھایا ہے، جیسے وہ لوگ جو بہت پہلے مر چکے ہیں۔\n4۔ اسی لیے میری روح مجھ میں مغلوب ہو گئی ہے؛ میرا دل میرے اندر ویران ہے۔\n5. مجھے پرانے دن یاد ہیں؛ میں تیرے تمام کاموں پر غور کرتا ہوں؛ میں تمہارے ہاتھوں کے کام پر غور کرتا ہوں۔\n6۔ میں اپنے ہاتھ تیرے لیے بڑھاتا ہوں: میری جان {پیاس ہے} تیرے پیچھے، جیسے پیاسی زمین۔ سیلہ۔\n7۔ اے خداوند، جلدی میری بات سن: میری روح کمزور ہے: اپنا چہرہ مجھ سے نہ چھپاؤ، ورنہ میں ان لوگوں کی طرح ہو جاؤں جو گڑھے میں اترتے ہیں۔ {ورنہ...: یا، کیونکہ میں جیسا بن گیا ہوں، وغیرہ}\n8. صبح مجھے اپنی محبت بھری مہربانی سناؤ؛ کیونکہ میں تم پر بھروسہ کرتا ہوں: مجھے بتاؤ کہ مجھے کس راستے پر چلنا ہے؛ کیونکہ میں اپنی جان تمہارے لیے اٹھاتا ہوں۔\n9. اے خداوند، مجھے میرے دشمنوں سے بچا: میں تیرے پاس چھپنے کے لیے بھاگتا ہوں۔ {فرار ہو...: عبرانی مجھے تمہارے ساتھ چھپا دو}\n10۔ مجھے اپنی مرضی کرنا سکھاؤ؛ کیونکہ تو میرے خدا ہو: تیری روح {نیکی} ہے؛ مجھے دیانت داری کی سرزمین میں لے چلو۔\n11۔ اے خداوند، اپنے نام کے لیے مجھے زندہ کر: تیری راستبازی کے لیے میری جان کو مصیبت سے نکال۔\n12۔ اور اپنی رحمت سے میرے دشمنوں کو کاٹ دو، اور ان سب کو تباہ کر دو جو میری روح کو تکلیف دیتے ہیں: کیونکہ میں تمہارا بندہ ہوں۔","1. [{داؤد کا زبور}] خداوند کو میری طاقت مبارک ہو، جو میرے ہاتھوں کو جنگ سکھاتا ہے، اور میری انگلیوں کو لڑنے کے لیے: طاقت: عبرانی۔ راک} {جنگ کے لیے...: عبرانی۔ جنگ کی طرف، وغیرہ}\n2۔ میری بھلائی اور میرا قلعہ؛ میرا بلند مینار، اور میرا نجات دہندہ؛ میرا ڈھال، اور {وہ} جس پر میں بھروسہ کرتا ہوں؛ جو میرے لوگوں کو میرے ماتحت کرتا ہے۔ {یا اللہ: یا، میری رحمت}\n3. اے خداوند، انسان کیا ہے کہ تو اس کے بارے میں جانتا ہے! {یا} انسان کے بیٹے، کہ تم اس کا حساب لگاتے ہو!\n4۔ انسان غرور کی مانند ہے: اس کے دن ایک سایہ کی طرح ہیں جو گزر جاتا ہے۔\n5. اے خداوند، اپنے آسمانوں کو جھک کر نیچے آؤ: پہاڑوں کو چھو، وہ دھواں اٹھائیں گے۔\n6۔ بجلی پھینکو، اور انہیں بکھیر دو: اپنے تیر چلاؤ، اور انہیں تباہ کر دو۔\n7۔ اوپر سے اپنا ہاتھ بھیجو؛ مجھے آزاد کرو، اور بڑے پانیوں سے نکالو، اجنبی بچوں کے ہاتھوں سے؛ {ہاتھ: عبوری۔ ہاتھوں سے}\n8۔ جس کا منہ باطل بولتا ہے، اور اس کا دایاں ہاتھ جھوٹ کا دایاں ہاتھ ہے۔\n9. اے خدا، میں تجھے ایک نیا گیت گاؤں گا: ایک زبور پر {اور} دس تاروں کا ساز میں تمہاری تعریف کروں گا۔\n10۔ {وہی ہے} جو بادشاہوں کو نجات دیتا ہے: جو اپنے خادم داؤد کو تکلیف دہ تلوار سے بچاتا ہے۔ {نجات: یا، فتح}\n11۔ مجھے آزاد کر، اور اجنبی بچوں کے ہاتھ سے نجات دے، جن کے منہ میں فضول باتیں ہیں، اور ان کا دایاں ہاتھ جھوٹ کا دایاں ہاتھ ہے:\n12۔ تاکہ ہمارے بیٹے {ہو سکیں} پودوں کی طرح جو اپنی جوانی میں بڑے ہوئے؛ {کہ} ہماری بیٹیاں {شاید} کونے کے پتھروں کی طرح ہوں، پالش شدہ {بعد} محل کی تشابہ: {پالش شدہ: عبرانی۔ کٹ}\n13. {تاکہ} ہمارے جمع شدہ {بھر} ہوں، ہر طرح کی ذخیرے کے لیے: {تاکہ} ہماری بھیڑیں ہماری گلیوں میں ہزاروں اور دس ہزار پیدا کر سکیں: {سب...: عبرانی۔ ایک قسم سے دوسری قسم}\n14. {کہ} ہمارے بیل {شاید} محنت کے لیے مضبوط ہوں؛ {کہ کوئی توڑ پھوڑ نہ ہو، نہ باہر جانا؛ کہ ہماری گلیوں میں کوئی شکایت نہ ہو۔ {مضبوط...: عبرانی۔ بوجھ اٹھانے کے قابل، یا، گوشت سے بھرپور}\n15. خوش {کیا یہ} لوگ، اس صورت میں: {ہاں}، خوش {کیا یہ} لوگ ہیں، جن کا خدا {ہے} خداوند۔","1. [داؤد کا {زبور} تعریف۔] اے بادشاہ، میں تجھ کی تعریف کروں گا، میرے خدا؛ اور میں ہمیشہ کے لیے تیرا نام برکت دوں گا۔\n2. ہر دن میں تمہیں برکت دوں گا؛ اور میں ہمیشہ ہمیشہ تیرے نام کی تعریف کروں گا۔\n3۔ عظیم {ہے} خداوند ہے، اور بہت زیادہ تعریف کے لائق ہے؛ اور اس کی عظمت {ناقابل تلاش} ہے۔ {اور اس کا...: عبرانی اور اس کی عظمت کی کوئی تلاش نہیں}\n4۔ ایک نسل تیری کارناموں کی تعریف کرے گی اور تمہارے عظیم اعمال کا اعلان کرے گی۔\n5۔ میں آپ کی عظمت کی شان و شوکت اور آپ کے حیرت انگیز کاموں کے بارے میں بات کروں گا۔ {تصانیف: عبرانی۔ چیزیں، یا، الفاظ}\n6۔ اور {لوگ} تمہارے خوفناک اعمال کی طاقت کے بارے میں بات کریں گے: اور میں تمہاری عظمت کا اعلان کروں گا۔ {اعلان کریں: عبرانی۔ اعلان کرو}\n7۔ وہ تیری عظیم نیکی کی یاد کو بھرپور انداز میں بیان کریں گے، اور تیری راستبازی کا گائیں گے۔\n8. خداوند مہربان اور ہمدردی سے بھرپور ہے؛ غصے میں آہستہ آہستہ اور بہت رحم کرنے والا۔ {عظیم...: عبرانی۔ رحمت میں عظیم}\n9۔ خداوند سب کے لیے اچھا ہے: اور اس کی نرم رحمتیں اس کے تمام اعمال پر غالب ہیں۔\n10۔ اے خداوند، تیری تمام اعمال تیری تعریف کریں گے؛ اور تمہارے مقدس تمہیں برکت دیں گے۔\n11۔ وہ تیری بادشاہی کی شان کی بات کریں گے، اور تیری طاقت کی بات کریں گے؛\n12۔ انسانوں کے بیٹوں کو اس کے عظیم اعمال اور اس کی سلطنت کی شان و شوکت سے آگاہ کرنا۔\n13. تیری بادشاہی ایک دائمی بادشاہی ہے، اور تیری سلطنت تمام نسلوں تک قائم رہے گی۔ {an...: عبرانی۔ ہر دور کی بادشاہت}\n14۔ خداوند ہر گرنے والے کو سہارا دیتا ہے، اور سب کو اٹھاتا ہے جو جھکے ہوئے ہیں۔\n15۔ سب کی نظریں تیرے انتظار میں ہیں؛ اور تم انہیں وقت پر ان کا گوشت دیتے ہو۔ {رکو...: یا، دیکھو}\n16۔ تو اپنا ہاتھ کھولتا ہے، اور ہر جاندار کی خواہش پوری کرتا ہے۔\n17. خداوند اپنی تمام راہوں میں راستباز اور اپنے تمام اعمال میں پاک ہے۔ {مقدس: یا، رحم کرنے والا، یا، فیاض}\n18. خداوند ان سب کے قریب ہے جو اسے پکارتے ہیں، ان سب کے جو اسے سچائی میں پکار رہے ہیں۔\n19۔ وہ ان لوگوں کی خواہش پوری کرے گا جو اس سے ڈرتے ہیں: وہ ان کی پکار بھی سنے گا، اور انہیں بچائے گا۔\n20۔ خداوند ان سب کو محفوظ رکھتا ہے جو اس سے محبت کرتے ہیں: لیکن وہ تمام بدکاروں کو تباہ کر دے گا۔\n21۔ میرا منہ خداوند کی حمد کرے گا: اور ہر جسم اس کے مقدس نام کو ہمیشہ ہمیشہ کے لیے برکت دے۔","1. خداوند کی تعریف کرو۔ اے میری جان، خداوند کی تعریف کرو۔ {تعریف ہو...: عبرانی۔ الحمد للہ}\n2۔ جب تک میں زندہ ہوں، میں خداوند کی تعریف کروں گا: جب تک میرے پاس کوئی وجود ہے، میں اپنے خدا کی تعریف کروں گا۔\n3۔ شہزادوں پر بھروسہ نہ کرو، نہ ہی انسان کے بیٹے پر، جس میں کوئی مدد نہیں۔ {مدد: یا، نجات}\n4۔ اس کی سانس باہر نکلتی ہے، وہ اپنی زمین میں واپس آتا ہے؛ اسی دن اس کے خیالات ختم ہو جاتے ہیں۔\n5. خوش نصیب ہے {کیا وہ} ہے کہ {ہے} یعقوب کے خدا کی مدد کے لیے، جس کی امید {ہے} خداوند اپنے خدا میں:\n6۔ جس نے آسمان، زمین، سمندر اور اس میں موجود سب کچھ بنایا: جو سچائی کو ہمیشہ قائم رکھتا ہے:\n7۔ جو مظلوموں کے لیے فیصلہ کرتا ہے: جو بھوکوں کو خوراک دیتا ہے۔ خداوند قیدیوں کو آزاد کرتا ہے:\n8۔ خداوند اندھوں کی آنکھیں کھولتا ہے: خداوند سجدہ کرنے والوں کو اٹھاتا ہے: خداوند راستبازوں سے محبت کرتا ہے:\n9۔ خداوند اجنبیوں کی حفاظت کرتا ہے؛ وہ یتیم اور بیوہ کو نجات دیتا ہے: لیکن بدکاروں کا راستہ الٹ پلٹ کر دیتا ہے۔\n10. خداوند ہمیشہ کے لیے حکومت کرے گا، {حتیٰ کہ} تیرا خدا، اے صییون، تمام نسلوں پر۔ خداوند کی تعریف ہو۔","1۔ خداوند کی تعریف کرو: کیونکہ ہمارے خدا کی حمد و ثنا کرنا اچھا ہے؛ کیونکہ {یہ} خوشگوار ہے؛ {اور} تعریف خوبصورت ہے۔\n2۔ خداوند یروشلم کو تعمیر کرتا ہے: وہ اسرائیل کے بے دخل لوگوں کو اکٹھا کرتا ہے۔\n3۔ وہ دل ٹوٹنے والوں کو شفا دیتا ہے، اور ان کے زخموں کو باندھ دیتا ہے۔ {زخم: عبرانی۔ غم}\n4۔ وہ ستاروں کی تعداد بتاتا ہے؛ وہ سب کو {ان} کے ناموں سے پکارتا ہے۔\n5۔ عظیم {ہے} ہمارا رب، اور عظیم طاقتور: اس کی سمجھ {لامحدود} ہے۔ {اس کا...: عبرانی اس کی سمجھ کے مطابق کوئی تعداد نہیں ہے}\n6۔ خداوند عاجزوں کو اٹھاتا ہے: وہ بدکاروں کو زمین پر گرا دیتا ہے۔\n7. خداوند کے لیے شکر گزاری کے ساتھ گاؤ؛ ہارپ پر ہمارے خدا کی حمد گاؤ:\n8۔ جو آسمان کو بادلوں سے ڈھانپتا ہے، جو زمین کے لیے بارش تیار کرتا ہے، جو پہاڑوں پر گھاس اگاتا ہے۔\n9۔ وہ جانور کو اپنا کھانا دیتا ہے، {اور} ان نوجوان کوؤں کو جو روتے ہیں۔\n10۔ وہ گھوڑے کی طاقت سے خوش نہیں ہوتا: وہ آدمی کی ٹانگوں میں خوشی محسوس نہیں کرتا۔\n11۔ خداوند ان لوگوں میں خوشی لیتا ہے جو اس سے ڈرتے ہیں، ان میں جو اس کی رحمت کی امید رکھتے ہیں۔\n12. اے یروشلم، خداوند کی تعریف کرو؛ اے صیہون، اپنے خدا کی تعریف کرو۔\n13۔ کیونکہ اس نے تمہارے دروازوں کی سلاخیں مضبوط کی ہیں؛ اس نے تمہارے بچوں کو تمہارے اندر برکت دی ہے۔\n14۔ وہ تمہاری سرحدوں میں امن قائم کرتا ہے، اور تمہیں بہترین گندم سے بھر دیتا ہے۔ {وہ...: عبرانی۔ جو تیری سرحد کو امن بناتا ہے} {بہترین...: عبرانی۔ گندم کی چکنائی}\n15۔ وہ زمین پر اپنا حکم بھیجتا ہے: اس کا کلام بہت تیزی سے پہنچتا ہے۔\n16۔ وہ برف کو اون کی طرح دیتا ہے: وہ برف کو راکھ کی طرح بکھیر دیتا ہے۔\n17۔ وہ اپنی برف کو ٹکڑوں کی طرح پھینکتا ہے: کون اس کی سردی کے سامنے کھڑا ہو سکتا ہے؟\n18۔ وہ اپنا کلام بھیجتا ہے، اور انہیں پگھلا دیتا ہے: وہ اپنی ہوا کو چلاتی ہے، {اور} پانی بہنے لگتا ہے۔\n19۔ وہ اپنا کلام یعقوب کو ظاہر کرتا ہے، اپنے قوانین اور اپنے فیصلے اسرائیل کو دیتا ہے۔ {اس کا لفظ: عبرانی۔ اس کے الفاظ}\n20۔ اس نے کسی قوم کے ساتھ ایسا سلوک نہیں کیا: اور {جہاں تک اس کے} فیصلوں کا تعلق ہے، وہ انہیں نہیں جانتے۔ خداوند کی تعریف ہو۔","1. خداوند کی تعریف کرو۔ آسمانوں سے خداوند کی حمد کرو: بلندیوں میں اس کی حمد کرو۔ {خداوند کی تعریف ہو۔ تعریف: عبرانی۔ ہللویا وغیرہ}\n2۔ اس کی تعریف کرو، اس کے تمام فرشتوں کو: اس کی تعریف کرو، اس کے تمام لشکروں کی تعریف کرو۔\n3. سورج اور چاند کی حمد کرو: اس کی حمد کرو، اے تمام روشنی کے ستارے۔\n4. اے آسمانوں کے آسمانوں اور آسمانوں کے اوپر والے پانیوں، اس کی تعریف کرو۔\n5۔ وہ خداوند کے نام کی تعریف کریں: کیونکہ اس نے حکم دیا، اور وہ پیدا ہوئے۔\n6۔ اس نے انہیں ہمیشہ ہمیشہ کے لیے قائم کر دیا ہے: اس نے ایک ایسا حکم دیا ہے جو کبھی نہیں گزرے گا۔\n7. اے زمین سے خداوند کی تعریف کرو، اے اژدہوں اور تمام گہرائیوں سے:\n8۔ آگ اور اولے بارے؛ برف، اور بخارات؛ طوفانی ہوا نے اس کا وعدہ پورا کیا:\n9۔ پہاڑ اور تمام پہاڑیاں؛ پھلدار درخت، اور تمام دیودار:\n10۔ جانور اور تمام مویشی؛ رینگتے ہوئے جانور، اور اڑتا ہوا پرندہ: {اڑتا ہوا...: ہیب۔ پرندوں کے پرندے}\n11۔ زمین کے بادشاہ اور تمام انسان؛ شہزادے، اور زمین کے تمام قاضی:\n12۔ دونوں نوجوان مرد اور دوشیزہ؛ بوڑھے مرد، اور بچے:\n13۔ وہ خداوند کے نام کی تعریف کریں: کیونکہ صرف اس کا نام بہترین ہے؛ اس کی شان {ہے} زمین اور آسمان کے اوپر۔ {بہترین: عبوری۔ Gracealted}\n14۔ وہ اپنے لوگوں کے سینگ کو بھی بلند کرتا ہے، جو اپنے تمام اولیاء کی تعریف ہے؛ {حتیٰ کہ} بنی اسرائیل میں سے ایک قوم تھی، جو اس کے قریب تھی۔ خداوند کی تعریف ہو۔","1. خداوند کی تعریف کرو۔ خداوند کو نیا گیت گاؤ، {اور} مقدسین کی جماعت میں اس کی تعریف کرو۔ {تعریف...: عبرانی۔ الحمد للہ}\n2۔ اسرائیل اس پر خوش ہو جس نے اسے بنایا: صیہون کے بچے اپنے بادشاہ میں خوش رہیں۔ {اس میں...: عبرانی۔ اپنے میکرز میں}\n3۔ رقص میں اس کے نام کی تعریف کریں: وہ اس کے لیے ٹمبرل اور ہارپ سے اس کی حمد گائیں۔ {میں...: یا، پائپ کے ساتھ}\n4۔ کیونکہ خداوند اپنی قوم میں خوشی پاتا ہے: وہ عاجزوں کو نجات سے خوبصورت بنائے گا۔\n5۔ مقدسین جلال میں خوش ہوں: وہ اپنے بستر پر بلند آواز میں گائیں۔\n6. {خدا کی اعلیٰ تعریف} ان کے منہ میں ہو، اور ہاتھ میں دو دھاری تلوار ہو؛ {منہ: عبرانی۔ گلا}\n7۔ کافروں سے انتقام لینا، {اور} عوام پر سزائیں دینا؛\n8۔ اپنے بادشاہوں کو زنجیروں سے باندھنا، اور اپنے اشرافیہ کو لوہے کی زنجیروں سے باندھنا؛\n9۔ ان پر لکھا ہوا فیصلہ نافذ کرنا: یہ عزت اس کے تمام مقدسین کو ملے۔ خداوند کی تعریف ہو۔","1. خداوند کی تعریف کرو۔ خدا کی عبادت گاہ میں اس کی تعریف کرو: اس کی طاقت کے آسمان میں اس کی تعریف کرو۔ {تعریف ہو...: عبرانی۔ الحمد للہ}\n2۔ اس کے عظیم اعمال کی تعریف کرو: اس کی عظیم عظمت کے مطابق اس کی تعریف کرو۔\n3۔ اس کی تعریف ترمپٹ کی آواز سے کرو: زبور اور ہارپ سے اس کی تعریف کرو۔ {ٹرمپٹ: اور، کارنیٹ}\n4. اس کی آواز اور رقص سے اس کی تعریف کریں: تار والے آلات اور آرگن سے اس کی تعریف کریں۔ {رقص: یا، پائپ}\n5. اونچی آواز والے سنبلز پر اس کی تعریف کرو: اونچی آواز والے سنبلز پر اس کی تعریف کرو۔\n6۔ ہر سانس لینے والی چیز خداوند کی تعریف کرے۔ خداوند کی تعریف ہو۔"];
